def number(value: object) -> float:
    return float(value) if isinstance(value, (int, float)) and math.isfinite(value) else 0.0


def _round(value: float) -> float:
    """Five significant digits, so a model's lines only change (and PoB recalculates) when the
    build really moved."""
    return float(f"{value:.5g}")


def line(text: str, scale: float = 1.0, *, when: list | None = None, per: str | None = None,
         stat: str | None = None, base: float = 0.0, skill: str | None = None) -> dict:
    """A modifier line for the bridge: PoB parses `text` (written with a magnitude of 1) and scales
    it by `scale`; with `per` (a model input) or `stat` (a PoB output stat such as Armour), the
    value is scale × that number + base."""
    mod: dict = {"kind": "Line", "line": text, "scale": _round(scale)}
    if when:
        mod["when"] = when
    if per:
        mod["per"] = per
        mod["base"] = _round(base)
    elif stat:
        mod["stat"] = stat
        mod["base"] = _round(base)
    if skill:
        mod["skill"] = skill
    return mod


UNIT = 1_000_000  # a fraction as a bridge model input (PoB multipliers are whole numbers; engine/bridge.lua DERIVED_UNIT)


def derived(name: str, fn: str, value: float, **args) -> dict:
    """A model input the bridge works out again on every calculation (engine/bridge.lua DERIVED), so what-ifs see it
    without a trial: PoB multiplier Ledger<name>, read by lines with per=name. `value` is the build's own (a whole number:
    a fraction comes x UNIT); `fn` and `args` are how the bridge works it out from a what-if's own items or output."""
    return {"kind": "Derived", "name": name, "fn": fn, "value": int(round(value)), "args": args}


def raw_mod(name: str, kind: str, value: float, skill: str | None = None, tag: str | None = None,
            condition: str | None = None, not_condition: str | None = None, slots: list[str] | None = None,
            keywords: list[str] | None = None, enemy: bool = False) -> dict:
    """A PoB modifier by its internal name (no text to parse): `kind` "INC" / "MORE" / "BASE" / "FLAG", tagged to
    `skill` if given (SkillName). For what PoB has no parseable line for, such as one skill's DebuffEffect MORE.
    `tag`: its source becomes "Assumption:<tag>", which a bridge read can leave out (TOTEM_ONE_TAG). `condition`: PoB
    applies it only under that player condition (MECH75: "Shocked"); `not_condition` only while it's off (MECHC32);
    `slots`: only on those items' own defences (PoB's SlotName tag, e.g. ["Helmet", "Boots", "Gloves"]; MECHC32).
    `enemy`: the mod goes ON THE ENEMY (the bridge carries it as an EnemyModifier, as PoB's config boxes put theirs in
    enemyModList), so the minions' hits read it too (MECH107: Critical Weakness's SelfCritChance)."""
    mod: dict = {"kind": "Raw", "name": name, "type": kind, "value": _round(value)}
    if enemy:
        mod["enemy"] = True
    if keywords:  # (GEM22: PoB KeywordFlag names, e.g. ["Ignite"]: the mod applies only where its cfg carries one)
        mod["keywordFlags"] = list(keywords)
    if condition:
        mod["condition"] = condition
    if not_condition:
        mod["notCondition"] = not_condition
    if slots:
        mod["slots"] = list(slots)
    if skill:
        mod["skill"] = skill
    if tag:
        mod["tag"] = tag
    return mod


def trigger_rate(skill: str, rate: float) -> list[dict]:
    return [{"kind": "SkillData", "skill": skill, "key": "triggerRate", "value": _round(rate)},
            {"kind": "SkillData", "skill": skill, "key": "triggered", "value": True}]


# (MECHB62, U1 from COV56's calibration, probe POE2T8044) ONE SPELL IN TWO SOCKET GROUPS: PoB tags an assumption by skill
# NAME (the bridge's SkillName tag), so a trigger rate or a "more" line one meta group's model gives its spell lands on
# every copy of that spell (cast by hand, or in another meta gem), and PoB keeps the LAST SkillData of a key
# (CalcActiveSkill 919-920): example build 15's main Comet read Speed 5e-61 from a Cast on Critical group's 0 rate.
# A mod with "group" (the socket group's index, bridge.groups) reaches only that group's copy (engine/bridge.lua
# installGroupAssumptions).
def in_group(mods: list[dict], group: int | None, names: set[str]) -> list[dict]:
    """`mods`, those for a skill in `names` (and not already given a group) now for socket group `group` only."""
    if group is None:
        return mods
    return [{**m, "group": group} if m.get("skill") in names and "group" not in m else m for m in mods]


def rates_by_name(mods: list[dict]) -> dict[str, float]:
    """{skill: triggers a second} from the trigger-rate mods: the last rate for each (skill, group), summed over a
    skill's groups (in_group: one spell triggered from two meta gems)."""
    last: dict[tuple, float] = {}
    for m in mods:
        if m.get("kind") == "SkillData" and m.get("key") == "triggerRate" and m.get("skill"):
            last[(m["skill"], m.get("group"))] = number(m.get("value"))
    out: dict[str, float] = {}
    for (name, _), value in last.items():
        out[name] = out.get(name, 0.0) + value
    return out


def shared_names(skills: list["Skill"], group: int | None, names: set[str]) -> set[str]:
    """The skills in `names` that also sit in another socket group than `group` (in_group's need)."""
    return {s.name for s in skills if s.name in names and s.group is not None and s.group != group}


def _derivative(f: Callable[[dict], float], x0: dict, key: str) -> float:
    up, down = dict(x0), dict(x0)
    up[key] += 1.0
    down[key] -= 1.0
    return (f(up) - f(down)) / 2.0


def more_lines(text: str, f: Callable[[dict], float], x0: dict, passive: dict, keys: tuple[str, ...],
               when: list | None = None, skill: str | None = None) -> list[dict]:
    """Lines for a "more" modifier worth f(x)% at the model inputs x. PoB multiplies "more"
    modifiers together, so each input gets its own factor 1 + h·(its passive total − now), with h
    chosen so the product has f's slope; at the current build the product is exactly f(x0)."""
    value = f(x0)
    mods = [line(text, value, when=when, skill=skill)] if abs(value) > 1e-6 else []
    factor = 1 + value / 100
    if factor < 0.05:  # (almost) no damage of this kind: slopes would explode
        return mods
    for key in keys:
        h = _derivative(f, x0, key) / 100 / factor
        if abs(h) > 1e-9:
            mods.append(line(text, 100 * h, when=when, per=key, base=-100 * h * passive.get(key, 0.0), skill=skill))
    return mods


def increased_lines(text: str, f: Callable[[dict], float], x0: dict, passive: dict, keys: tuple[str, ...],
                    when: list | None = None) -> list[dict]:
    """Lines for an "increased" modifier worth f(x)%: PoB adds those, so value + slope × change."""
    value = f(x0)
    mods = [line(text, value, when=when)] if abs(value) > 1e-6 else []
    for key in keys:
        slope = _derivative(f, x0, key)
        if abs(slope) > 1e-9:
            mods.append(line(text, slope, when=when, per=key, base=-slope * passive.get(key, 0.0)))
    return mods


# Inputs ------------------------------------------------------------------------------------------

INPUT = re.compile(r"^(mult|flag):(\w+)\s*(-?[\d.]+)?$")


@dataclass
class Inputs:
    """A build's custom-model inputs: totals of `mult:` inputs and the `flag:` conditions, split by
    where they come from (PoB counts the passive part itself; item lines are read here)."""
    passive: dict[str, float] = field(default_factory=dict)
    items: dict[str, float] = field(default_factory=dict)
    flags: set[str] = field(default_factory=set)
    item_flags: set[str] = field(default_factory=set)
    used: list[tuple[str, str, str]] = field(default_factory=list)  # (source, line, ledger entry)

    def total(self, name: str) -> float:
        return self.passive.get(name, 0.0) + self.items.get(name, 0.0)

    def has(self, flag: str) -> bool:
        return flag in self.flags or flag in self.item_flags

    def condition(self, flag: str, on: bool) -> list | None:
        """`when` conditions for a block that needs `flag` on or off: [] when that always holds,
        None when it never can (an item switches it on for good)."""
        if flag in self.item_flags:
            return [] if on else None
        return [{"var": flag}] if on else [{"var": flag, "neg": True}]


def read_inputs(lines: list[dict]) -> Inputs:
    """Model inputs from the build's passive and item lines (bridge `sourceLines`)."""
    inputs = Inputs()
    for entry_line in lines:
        text, source = entry_line["text"], entry_line["source"]
        entry = model_entry(text)
        if entry is None:
            continue
        passive = source.startswith("passive:")
        for replacement in entry.translate(text) or []:
            m = INPUT.match(replacement)
            if not m:
                continue
            kind, name, value = m.groups()
            if kind == "flag":
                (inputs.flags if passive else inputs.item_flags).add(name)
            elif value is not None:
                target = inputs.passive if passive else inputs.items
                target[name] = target.get(name, 0.0) + float(value)
        inputs.used.append((source, text, entry.id))
    return inputs


@dataclass
class Skill:
    """What a model needs to know about an active skill (bridge `activeSkills`)."""
    name: str
    group: int | None = None
    spell: bool = False
    attack: bool = False
    melee: bool = False
    triggered: bool = False
    energy: bool = False  # a meta skill that gains Energy
    cast_time: float = 0.0
    cooldown: float | None = None
    cooldown_recovery: float = 1.0
    level_stats: dict[str, float] = field(default_factory=dict)  # only for skills asked for (Iron Ward)
    wrong_weapon: bool = False  # needs a weapon type in neither hand (PoB disables only Attacks for that)
    corpses: bool = False  # consumes or targets corpses (the game's skill types; corpse_model)
    level: int | None = None  # gem level of a meta skill that gains Energy (gem_energy)
    minion: dict | None = None  # a triggered skill summoning Temporary minions: their duration, casts, limit (minion_count)
    summon: dict | None = None  # any minion skill's minions: limit, duration (0: until killed), persistent (minion_deaths)
    support_stats: dict[str, float] = field(default_factory=dict)  # named stats of its supports, summed (gem_stat_model)
    early_hazard: dict | None = None  # its scored set's "less damage if set off in its first 0.5 s" (hazard_early_model)
    energy_final: float = 0.0  # its own active_skill_energy_generated_+%_final (energy_gain; Incinerate -98)
    total_time_added: float = 0.0  # its "+N seconds to Total Cast / Attack Time" (PoB's TotalCastTime; energy_cost)
    stat_set: str | None = None  # the label of the stat set PoB calculates for it (bridge activeSkills statSet; COVE8)
    totem_limit: float = 0.0  # a totem-summoning skill's Totem Limit (bridge activeSkills totemLimit; totem_count_model)
    # a totem skill's count PoB multiplies its ailment stacks by: {override, limit} (bridge ailmentTotems; totem_count_model)
    ailment_totems: dict | None = None
    mark_duration: float = 0.0  # a Mark's duration with the build's modifiers (bridge activeSkills markDuration; MECH62)
    # its raw per-minute costs and cast speed multiplier if cast speed also scales its cost (bridge overTimeCost; GEM15)
    over_time_cost: dict | None = None
    # a totem-summoning skill's own base Totem Limit, without the build's "+N" lines (bridge totemLimitOwn; MECHB34)
    totem_limit_own: float = 0.0
    by_totem: bool = False  # used by a totem (bridge activeSkills byTotem; MECHB37 cannons_ready_model)
    projectile_attack: bool = False  # an Attack that fires projectiles (bridge projectileAttack; cannons_ready_model)
    # (GEM41) Totem Limit the game's is_melee_attack_totem lets "Melee Attack Skills have +N" lines add (bridge
    # meleeAttackTotemAdded; already in totem_limit; totem_count_model's "without it" row)
    melee_totem_added: float = 0.0
    # (GEM42, RESEARCH59 R59-3) Totem Limit "Attack Skills have +N" lines add on top for such a totem (bridge
    # attackTotemAdded; already in totem_limit; its own "without it" row, MEDIUM)
    attack_totem_added: float = 0.0

    @classmethod
    def of(cls, raw: dict) -> Skill:
        return cls(raw["name"], raw.get("group"), bool(raw.get("spell")), bool(raw.get("attack")),
                   bool(raw.get("melee")), bool(raw.get("triggered")), bool(raw.get("energy")),
                   number(raw.get("castTime")), raw.get("cooldown"), number(raw.get("cooldownRecovery")) or 1.0,
                   dict(raw.get("levelStats") or {}), bool(raw.get("wrongWeapon")),
                   bool(raw.get("corpses")), raw.get("level"), raw.get("minion"), raw.get("summon"),
                   dict(raw.get("supportStats") or {}), raw.get("earlyHazard"), number(raw.get("energyFinal")),
                   number(raw.get("totalTimeAdded")), raw.get("statSet"), number(raw.get("totemLimit")),
                   raw.get("ailmentTotems"), number(raw.get("markDuration")), raw.get("overTimeCost"),
                   number(raw.get("totemLimitOwn")), bool(raw.get("byTotem")), bool(raw.get("projectileAttack")),
                   number(raw.get("meleeAttackTotemAdded")), number(raw.get("attackTotemAdded")))


# (MECH93, an OVERCOUNT before; the manager 07:25, MECHC45's list) AT_MAIN_SHARE: the main skill's share of the fight
# as the score counts it (assumptions.main_time_share: the press model's time the pressed side skills leave it, x the
# search's chosen presses outside it), which Conditions.evidence puts in stats["_main_share"] (MECHC44). MECH-A's
# ailment, debuff, ground and buildup readers took the main skill's hits at PoB's full Speed, as if it were used all
# fight. at_main_share gives the stats with Speed x the share and "_main_share" blanked (MECHC45's own convention, so a
# reader called inside another, or a MECH-C reader, never scales twice); unchanged where no share is set (1 with no
# presses; readers called from Assumptions with PoB's plain stats: not scaled, UNVERIFIED there).
# (MECH99; the manager 20:50, the approved split) Two kinds of cut on the main skill: TIME off it (a channel in its
# cooldown, a wind-up, a pause, a cooldown-gated release: build.main_hit_cut, in "_main_share", read by every reader of
# its uses and hits) and HITS A USE (bolts or projectiles landing per use: build.main_hits_per_use, in "_hits_per_use",
# read only by readers of its HITS: the skill is used as often). A model tags the second with HIT_CUT_PER_USE on its
# "DPS" MORE mod (the first keeps MECHB52's "hit_cut" key, or the mod's whole value). at_main_share(stats) is the hit
# readers' view; at_main_share(stats, per_use=False) a uses reader's. HITS_PER_USE_MAX caps the factor at 1 for now
# (the lower reading; a model that ADDS hits is the manager's step 3, reader by reader). Untagged: None, no change.
HIT_CUT_PER_USE = "hit_cut_per_use"
HITS_PER_USE_MAX = 1.0
# (MECH100; the manager 12:00 from MECHB55: Explosive Rhythm's uncapped uses during Fervour, the Last Lament's bolts
# with no reload while Life pays, Forge Hammer's throw-and-recall loop) A third kind: MORE USES a second, each use still
# one hit. Neither a time share (build.main_hit_cut is clamped to [0, 1]: such a raise never reached the readers) nor
# hits a use (k uses aren't one use's 1 - (1 - c)^k). A model tags its "DPS" MORE mod with USES_RAISE (the factor; the
# mod's whole value without it); hit_cut hands it to build.main_uses_raise, Conditions.evidence to stats["_uses_raise"]
# (at least 1), and at_main_share multiplies the main skill's Speed by it for every reader, as if the skill were used
# that much faster (uses and hits alike: each extra use is a use and its hit). Readers that read "_main_share" or
# "Speed" directly, not through at_main_share, keep PoB's rate (the lower reading). Untagged: no change.
USES_RAISE = "uses_raise"


def uses_raise(stats: dict) -> float:
    """The main skill's uses-a-second raise in `stats` (>= 1; 1 without one)."""
    got = stats.get("_uses_raise")
    return max(1.0, float(got)) if isinstance(got, (int, float)) and not isinstance(got, bool) else 1.0


def _hits_a_use(stats: dict) -> float | None:
    """stats["_hits_per_use"] as a number, or None. (MECH99, the manager 02:52: MECHC44's (hits a use, how) tuple once
    shared this key, and number() reads a tuple as 0, so every hit reader saw no hits on Twister / Galvanic Field: an
    UNDERCOUNT. A value that isn't a number is read as no factor (None: 1), never as 0.) Under pytest (MECH100, the
    manager 02:52's second half) a value that is neither None nor a number RAISES a TypeError, so a new writer that
    shares the key fails the suite instead of reading quietly as no factor."""
    got = stats.get("_hits_per_use")
    if isinstance(got, (int, float)) and not isinstance(got, bool):
        return float(got)
    if got is not None and os.environ.get("PYTEST_CURRENT_TEST"):
        raise TypeError(f'stats["_hits_per_use"] must be a number or None, got {got!r} (models._hits_a_use)')
    return None


def per_use_factor(stats: dict) -> float:
    """The main skill's hits-per-use factor in `stats` (1 without one; clamped to [0, HITS_PER_USE_MAX])."""
    got = _hits_a_use(stats)
    return 1.0 if got is None else max(0.0, min(HITS_PER_USE_MAX, got))


# (MECH99, step 3 of the split, the manager 22:20: the cap lifts for models that ADD hits) Hits a use above 1 (Spell
# Cascade's areas, Freezing Salvo's and Zarokh's Repeats, Lightning Conduit's bolts, extra projectiles all hitting) land
# TOGETHER within a use. A reader that counts hits linearly (a buildup or a stack per hit) may take them as more hits:
# at_main_share(stats, raise_hits=True). A duration ailment can't: three hits at once raise the use's chance to apply
# it (1 - (1 - c)^k), not how often it is applied (a sure Shock from one cast every 10 s with three areas is up 40%,
# not min(1, 3 x 0.4)): ailment_uptime reads hits_raise(stats) as that per-use chance. Every other reader keeps the cap
# at 1 (the lower reading) until checked.
def hits_raise(stats: dict) -> float:
    """The main skill's hits a use beyond one (>= 1; 1 without a raise): the factor above HITS_PER_USE_MAX's cap."""
    got = _hits_a_use(stats)
    return 1.0 if got is None else max(1.0, got)


def at_main_share(stats: dict, per_use: bool = True, raise_hits: bool = False) -> dict:
    share = stats.get("_main_share")
    hits = _hits_a_use(stats) if per_use else None
    more = uses_raise(stats)  # (MECH100: USES_RAISE, more uses a second)
    if share is None and hits is None and more == 1.0:
        return stats
    speed = number(stats.get("Speed")) * (1.0 if share is None else max(0.0, min(1.0, number(share)))) * more
    factor = (per_use_factor(stats) * (hits_raise(stats) if raise_hits else 1.0)) if per_use else 1.0
    return {**stats, "Speed": speed * factor, "_main_share": None, "_hits_per_use": None, "_uses_raise": None}


def hits_per_second(stats: dict) -> float:
    return number(stats.get("Speed")) * number(stats.get("HitChance")) / 100


def crits_per_second(stats: dict) -> float:
    return hits_per_second(stats) * number(stats.get("CritChance")) / 100


# Elemental Archon --------------------------------------------------------------------------------
# https://poe2db.tw/us/Elemental_Archon: 25% more Elemental Damage with Spells, no non-elemental
# damage from Spells; "By default, each Archon Buff lasts 10 seconds"; no Archon Buff can be gained
# during "a recovery period after you lose one, which lasts 20 seconds by default"; using a
# non-instant Attack removes it.

ARCHON_DURATION = 10.0
ARCHON_RECOVERY = 20.0
ELEMENTAL_ARCHON_MORE = 25.0
ARCHON_INPUTS = ("ArchonDuration", "ArchonRecovery", "ArchonEffect", "ArchonCritChance", "ArchonCritDamage")
ARCHON_TIMING = ("ArchonDuration", "ArchonRecovery")


def archon_uptime(duration_inc: float, recovery_faster: float, wait: float, no_recovery: bool = False,
                  expiry: float = 1.0) -> float:
    """Share of a long fight with the Archon Buff up: it lasts D, then the recovery period R, then
    the next gain comes `wait` seconds later. "Expires X% faster/slower" changes how fast the
    recovery period passes. `expiry`: "Buffs on you expire N% slower" (conditions.buff_expiry, MECHC35), x the duration."""
    duration = ARCHON_DURATION * max(0.0, 1 + duration_inc / 100) * expiry
    if duration <= 0:
        return 0.0
    recovery = 0.0
    if not no_recovery:
        speed = 1 + recovery_faster / 100
        if speed <= 0:
            return 0.0
        recovery = ARCHON_RECOVERY / speed
    return duration / (duration + recovery + max(wait, 0.0))


def flame_uptime(cycle: float, recovery_faster: float, no_recovery: bool = False) -> tuple[float, float, float]:
    """Seething Body's Elemental Archon over Pyromantic Pact's Infernal Flame cycle (MECHC4; RESEARCH12 18af,
    archon-infernal-rest.md, rules HIGH): Flame climbs from 0 to its maximum (2 x maximum Mana) in `cycle` seconds of the
    build's skill costs, then resets to 0. Archon comes with the first spell cast on High Infernal Flame (65% of maximum)
    once the recovery period is over, and lasts until the reset ("does not expire while on High Infernal Flame"; "Lose
    Elemental Archon on reaching maximum Infernal Flame"), so Archon Duration lines don't lengthen it. (uptime, on, off)."""
    if cycle <= 0:
        return 0.0, 0.0, 0.0
    if FLAME_MANAGED:  # (the play guide's "pause near the top" trial: Archon held all fight, flame_pause_share's cost)
        return 1.0, math.inf, 0.0
    recovery = 0.0
    if not no_recovery:
        speed = 1 + recovery_faster / 100
        if speed <= 0:
            return 0.0, 0.0, 0.0
        recovery = ARCHON_RECOVERY / speed
    high = FLAME_HIGH * cycle  # (seconds into a cycle when Flame reaches High)
    whole, rest = divmod(recovery, cycle)
    if rest <= high:
        off = whole * cycle + high
    else:  # (the recovery ends while Flame is already High: gained at once)
        off = recovery
    on = (whole + 1) * cycle - off
    return on / (on + off), on, off


FLAME_HIGH = 0.65  # KeywordPopups HighInfernalFlame: 65% of maximum Infernal Flame or more
# Managing the bar (MECHC8; FIX_QUEUE "Seething Body", research/archon-infernal-rest.md): cast until Flame is nearly at its
# maximum, then stop: after 2 s without gaining Flame it decays by 25% of its maximum per second (Pyromantic Pact; the
# stat id says "of MAX", the text "of Infernal Flame": MEDIUM), so 1.4 s more brings it back to High (65%). Archon then
# never ends (it doesn't expire on High and the reset never comes), and no self-hit; the cost is the pause, 3.4 s per
# 0.7 x 2 x maximum Mana / cost of casting. Pausing longer (to 65%) is the best ratio: the 2 s are paid per pause, so the
# casting between them should be as long as High allows. LOW for how players time it (a play strategy, not counted in
# the headline: the play guide's row). FLAME_MANAGED is only switched on by that row's trial.
FLAME_MANAGED = False
FLAME_IDLE = 2.0  # seconds without gaining Flame before it decays (research note, MEDIUM)
FLAME_DECAY = 0.25  # share of maximum Flame lost per second once decaying (MEDIUM)


def flame_pause_share(mana: float, cost: float) -> float:
    """The share of the fight spent casting when the bar is managed (cast from High to the top, pause until High again)."""
    if mana <= 0 or cost <= 0:
        return 0.0
    cast = (1 - FLAME_HIGH) * 2 * mana / cost
    pause = FLAME_IDLE + (1 - FLAME_HIGH) / FLAME_DECAY
    return cast / (cast + pause)


def archon_effects(x: dict, wait: float, no_recovery: bool, flame: float = 0.0, expiry: float = 1.0) -> dict[str, float]:
    """The Archon Buff's effects averaged over a fight, in percent. `flame`: Seething Body's Infernal Flame cycle in
    seconds (flame_uptime), which replaces the duration and the wait."""
    if flame > 0:
        uptime = flame_uptime(flame, x["ArchonRecovery"], no_recovery)[0]
    else:
        uptime = archon_uptime(x["ArchonDuration"], x["ArchonRecovery"], wait, no_recovery, expiry)
    effect = max(0.0, 1 + x["ArchonEffect"] / 100)
    return {"uptime": uptime, "effect": effect, "more": ELEMENTAL_ARCHON_MORE * effect * uptime,
            "crit_chance": x["ArchonCritChance"] * effect * uptime,
            "crit_damage": x["ArchonCritDamage"] * effect * uptime}


# Nature's Archon's uptime (MECHC44, for GEM24's Accelerated Growth; GEM23's 20:23 / plans/kw-archon-buff.md item 3).
# Its gain: "(25-50)% chance to gain Nature's Archon when your Plants Overgrow" (Mods AlloyNaturesArchon1; its stat
# chance_%_to_gain_archon_of_nature_on_overgrowing_plant has no other carrier: checked, the Stats ids holding archon with
# nature / plant (3) over every game table under 400 MB, game 26650308, and PoB's ModItem.lua; poe2db's Natures_Archon
# page, GEM24's 19 Nov read, names the same source; the model reads any line of that text). It is an
# Archon Buff (KeywordPopups Archon: 10 s by default; none gained while you have one or in the 20 s recovery period after
# it), so one cycle: D up, R recovering, then the wait for the next gain, 1 / (chance x Overgrows a second), the Overgrows
# taken as random arrivals (MEDIUM). Overgrows a second are the CALLER's (the build's plants a second x the share
# Overgrown by its other sources: overgrown_share without the Archon), counted outside the Archon and its recovery (the
# Archon's own 100% Overgrow can't start a new Archon while it's up). One recovery period covers every Archon kind
# (KeywordPopups): a build with another Archon source shares the cycle, not counted here (an overcount for such a build
# where both are summed: none are summed today). No Overgrow, no line: 0. Readers: natures_archon_uptime below; the
# Overgrown share with it is 1 - (1 - uptime) x (1 - the other sources' share).
NATURES_ARCHON_GAIN = re.compile(r"^(\d+(?:\.\d+)?)% chance to gain Nature's Archon when your Plants Overgrow$", re.I)


def natures_archon_uptime(texts: list[str], overgrows: float, x: dict | None = None, no_recovery: bool = False,
                          expiry: float = 1.0) -> tuple[float, str]:
    """(MECHC44) (Nature's Archon's share of the fight, how) from the build's NATURES_ARCHON_GAIN lines and `overgrows`,
    its Plants' Overgrows a second outside the Archon (the note above). `x`: ArchonDuration / ArchonRecovery totals (%,
    as archon_model reads them from the bridge's inputs); `no_recovery`: Dominion's ArchonNoRecovery; `expiry`:
    "Buffs on you expire N% slower" (conditions.buff_expiry)."""
    chance = min(100.0, sum(float(m.group(1)) for t in texts if (m := NATURES_ARCHON_GAIN.match(t.strip()))))
    if chance <= 0:
        return 0.0, ""
    rate = chance / 100 * max(overgrows, 0.0)
    if rate <= 0:
        return 0.0, f"{chance:g}% chance on each Overgrow, but nothing Overgrows the build's Plants: 0"
    x = x or {}
    duration_inc, faster = number(x.get("ArchonDuration")), number(x.get("ArchonRecovery"))
    up = archon_uptime(duration_inc, faster, 1 / rate, no_recovery, expiry)
    duration = ARCHON_DURATION * max(0.0, 1 + duration_inc / 100) * expiry
    recovery = 0.0 if no_recovery else ARCHON_RECOVERY / max(1 + faster / 100, 1e-9)
    return up, (f"Nature's Archon {duration:.3g} s, then {recovery:.3g} s recovery, then the next gain a mean "
                f"{1 / rate:.3g} s later ({chance:g}% x {overgrows:.3g} Overgrows/s, random: MEDIUM): up {up:.0%} "
                "(KeywordPopups Archon: one Archon at a time, one recovery period for all kinds)")


# Archon of Undeath (MECHC55; MECHC54's item 3, coverage rows 95 / 300; plans/kw-archon-of-undeath.md; an UNDERCOUNT: every
# effect counted 0). KeywordPopups UndeadArchon (game 26650308): "Archon of Undeath is a type of Archon Buff. It grants:
# 25% more Minion Damage; 200% more Cooldown Recovery Rate for Command Skills; Temporary Minion Skills have 100% more Limit
# of Minions summoned. When you gain Archon of Undeath all of your Persistent Undead Minions are revived." KeywordPopups
# Archon: 10 s by default, none gained while you have one or in the 20 s recovery period after one (one period for every
# kind). Its gains (checked: game files 26650308, every Stats id holding undeath (9: have_archon_undeath, the two
# chances, Brequel's crafted roll, the four effect stats, puppet_master_does_not_expire_while_you_have_archon_of_undeath)
# over Mods, PassiveSkills, GrantedEffectStatSets / PerLevel, SoulCoreStats, UtilityFlaskBuffs and the ascendancy /
# class overrides: chance_%_to_gain_archon_of_undeath_on_using_command_skill 15 on the notable Archon of Undeath
# (PassiveSkills archon23) and chance_%_to_gain_archon_of_undeath_when_you_create_an_offering (35-50) on the Genesis Tree
# belt mods GenesisTreeBeltArchonUndeathOnOfferingUse / ...Crafted are the only gains; Beyond Death: Unending (+5) only
# raises the crafted roll; the effect stats and the Puppet Master one are on no carrier in these tables (the buff's own
# definition isn't extracted); PoB's ModCache 2215 / 4295 hold both gain lines with leftover text (never applied) and no
# Module reads an Undeath buff; second source: poe2db 22 Nov, /us/Archon_of_Undeath (the notable archon23, also anointable,
# the buff's 25 / 200 / 100, 10 s) and /us/The_Genesis_Tree (the belt suffix "of Unending", (35-50)%), no other source.)
# The rate, from the build (CLAUDE.md, no flat rates): a build that takes either line plays to feed it,
# so its Commands pressed on their cooldowns (command_uses, as Puppet Master's) and its Offerings kept up, re-cast as each
# spike ends (OFFERING_SECONDS, their base durations; the three player Offerings: checked, ActiveSkills with the Offering
# type, Dark / Grave Offering [DNT-UNUSED]). Gains a second outside the Archon and its recovery: lambda = chance_c x
# Commands/s + chance_o x Offerings/s, taken as random arrivals (MEDIUM): a mean wait 1 / lambda; archon_uptime gives the
# share (the shared Archon duration / recovery / effect lines, Dominion's no recovery, buffs expiring slower). Another
# Archon kind the build gains races it for the one slot (archon_race: the first gain after the recovery wins). Counted:
# the 25% more Minion Damage x effect x uptime (as "Minions deal N% more Damage", the whole minion pool). Not counted
# (labelled, UNDERCOUNTS): the Commands' 200% more Cooldown Recovery while up (Command damage is scored apart), the
# Temporary minions' doubled limit, the revive on each gain.
ARCHON_UNDEATH_MORE = 25.0  # KeywordPopups UndeadArchon: 25% more Minion Damage
ARCHON_UNDEATH_COMMAND = 200.0  # KeywordPopups UndeadArchon: 200% more Cooldown Recovery Rate for Command Skills
UNDEATH_COMMAND_TAG = "ArchonOfUndeathCommands"
UNDEATH_COMMAND_STAT = "_undeath_command"  # (the note's key: the Command recovery factor its mods give PoB)
# (MECHC56) "Temporary Minion Skills have 100% more Limit of Minions summoned" (KeywordPopups UndeadArchon; the stat
# temporary_minion_limit_+%_final_from_archon_of_undeath; a Temporary minion is one "that does not revive after it dies",
# KeywordPopups TemporaryMinion: Raise Zombie's 20 s zombies). PoB reads neither. The note carries UNDEATH_LIMIT_STAT =
# (the share of the fight it's up, the limit's factor while up: 1 + 100% x the Archon effect); a temporary minion count
# whose limit binds is then the time mix (undeath_limit_mix): (1 - up) x count(limit) + up x count(limit x factor). The
# minions standing when it ends are taken to stay until their duration runs out (LOW: whether the extra ones die then
# is UNVERIFIED; the mix is the lower reading where they would stay). Hooked: Raise Zombie (Assumptions.zombie_count);
# (MECHB61) the meta-triggered Temporary minions (Wardbound Minions: minion_count, inside energy_model's `undeath`).
# Not hooked (labelled): Skyfall's minions, which have no count model of their own yet (PoB's one kept,
# minion_alive_count's Temporary-minion row), so there is no limit for the Archon to raise.
UNDEATH_LIMIT_STAT = "_undeath_limit"
UNDEATH_LIMIT_MORE = 100.0
UNDEATH_ON_COMMAND = re.compile(r"^(\d+(?:\.\d+)?)% chance to gain Archon of Undeath when you use a Command skill$", re.I)
UNDEATH_ON_OFFERING = re.compile(r"^(\d+(?:\.\d+)?)% (?:chance )?to gain Archon of Undeath when you create an Offering"
                                 r"(?: Minion)?$", re.I)  # (poe2db's belt text ends "Offering Minion"; PoB's "Offering")


def archon_race(own: float, others: float) -> float:
    """(MECHC55) The share of an Archon's cycles that are this kind's when another kind's gains (`others` a second)
    race it for the one slot after the shared recovery period (KeywordPopups Archon): own / (own + others)."""
    total = max(own, 0.0) + max(others, 0.0)
    return max(own, 0.0) / total if total > 0 else 0.0


def archon_of_undeath_model(skills: list[Skill], texts: list[str], x: dict | None = None, effect: float = 0.0,
                            no_recovery: bool = False, expiry: float = 1.0,
                            others: tuple[float, str] = (0.0, ""),
                            command_prior: float = 1.0) -> tuple[list[dict], list[dict]]:
    """(MECHC55) (mods, notes) for Archon of Undeath (see above). `x`: ArchonDuration / ArchonRecovery totals (%);
    `effect`: ArchonEffect (%); `others`: (gains a second of the other Archon kinds the build has, how);
    `command_prior`: the Command Cooldown Recovery factor this model's last mods gave PoB (UNDEATH_COMMAND_STAT's note),
    taken back out of the Commands' rate for the gains. The note carries UNDEATH_COMMAND_STAT: the factor of these mods."""
    texts = [t.strip() for t in texts]
    on_command = min(100.0, sum(float(m.group(1)) for t in texts if (m := UNDEATH_ON_COMMAND.match(t))))
    on_offering = min(100.0, sum(float(m.group(1)) for t in texts if (m := UNDEATH_ON_OFFERING.match(t))))
    if on_command <= 0 and on_offering <= 0:
        return [], []
    label = "Archon of Undeath: 25% more Minion Damage at its share of the fight*"
    prior = max(number(command_prior), 1.0)
    base = [replace(k, cooldown_recovery=(k.cooldown_recovery or 1.0) / prior) if k.summon and prior != 1.0 else k
            for k in skills]  # (the gains come outside the Archon: its own Command speed-up taken back out)
    commands, command_parts = command_uses(base) if on_command > 0 else (0.0, [])
    offerings, offering_how, recast_row = offering_casts(skills) if on_offering > 0 else (0.0, "", 0.0)
    rate = on_command / 100 * commands + on_offering / 100 * offerings
    parts = []
    if on_command > 0:
        parts.append(f"{on_command:g}% a Command use x {commands:.3g}/s ("
                     + (", ".join(command_parts) if command_parts else "no Command this model maps") + ")")
    if on_offering > 0:
        parts.append(f"{on_offering:g}% an Offering created x {offerings:.3g}/s ({offering_how})")
    minions = any(s.summon for s in skills)
    if rate <= 0:
        return [], [{"label": label, "value": 0, "confidence": "MEDIUM",
                     "basis": "; ".join(parts) + ": nothing gains it, so 0 (no source, never a flat guess)",
                     "play": "Archon of Undeath needs Command skills pressed or Offerings created: without them it "
                             "never comes."}]
    x = x or {}
    duration_inc, faster = number(x.get("ArchonDuration")), number(x.get("ArchonRecovery"))
    other_rate, other_how = others
    up_alone = archon_uptime(duration_inc, faster, 1 / rate, no_recovery, expiry)
    if other_rate > 0:  # (one slot: the first gain after the recovery wins; the wait is the joint stream's)
        total = rate + other_rate
        up = archon_race(rate, other_rate) * archon_uptime(duration_inc, faster, 1 / total, no_recovery, expiry)
    else:
        up = up_alone
    scale = max(0.0, 1 + effect / 100)
    more = ARCHON_UNDEATH_MORE * scale * up if minions else 0.0
    # (the Commands' 200% more Cooldown Recovery Rate while it's up: the time average, 1 + 2 x effect x up, on every
    # Command-bearing minion skill (COMMANDS), so each reader of its cooldown_recovery (the Command rates: Death Storm,
    # Explosive Demise, Shattering Roar, Puppet Master, different Commands) uses them that much more often)
    command_more = ARCHON_UNDEATH_COMMAND * scale * up
    commanders = sorted({k.name for k in skills if k.summon and any(m in k.name for m in COMMANDS)})
    command_mods = [raw_mod("CooldownRecovery", "MORE", command_more, skill=n, tag=UNDEATH_COMMAND_TAG)
                    for n in commanders] if command_more > 0 else []
    if on_offering > 0 and recast_row > 0 and recast_row != offerings:  # (R49-7's row: re-casts don't count)
        row_rate = on_command / 100 * commands + on_offering / 100 * recast_row
        row_up = archon_uptime(number((x or {}).get("ArchonDuration")), number((x or {}).get("ArchonRecovery")),
                               1 / row_rate, no_recovery, expiry) if row_rate > 0 else 0.0
    else:
        row_up = None
    duration = ARCHON_DURATION * max(0.0, 1 + duration_inc / 100) * expiry
    recovery = 0.0 if no_recovery else ARCHON_RECOVERY / max(1 + faster / 100, 1e-9)
    basis = (f"gains: {'; '.join(parts)} = {rate:.3g} a second, taken as random (MEDIUM): a mean {1 / rate:.3g} s "
             f"after the {recovery:.3g} s recovery; it lasts {duration:.3g} s: up {up_alone:.0%}"
             + (f"; racing {other_how} ({other_rate:.3g} gains a second) for the one Archon slot: up {up:.0%}"
                if other_rate > 0 else "")
             + (f"; effect x{scale:.2f}" if scale != 1 else "")
             + (f": {more:.2f}% more Minion Damage averaged" if minions else ": the build has no minions, so no damage")
             + (f"; the Commands' 200% more Cooldown Recovery while it's up: x{1 + command_more / 100:.3f} on "
                f"{', '.join(commanders)}'s Commands on average" if command_mods else "")
             + (f". Row (R49-7, MEDIUM: each cast creates one): if re-casts while a spike stands didn't count, up "
                f"{row_up:.0%}" if row_up is not None else "")
             + (f"; Temporary minion limits x{1 + UNDEATH_LIMIT_MORE / 100 * scale:.2f} while it's up (Raise Zombie's "
                f"count at that mix, undeath_limit_mix)" if minions else "")
             + ". Not counted (UNDERCOUNTS): the Persistent Undead minions revived on each gain, the doubled limit on "
               "Skyfall's minions (no count model yet); not raced: a Nature's Archon source (one slot for every kind: "
               "an OVERCOUNT where the build has one)")
    play = (f"Archon of Undeath: press your Commands on cooldown / keep your Offerings up to gain it; without it +0%, "
            f"with it {more:.1f}% more Minion Damage averaged (up {up:.0%})")
    note = {"label": label, "value": round(more, 2), "basis": basis, "play": play,
            "confidence": "MEDIUM (game text: the chances, the 25%, the Archon cycle; the gains taken as random)",
            UNDEATH_COMMAND_STAT: 1 + command_more / 100,
            UNDEATH_LIMIT_STAT: (up, 1 + UNDEATH_LIMIT_MORE / 100 * scale)}
    return ([line("Minions deal 1% more Damage", more)] if more > 0 else []) + command_mods, [note]


def undeath_limit_mix(count_at, limit: float, mix: tuple[float, float] | None) -> tuple[float, str]:
    """(MECHC56, UNDEATH_LIMIT_STAT's note) (a Temporary minion count with Archon of Undeath's limit mixed in, how).
    `count_at(limit)` gives the count at a limit; `mix` = (the share of the fight it's up, the limit's factor)."""
    base = count_at(limit)
    up, factor = mix or (0.0, 1.0)
    if up <= 0 or factor <= 1 or limit <= 0:
        return base, ""
    raised = count_at(limit * factor)
    if raised <= base:
        return base, ""
    count = (1 - up) * base + up * raised
    return count, (f"Archon of Undeath up {up:.0%}: its limit x{factor:.2f} ({limit:g} -> {limit * factor:g}) "
                   f"lets {raised:.3g} stand then, {base:.3g} otherwise: {count:.3g} on average (LOW: the extra ones "
                   f"taken to stay out their duration)")


def offering_casts(skills: list[Skill]) -> tuple[float, str, float]:
    """(MECHC55; RESEARCH49 R49-7, MEDIUM: each Offering cast creates an Offering, re-casts too) (Offerings created a
    second while the build feeds Archon of Undeath, how, the row's rate if re-casts didn't count): the build's Offering
    skills cast back to back (their PoB cast time), each needing an active Skeleton (KeywordPopups Offering: "Offering
    Skills target an active Skeleton Minion"; the skewered one revives: revive_seconds, as danse_macabre_model), so at
    most its Persistent Skeletons / their revive time. Cast only while waiting for the next Archon (the build plays to
    feed it): their cast time is a small share of the fight (not charged, LOW). No Skeleton: 0."""
    offerings = [k for k in skills if k.name in OFFERING_SECONDS and k.group is not None]
    if not offerings:
        return 0.0, "no Offering in the build", 0.0
    recast_row = sum(1 / OFFERING_SECONDS[n] for n in dict.fromkeys(k.name for k in offerings))
    skeletons = [k for k in skills if k.summon and k.summon.get("persistent") and "Skelet" in k.name
                 and not number(k.summon.get("duration"))]
    count = sum(number(k.summon.get("limit")) for k in skeletons)
    if count <= 0:
        return 0.0, "no Persistent Skeleton for an Offering to target: 0", recast_row
    revive, revive_how = revive_seconds(skeletons)
    cast = min((k.cast_time or 1.0) for k in offerings)
    supply = count / revive if revive > 0 else math.inf
    casts = min(1 / cast, supply)
    names = ", ".join(dict.fromkeys(k.name for k in offerings))
    return casts, (f"{names} cast back to back while waiting for it: one per {cast:.2g} s cast"
                   + (f", held to {count:g} Skeletons / {revive:.3g} s to revive ({revive_how})" if supply < 1 / cast
                      else f" ({count:g} Skeletons, {revive:.3g} s to revive, enough)")), recast_row


def archon_gain_rate(source: ArchonSource | None) -> tuple[float, str]:
    """(MECHC55) (gains a second, how) of an Elemental Archon source (archon_sources), for archon_race: 1 / its wait
    after the recovery; Seething Body's Flame cycle at the wait that gives its base uptime (archon_sources' rank)."""
    if source is None:
        return 0.0, ""
    wait = source.wait
    if source.flame > 0:
        share = flame_uptime(source.flame, 0.0)[0]
        wait = ARCHON_DURATION / share - ARCHON_DURATION - ARCHON_RECOVERY if share > 0 else math.inf
    if not math.isfinite(wait):
        return 0.0, ""
    return 1 / max(wait, 1e-3), f"Elemental Archon ({source.name})"


@dataclass
class ArchonSource:
    name: str
    flag: str | None  # the condition its passive switches on; None: always there (a support gem)
    wait: float  # seconds from the end of the recovery period to the next gain
    basis: str
    # True: the counter behind it may also run during the buff and its recovery (unsettled); the headline takes `wait`
    # (it doesn't run) and the notes add the other reading, uncounted (MECHC2, the manager's ruling)
    counter_may_run: bool = False
    flame: float = 0.0  # Seething Body: the Infernal Flame cycle in seconds (flame_uptime); 0 for the others


def archon_sources(stats: dict, main_gems: set[str]) -> list[ArchonSource]:
    """Ways to gain Elemental Archon on a boss, fastest first."""
    mana, cost = number(stats.get("Mana")), number(stats.get("ManaPerSecondCost"))
    # Seething Body (MECHC4; RESEARCH12 18af: before, a 10 s Archon regained at once after the 20 s recovery, 33% at base,
    # an overcount for fast spenders): Pyromantic Pact, which Seething Body needs (tree links: research note), turns skill
    # costs into Infernal Flame up to 2 x maximum Mana (PoB reads neither node, so Mana and ManaPerSecondCost are the
    # build's own). 1 Flame per 1 Mana of cost (MEDIUM: "Gain Infernal Flame instead of spending Mana"). No cost: no
    # Flame, no Archon. Pausing near the top to hold High without the reset isn't counted (a play choice that costs casts).
    cycle = 2 * mana / cost if mana > 0 and cost > 0 else 0.0
    sources = [ArchonSource("Seething Body", "ArchonInfernal", math.inf if cycle <= 0 else 0.0,
                            (f"Infernal Flame (2 x {mana:,.0f} Mana) fills in {cycle:.1f}s at {cost:,.0f} Mana of costs "
                             "per second, then resets (a Fire hit of your maximum Life and Energy Shield each time); "
                             "Archon from the first cast on High (65%) after the recovery until the reset"
                             if cycle > 0 else "the build's skills cost no Mana, so no Infernal Flame is gained"),
                            flame=cycle if cycle > 0 else 0.0)]
    if mana > 0 and cost > 0:
        spend = mana / cost
        # The lower uptime bound (MECHC2, the manager's ruling, as for the Arcane Surge support): only Mana spent after the
        # recovery ends counts, so the next gain comes a full spend time later. Whether Mana spent during the Archon and its
        # recovery counts is unsettled (RESEARCH1 mana-spend-counters.md, LOW); archon_model adds that reading as an
        # uncounted note. (Before: half the spend time, the midpoint.)
        sources.append(ArchonSource("Archon of the Storm", "ArchonMana", spend,
                                    f"spending {mana:,.0f} Mana takes {spend:.1f}s at {cost:,.0f} Mana per second, counted "
                                    "from the end of the recovery (LOW: Mana spent during the Archon and its recovery taken "
                                    "as not counting toward the next, the lower bound; unsettled, "
                                    "research/mana-spend-counters.md)", counter_may_run=True))
    if number(stats.get("EnergyShield")) > 0:
        # (MECH46, FLAT_RATES A8: before, a flat 2 x delay, though every boss hit that lands restarts the delay.) The
        # boss's landing hits taken as a Poisson stream (enemySkillTime, less evaded and blocked hits): the expected wait
        # for a gap of `delay` with none is (e^(rate x delay) - 1) / rate. The boss's misses by timing aren't counted
        # (MEDIUM). Damage over time its hits leave on you (Ignite, Corrupted Blood) lengthens the gap it needs (MECHC6,
        # RESEARCH21 #126: boss_hits.recharge_wait; before, hits only: an overcount against the Arbiter's Fire hits).
        delay = number(stats.get("EnergyShieldRechargeDelay")) or 4.0
        every = number(stats.get("enemySkillTime")) or 0.7
        land = boss_hits.land_share(stats) / every  # (red-flash hits always land, MECHC5)
        wait = boss_hits.recharge_wait(stats, delay, land)
        sources.append(ArchonSource("Archon of the Blizzard", "ArchonRecharge", wait,
                                    f"Energy Shield Recharge begins after {delay:g}s without damage; the boss lands "
                                    f"{land:.2f} hits/s (one per {every:g}s, LOW: PoB's placeholder; less evaded and "
                                    f"blocked), each restarting it: a {delay:g}s gap comes after {wait:.1f}s on average; "
                                    + boss_hits.recharge_text(stats, delay, land)))
    if "Arbiter's Ignition" in main_gems:
        crit = number(stats.get("CritChance")) / 100
        chance = (number(stats.get("IgniteChanceOnHit")) * (1 - crit) + number(stats.get("IgniteChanceOnCrit")) * crit) / 100
        ignites = hits_per_second(stats) * min(chance, 1.0)
        if stats.get("_main_share") is not None:  # (MECHC45: the main skill's hits at its share of the fight)
            ignites *= max(0.0, min(1.0, number(stats["_main_share"])))
        if ignites > 0:
            sources.append(ArchonSource("Arbiter's Ignition", None, 1 / ignites,
                                        f"the main skill ignites {ignites:.2f} times per second"))
    def rank(source: ArchonSource) -> float:  # (Seething Body by the wait that would give its uptime at base)
        if source.flame <= 0:
            return source.wait
        share = flame_uptime(source.flame, 0.0)[0]
        return ARCHON_DURATION / share - ARCHON_DURATION - ARCHON_RECOVERY if share > 0 else math.inf

    return sorted(sources, key=rank)


def archon_block(x0: dict, passive: dict, wait: float, no_recovery: bool, when: list, nonelemental: bool,
                 flame: float = 0.0, expiry: float = 1.0) -> list[dict]:
    def effect(key: str) -> Callable[[dict], float]:
        return lambda x: archon_effects(x, wait, no_recovery, flame, expiry)[key]

    mods = more_lines("1% more Elemental Damage with Spells", effect("more"), x0, passive,
                      ("ArchonDuration", "ArchonRecovery", "ArchonEffect"), when)
    mods += increased_lines("1% increased Critical Hit Chance", effect("crit_chance"), x0, passive, ARCHON_INPUTS, when)
    mods += increased_lines("1% increased Critical Damage Bonus", effect("crit_damage"), x0, passive, ARCHON_INPUTS, when)
    if nonelemental:  # "No Non-Elemental Damage from Spells" while it lasts
        def lost(x: dict) -> float:
            return -100 * archon_effects(x, wait, no_recovery, flame, expiry)["uptime"]
        for kind in ("Physical", "Chaos"):
            mods += more_lines(f"1% more {kind} Damage with Spells", lost, x0, passive, ARCHON_TIMING, when)
    return mods


def archon_model(inputs: Inputs, stats: dict, main: Skill | None, main_gems: set[str]) -> tuple[list[dict], list[dict]]:
    """Elemental Archon for a spell main skill: one block of lines per (best source, recovery
    period or not), each averaged over its uptime."""
    sources = archon_sources(stats, main_gems)
    current = next((s for s in sources if s.flag is None or inputs.has(s.flag)), None)
    if main is None or not main.spell or main.attack:
        notes = [] if current is None else [{
            "label": "Elemental Archon (not counted)", "value": 0,
            "basis": f"the main skill ({main.name if main else 'none'}) isn't a spell; using a non-instant attack "
                     "removes Elemental Archon",
            "confidence": "datamined"}]
        return [], notes
    x0 = {k: inputs.total(k) for k in ARCHON_INPUTS}
    passive = {k: inputs.passive.get(k, 0.0) for k in ARCHON_INPUTS}
    expiry, expiry_how = stats.get("_buff_expiry") or (1.0, "")  # (MECHC35: "Buffs on you expire N% slower")
    hit = sum(number(stats.get(f"{t}HitAverage")) for t in DAMAGE_TYPES)
    nonelemental = hit > 0 and (number(stats.get("PhysicalHitAverage")) + number(stats.get("ChaosHitAverage"))) > 0.01 * hit
    mods: list[dict] = []
    for i, source in enumerate(sources):
        better = sources[:i]
        if any(b.flag is None or b.flag in inputs.item_flags for b in better):
            break  # a better source is always there: this one never decides
        when = [{"var": source.flag}] if source.flag else []
        if better:
            when.append({"any": [b.flag for b in better], "neg": True})
        for no_recovery in (False, True):
            state = inputs.condition("ArchonNoRecovery", no_recovery)
            if state is not None:
                mods += archon_block(x0, passive, source.wait, no_recovery, when + state, nonelemental, source.flame,
                                     expiry)
    notes = []
    if current is not None:
        no_recovery = inputs.has("ArchonNoRecovery")
        e = archon_effects(x0, current.wait, no_recovery, current.flame, expiry)
        duration = ARCHON_DURATION * max(0.0, 1 + x0["ArchonDuration"] / 100) * expiry
        recovery = 0.0 if no_recovery else ARCHON_RECOVERY / max(1 + x0["ArchonRecovery"] / 100, 1e-9)
        regained = current.wait
        if current.flame > 0:
            _, duration, off = flame_uptime(current.flame, x0["ArchonRecovery"], no_recovery)
            regained = off - recovery
        parts = []
        if e["crit_chance"]:
            parts.append(f"{e['crit_chance']:.1f}% increased Critical Hit Chance")
        if e["crit_damage"]:
            parts.append(f"{e['crit_damage']:.1f}% increased Critical Damage Bonus")
        if nonelemental:
            parts.append(f"{100 * e['uptime']:.0f}% less physical and chaos spell damage")
        notes.append({
            "label": "Elemental Archon: % more Elemental spell damage, averaged over a boss fight",
            "value": round(e["more"], 2),
            "basis": (f"also {', '.join(parts)}; " if parts else "") + f"up {e['uptime']:.0%} of the time: lasts {duration:.1f}s, then "
                     + ("no recovery period" if no_recovery else f"a {recovery:.1f}s recovery period")
                     + f", regained {regained:.1f}s later ({current.name}: {current.basis}); "
                     f"effect ×{e['effect']:.2f} (duration and recovery datamined; how soon it's regained assumed)"
                     + (f"; the duration x{expiry:.3f}: {expiry_how} (the Archon Recovery is a Buff too, so read "
                        f"literally it would pass slower as well: {archon_uptime(x0['ArchonDuration'], ((1 + x0['ArchonRecovery'] / 100) / expiry - 1) * 100, current.wait, no_recovery, expiry):.0%} up, a row, UNVERIFIED)"
                        if expiry != 1.0 and current.flame <= 0 else ""),
            "confidence": "theory"})
        if current.counter_may_run:  # the other reading, shown and not counted (accuracy first: the headline takes the lower)
            alt_wait = max(0.0, current.wait - duration - recovery)
            alt = archon_effects(x0, alt_wait, no_recovery)
            if alt["uptime"] > e["uptime"] + 1e-9:
                notes.append({
                    "label": "Elemental Archon if Mana spent during it and its recovery counts (not counted)",
                    "value": 0,
                    "basis": f"{alt['more']:.2f}% more Elemental spell damage averaged (up {alt['uptime']:.0%} instead of "
                             f"{e['uptime']:.0%}): the {current.wait:.1f}s of spending would run through the "
                             f"{duration + recovery:.1f}s of Archon and recovery, regained {alt_wait:.1f}s after it ends. "
                             "Unsettled (research/mana-spend-counters.md); the headline takes the lower uptime",
                    "confidence": "theory"})
    return mods, notes


# Meta-skill Energy -------------------------------------------------------------------------------
# Energy from the meta gem's level (game files, build 26476662, GrantedEffectStatSetsPerLevel "energy_generated_+%"): 3% per
# level above 1 (57% at 20, 117% at 40) for every one below but Elemental Invocation, round(3.6% per level above 1) (68% at 20).
# Quality adds none (GrantedEffectQualityStats has no row for any of them). PoB's data gave 72% at 20/20 to some, which counted
# Thundergod's Wrath, Cast on Elemental Ailment, Spellslinger and Barrier Invocation 15 points high, and Mjolner's level-11
# Thundergod's Wrath (30%) as 72%. A level the bridge doesn't report is taken as 20 (labelled). Each triggered
# spell costs 10 Energy per 0.1 s of its base cast time, its "+N s to Total Cast Time" counted double (energy_seconds) (support stat
# "generic_ongoing_trigger_1_maximum_energy_per_Xms_total_cast_time" = 10). Cast on Critical gains
# 1 Energy per Power of the enemy it critically hits, scaled by the share of the enemy's Ailment
# Threshold the hit deals, and its spells deal 20% less damage; the elemental-ailment metas gain 1
# Energy per Power per Shock or Ignite, 10 per Freeze (game files, GrantedEffectStatSets MetaCastOnElementalAilmentPlayer and
# MetaElementalInvocationPlayer: ..._centienergy_per_monster_power_on_shock / _ignite 100, _on_freeze 1000), the boss's
# Freezes at models.buildup_rate (MECH41; before, a Freeze was never assumed on a boss).
# The others, from their 0.5 skill data (centienergy: 100 = 1 Energy): Cast on Block (Svalinn) 25 Energy per block
# (cast_on_block_gain_X_centienergy_on_block 2500), counted at the boss's hits that land and are blocked; Thundergod's
# Wrath (Mjolner) 3 per Power per melee hit (cast_lightning_spell_on_hit_..._per_monster_power_on_hit 300); Spellslinger
# (Dueling Wand) 0.2 per 10 ms of the cast spell's base cast time (spellslinger_invocation_gain_X_centienergy_per_10ms_base_cast_time
# 20); Cast on Charm Use (Bijouborne) 2 per charm charge used (cast_on_using_charm_gain_X_centienergy_per_charm_charge_used_on_using_charm
# 200), at the charges the equipped charms spend against a boss (flasks.charm_charges_used). Energy on kills (Reaper's
# Invocation) comes from the boss preset's killable adds (kill_rate; MECHB9), on minion deaths from minion_deaths. Barrier Invocation (poe2db): "When Hit by an Enemy, gain 1 Energy for each 10 Energy Shield lost to
# damage taken" (barrier_invocation_gain_1_energy_per_X_energy_shield_damage_taken_when_hit 10): the boss's hits that land
# per second x the damage each takes after mitigation (PoB's {Type}TakenHit at its boss preset), up to the Energy Shield
# pool, while the build has Energy Shield. Cast on Dodge: "Gain 2 Energy per metre travelled while dodge rolling" (its 0.5
# description of cast_on_dodge_roll_gain_X_centienergy_per_unit_travelled_while_dodge_rolling 200, shown /100 per metre;
# the stat's name says per unit, 10 units a metre, which would be ten times more: the game's own text is used), over the
# dodge roll's base distance, dodge_roll_base_travel_distance 46 units = 4.6 m (DodgeRollPlayer's constant stats, shown
# /10 as metres; the user had heard 3.7 m, from an older source), at DODGE_EVERY seconds between rolls against a boss (the
# user's default). A build whose damage counts on Cast on Dodge also loses the time its rolls take from its main skill
# (the user, 7 Nov): DODGE_ROLL_SECONDS per roll, as less Attack and Cast Speed; other builds aren't charged.

FREEZE_ENERGY = 10.0  # Energy per monster Power per Freeze (centienergy 1000, above)

META_GEMS = {
    "Cast on Critical": {"per_level": 3.0, "gain": "crit", "less": 20.0},
    "Cast on Elemental Ailment": {"per_level": 3.0, "gain": "ailment"},
    "Elemental Invocation": {"per_level": 3.6, "gain": "ailment", "invocation": True},
    "Cast on Block": {"per_level": 3.0, "gain": "block", "per": 25.0},
    "Thundergod's Wrath": {"per_level": 3.0, "gain": "melee hit", "per": 3.0},
    "Spellslinger": {"per_level": 3.0, "gain": "cast", "per": 0.2, "invocation": True},
    "Cast on Charm Use": {"per_level": 3.0, "gain": "charm", "per": 2.0},
    "Barrier Invocation": {"per_level": 3.0, "gain": "energy shield lost", "per": 0.1, "invocation": True},
    "Cast on Dodge": {"per_level": 3.0, "gain": "dodge", "per": 2.0},
    # Cast on Minion Death (MECH44, 11 Nov 2026; before, in NO_ENERGY_ON_A_BOSS: "none on a single boss"): "Gains 50 base
    # Energy when a Minion is killed, modified by the Minion's Power" (MetaCastOnMinionDeathPlayer,
    # cast_on_minion_death_gain_1_energy_per_X_minion_relative_defensiveness_% 2; energy_generated_+% 3 a level). The game
    # files: it gains "when one of your Persistent Minions is Killed" (its description), and KeywordPopups MinionDeath says
    # expiring or despawned minions aren't Killed. The deaths per second come from the build's own sources (minion_deaths,
    # MECH45; MECH44's flat one every 10 s is gone: the user, 11 Nov), at 100% relative Power (assumed: 50 Energy, LOW).
    "Cast on Minion Death": {"per_level": 3.0, "gain": "minion death", "per": 50.0},
    # Reaper's Invocation (MECHB9; before, in NO_ENERGY_ON_A_BOSS: "none on a single boss"): "While active, gains Energy
    # when you kill an enemy with a Melee Attack" (ActiveSkills reapers_invocation), 30 Energy per monster Power
    # (melee_kill_invocation_gain_X_centienergy_per_monster_power_on_melee_kill 3000; PoB's MetaReapersInvocationPlayer).
    # Against a lone boss the kill ends the fight; the King in the Mists' and Atziri's adds give some (kill_rate: the boss
    # preset's AddKillsPerSecond, MECH-D's). Your own minions are not enemies, so they never count (its text says "an
    # enemy"). An add's Power: 1 assumed (KeywordPopups Power: "An average monster has a Power of 1", x1 Normal; LOW).
    "Reaper's Invocation": {"per_level": 3.0, "gain": "melee kill", "per": 30.0, "invocation": True},
    # Smith of Kitava's Heat of the Forge: the same stats as Thundergod's Wrath (cast_fire_spell_on_hit_gain_X_centienergy_
    # per_monster_power_on_hit 300, the same level table; game files), Fire spells. The game and the tree call it Fire Spell
    # on Hit, PoB's skill Fire Spell on Melee Hit; the notable gives no level, so PoB's is used (the bridge reports it).
    "Fire Spell on Hit": {"per_level": 3.0, "gain": "melee hit", "per": 3.0},
    "Fire Spell on Melee Hit": {"per_level": 3.0, "gain": "melee hit", "per": 3.0},
}
META_LEVEL_ASSUMED = 20  # a meta gem whose level the bridge doesn't report


def gem_energy(meta: str, level: int | None) -> float:
    """The meta gem's own increased Energy at its level (META_GEMS "per_level"; game files)."""
    return float(int(META_GEMS[meta]["per_level"] * (max(level or META_LEVEL_ASSUMED, 1) - 1) + 0.5))
# Supports of a meta group that change its Energy, which PoB doesn't read (game files, build 26476662,
# GrantedEffectStatSets): Boundless Energy I and II "energy_generated_+%" 35 and 45, Energy Retention
# "trigger_skills_refund_half_energy_spent_chance_%" 35. They count for the meta skill they support only.
META_SUPPORTS = {"Boundless Energy I": ("MetaEnergy", 35.0), "Boundless Energy II": ("MetaEnergy", 45.0),
                 "Energy Retention": ("EnergyRefund", 35.0)}


def energy_seconds(skill: Skill) -> float:
    """A skill's use time as Energy counts it (MECHB6, AUDIT17 A17-1): its base cast time plus twice its "+N seconds to
    Total Cast Time". The game's Energy definition (KeywordPopups Energy): "When calculating Energy gain or consumption
    from the use time of a Skill, modifiers to Total use time are treated as though they were double the value." Comet,
    Lightning Conduit, Skyfall and His Foul Emergence carry +1 s, Crushing Earth +1.5 s, Plasma Blast +2 s
    (total_cast_time_+_ms in their own stat sets, game files): Comet's base 1 s costs 300 Energy, not 100. Whether a
    skill's own +N s is such a modifier (300) or part of its base (200) has no game text beyond the definition: the
    definition's reading is taken, SETTLED at 300 (MEDIUM-HIGH: RESEARCH26 R26-49 (b), own-minion-kills-and-comet-
    energy-r26.md: 1 s cast + "+1 s to Total Cast Time", the Total use time counted double: 3 s x 100)."""
    return (skill.cast_time or 0.0) + 2 * (skill.total_time_added or 0.0)


def energy_cost(skill: Skill) -> float:
    """Energy one trigger of `skill` costs: 10 per 0.1 s of its use time as Energy counts it (energy_seconds)."""
    return 100 * energy_seconds(skill)


def energy_time_note(skills: list[Skill]) -> str:
    added = [s for s in skills if s.total_time_added]
    return "".join(f"; {s.name}: {s.cast_time:g} s base + 2 x its {s.total_time_added:+g} s to Total Cast Time (the game's "
                   f"Energy definition counts Total use time modifiers double) = {energy_cost(s):.0f} Energy" for s in added)


INVOCATION_MAX_ENERGY = 500  # generic_ongoing_trigger_maximum_energy of every Invocation (game files, build 26476662)
# Energy Capacitor: "Supports Invocation Skills ... Supported Skills have significantly higher Maximum Energy"
# (SupportEnergyCapacitorPlayer: skill_maximum_energy_+% 80, constant; requireSkillTypes Invocation). The game files hold
# skill_maximum_energy_+% on no other stat set (checked: GrantedEffectStatSets, GrantedEffectStatSetsPerLevel, Mods,
# PassiveSkills, SoulCoreStats, build 26476662; PoB 0.23 sup_int.lua agrees). Player-wide "Invocated skills have N%
# increased Maximum Energy" (invocation_skill_maximum_energy_+%: the Invocated Limit notable 30, the Genesis tree ring mod
# 25-35, a soul core's Bonded 25) reaches the model as the InvocationMaxEnergy input (ledger meta-invocation-maximum);
# PoB parses that line only in part (ModCache: leftover " Maximum Energy "), so applies none of it.
ENERGY_CAPACITY_SUPPORTS = {"Energy Capacitor": 80.0}
# Gem quality adding to the store (MECHB26): Elemental Invocation's quality gives +5 generic_ongoing_trigger_maximum_energy
# per 1% (GrantedEffectQualityStats row 196, MetaElementalInvocationPlayer, 5000 permille). It is the one Invocation whose
# quality does (checked: every GrantedEffectQualityStats row holding stat 17830 generic_ongoing_trigger_maximum_energy,
# build 26476662: only that row; PoB 0.23 act_int.lua's qualityStats agree, only Elemental Invocation's line 5721). The
# flat quality Energy is taken as added before the increases (the usual base-then-increased order; UNVERIFIED).
QUALITY_MAX_ENERGY = {"Elemental Invocation": 5.0}


def invocation_max_energy(inputs: "Inputs | None", supports: list[str], meta: str = "",
                          quality: float = 0.0) -> tuple[float, str]:
    """An Invocation's maximum Energy: (500 + its gem quality's flat Energy, QUALITY_MAX_ENERGY) x (1 + (its group's
    Energy Capacitor + the build's Invocated-skills increased Maximum Energy) / 100), and a few words on where the change
    came from ("" with none). The increases are taken as adding together (both are "increased"; no game text says
    otherwise: UNVERIFIED)."""
    own = sum(ENERGY_CAPACITY_SUPPORTS.get(n, 0.0) for n in supports)
    wide = inputs.total("InvocationMaxEnergy") if inputs is not None else 0.0
    flat = QUALITY_MAX_ENERGY.get(meta, 0.0) * max(0.0, quality)
    pct = own + wide
    cap = max(0.0, (INVOCATION_MAX_ENERGY + flat) * (1 + pct / 100))
    parts = (([f"+{flat:g} from its {quality:g}% quality"] if flat else [])
             + ([f"Energy Capacitor {own:+g}%"] if own else [])
             + ([f"Invocated skills {wide:+g}% (passives, items)"] if wide else []))
    return cap, (f" ({INVOCATION_MAX_ENERGY} base, {', '.join(parts)}"
                 + (" increased Maximum Energy" if pct else "") + ")" if parts else "")
DODGE_ROLL_METRES = 4.6  # dodge_roll_base_travel_distance 46 units (game files, build 26476662); distance mods not counted
DODGE_EVERY = 2.0  # seconds between dodge rolls against a boss: the user's default (7 Nov 2026), said in the guide
DODGE_ROLL_SECONDS = 0.75  # DodgeRollPlayer's cast time, 750 ms (game files); movement speed doesn't shorten it (RESEARCH 18w)
# The build's own roll (MECHB3, COVD4 / FIX_QUEUE "Dodge roll and movement speed"): flat distance lines add to
# dodge_roll_base_travel_distance (10 units a metre): "+1 metre to Dodge Roll distance" (Surefooted Sigil, Amanamu boots,
# time-influenced boots, Rune of Acrobatics +0.3), Lioneye's Glare's "+2 metres ... if you haven't Dodge Rolled Recently"
# and "-1 metre ... if you've Dodge Rolled Recently" (dodge_roll_travel_distance_+_if_(not_)dodge_rolled_recently; a
# build that rolls every DODGE_EVERY s has always rolled within RECENTLY's 4 s, so only the -1 m holds), Tactical Retreat's
# "+0.5 metres ... while Surrounded" (Surrounded: "at least 5 enemies within 3 metres", KeywordPopups; one unique,
# UniqueLessEnemiesToBeSurrounded1, "Require 2-4 fewer enemies": at 4 fewer one enemy is enough, so the line counts there
# while you stay within 3 m of the boss, a play condition). (checked: the game tables' Stats with dodge_roll and distance
# or speed in their ids; Mods, PassiveSkills, SoulCoreStats, GrantedEffectStatSets(PerLevel) and GrantedEffectQuality-
# Stats for them; PoB ModCache: none of these lines is applied, all leave text; the Sanctum-only map_player_ stat is left
# out, a Sanctum relic.) Distance scales with movement speed, in the same 0.75 s (MEDIUM: RESEARCH26 R26-44 (b),
# poe2wiki and Mobalytics, 0.5.4e fits; RESEARCH 18w had community sources only). "X% faster
# Dodge Roll" (dodge_roll_speed_+%, one unique) shortens the roll's 0.75 s (assumed: time / (1 + X%), LOW); it doesn't
# change the distance. Cast on Dodge's alternate quality (cast_on_dodge_dodge_roll_distance_granted_+, +0.05 m a quality)
# isn't read: the builder sets no alternate qualities.
DODGE_DISTANCE = re.compile(r"^([+-]?\d+(?:\.\d+)?) metres? to Dodge Roll distance(?: (.+))?$", re.I)
DODGE_SPEED = re.compile(r"^(\d+(?:\.\d+)?)% (faster|slower) Dodge Roll$", re.I)
FEWER_TO_BE_SURROUNDED = re.compile(r"^Require (\d+) fewer enemies to be Surrounded$", re.I)
SURROUNDED_NEEDS = 5  # KeywordPopups Surrounded: "at least 5 enemies within 3 metres of you"


def dodge_roll(texts: list[str], stats: dict) -> dict:
    """The build's own dodge roll against a lone boss, rolling every DODGE_EVERY s: {"metres", "base_metres" (before
    movement speed), "seconds" (the roll's time), "basis"}."""
    flat, used, skipped = 0.0, [], []
    fewer = sum(float(m.group(1)) for t in texts if (m := FEWER_TO_BE_SURROUNDED.match(t.strip())))
    surrounded = SURROUNDED_NEEDS - fewer <= 1
    faster = 0.0
    for text in texts:
        text = text.strip()
        if m := DODGE_SPEED.match(text):
            faster += float(m.group(1)) * (1 if m.group(2).lower() == "faster" else -1)
            used.append(text)
            continue
        m = DODGE_DISTANCE.match(text)
        if not m:
            continue
        when = (m.group(2) or "").lower()
        if not when or ("dodge rolled recently" in when and "haven't" not in when and "not" not in when.split()):
            flat += float(m.group(1))
            used.append(text)
        elif "while surrounded" in when and surrounded:
            flat += float(m.group(1))
            used.append(f"{text} (one enemy is enough with \"Require {fewer:g} fewer enemies\": "
                                                    "within 3 m of the boss, a play condition)")
        else:
            skipped.append(text + (" (a lone boss doesn't Surround you: 5 enemies within 3 m)" if "surrounded" in when
                                   else (" (you roll every %g s, so you have always rolled recently: each roll has another in "
                                         "the 4 s before it, so it never holds when you roll; it would on rolls 4 s or "
                                         "more apart, which no "
                                         "reader of the roll models: MECH89)") % DODGE_EVERY
                                   if "haven't" in when else " (condition not read)"))
    base = max(DODGE_ROLL_METRES + flat, 0.0)
    speed = number(stats.get("MovementSpeedMod")) or 1.0
    seconds = DODGE_ROLL_SECONDS / max(1 + faster / 100, 0.1)
    basis = (f"{base:g} m a roll ({DODGE_ROLL_METRES:g} m base"
             + (f"; {'; '.join(used)}" if used else "") + (f"; not counted: {'; '.join(skipped)}" if skipped else "")
             + f"), x{speed:g} movement speed = {base * speed:.2f} m (rolls scaling with movement speed in the same "
               "0.75 s: MEDIUM, RESEARCH26 R26-44 (b))" + (f"; each roll takes {seconds:.3g} s" if faster else ""))
    return {"metres": base * speed, "base_metres": base, "seconds": seconds, "basis": basis}
NO_ENERGY_ON_A_BOSS: dict[str, str] = {}  # (Reaper's Invocation left it in MECHB9: it reads the boss's add kills)
# Skills whose own use can't feed a meta skill's Energy: base_skill_cannot_generate_energy, "This Skill cannot cause Meta
# Skills to generate Energy" (active_skill_gem_stat_descriptions). (checked, MECH47: the game tables' GrantedEffectStatSets
# carry the stat on MidnightStarPlayer alone and GrantedEffectStatSetsPerLevel on none; PoB's Skills/other.lua has it in
# Midnight Zenith's two stat sets alone; poe2db not checked.) Only the gains the main skill's own use makes are zeroed;
# Energy from blocks, dodges, Energy Shield lost or minion deaths still counts.
CANNOT_GENERATE_ENERGY = {"Midnight Zenith"}
OWN_USE_GAINS = ("crit", "ailment", "melee hit", "cast")
# Your minions' deaths against a boss (MECH45, FIX_QUEUE; the user, 11 Nov 2026: "that's a dangerous assumption ... needs
# to be smarter than just making a flat assumption"; CLAUDE.md "No flat rates"). Game files, KeywordPopups MinionDeath:
# "Minions whose durations expire or that are despawned by the player are considered to have died. However, effects that
# state they trigger when a Minion is Killed do not trigger in these cases. Minions are only Killed if they reach 0 life,
# though this can be caused by their summoner as well as enemies." Cast on Minion Death gains Energy "when one of your
# Persistent Minions is Killed" (its ActiveSkills description), so neither expiring temporary minions nor despawns feed
# it; Grim Feast stores Life when "your Reviving Minions" die (its description). Reviving (KeywordPopups): they "revive
# after a short delay when killed. This delay is reset whenever another Reviving Minion dies": the delay T is each skill's
# own base (12 s on most summon skills) or 7.5 s, over the revival speed (revive_seconds, below; LOW). With N such minions
# and kills at r per second, the deaths run in waves: N killed in N / r s, then all revive T after the last, so the
# sustained rate is N r / (N + T r).
# The build's own sources counted (each at its real use rate):
#  - Sacrifice (its description: "your undead Reviving Minions can be used in place of Corpses by your skills"): a main skill
#    that consumes corpses (the corpse_model's skill types) uses one minion per use (one corpse per use assumed; that a
#    minion used as a corpse is Killed, reaching 0 life, is UNVERIFIED: LOW);
#  - Explosive Demise, Skeletal Arsonists' Command ("Detonate an allied Minion whose current Life is below a threshold"):
#    one minion per use, on its 3 s cooldown (PoB's minion.lua and the game files) x cooldown recovery, when the build has
#    another minion to detonate (that one is below the threshold when the Command comes up is assumed: LOW).
#  - Minion Pact I / II (AUDIT23 A23-2, MECHB11): its skill "remove[s] 100% (150%) of your maximum Life from a nearby
#    Minion on use" (support_minion_pact_user_life_%_removed_from_nearby_minion; game files SupportMinionPactPlayer /
#    PlayerTwo; PoB's sup_int.lua, which reads only its 30% / 35% more damage, with a minion in your Presence). Removing
#    Life is Sacrificing it ("Sacrifices you cause on others (such as Sacrificing Minion Life) can lead to their death",
#    KeywordPopups Sacrifice) and a minion brought to 0 Life by its summoner is Killed (KeywordPopups MinionDeath). Counted:
#    one minion Killed per ceil(its Life / Life removed) uses of the main skill it supports (PoB's Speed): pact_uses_per_kill
#    (AUDIT25 A25-2, MECHB12: before, one per use whatever the minion's Life, an overcount); the "without it" rate is in
#    the note.
# Not counted (labelled): Dark Pact ("Sacrifices 13% of Minion's life", skeletal_chains_aoe_%_health_dealt_as_chaos_damage
# 13 at level 20) and Abyssal Pact (20%, ..._as_physical_damage): PoB has no skill for them, so the build has no use rate
# to read (no source, so 0); "13% of life" is taken as of maximum Life (ASSUMED, MEDIUM, RESEARCH26 R26-77: Abyssal
# Pact's text "of a damageable Minion's maximum life"; Sacrifice "can lead to their death"): ~8 / 5 uses kill a minion
# (of current Life it would never bring one to 0). The boss killing your minions (their Life and defences against
# the boss preset's hits), Offerings (the skeleton becomes the spike: whether it's Killed is UNVERIFIED, not counted),
# minions taking damage for you, other on-minion-death lines.
RESUMMON_SECONDS = 7.5  # global_resummon_time_ms (PoB Misc.lua)
EXPLOSIVE_DEMISE_COOLDOWN = 3.0  # s (PoB minion.lua:815 levels; game files)
SACRIFICE = "Sacrifice"
ARSONIST = "Skeletal Arsonist Minion"
MINION_PACT_STAT = "support_minion_pact_user_life_%_removed_from_nearby_minion"

# Umbilicus Immortalis (MECHB39; an OVERCOUNT before: the build's own minion Kills counted while its minions couldn't
# die). The belt's lines: "Your Life Flask also applies to your Minions" (your_life_flasks_also_apply_to_your_minions,
# UniqueLifeFlasksApplyToMinions1) and "Minions cannot Die while affected by a Life Flask"
# (minions_cannot_die_while_affected_by_life_flask, MinionsCannotDieWhileAffectedByYourLifeFlasks1). (checked: game files
# 26650308, Stats ids with cannot_die / immortal / flask+minion, every Mods row, PassiveSkills and GrantedEffectStatSets(
# PerLevel) stat columns: the cannot-die line is on that one item mod and no passive or skill; PoB's uniques list: only
# Umbilicus Immortalis carries either line; patch-notes archive --history "Umbilicus": no hit, which is not evidence of
# absence.) KeywordPopups MinionDeath: "Minions are only Killed if they reach 0 life"; Sacrifice: Sacrificing a
# minion's Life "can lead to their death". So Minion Pact (Life removed from a minion) Kills none while the flask is up:
# its Kills x (1 - the Life flask's uptime, flasks.uptime with the belt's reduced Flask Effect Duration and the
# Life-full cap) (MEDIUM: the minions' copy taken to last as long as yours; whether it ends at the minion's own full
# Life is UNVERIFIED). Sacrifice's consumption (a living minion used as a corpse, R26-68), Explosive Demise's detonation
# and Offerings' skewering don't go through 0 Life in their texts: whether "cannot Die" stops them is UNVERIFIED, so
# they stay counted (CLAUDE.md: never cut on an unverified reading), with the cut reading in the note. Assumptions.models
# sets the stats key from the equipped items (build.minion_deathless); 0 without the line or a Life flask.
MINION_DEATHLESS = re.compile(r"(?i)minions cannot die while affected by a life flask")
MINION_DEATHLESS_STAT = "_minion_deathless"  # stats key: (share of the fight your minions can't die, how)
FORCED_REVIVES_STAT = "_forced_revives"  # stats key: (fallen minions brought back a second, parts): forced_revives (MECHB40)


def minion_deathless(raws: list[str], life_flask_up: float | None) -> tuple[float, str]:
    """(share of the fight your minions cannot die, how): Umbilicus Immortalis' line while your Life flask is up.
    `raws`: the equipped items' texts; `life_flask_up`: the Life flask's uptime (flasks.uptime), None without one."""
    if not any(MINION_DEATHLESS.search(r or "") for r in raws):
        return 0.0, ""
    if not life_flask_up or life_flask_up <= 0:
        return 0.0, ("\"Minions cannot Die while affected by a Life Flask\": no Life flask up in this build, so it "
                     "stops no death (0)")
    share = min(1.0, life_flask_up)
    return share, (f"\"Minions cannot Die while affected by a Life Flask\" (Umbilicus Immortalis, with \"Your Life Flask "
                   f"also applies to your Minions\"): your Life flask is up {share:.0%} of the fight (its charges, "
                   "duration and the Life-full end), and your minions can't be Killed then (MEDIUM: their copy taken "
                   "to last as long as yours; whether it ends at the minion's own full Life is UNVERIFIED)")


# How many uses of Minion Pact Kill one minion (AUDIT25 A25-2, MECHB12; an OVERCOUNT before: one per use whatever the
# minion's Life). Each use removes p% of YOUR maximum Life (stats "Life") from a nearby minion; it dies when the removals
# reach its maximum Life (PoB's env.minion Life, which the bridge's useRates reports per minion group: stats
# "_minion_lives", {skill: Life}, filled by Assumptions.models). So uses per kill = ceil(minion Life / removed). Taken: the
# build's lowest-Life Reviving minion (a player feeding Minion Pact keeps its weakest minions near; which minion the gem
# picks is UNVERIFIED), uses landing on the same minion until it dies, and no regeneration or recovery in between (an
# overcount where minions regenerate fast, small at Minion Pact's use rates; Energy Shield doesn't shield Life removal:
# UNVERIFIED, not added). No Life read for any minion: 0 Kills, with a note (CLAUDE.md: no flat guess).
def pact_uses_per_kill(reviving: list[Skill], pact: float, stats: dict) -> tuple[float, str]:
    lives = stats.get("_minion_lives") or {}
    found = {s.name: number(lives.get(s.name)) for s in reviving if number(lives.get(s.name)) > 0}
    removed = number(stats.get("Life")) * pact / 100
    if not found or removed <= 0:
        return 0.0, ("no minion's Life or your maximum Life was read, so no Kills are counted (0, a note: not a flat "
                     "guess)")
    name, life = min(found.items(), key=lambda kv: kv[1])
    per_kill = float(math.ceil(life / removed - 1e-9))
    return per_kill, (f"it removes {removed:,.0f} Life a use; your weakest Reviving minion ({name}) has {life:,.0f}, so "
                      f"one dies every {per_kill:g} use{'s' if per_kill != 1 else ''} (MEDIUM: the same minion until it "
                      "dies, no regeneration between uses; which minion the gem picks is UNVERIFIED)")


def own_uses(main: Skill | None, stats: dict) -> tuple[float, str]:
    """(uses per second, how) the main skill feeds minion_deaths' sources. For a corpse-using main skill, PoB's Speed is
    corpse_model's own triggerRate (the corpse supply), so reading it back would shrink Sacrifice's supply to 0 at every
    resolve (MECHB20, MECHC15's silent 0 on a real Detonate Dead + Sacrifice build): its base cast time instead, without
    your cast speed (an undercount, labelled)."""
    if main is not None and main.corpses and main.cast_time > 0:
        return 1.0 / main.cast_time, f"its base {main.cast_time:g} s cast, without cast speed (an undercount)"
    return number(stats.get("Speed")), "PoB's Speed"


def minion_deaths(skills: list[Skill], main: Skill | None, stats: dict,
                  sacrifice_only: bool = False) -> tuple[float, str]:
    """Your Persistent, Reviving minions Killed per second against a boss, from the build's own sources (see above), capped
    by their revival (N r / (N + revive r: revive_seconds)), and how. 0 with a note when nothing in the build kills them.
    `sacrifice_only` (MECHB33, R26-68): only the deaths that are the corpse skill's own uses with Sacrifice, their share
    of the capped total (the other sources still take minions off the field)."""
    names = {s.name for s in skills}
    reviving = [s for s in skills if s.summon and s.summon.get("persistent") and not number(s.summon.get("duration"))]
    count = sum(number(s.summon.get("limit")) for s in reviving)
    if count <= 0:
        return 0.0, "the build has no Persistent minions to be Killed (temporary minions expiring aren't Killed)"
    kills, parts, sacrificed = 0.0, [], 0.0
    if SACRIFICE in names and main is not None and main.corpses:
        undead = sum(number(s.summon.get("limit")) for s in reviving if s.summon.get("undead"))
        uses, source = own_uses(main, stats)
        if undead > 0 and uses > 0:
            kills += uses
            sacrificed = uses
            parts.append(f"Sacrifice: {main.name} uses one of your {undead:g} living undead minions as its corpse each use "
                         f"({uses:.2f} uses/s, {source}; one corpse per use; RESEARCH26 R26-68: a living minion, consumed, "
                         "that revives later, MEDIUM-HIGH)")
    pact = number(main.support_stats.get(MINION_PACT_STAT)) if main is not None else 0.0
    if pact > 0 and number(stats.get("Speed")) > 0:
        uses = number(stats.get("Speed"))
        without = kills
        per_kill, how = pact_uses_per_kill(reviving, pact, stats)
        guarded = ""
        if per_kill > 0:
            pact_kills = uses / per_kill
            guard, guard_how = stats.get(MINION_DEATHLESS_STAT) or (0.0, "")
            if guard > 0:  # (MECHB39: Umbilicus Immortalis, no Kill through 0 Life while the Life flask is up)
                guarded = (f"; {guard_how}: {pact_kills:.3f} -> {pact_kills * (1 - guard):.3f} Kills/s from it "
                           f"(without the line: {pact_kills:.3f})")
                pact_kills *= 1 - guard
            kills += pact_kills
        parts.append(f"Minion Pact: each use of {main.name} removes {pact:g}% of your maximum Life from a nearby minion "
                     f"({uses:.2f} uses/s; KeywordPopups Sacrifice / MinionDeath: a minion its summoner brings to 0 Life is "
                     f"Killed): {how}{guarded}. Without it: {without:.2f} deaths/s from the other sources before revival")
    arsonist = next((s for s in skills if s.name == ARSONIST), None)
    if arsonist is not None and count > number(arsonist.summon.get("limit")):
        every = EXPLOSIVE_DEMISE_COOLDOWN / (arsonist.cooldown_recovery or 1.0)
        kills += 1 / every
        parts.append(f"Explosive Demise (your Skeletal Arsonists' Command) detonates one of your other minions every "
                     f"{every:.2f} s (its {EXPLOSIVE_DEMISE_COOLDOWN:g} s cooldown; that one is below its Life threshold "
                     f"when the Command comes up is assumed, LOW)")
    not_counted = ("not counted yet: the boss killing your minions, minions taking damage for you, Offerings (an "
                   "undercount); Dark Pact / Abyssal Pact (13% / 20% of a minion's Life a use) have no skill in PoB, so no "
                   "use rate here")
    guard, guard_how = stats.get(MINION_DEATHLESS_STAT) or (0.0, "")
    others = [n for n, p in ((SACRIFICE, "Sacrifice"), ("Explosive Demise", "Explosive Demise"))
              if any(x.startswith(p) for x in parts)]
    if guard > 0 and others:  # (MECHB39: their deaths don't go through 0 Life in the texts: UNVERIFIED, kept)
        not_counted += (f"; Umbilicus Immortalis' \"Minions cannot Die while affected by a Life Flask\" (your Life flask up "
                        f"{guard:.0%} of the fight) is taken not to stop {' / '.join(others)} (a consumption or "
                        "detonation, not 0 Life: UNVERIFIED); if it does, their deaths x"
                        f"{1 - guard:.2f}")
    if kills <= 0:
        return 0.0, f"nothing in this build kills its minions ({'; '.join(parts + [not_counted])})"
    revive, how = revive_seconds(reviving)
    # (MECHB40: forced revives bring fallen minions back at once, so more are alive to be killed: the alive share
    # 1 - (deaths - forced) T / N, deaths = kills x that share, at most kills)
    forced, forced_parts = stats.get(FORCED_REVIVES_STAT) or (0.0, [])
    excess, excess_how = cleric_excess(skills, reviving, kills)  # (MECHB42, R33-15: Clerics revive Skeletons only)
    forced = max(0.0, number(forced) - excess)
    forced_parts = list(forced_parts) + ([excess_how] if excess_how else [])
    rate = min(kills, kills * (count + forced * revive) / (count + revive * kills))
    if forced > 0:
        how += f"; forced revives {forced:.2f}/s ({'; '.join(forced_parts)}) bring fallen ones back sooner"
    defaults = [s.name for s in reviving if s.summon.get("limitFrom") == "default"]
    if defaults:  # (AUDIT29 A29-2: no count stat in the game files or PoB)
        how += (f"; {', '.join(defaults)}: one minion each (no count stat in the game files or PoB; UNVERIFIED, an "
                "undercount if a gem summons more)")
    if sacrifice_only:
        undead = sum(number(s.summon.get("limit")) for s in reviving if s.summon.get("undead"))
        cap = undead * sacrificed / (undead + revive * sacrificed) if sacrificed > 0 else 0.0  # (only undead ones used)
        used = min(rate * sacrificed / kills, cap)
        others = [p for p in parts if not p.startswith("Sacrifice")]
        return used, (f"{used:.3f} corpses a second: " + "; ".join(p for p in parts if p.startswith("Sacrifice"))
                      + f", capped by the {undead:g} undead minions' revival and their share of all {rate:.3f} deaths a "
                      "second" + (f" (the others leave no corpse: {'; '.join(others)})" if others else "")
                      + f"; each revives {revive:.3g} s after the last death ({how})")
    return rate, (f"{rate:.3f} of your {count:g} Reviving minions Killed per second: " + "; ".join(parts)
                  + f"; each revives {revive:.3g} s after the last death (KeywordPopups Reviving: the delay "
                    f"resets on each death; {how}), so {count:g} x {kills:.2f} / ({count:g} + {revive:.3g} x {kills:.2f}); "
                  + not_counted)


# Revival time (MECHB2; FIX_QUEUE: Sacrifice makes revival 40% slower, AUDIT5). PoB works it out per Reviving minion skill
# (CalcOffence 1616: base / MinionRevivalSpeed): Sacrifice's harvester_minion_resummon_speed_+%_final (-40% at level 20, a
# MORE buff) and "Minions Revive N% faster" lines are in its MinionRevivalSpeed, which the bridge reports.
# The base (MECHB5, AUDIT15 A15-2 / A15-3): each skill's own minion_base_resummon_time_ms (12 s on 17 player summon skills:
# skeletons, spectres, companions...; PoB's BaseReviveTime override, CalcOffence 1616, which the bridge reports as
# reviveBase) where the skill carries it, else the game constant global_resummon_time_ms 7.5 s (PoB Misc.lua; the
# Infernal Hound and the three djinns carry no 12 s, A15-3). The sources disagree (the 0.2.0e notes: each later death
# adds less, capped at 7.5 s), so 7.5 s goes beside it in the note: LOW until in-game test #21 settles it. A longer
# revival means fewer deaths (Cast on Minion Death, Grim Feast): with 12 s, up to 1.6x fewer than at 7.5 s.
# (checked: the game's GrantedEffectStatSets carry it at 12000 on 17 player sets (8 here are monsters'); PoB's Data/Skills on
# 14 of them; the other three, DemonMagusPlayer, SoulCrystalPlayer and SummonMercenaryCompanionPlayer, aren't PoB skills.)
def revive_seconds(reviving: list[Skill]) -> tuple[float, str]:
    """Seconds a Reviving minion takes to revive: the count-weighted mean over the build's Reviving minion skills of their
    own base (reviveBase, else RESUMMON_SECONDS) over PoB's MinionRevivalSpeed, and how."""
    rows = [(number(s.summon.get("limit")), number(s.summon.get("reviveBase")) or RESUMMON_SECONDS,
             number(s.summon.get("reviveSpeed")) or 1.0) for s in reviving]
    total = sum(w for w, _, _ in rows)
    if total <= 0:
        rows, total = [(1.0, RESUMMON_SECONDS, 1.0)], 1.0
    # (MECHB33; RESEARCH26 R26-12, cast-on-minion-death-power-r26.md: Mark_GGG, forum 3788466, 9 Jun 2025, minions revive
    # at "12.5% (1/8th) of a revive per second"; a player timed 8 s, a Feb 2025 thread 8 s, nobody reports 12 s. So the
    # game constant 7.5 s is the headline (MEDIUM), the skills' own 12 s base the other row.)
    own = sum(w * b / v for w, b, v in rows) / total
    seconds = sum(w * RESUMMON_SECONDS / v for w, _, v in rows) / total
    base = sum(w * b for w, b, _ in rows) / total
    speed = RESUMMON_SECONDS / seconds if seconds else 1.0
    if abs(base - RESUMMON_SECONDS) > 1e-6:
        bases = (f"base {RESUMMON_SECONDS:g} s, the game constant (MEDIUM: a GGG staff post, 9 Jun 2025, \"12.5% (1/8th) "
                 f"of a revive per second\", and players' ~8 s timings); with the skills' own minion_base_resummon_time_ms "
                 f"({base:.3g} s, PoB's BaseReviveTime) instead: {own:.3g} s, fewer deaths")
    else:
        bases = (f"base {RESUMMON_SECONDS:g} s, the game constant (MEDIUM: a GGG staff post, 9 Jun 2025, ~8 s; the skills "
                 "carry no base of their own)")
    if abs(speed - 1.0) < 1e-6:
        return seconds, bases
    return seconds, (f"{bases}; revival speed x{speed:.2f} (PoB's MinionRevivalSpeed: Sacrifice's 40% slower at level "
                     f"20, Revive-faster lines), {seconds:.3g} s")


# Fallen Skeletons and Death Storm (MECHB20, for MECH-A's Shocked Ground: MECH61 / MECH62, AUDIT26 A26-2). Death Storm
# is the Skeletal Storm Mages' Command (ActiveSkills death_storm: "Lightning bolts strike all fallen Skeletons in the area,
# creating [ShockedGround|Shocked Ground] around them"; GrantedEffects DeathStormSkeletonStormMageMinion: cast time 2 s,
# GrantedEffectsPerLevel Cooldown 5000 ms; its stat set: is_commandable_skill, area radius 20 and secondary radius 20
# (2 m), base_skill_effect_duration 6000; checked: game files; second source research/shocked-ground-sources.md, AUDIT26
# A26-2 confirmed these numbers). A "fallen" Skeleton is taken to be a Reviving Skeleton lying dead while it waits to
# revive (the text doesn't define it: UNVERIFIED, LOW; a Temporary Skeleton expiring isn't counted).
# Which minions are Skeletons: the skill type CreatesSkeletonMinion (ActiveSkillType 125; PoB SkillType 126, the bridge's
# summon.skeleton), else "Skelet" in the skill's name (the game's ten: Summon Skeletons, Revive Skeleton and the eight
# Skeletal X Minion skills; checked: ActiveSkills DisplayedName, ActiveSkillType).
# The rate: models.minion_deaths' Reviving minions Killed per second, from the build's own sources (Sacrifice, Minion Pact,
# Explosive Demise; no source: 0 with a note, CLAUDE.md), shared over the Reviving minions by count (the Skeletons' share:
# deaths taken as spread evenly, LOW; Sacrifice uses only undead minions, so it's a little more for Skeletons). Each lies
# fallen for the revival time (revive_seconds), so the mean number fallen at a moment is rate x revive (Little's law;
# with deaths at random times the number is Poisson, so a press finds at least one with 1 - e^-mean; capped by the
# Skeletons there are). Not counted (labelled): the boss killing your Skeletons (an undercount), where the Skeletons fall
# (melee ones at the boss, ranged ones and Minion Pact's "nearby" minions further off: MECH-A's ground reads the area),
# and a player timing the press just after a kill (more fallen than the mean).
SKELETON_NAME = "Skelet"
STORM_MAGE = "Skeletal Storm Mage Minion"
DEATH_STORM = "Death Storm"
DEATH_STORM_COOLDOWN = 5.0  # s (GrantedEffectsPerLevel DeathStormSkeletonStormMageMinion Cooldown 5000)
DEATH_STORM_SECONDS = 6.0  # its Shocked Ground's duration (base_skill_effect_duration 6000)
DEATH_STORM_RADIUS = 2.0  # m (active_skill_base_secondary_area_of_effect_radius 20)
DEATH_STORM_CAST = 2.0  # s (GrantedEffects CastTime 2000: the Storm Mage's own cast, a floor under the cooldown)


def is_skeleton(skill: Skill) -> bool:
    """Whether a minion skill's minions are Skeletons (the bridge's summon.skeleton, else the name)."""
    summon = skill.summon or {}
    if "skeleton" in summon:
        return bool(summon["skeleton"])
    return SKELETON_NAME in skill.name


def fallen_skeletons(skills: list[Skill], main: Skill | None, stats: dict) -> tuple[float, float, str]:
    """(mean Reviving Skeletons lying fallen at a moment, Skeletons Killed per second, how), from minion_deaths' rate."""
    reviving = [s for s in skills if s.summon and s.summon.get("persistent") and not number(s.summon.get("duration"))]
    skeletons = [s for s in reviving if is_skeleton(s)]
    count = sum(number(s.summon.get("limit")) for s in reviving)
    bones = sum(number(s.summon.get("limit")) for s in skeletons)
    if bones <= 0:
        return 0.0, 0.0, "the build has no Reviving Skeletons to fall (0)"
    killed, how = minion_deaths(skills, main, stats)
    if killed <= 0:
        return 0.0, 0.0, f"no Skeleton falls: {how}"
    revive, _ = revive_seconds(reviving)
    rate = killed * bones / count
    fallen = min(rate * revive, bones)
    return fallen, rate, (f"{rate:.3f} of your {bones:g} Reviving Skeletons Killed per second ({bones:g} of {count:g} "
                          f"Reviving minions: deaths spread evenly, LOW), each fallen {revive:.3g} s until it revives, "
                          f"so {fallen:.2f} fallen at a moment on average (deaths: {how})")


def death_storm(skills: list[Skill], main: Skill | None, stats: dict) -> tuple[float, float, float, str]:
    """Death Storm, the Skeletal Storm Mages' Command: (uses per second, mean fallen Skeletons struck a use, the share of
    uses that find at least one, how). Each struck Skeleton makes DEATH_STORM_RADIUS m of Shocked Ground for
    DEATH_STORM_SECONDS s (MECH-A's shocked_ground places it). 0 with a note without Storm Mages or fallen Skeletons."""
    mage = next((s for s in skills if s.name == STORM_MAGE), None)
    if mage is None:
        return 0.0, 0.0, 0.0, "no Skeletal Storm Mages, so no Death Storm"
    every = max(DEATH_STORM_COOLDOWN / (mage.cooldown_recovery or 1.0), DEATH_STORM_CAST)
    fallen, rate, how = fallen_skeletons(skills, main, stats)
    if fallen <= 0:
        return 0.0, 0.0, 0.0, f"Death Storm strikes fallen Skeletons, and none fall: {how} (0, not a flat guess)"
    mages = number(mage.summon.get("limit")) if mage.summon else 0.0
    bones = sum(number(s.summon.get("limit")) for s in skills if s.summon and s.summon.get("persistent")
                and not number(s.summon.get("duration")) and is_skeleton(s))
    # a Command needs a living Storm Mage: all of them fallen at once, taken as independent, is (fallen / Skeletons)^mages
    down = (fallen / bones) ** mages if bones > 0 and mages > 0 else 0.0
    uses = (1.0 - down) / every if every > 0 else 0.0
    some = 1.0 - math.exp(-fallen)
    return uses, fallen, some, (
        f"Death Storm (a Command: one press every {every:.3g} s, its {DEATH_STORM_COOLDOWN:g} s cooldown over your "
        f"Cooldown Recovery; a press under the button cap) strikes each fallen Skeleton in its 2 m area: {fallen:.2f} on "
        f"average, at least one on {some:.0%} of presses (deaths at random times: Poisson; a press timed just after a "
        f"kill finds more); {down:.1%} of presses lost to every Storm Mage being fallen; {how}. Not counted: the boss "
        "killing your Skeletons (an undercount), where they fall (MECH-A's ground reads the area, LOW)")


# Shattering Roar (MECHB30, PATCH_CHECK H4-1), the Skeletal Brutes' Command: "Command a Skeletal Brute to use a Warcry,
# Intimidating nearby enemies and Consuming Freeze ..." (ActiveSkills brute_warcry; a Command since 0.3.0, and it
# Intimidates only since 0.5.2's fix: "did not intimidate enemies", the newest entry, patch-notes archive --history).
# Game files (26476662): GrantedEffects ShatteringRoarSkeletalBruteMinion CastTime 1000 ms; GrantedEffectsPerLevel
# Cooldown 8000 ms, StoredUses 1; its stat set is_commandable_skill, base_skill_effect_duration 4000, area radius 40
# (4 m). Intimidate (KeywordPopups): "a Debuff that inflicts 10% increased damage taken and 10% reduced damage dealt"
# (PoB's conditionEnemyIntimidated: DamageTaken INC 10; MECH-A's debuff box wires this rate in).
# The rate: one Command press each time the cooldown is up (a play strategy under the button cap, shown with and without
# it in the play guide), over your Cooldown Recovery, the Brute's 1 s cast a floor. One Roar a cooldown however many
# Brutes you keep: whether a second press Commands another Brute whose cooldown is up is UNVERIFIED (the text says "a
# Skeletal Brute"), so the lower reading is used and the other (min(1, Brutes x 4 / 8)) is in the note. The Brutes are
# melee, so the boss is taken to be within the 4 m (MEDIUM). Presses lost while every Brute is fallen are taken off as
# death_storm does ((fallen / Skeletons)^Brutes). Not counted: the minion's own Skill Effect Duration modifiers (an
# undercount; the player's "increased Intimidate Duration" lines are counted through duration_scale).
SKELETAL_BRUTE = "Skeletal Brute"
SHATTERING_ROAR_COOLDOWN = 8.0  # s (GrantedEffectsPerLevel ShatteringRoarSkeletalBruteMinion Cooldown 8000)
SHATTERING_ROAR_SECONDS = 4.0  # its Intimidate's duration (base_skill_effect_duration 4000)
SHATTERING_ROAR_CAST = 1.0  # s (GrantedEffects CastTime 1000)


def shattering_roar(skills: list[Skill], main: Skill | None, stats: dict, texts: list[str] = ()) -> tuple[float, str]:
    """(share of the fight the boss is Intimidated by your Skeletal Brutes' Shattering Roar, how). 0 with a note without
    Brutes. MECH-A's Intimidated box reads it as one more source."""
    brute = next((s for s in skills if SKELETAL_BRUTE in s.name), None)
    if brute is None:
        return 0.0, "no Skeletal Brutes, so no Shattering Roar"
    brutes = number(brute.summon.get("limit")) if brute.summon else 0.0
    if brutes <= 0:
        return 0.0, "your Skeletal Brute skill keeps no Brutes up (0)"
    every = max(SHATTERING_ROAR_COOLDOWN / (brute.cooldown_recovery or 1.0), SHATTERING_ROAR_CAST)
    duration = SHATTERING_ROAR_SECONDS * duration_scale(list(texts), "Intimidate")
    fallen, _, fall_how = fallen_skeletons(skills, main, stats)
    bones = sum(number(s.summon.get("limit")) for s in skills if s.summon and s.summon.get("persistent")
                and not number(s.summon.get("duration")) and is_skeleton(s))
    down = (fallen / bones) ** brutes if bones > 0 and fallen > 0 else 0.0
    up = min(1.0, (1.0 - down) * duration / every)
    other = min(1.0, (1.0 - down) * brutes * duration / every)
    return up, (f"Shattering Roar (your Skeletal Brutes' Command: one press every {every:.3g} s, its "
                f"{SHATTERING_ROAR_COOLDOWN:g} s cooldown over your Cooldown Recovery; a press under the button cap) "
                f"Intimidates the boss for {duration:g} s: {up:.0%} of the fight"
                + (f", {down:.1%} of presses lost to every Brute being fallen ({fall_how})" if down > 0 else "")
                + (f". If each press Commands another Brute whose cooldown is up (UNVERIFIED), {brutes:g} Brutes give "
                   f"{other:.0%}" if other > up else "")
                + ". The Brutes are melee, so the boss is taken to be in its 4 m (MEDIUM); the minion's own Skill Effect "
                  "Duration isn't counted (an undercount)")


# Puppet Master (MECHB30, PATCH_CHECK H4-3). KeywordPopups PuppetMaster: "a stacking Buff which grants: 10% increased
# Skill Speed with Command Skills, 10% reduced Movement Speed Penalty with Command Skills, Minions deal 10% increased
# damage with Command Skills, Minions have 2% increased Movement Speed, Minions have 3% increased Skill Speed. Each stack
# has an independent duration of 8 seconds. Maximum 5 stacks." Its sources (game files 26476662, the stats
# surpassing_chance_%_to_gain_1_puppeteer_stack_on_using_command_skill, max_puppet_master_stacks_+,
# puppet_master_duration_+%, puppet_master_effect_+%): the tree's twenty "Puppet Master chance" passives (Puppetmaster1-20:
# 10-35% chance, +1 stack, 25% duration, 15-20% effect), the Delirium anoint Replenishing Horde (25%), the ring mod
# GenesisTreeRingMinionPuppetMaster (40-50%), the Kurgal staff suffix (+3-4 stacks, 0.5.3), the Verisium mods
# AlloyPuppetMasterChance1 / AlloyPuppeteerStacks1. PoB counts none of it: every Puppet Master line in its ModCache has
# leftover text (never applied) or none. Surpassing Chance (KeywordPopups SurpassChance): once per 100%, then the rest as
# a chance, so a use gives chance / 100 stacks on average.
# The rate: a build that takes Puppet Master presses its Commands to feed it (a play strategy, shown with and without
# it): each Command its minions have, on its own cooldown over your Cooldown Recovery (its cast a floor), the game's
# cooldowns below (GrantedEffectsPerLevel; the minion each comes from by its GrantedEffect id). Stacks held = uses/s x
# stacks a use x duration (independent durations: Little's law), capped at the maximum. No Command, or no chance line: 0
# with a note. Counted: the minions' 3% increased Skill Speed a stack (PoB's "Minions have N% increased Skill Speed",
# scaled by the effect lines). Not counted (labelled): the Command Skills' own 10% Skill Speed / minion damage (the
# Commands are scored apart, an undercount), the movement lines (no damage), presses lost while every minion of a kind
# is fallen, and the Commands of djinns (MECH-A's), Mirror Breaker, Mad Flight and Death From Above, whose minions this
# table doesn't map (an undercount), and Sandblast / Ruzhan's Brand (no cooldown: their rate is the presses, not modelled).
# Whether pressing a Command again while one minion's cooldown runs uses another minion: UNVERIFIED, so one use a
# cooldown per Command (the lower reading).
PUPPET_SECONDS = 8.0  # KeywordPopups PuppetMaster: "an independent duration of 8 seconds"
PUPPET_STACKS = 5  # "Maximum 5 stacks"
PUPPET_SKILL_SPEED = 3.0  # "Minions have 3% increased Skill Speed" a stack
COMMANDS = {  # minion skill (a substring of its name): [(Command, cooldown s, cast s)] (GrantedEffects / PerLevel 26476662)
    "Skeletal Reaver": [("Enrage", 4.0, 1.0)],
    "Skeletal Sniper": [("Gas Arrow", 6.0, 1.0)],
    "Skeletal Storm Mage": [(DEATH_STORM, DEATH_STORM_COOLDOWN, DEATH_STORM_CAST)],
    "Skeletal Arsonist": [("Explosive Demise", EXPLOSIVE_DEMISE_COOLDOWN, 1.0)],
    "Skeletal Frost Mage": [("Ice Bomb", 8.0, 1.25), ("Ice Armour", 12.0, 1.0)],
    SKELETAL_BRUTE: [("Shattering Roar", SHATTERING_ROAR_COOLDOWN, SHATTERING_ROAR_CAST)],
    "Azmerian Wolf": [("Eternal Hunt", 15.0, 4.0)],
}
PUPPET_CHANCE = re.compile(r"(\d+(?:\.\d+)?)% surpassing chance to gain a puppet master stack whenever you use a command "
                           r"skill", re.I)
PUPPET_MAX = re.compile(r"\+(\d+) maximum stacks? of puppet master", re.I)
PUPPET_DURATION = re.compile(r"(\d+(?:\.\d+)?)% (increased|reduced) duration of each puppet master stack", re.I)
PUPPET_EFFECT = re.compile(r"(\d+(?:\.\d+)?)% (increased|reduced) effect of puppet master", re.I)


def command_uses(skills: list[Skill]) -> tuple[float, list[str]]:
    """(Command uses a second with every Command of the build's minions pressed on its cooldown, the parts)."""
    total, parts, seen = 0.0, [], set()
    for skill in skills:
        if not skill.summon or not number(skill.summon.get("limit")):
            continue
        for minion, commands in COMMANDS.items():
            if minion not in skill.name or minion in seen:
                continue
            seen.add(minion)
            for name, cooldown, cast in commands:
                every = max(cooldown / (skill.cooldown_recovery or 1.0), cast)
                total += 1.0 / every
                parts.append(f"{name} every {every:.3g} s")
    return total, parts


# Different Command Skills used in the past 15 seconds (MECHB39; the coverage ranking's section C, an UNDERCOUNT: 0
# before). The Genesis Tree belt mod "N% increased Minion Damage per different Command Skill used in the past 15
# seconds" (minion_damage_+%_per_different_command_skills_used_in_last_15_seconds: GenesisTreeBeltMinionDamagePer
# DifferentCommandSkillUsedLast15Seconds and its Crafted copy; the Genesis Tree is core since 0.5.0): PoB's ModCache 1659
# reads it as a MinionModifier with leftover text and never applies it. (checked: game files 26650308, every Stats id
# holding "command", their Mods / PassiveSkills / GrantedEffectStatSets rows: those two belt mods are the only sources;
# Brequel's "Instructor's" reward node only raises the crafted chance.) The count, from the build (CLAUDE.md's no-flat-
# rate rule): a build that takes the line presses its minions' Commands (a play strategy, as puppet_master_model), each
# on its own cooldown over your Cooldown Recovery (COMMANDS, command_uses); a Command used at least every 15 s counts
# whole, a slower one at 15 / its period (the mean of the count: the damage is linear in it). Not counted (labelled):
# djinn Commands (MECH-A's) and the other Commands COMMANDS doesn't map (an undercount), presses lost while every
# minion of a kind is fallen (a small overcount for death-fed builds).
COMMAND_WINDOW = 15.0
DIFFERENT_COMMANDS = re.compile(r"^(\d+(?:\.\d+)?)% increased Minion Damage per different Command Skill used in the past "
                                r"15 seconds$", re.I)


# "Your Minions are Gigantic if they have Revived Recently" (MECHB39; the coverage ranking's section C, an UNDERCOUNT: 0
# before): the Genesis Tree belt mod GenesisTreeBeltMinionsGiganticRevivedRecently and its Crafted copy (stat
# minions_are_gigantic_if_have_revived_recently). (checked: game files 26650308, every Stats id holding "gigantic" or
# "revived", their Mods / PassiveSkills / GrantedEffectStatSets rows: those two belt mods are its only sources; the
# always-on "minions_are_gigantic" (Gigantic Following, Hulking Minions, an Essence) is a different stat PoB parses.)
# PoB's ModCache 9986 holds it with no mod at all. KeywordPopups Gigantic: "20% more Maximum Life, 20% more Damage and
# 20% increased size". The share of the minions' time alive that they've Revived Recently is revived_recently_share's
# (Crazed Minions' share: from the build's own minion Kills, minion_deaths; none: 0 with its note); 20% more Damage at
# that share ("Minions deal N% more Damage" on the whole minion pool: MEDIUM-LOW, the deaths taken as spread evenly).
# Not counted: the 20% more Life (a defence; no damage) and the size.
GIGANTIC_REVIVED = re.compile(r"^Your Minions are Gigantic if they have Revived Recently$", re.I)
GIGANTIC_MORE = 20.0  # KeywordPopups Gigantic: 20% more Damage


def gigantic_revived_model(texts: list[str], skills: list[Skill], main: Skill | None, stats: dict
                           ) -> tuple[list[dict], list[dict]]:
    """The belt's Gigantic minions at the share of their time they've Revived Recently (see above)."""
    if not any(GIGANTIC_REVIVED.match(t.strip()) for t in texts):
        return [], []
    reviving = [s for s in skills if s.summon and s.summon.get("persistent") and not number(s.summon.get("duration"))]
    if not reviving:
        share, how = 0.0, "the build has no Reviving minions"
    else:
        share, how, _ = revived_recently_share(reviving[0], {**stats, "_skills": skills}, main)
    more = GIGANTIC_MORE * share
    note = {"label": "Gigantic minions after Reviving (20% more Damage)*", "value": f"+{more:.1f}% more",
            "confidence": "MEDIUM-LOW",
            "basis": (f"\"Your Minions are Gigantic if they have Revived Recently\": Gigantic is 20% more Damage and Life "
                      f"(KeywordPopups); {how}. PoB holds the line with no mod (0 before). The 20% more Life isn't counted "
                      "(a defence)"),
            "play": (f"Keep your Reviving minions dying and reviving (Sacrifice, Minion Pact, Explosive Demise): without "
                     f"it +0%; with it +{more:.1f}% more Minion Damage" if more > 0 else
                     "Nothing in the build kills its own Reviving minions, so they never Revive: +0%")}
    return ([line("Minions deal 1% more Damage", more)] if more > 0 else []), [note]


def different_commands_model(skills: list[Skill], texts: list[str]) -> tuple[list[dict], list[dict]]:
    """The minions' damage per different Command used in the past 15 s, at the build's own Commands (see above)."""
    pct = sum(float(m.group(1)) for t in texts if (m := DIFFERENT_COMMANDS.search(t.strip())))
    if pct <= 0:
        return [], []
    count, parts, seen = 0.0, [], set()
    for skill in skills:
        if not skill.summon or not number(skill.summon.get("limit")):
            continue
        for minion, commands in COMMANDS.items():
            if minion not in skill.name or minion in seen:
                continue
            seen.add(minion)
            for name, cooldown, cast in commands:
                every = max(cooldown / (skill.cooldown_recovery or 1.0), cast)
                share = min(1.0, COMMAND_WINDOW / every)
                count += share
                parts.append(f"{name} every {every:.3g} s" + (f" ({share:.0%} of windows)" if share < 1 else ""))
    gain = pct * count
    note = {"label": "Minion Damage per different Command used in the past 15 s*", "value": f"+{gain:.0f}%",
            "confidence": "MEDIUM",
            "basis": (f"{pct:g}% a Command; {count:.2f} different Commands in any 15 s: "
                      + ("; ".join(parts) if parts else "the build's minions have no Command this model maps")
                      + ". Each pressed on its cooldown (a play strategy under the button cap). PoB reads the line with "
                      "leftover text and never applies it (0 before). Not counted: djinn Commands and Commands of minions "
                      "the table doesn't map (an undercount), presses lost while those minions are fallen"),
            "play": (f"Press each of your minions' Commands at least every 15 s: without them +0%; with them +{gain:.0f}% "
                     "Minion Damage" if gain > 0 else "No minion Command to press: +0%")}
    return ([line("Minions deal 1% increased Damage", gain)] if gain > 0 else []), [note]


def _summed(pattern: re.Pattern, texts: list[str], signed: bool = False) -> float:
    total = 0.0
    for text in texts:
        for m in pattern.finditer(text):
            total += float(m.group(1)) * (-1 if signed and m.group(2).lower() == "reduced" else 1)
    return total


def puppet_master_model(skills: list[Skill], texts: list[str]) -> tuple[list[dict], list[dict]]:
    """(mods, notes) for Puppet Master: the minions' Skill Speed at the stacks the build's Commands keep up."""
    chance = _summed(PUPPET_CHANCE, texts)
    if chance <= 0:
        return [], []
    uses, parts = command_uses(skills)
    label = "Puppet Master (stacks from your Commands)"
    if uses <= 0:
        return [], [{"label": label, "value": 0, "confidence": "MEDIUM",
                     "basis": f"{chance:g}% Surpassing Chance a Command, but no minion here has a Command this model "
                              "maps (djinns, Mirror Breaker, Mad Flight, Death From Above aren't mapped): 0, not a flat guess"}]
    most = PUPPET_STACKS + _summed(PUPPET_MAX, texts)
    duration = PUPPET_SECONDS * max(0.0, 1 + _summed(PUPPET_DURATION, texts, True) / 100)
    effect = max(0.0, 1 + _summed(PUPPET_EFFECT, texts, True) / 100)
    stacks = min(most, uses * chance / 100 * duration)
    speed = PUPPET_SKILL_SPEED * stacks * effect
    basis = (f"{uses:.3f} Command uses/s ({', '.join(parts)}: each pressed on its cooldown over your Cooldown Recovery, "
             f"one use a cooldown, UNVERIFIED for several minions) x {chance:g}% Surpassing Chance x {duration:g} s a "
             f"stack: {stacks:.2f} of {most:g} stacks held on average; x {PUPPET_SKILL_SPEED:g}% Skill Speed x "
             f"{effect:.2f} effect = Minions have {speed:.1f}% increased Skill Speed. Not counted: the Commands' own 10% "
             "Skill Speed and minion damage a stack, movement, presses lost while minions are fallen (labelled)")
    note = {"label": label, "value": round(speed, 2), "basis": basis, "confidence": "MEDIUM",
            "play": (f"Press your Commands on cooldown to keep Puppet Master up: with it {stacks:.1f} stacks (+{speed:.1f}% "
                     f"minion Skill Speed), without it 0")}
    return ([line("Minions have 1% increased Skill Speed", speed)] if speed > 0 else []), [note]


MINION_TYPES = {"Minion", "CreatesMinion"}


def minion_skill_names(groups: list[dict], gems: dict[str, dict]) -> list[str]:
    """The build's enabled skill gems that make minions (skill types Minion / CreatesMinion), for Cast on Minion Death."""
    return sorted({g["name"] for group in groups for g in group.get("gems") or []
                   if not g.get("support") and g.get("enabled", True) and g["name"] != "Cast on Minion Death"
                   and MINION_TYPES & set((gems.get(g["name"]) or {}).get("skillTypes") or [])})
# Gone from the game by two sources that agree (the rule for removing anything): the game files reach them by no source
# (data/game-*/live.json: no uncut tier, base item, passive, or collection unique grants them) and poe2db shows them
# with no tier or source; the user also found no Curse on Block in game (7 Nov). Never picked; a PoB code that has one
# gets no triggers from it, said in the guide.
DEPRECATED = {name: "removed from the game (the 0.5 game files and poe2db agree; deprecated)"
              for name in ("Curse on Block", "Cast on Melee Stun", "Cast on Melee Kill")}
NOT_MODELED_YET = {
    "Feral Invocation": "a clone uses its socketed Attacks (Energy cost per 10 ms of base attack time; 1 Energy per 20 Mana "
                        "spent): the Energy model prices triggered Spells only so far",
}
