GLORY_INSTANCE = {"Ancestral Cry": 8.0, "Apocalypse": 12.0, "Walking Calamity": 10.0, "Skyfall": 20.0,
                  "Starborn Onslaught": 8.0, "Hammer of the Gods": 2.5, "Archon of Chayula": 10.0, "Spear of Solaris": 4.0}
# (MECHC43, COV45's routed fix: Archon of Chayula's instance is the Archon itself, 10 s: the game's Archon keyword ("By
# default, each Archon Buff lasts 10 seconds", as ARCHON_DURATION) and poe2db's Archon of Chayula "Duration: 10"; the 8 s
# above was its tornado's. An OVERCOUNT of its uses before: one per 10 s + refill, not 8 s + refill)
MODEL_FIELDS.extend(f for f in (f"{h}{t}HitAverage" for h in ("MainHand.", "OffHand.") for t in DAMAGE_TYPES)
                    if f not in MODEL_FIELDS)  # (glory_events: an Attack's hits per hand)


def glory_events(stats: dict, main: Skill | None) -> dict[str, float]:
    """Glory-building events per second from the main skill on the boss."""
    hits = hits_per_second(stats)
    crit = min(number(stats.get("CritChance")), 100) / 100
    # (MECHC43, MECHB42 / COV45's routed UNDERCOUNT: PoB keeps an Attack's hits per hand, MainHand. / OffHand.
    # <type>HitAverage, and leaves the plain field empty, so an Attack's Chaos / elemental hits read none: Archon of
    # Chayula's and Apocalypse's Glory were 0 on every Attack build; either hand's hits count)
    hit = {t: max(number(stats.get(f"{p}{t}HitAverage")) for p in ("", "MainHand.", "OffHand.")) > 0
           for t in DAMAGE_TYPES}
    chance = lambda a: (number(stats.get(f"{a}ChanceOnHit")) * (1 - crit) + number(stats.get(f"{a}ChanceOnCrit")) * crit) / 100
    poison = min(chance("Poison"), 1.0)  # (MECHC56, R51-3: a Chaos damage over time Debuff feeds Chayula)
    return {
        "attack hit": hits if main is not None and main.attack else 0.0,
        "elemental hit": hits if any(hit[t] for t in ("Fire", "Cold", "Lightning")) else 0.0,
        "chaos hit": hits if hit["Chaos"] else hits * poison,
        "heavy stun": heavy_stun_rate(stats)[0],
        "freeze": buildup_rate(stats, "Freeze"),
        "ignite": hits * min(chance("Ignite"), 1.0),
        "shock": hits * min(chance("Shock"), 1.0),
        "chill": hits * _chill_chance(stats),  # (MECHC56: Starborn Onslaught, GLORY_STATED)
    }


def _chill_chance(stats: dict) -> float:
    """The chance a main-skill hit Chills the boss (conditions._chill_per_hit: PoB's ChillChanceOnHit, the 30% floor);
    0 when the stats don't carry the Chill fields."""
    if number(stats.get("ChillChanceOnHit")) <= 0:
        return 0.0
    from builder.search import conditions
    return conditions._chill_per_hit(stats)


def glory_row_events(row: dict) -> dict[str, float]:
    """(MECHC56, GLORY_ROWS' note) Glory events a second from one of the build's other skills' rows."""
    hits = max(0.0, number(row.get("hits")))
    types = set(row.get("types") or ())
    return {"attack hit": hits if row.get("attack") else 0.0,
            "elemental hit": hits if types & {"Fire", "Cold", "Lightning"} else 0.0,
            "chaos hit": hits if "Chaos" in types else hits * min(max(number(row.get("poison")), 0.0), 1.0),
            "ignite": hits * min(max(number(row.get("ignite")), 0.0), 1.0),
            "shock": hits * min(max(number(row.get("shock")), 0.0), 1.0),
            "chill": hits * min(max(number(row.get("chill")), 0.0), 1.0)}


MANA_FLARE = "Mana Flare"  # the support's triggered spell (game files: TriggeredManaFlarePlayer, GrantedEffects 734)
MANA_FLARE_SHARE = 0.25  # stat set 878: support_mana_flare_%_of_current_mana_consumed 25
MANA_FLARE_FIELDS = ["Speed", "HitChance", "CritChance", "ManaPerSecondCost", "ManaRegenRecovery", "Mana"]


def mana_flare(spell: dict, cooldown: float, recovery: float) -> tuple[float, float, str]:
    """Mana Flare's uses per second and the share of maximum mana it finds. Game files: "Supported Skills trigger Mana
    Flare on Critical Hit", a 1 s cooldown (StoredUses 1), and each flare consumes 25% of current mana. PoB has no trigger
    for it (no rate) and calculates it at full mana (config multiplierCurrentManaPercentage, default 100): two overcounts.
    `spell`: the supported spell's own output (MANA_FLARE_FIELDS), calculated as the main skill.
    - rate = the lower of the cooldown's (recovery / cooldown) and the spell's Critical Hits per second (casts x hit chance
      x crit chance; one hit per cast counted, so a spell that hits several times per cast is undercounted)
    - mana: each flare takes 25% of current mana, and the mana regenerated between flares, (regen - the spell's mana per
      second) / rate, puts it back. Before each flare that settles at m = (regen - cost) / (0.25 x rate), capped at maximum
      mana; none if the spell costs more than regen gives."""
    casts = float(spell.get("Speed") or 0.0)
    crits = casts * min(1.0, float(spell.get("HitChance") or 100.0) / 100.0) * min(1.0, float(spell.get("CritChance") or 0.0) / 100.0)
    cap = recovery / cooldown if cooldown else math.inf
    rate = min(cap, crits)
    mana = float(spell.get("Mana") or 0.0)
    net = float(spell.get("ManaRegenRecovery") or 0.0) - float(spell.get("ManaPerSecondCost") or 0.0)
    if rate <= 0.0 or mana <= 0.0:
        share = 1.0 if mana > 0.0 else 0.0
    else:
        share = min(1.0, max(0.0, net) / (MANA_FLARE_SHARE * rate) / mana)
    basis = (f"the lower of its cooldown ({cap:.2f}/s) and the supported spell's Critical Hits ({casts:.2f} casts/s x "
             f"{min(1.0, float(spell.get('CritChance') or 0.0) / 100.0):.0%} crit = {crits:.2f}/s; one hit per cast); "
             f"mana before each flare {share:.0%} of maximum (regen {float(spell.get('ManaRegenRecovery') or 0.0):.1f}/s "
             f"less the spell's {float(spell.get('ManaPerSecondCost') or 0.0):.1f}/s, 25% of current mana taken per flare"
             + ("; the spell costs more than regen gives, so the flare finds none" if net <= 0.0 else "") + ")")
    return rate, share, basis


# The build's Glory lines (MECHC13; game files' stat descriptions, build 26476662, without the markup; PoB's ModCache
# parses "increased Glory generation" to no mod, and none of the others, so glory_plan reads their text):
# - "N% increased / reduced Glory generation" (and "Body Armour grants ..." from a socketable): the Glory each Monster
#   Power event gives; "... for Banner Skills" on Banners only; "... if you have at least 100 Tribute": Tribute isn't
#   modelled, so not counted (said). Not applied to the flat gains below or to Zerphi's Infamy's Life-spent Glory (whether
#   "generation" covers them is UNVERIFIED: the lower reading);
# - "Skills which require Glory generate N Glory every 2 seconds": N / 2 a second for each Glory skill; "Banners gain N
#   Glory per second" (PoB's ModCache holds it): N a second for each Banner;
# - "Skills gain 1 Glory every N seconds for each Rare or Unique monster in your Presence": the boss is Unique: 1 / N a
#   second while it stands in your Presence (MECHC50: stats["_boss_in_presence"], conditions.boss_in_presence: the
#   build's distance against PresenceRadius; 0 outside it, an OVERCOUNT before; a caller that doesn't say: in it, LOW);
# - "(Skills have a) N% chance to not consume Glory": a use consumes (1 - N%); "N% chance (for Skills) to retain 40% of Glory on use": a
#   use consumes (1 - 0.4 x N%); "When a Banner expires, recover N% of the Glory required for that Banner": a Banner's
#   next use needs N% less (each placed Banner taken to expire, LOW);
# - "A random Skill that requires Glory generates N% of its maximum Glory when your Marks Activate" (Quipolatl's Thesis
#   in a Helmet, SoulCoreStats mark_grants_%_max_glory_to_random_skill_on_activate 50; 0.5.0: 50%, was 15%; MECHC26,
#   PATCH_CHECK H3-4, an UNDERCOUNT before): at the build's own Mark Activations (mark_activations, the first Mark, as
#   mark_model: one Mark on an enemy at a time), each going to one of the build's Glory skills at random (1 / k of them
#   to each of k); a skill's "maximum Glory" taken as the Glory its use requires (UNVERIFIED); not scaled by "increased
#   Glory generation" (the lower reading, as the flat gains).
# A Glory skill with a cooldown is used at most once per cooldown (Skill.cooldown / cooldown_recovery; before, never read).
GLORY_INC = re.compile(r"^(?:body armour grants )?(\d+(?:\.\d+)?)% (increased|reduced) glory generation"
                       r"( for banner skills| if you have at least 100 tribute)?$", re.I)
GLORY_FLAT = re.compile(r"^skills which require glory generate (\d+(?:\.\d+)?) glory every 2 seconds$", re.I)
GLORY_PRESENCE = re.compile(r"^skills gain 1 glory every (\d+(?:\.\d+)?) seconds? for each rare or unique monster in your "
                            r"presence$", re.I)
GLORY_BANNER_FLAT = re.compile(r"^banners gain (\d+(?:\.\d+)?) glory per second\b", re.I)
GLORY_NOT_CONSUME = re.compile(r"^(?:skills have an? )?(\d+(?:\.\d+)?)% chance to not consume glory$", re.I)
# (MECHC65, GEM44's MECH-C row; an UNDERCOUNT before: only text lines were read) Spear of Solaris' quality stat (PoB
# act_dex.lua SpearOfSolarisPlayer qualityStats: chance_to_retain_40%_of_glory_on_use_% 1.25 a quality point, 25% at
# 20%) on that skill alone, from its own levelStats (the bridge's buildSkillInstanceStats takes quality), added to the
# lines' chance as GLORY_RETAIN's (summed, at most 100%).
GLORY_RETAIN_STAT = "chance_to_retain_40%_of_glory_on_use_%"
GLORY_RETAIN = re.compile(r"^(\d+(?:\.\d+)?)% chance (?:for skills )?to retain 40% of glory on use$", re.I)
GLORY_BANNER_REFUND = re.compile(r"^when a banner expires, recover (\d+(?:\.\d+)?)% of the glory required for that banner$",
                                 re.I)
GLORY_MARK = re.compile(r"generates (\d+(?:\.\d+)?)% of its maximum glory when your marks? activates?", re.I)


def glory_lines(texts: list[str]) -> dict:
    """The build's Glory lines (above), summed: inc / banner_inc (%), flat (Glory a second a skill), presence (Glory a
    second from the boss in your Presence), not_consume / retain / refund (chances and shares, 0-1), and unread texts."""
    out = {"inc": 0.0, "banner_inc": 0.0, "flat": 0.0, "banner_flat": 0.0, "presence": 0.0, "not_consume": 0.0, "retain": 0.0, "refund": 0.0,
           "mark": 0.0, "unread": []}
    for raw in texts:
        t = raw.strip()
        if m := GLORY_INC.match(t):
            value = float(m.group(1)) * (1 if m.group(2).lower() == "increased" else -1)
            where = (m.group(3) or "").lower()
            if "tribute" in where:
                out["unread"].append(f"'{t}' (Tribute isn't modelled)")
            elif "banner" in where:
                out["banner_inc"] += value
            else:
                out["inc"] += value
        elif m := GLORY_FLAT.match(t):
            out["flat"] += float(m.group(1)) / 2
        elif m := GLORY_BANNER_FLAT.match(t):
            out["banner_flat"] += float(m.group(1))
        elif m := GLORY_PRESENCE.match(t):
            out["presence"] += 1 / float(m.group(1))
        elif m := GLORY_NOT_CONSUME.match(t):
            out["not_consume"] = 1 - (1 - out["not_consume"]) * (1 - min(float(m.group(1)), 100) / 100)
        elif m := GLORY_RETAIN.match(t):
            out["retain"] = min(1.0, out["retain"] + float(m.group(1)) / 100)
        elif m := GLORY_BANNER_REFUND.match(t):
            out["refund"] = min(1.0, out["refund"] + float(m.group(1)) / 100)
        elif m := GLORY_MARK.search(t):
            out["mark"] += float(m.group(1)) / 100
    return out


def glory_uses(names: list[str], stats: dict, main: Skill | None, skills: list[Skill] | None = None,
               texts: list[str] | None = None) -> tuple[float, str]:
    """Uses per second of the build's Glory skills on a boss, all together, and how."""
    plan, how = glory_plan(names, stats, main, skills, texts)
    return sum(uses for uses, _ in plan.values()), how


def glory_spent(names: list[str], stats: dict, main: Skill | None, skills: list[Skill] | None = None,
                texts: list[str] | None = None) -> tuple[float, str]:
    """Glory the build's Glory skills consume a second on a boss (their uses x the Glory a use consumes; MECHC13, for
    "Recover N% of maximum Life per Glory consumed"), and how."""
    plan, how = glory_plan(names, stats, main, skills, texts)
    return sum(uses * spent for uses, spent in plan.values()), how


def _glory_with_rows(events: dict, gains: dict, stats: dict, name: str = "",
                     skills: list[Skill] | None = None) -> tuple[dict, float, str]:
    """(MECHC56, GLORY_ROWS' note) (the main skill's events plus the other skills' rows that feed `gains`, those rows'
    uses a second, how). Without GLORY_ROWS, the legacy OTHER_ATTACK_HITS figure as one Attack row. The Glory skill
    `name`'s own rows (its group in `skills`, GLORY_OWN_HITS) are left out."""
    rows = stats.get(GLORY_ROWS)
    if rows is None:
        other, other_how = stats.get(OTHER_ATTACK_HITS) or (0.0, "")
        rows = [{"hits": number(other), "attack": True, "how": other_how}] if number(other) > 0 else []
    groups = {s.group for s in skills or [] if s.name == name and s.group is not None}
    mine = {name, *GLORY_OWN_HITS.get(name, ())}
    rows = [r for r in rows if str(r.get("name") or "") not in mine
            and not (groups and r.get("index") is not None and r.get("index") in groups)]
    own, uses, parts = dict(events), 0.0, []
    for row in rows:
        got = {e: v for e, v in glory_row_events(row).items() if e in gains and v > 0}
        if not got:
            continue
        for e, v in got.items():
            own[e] = own.get(e, 0.0) + v
        uses += max(0.0, number(row.get("hits")))
        parts.append(f"{row.get('how') or row.get('name') or 'another skill'}: "
                     + ", ".join(f"{v:.2f} {e}s/s" for e, v in got.items()))
    if not parts:
        return own, 0.0, ""
    return own, uses, ("the main skill's " + ", ".join(f"{events.get(e, 0.0):.2f} {e}s/s" for e in gains)
                       + " + the build's other skills' (every skill's events build Glory, KeywordPopups Glory): "
                       + "; ".join(parts))


def glory_plan(names: list[str], stats: dict, main: Skill | None, skills: list[Skill] | None = None,
               texts: list[str] | None = None) -> tuple[dict[str, tuple[float, float]], str]:
    """({Glory skill: (uses per second, Glory a use consumes)}, how) on a boss. `skills`: the build's skills, for each
    Glory skill's cooldown; `texts`: the build's lines (glory_lines; stats["_texts"] when not given).
    (MECHC45, an OVERCOUNT before) stats["_main_share"], when the caller sets it: the main skill's share of the fight
    (assumptions.main_time_share, as objective.dps scores it): its Speed and Life spent a second are taken at that share,
    so its hits, Heavy Stuns, Freezes, Ignites, Shocks and Life spent feed Glory only while it is used (before, at PoB's
    full Speed though the pressed side skills and the Glory presses take part of its time)."""
    share = stats.get("_main_share")
    share_how = ""
    if share is not None and main is not None:
        share = max(0.0, min(1.0, number(share)))
        stats = {**stats, "_main_share": None, "Speed": number(stats.get("Speed")) * share,
                 "LifePerSecondCost": number(stats.get("LifePerSecondCost")) * share}
        if share < 1.0:
            share_how = f"the main skill used {share:.0%} of the fight (the rest pressing other skills); "
    events = glory_events(stats, main)
    lines = glory_lines(list(texts if texts is not None else stats.get("_texts") or []))
    cooldowns = {s.name: s.cooldown / (s.cooldown_recovery or 1.0) for s in skills or [] if s.cooldown}
    power = power_of(stats, texts if texts is not None else None)
    plan, parts = {}, []
    marked, marked_how = glory_mark_rate(skills or [], stats) if lines["mark"] else (0.0, "")
    glory_kinds = len({s.name for s in skills or [] if s.name in GLORY_SKILLS or s.name in GLORY_FROM_LIFE}) or 1
    for name in dict.fromkeys(names):
        banner = name.endswith("Banner")
        extra = []
        gain_events = 0.0  # (MECHC57: the skill's own gains a second, for Glory's decay)
        if name in GLORY_SKILLS:
            cost, gains = GLORY_SKILLS[name]
            if power != BOSS_POWER:
                gains = {e: g if (name, e) in GLORY_FLAT_EVENTS else g * power / BOSS_POWER for e, g in gains.items()}
            own, side_uses, side_how = _glory_with_rows(events, gains, stats, name, skills)
            rate = sum(own[e] for e in gains)
            glory = sum(own[e] * g for e, g in gains.items())
            how = " + ".join(f"{own[e]:.2f} {e}s/s x {g:g}" for e, g in gains.items()) or "no source counted"
            if side_how:
                how += f" ({side_how})"
            if rate > 0:  # one gain per 0.5 s per monster
                # (MECHC56: merged_gains, the main skill's rhythm plus the other skills' events at random)
                speed = number(stats.get("Speed"))
                main_rate = sum(events.get(e, 0.0) for e in gains)
                kept = merged_gains(main_rate, speed, rate - main_rate) / rate
                glory *= kept
                gain_events = rate * kept
                how += (f", at most one gain per {GLORY_GAIN_EVERY:g} s on the boss ({kept:.0%} of them count"
                        + ("; the other skills' events at random beside the main skill's rhythm, merged_gains" if side_uses > 0 else "") + ")")
                stated = [e for e in gains if e in GLORY_STATED and own[e] > 0]
                if stated:  # (MECHC56: the reading without that event, beside the headline)
                    alt = {e: g for e, g in gains.items() if e not in stated}
                    alt_rate = sum(own[e] for e in alt)
                    alt_main = sum(events.get(e, 0.0) for e in alt)
                    alt_glory = (sum(own[e] * g for e, g in alt.items()) * merged_gains(alt_main, speed, alt_rate - alt_main)
                                 / alt_rate if alt_rate > 0 else 0.0)
                    how += (f"; {'; '.join(GLORY_STATED[e] for e in stated)}: counted (the skill's own text); without "
                            f"them {alt_glory:.2f} Glory/s instead of {glory:.2f} (MEDIUM-LOW)")
            if name in GLORY_FROM_WARD:  # (MECHC54: GLORY_FROM_WARD's note)
                spent, spent_how = stats.get("_ward_spent") or (0.0, "no Ward-cost skill paid")
                glory += GLORY_FROM_WARD[name] * number(spent)
                how = (f"{GLORY_FROM_WARD[name]:.0%} of {number(spent):.1f} Runic Ward spent/s by the build's other "
                       f"Ward-cost skills ({spent_how}; its own cost left out)")
            if name in GLORY_FROM_RAGE:  # (MECHC59: GLORY_FROM_RAGE's note)
                at_max, at_max_events, at_max_how = stats.get("_rage_at_max") or (
                    0.0, 0.0, "no Rage gained while at maximum Rage (the Rage box: none held at its maximum)")
                glory += GLORY_FROM_RAGE[name] * number(at_max)
                gain_events += number(at_max_events)
                low = number(at_max_events)
                how = (f"{number(at_max):.2f} Rage/s gained while at maximum Rage ({at_max_how}), 1 Glory a point "
                       "(R58-5, MEDIUM-LOW, UNVERIFIED)" + (
                           f"; row, 1 Glory a gain event: {low:.2f} Glory/s, one use per "
                           f"{GLORY_INSTANCE.get(name, 0.0) + cost / low:.1f} s" if 0 < low < number(at_max) else ""))
            inc = lines["inc"] + (lines["banner_inc"] if banner else 0.0)
            if inc and glory > 0:
                glory *= max(0.0, 1 + inc / 100)
                extra.append(f"{inc:+g}% Glory generation")
        elif name in GLORY_FROM_LIFE:
            cost, share = GLORY_FROM_LIFE[name]
            glory = share * number(stats.get("LifePerSecondCost"))
            how = f"{share:.0%} of {number(stats.get('LifePerSecondCost')):.0f} Life spent/s"
        else:
            continue
        if lines["flat"]:
            glory += lines["flat"]
            gain_events += 0.5  # ("every 2 seconds")
            extra.append(f"+{lines['flat']:g}/s ('generate N Glory every 2 seconds')")
        if banner and lines["banner_flat"]:
            glory += lines["banner_flat"]
            gain_events += 1.0  # ("per second")
            extra.append(f"+{lines['banner_flat']:g}/s ('Banners gain N Glory per second')")
        if lines["presence"] and stats.get("_boss_in_presence") is False:
            # (MECHC50, an OVERCOUNT before for a build standing outside its Presence: counted at any distance)
            extra.append(f"'for each Rare or Unique monster in your Presence': 0, {stats.get('_boss_presence_how') or 'the boss outside your Presence'}")
        elif lines["presence"]:
            glory += lines["presence"]
            gain_events += 1.0
            extra.append(f"+{lines['presence']:g}/s from the boss in your Presence ("
                         + (stats.get("_boss_presence_how") or "kept in it: a play note, LOW") + ")")
        if marked > 0:  # (MECHC26, H3-4: Quipolatl's Thesis)
            gain = marked / glory_kinds * lines["mark"] * cost
            glory += gain
            gain_events += marked / glory_kinds
            extra.append(f"+{gain:.2f}/s from Mark Activations ({marked_how}: {marked:.3f}/s, {lines['mark']:.0%} of its "
                         f"{cost} Glory each" + (f", 1 in {glory_kinds} going to it" if glory_kinds > 1 else "")
                         + "; maximum Glory taken as the Glory a use requires, UNVERIFIED)")
        if glory <= 0:
            parts.append(f"{name}: {how}, never")
            continue
        own_retain = max((number(sk.level_stats.get(GLORY_RETAIN_STAT)) for sk in skills or [] if sk.name == name),
                         default=0.0) / 100  # (MECHC65: GLORY_RETAIN_STAT's note)
        retain = min(1.0, lines["retain"] + own_retain)
        if own_retain:
            extra.append(f"its quality's {own_retain:.0%} chance to retain 40% of Glory on use")
        consumed = cost * (1 - lines["not_consume"]) * (1 - 0.4 * retain)
        needed = consumed * (1 - lines["refund"] if banner else 1.0)
        if needed != cost:
            extra.append(f"{needed:.0f} Glory needed a use (chance not to consume / retain"
                         + (", the Banner's refund on expiry, LOW" if banner and lines["refund"] else "") + ")")
        if name not in GLORY_FROM_LIFE and name not in GLORY_FROM_WARD:  # (MECHC57: GLORY_DECAY_AFTER's note)
            kept_glory = glory_after_decay(glory, gain_events, needed)
            if kept_glory < glory:
                extra.append(f"one gain every {1 / gain_events:.0f} s, so the banked Glory loses {GLORY_DECAY_PER_SECOND:g} a "
                             f"second past {GLORY_DECAY_AFTER:g} s without one: {glory:.2f} -> {kept_glory:.2f} Glory/s")
                if kept_glory <= 0:
                    parts.append(f"{name}: {how} ({'; '.join(extra)}), never")
                    continue
                glory = kept_glory
        held = GLORY_INSTANCE.get(name, 0.0)
        every = held + needed / glory
        cooldown = cooldowns.get(name, 0.0)
        if cooldown > every:
            extra.append(f"held to its {cooldown:.1f} s cooldown")
            every = cooldown
        plan[name] = (1 / every, consumed)
        parts.append(f"{name}: {how}" + (f" ({'; '.join(extra)})" if extra else "")
                     + f" Glory against {cost} per use = one per {every:.1f} s"
                     + (f" (no Glory while its {held:g} s instance is up)" if held else ""))
    if lines["unread"]:
        parts.append("not counted: " + ", ".join(lines["unread"]))
    return plan, share_how + ("; ".join(parts) or "no Glory skill")


def glory_mark_rate(skills: list[Skill], stats: dict) -> tuple[float, str]:
    """(Mark Activations a second, which Mark) for "generates N% of its maximum Glory when your Marks Activate": the
    first Mark as mark_model picks it (one Mark on an enemy at a time), at mark_activations' rate (Eternal Mark in its
    group: up to twice an application); (0, "") with no Mark."""
    marks = [s for s in skills if s.name in MARKS]
    marks += [s for s in skills if s.name == PREDATORS_MARK and s.group not in {m.group for m in marks}]
    if not marks:
        return 0.0, ""
    mark = marks[0]
    eternal = number(mark.support_stats.get(ETERNAL_MARK_STAT)) > 0
    return mark_activations(mark, skills, stats, None, None, eternal)[0], mark.name


# Deadly Resolve (model: deadly_resolve) -----------------------------------------------------------------------------------
# The support (poe2db, matching the 0.5 data): "Gain a stage every 1 second" while channelling the supported skill, "3
# maximum stages", "Stage duration is 10 seconds"; "Expend a stage of Deadly Resolve when an enemy Hits you to Trigger a
# deadly slash", "Can Trigger Deadly Resolve once every 0.3 seconds". PoB counts the slash at its own use rate (1 s at the
# build's attack speed: 1.34 per second on 2b75d's reference). On a boss it comes at most once per stage, one per second
# of channelling, and only when the boss hits you: one hit per boss skill use (bosses.benefit_skill_time, MECHC11; was
# 0.7 s), less those evaded; BLOCKED hits count (MECHB34; RESEARCH26 R26-33, MEDIUM: "Expend a stage ... when an enemy
# Hits you"; KeywordPopups Block: "Blocking completely prevents the damage of an incoming Hit", the Hit still lands,
# Evasion prevents it "from Hitting you at all"; the user's Thorns ruling 14 Nov, "Yes, blocked hits count", on the same
# "when an enemy Hits you" wording; before, blocked hits were taken out too, an UNDERCOUNT for block builds). Read as
# boss_hits.gain_hits with Block at 0 (the lowest real boss on the worst case, as before). Channelled for the whole fight
# while the supported skill is the main skill; otherwise not counted.

DEADLY_RESOLVE = "Deadly Resolve"
DEADLY_RESOLVE_STAGE_EVERY = 1.0  # seconds of channelling per stage
DEADLY_RESOLVE_COOLDOWN = 0.3


def deadly_resolve_model(skills: list[Skill], stats: dict, main: Skill | None,
                         channelled: bool = True) -> tuple[list[dict], list[dict]]:
    """`channelled`: the main skill carries the Channel skill type (MECHB47, MECH94's find in GEM26's sweep: beside a
    Boneshatter PoB still scored the slash, 227 DPS; stages come only "while channelling", so a skill that isn't
    channelled gives none: an OVERCOUNT, now 0)."""
    slashes = [s for s in skills if s.name == DEADLY_RESOLVE and s.triggered]
    if not slashes:
        return [], []
    slash = slashes[0]
    if main is not None and slash.group == main.group and not channelled:
        return trigger_rate(DEADLY_RESOLVE, 0.0), [{
            "label": "Deadly Resolve slashes per second", "value": 0,
            "basis": (f"its stages come only while channelling (\"Gain a stage every 1 second\" while channelling the "
                      f"supported skill); {main.name} isn't a Channelling skill (no Channel skill type), so it never "
                      "gains a stage: not counted (PoB scores the slash at its own use rate regardless)"),
            "confidence": "HIGH", "entry": "deadly-resolve-rate"}]
    if main is None or slash.group != main.group:
        return trigger_rate(DEADLY_RESOLVE, 0.0), [{
            "label": "Deadly Resolve slashes per second", "value": 0,
            "basis": "its channelled skill isn't the main skill, so it isn't channelled through the fight: not counted",
            "confidence": "theory", "entry": "deadly-resolve-rate"}]
    every = bosses.benefit_skill_time(stats)  # (a "when hit" benefit: one hit per boss skill use, MECHD4 / MECHC11)
    # (MECHB6: red-flash hits always land; MECHC20: a gain, so the worst case reads the lowest real boss's landed hits)
    hits, landed_how = boss_hits.gain_hits({**stats, "EffectiveBlockChance": 0})  # (MECHB34: blocked hits count)
    landed = boss_hits.gain_hits(stats)[0]
    rate = min(1 / DEADLY_RESOLVE_STAGE_EVERY, hits, 1 / DEADLY_RESOLVE_COOLDOWN)
    without = min(1 / DEADLY_RESOLVE_STAGE_EVERY, landed, 1 / DEADLY_RESOLVE_COOLDOWN)
    limit = "a stage per second of channelling" if rate < hits else "the boss's hits on you"
    return trigger_rate(DEADLY_RESOLVE, rate), [{
        "label": "Deadly Resolve slashes per second", "value": round(rate, 3),
        "basis": f"one per stage (a stage per {DEADLY_RESOLVE_STAGE_EVERY:g} s of channelling {main.name}) when the boss hits you: "
                 f"{hits:.2f} hits/s reach you (one every {every:g} s, less evaded hits, red-flash hits always landing: {landed_how}); "
                 "blocked hits count (MEDIUM, RESEARCH26 R26-33: the trigger is \"when an enemy Hits you\" and a Blocked hit "
                 "still Hits, only its damage is prevented, KeywordPopups Block; the user's Thorns ruling, 14 Nov)"
                 + (f"; if they didn't: {without:.3f}/s" if abs(without - rate) > 1e-9 else "")
                 + f"; limited by {limit}. PoB alone counts it at its own use rate.",
        "play": "Channel the supported skill through the fight and let the boss hit you; stepping out of its hits stops the slashes.",
        "confidence": "theory", "entry": "deadly-resolve-rate"}]


# Blood Mage's Sanguine Tides (model: sanguine) ----------------------------------------------------------------------------
# "Gain 1 Life Flask Charge per 2% Life spent"; "On Hitting an Enemy while a Life Flask is at full Charges, 40% of its
# Charges are consumed"; "Gain 1% of damage as Physical damage for 5 seconds per Charge consumed this way" (poe2db). In
# steady state every charge filled is consumed, so the buff holds 5 s x charges per second x 1%: 2.5 x the % of Life spent
# per second (the main skill's Life cost per second over maximum Life). Counted from the next resolve (PoB's Life cost per
# second is worked out after the modifiers a what-if would re-read).

SANGUINE = "SanguineTides"
SANGUINE_PER_PERCENT = 5.0 / 2.0  # 5 s per charge, 1 charge per 2% of Life spent
SANGUINE_CONSUMED = 0.4  # of the full Life Flask's charges, consumed on Hit, 1% each (AscendancyWitch2Notable9)


def sanguine_model(inputs: Inputs, stats: dict, flask_charges: float | None = None) -> tuple[list[dict], list[dict]]:
    """Sanguine Tides (RESEARCH4, sanguine-tides.md): 1 Life Flask charge per 2% of Life spent; on Hit with a full Life Flask,
    40% of its charges are consumed for 1% of damage as Physical each, for 5 s. The buff refreshes rather than stacks
    (poe2wiki; SETTLED by RESEARCH26 R26-28: BuffDefinitions MergeMode 3, MEDIUM-HIGH), so it is one value, 0.4 x the flask's maximum charges, up while refills come within 5 s: gain =
    min(0.4 C, 2.5 x % of Life spent per second) (before, 2.5 x L% uncapped: an overcount above the cap). `flask_charges`:
    the equipped Life Flask's maximum charges, 0 with none (no flask to consume: nothing); None leaves it uncapped (tests)."""
    if not inputs.has(SANGUINE):
        return [], []
    life, spent = number(stats.get("Life")), number(stats.get("LifePerSecondCost"))
    when = inputs.condition(SANGUINE, True)
    if when is None:
        return [], []
    # "Buffs on you expire N% slower" (MECHC36): Sanguine Tide (blood_mage_life_flask_buff) is in the game's Buff category
    # (BuffDefinitions BuffCategory 1, RESEARCH29), so its 5 s lasts x the factor
    expiry, expiry_how = stats.get("_buff_expiry") or (1.0, "")
    per_percent = SANGUINE_PER_PERCENT * expiry
    gain = per_percent * spent / life * 100 if life > 0 and spent > 0 else 0.0
    cap = SANGUINE_CONSUMED * flask_charges if flask_charges is not None else None
    capped = cap is not None and gain > cap
    if cap is not None:
        gain = min(gain, cap)
    # (worked out again by the bridge from each calculation's Life and Life cost, capped by the flask)
    mods = [line("Gain 1% of Damage as Extra Physical Damage", 1 / UNIT, when=when, per=SANGUINE),
            derived(SANGUINE, "sanguine", gain * UNIT, perPercent=per_percent,
                    **({"cap": cap} if cap is not None else {}))]
    if cap == 0:
        return mods, [{"label": "Sanguine Tides", "value": "not counted",
                       "basis": "no Life Flask equipped: the charges it consumes on Hit come from a full Life Flask",
                       "confidence": "theory"}]
    if gain <= 0:
        return mods, [{"label": "Sanguine Tides", "value": "not counted", "basis": "the build spends no Life on its skills",
                       "confidence": "theory"}]
    return mods, [{
        "label": "Sanguine Tides: damage gained as Physical", "value": f"{gain:.1f}%",
        "basis": f"the main skill spends {spent:,.0f} Life/s ({spent / life:.1%} of {life:,.0f} per second): 1 Life Flask charge per 2% spent, "
                 f"40% of the full flask's charges consumed on Hit, 1% each for {5 * expiry:.3g} s"
                 + (f" ({expiry_how})" if expiry != 1.0 else "") + "; the buff refreshes, it doesn't stack "
                 "(SETTLED, MEDIUM-HIGH: the game's BuffDefinitions MergeMode 3, one copy refreshed; RESEARCH26 R26-28)"
                 + (f", so it is capped at {cap:.0f}% (40% of the Life Flask's {flask_charges:.0f} charges)" if capped else
                    (f"; the flask refills too slowly to keep its {cap:.0f}% up, so it is up part of the time" if cap else ""))
                 + "; you hit the boss whenever the flask is full",
        "play": "Hitting less often than the flask fills, or a flask that never fills, lowers it.", "confidence": "theory"}]


# What-ifs and the models (the what-if limit) ---------------------------------------------------------------------------
# Model inputs the bridge can work out (item counts, uptimes from Mana, Life and speed) are worked out again on every
# calculation (derived(), engine/bridge.lua DERIVED), so plain what-ifs see them. An item that carries a model itself (a
# resistance ring, Melting Maelstrom, model inputs on its lines) still counts from the next resolve: Build.item_deltas
# re-scores the best few such candidates (or those that replace such an item) with a real trial, models included.

def item_read_by_models(raw: str, build_texts: list[str]) -> bool:
    """Does a model read this item's lines? (Its own model inputs, Melting Maelstrom, a resistance ring: the item carries
    the model itself. The items a ring counts are counted by the bridge on every calculation; `build_texts` is kept for
    models that read the build's lines.)"""
    lines = [l.strip() for l in (raw or "").splitlines() if l.strip()]
    return any(model_entry(text) is not None or MAELSTROM.match(text) or RING_LINE.match(text) for text in lines)


@dataclass
class PressCap:
    """The most uses a second the build can feed a skill (MECHB5, COVC6 / COVC7: usage.py's combo_rate, travel_rate and
    throw_rate), why, and the seconds spent walking before each use (the travel requirement)."""
    uses: float
    how: str
    moving: float = 0.0
    confidence: str = "LOW"


# A pressed non-main skill in Full DPS (MECH37) -------------------------------------------------------------------
# PoB's Full DPS counts every group in it as used nonstop, though only the main skill is: a skill the player presses
# beside it is used on its cooldown, once per its buff/debuff duration if it's pressed to keep one up, or else at a
# rate the search chooses (PRESS_CHOICES below; none chosen: 0), and the main skill loses the time those presses take.
# (MECHB18: PRESS_EVERY, the old flat 5 s guess, is gone: its last reader, flasks.py's Perfect Timing charm, reads the
# build's own presses since MECHC12, cd32ab1.)
# Full DPS's ailment entries (source: the skill that's their best source) and the ailment whose stacks set each
# (PoB: Burning Ground is a share of the Ignite's damage)
PRESS_AILMENTS = {"Best Ignite DPS": "Ignite", "Best Burning Ground DPS": "Ignite", "Best Bleed DPS": "Bleed",
                  "Best Poison DPS": "Poison"}


def press_key(name: str, source: str | None) -> str:
    """objective.Objective.press_scales' key for a SkillDPS entry: its name, and its source for an ailment's."""
    return f"{name} from {source}" if source and source != name else name


# A skill the models use 0 times a second still feeds PoB's "Best <ailment> DPS" (MECH88; SEARCH27's finding, the manager's
# 11:35 routing: an OVERCOUNT). PoB's Full DPS takes each ailment's best single source over the Full DPS skills (Calcs.lua
# mergeFullDPSPass, mode "max", the row's source = that skill) and works a skill's ailment out at its own stacks whatever
# use rate a model hands it, so a skill a model sets to 0 uses (a SkillData triggerRate of 0: corpse_model's Decompose with
# no corpses, a trigger with no Energy ...; or an entry_scales of 0) can still be the best Poison / Ignite / Bleed source:
# s25-pick's 2b75b build, the Acrid Wand's Decompose at 0 uses, Best Poison DPS 2,144, +8.7% (SEARCH27's POE2T4260).
# Such a row is scaled to the best OTHER Full DPS group's own ailment DPS (the bridge's useRates: each group calculated
# alone, as PoB's Full DPS does) over the row's, 0 when no other group deals it; pressed groups keep press_model's own
# scales (theirs come first). The other groups' values are read at the resolve, as press_model's.
BEST_AILMENT_FIELDS = {"Best Ignite DPS": "IgniteDPS", "Best Poison DPS": "PoisonDPS", "Best Bleed DPS": "BleedDPS",
                       "Best Corr. Blood DPS": "CorruptingBloodDPS", "Best Burning Ground DPS": "BurningGroundDPS",
                       "Best Caustic Ground DPS": "CausticGroundDPS"}


def named(label: str | None, names: set[str]) -> bool:
    """Whether a PoB label (a Full DPS source, a useRates row name) is one of `names` or a part of one ("<name>: <part>")."""
    label = str(label or "")
    return any(label == n or label.startswith(f"{n} ") or label.startswith(f"{n}:") for n in names)


def zero_use_ailment_scales(skill_dps: list[dict], zero: set[str], rows: list[dict],
                            taken: dict | None = None) -> tuple[dict[str, float], list[dict]]:
    """({press_key: scale}, notes) for the "Best <ailment> DPS" rows whose source is used 0 times (see above); `rows` the
    Full DPS groups' useRates rows, `taken` the scales already set (press_model's)."""
    scales, notes = {}, []
    for entry in skill_dps:
        name, source = entry.get("name"), entry.get("source")
        field = BEST_AILMENT_FIELDS.get(name)
        key = press_key(name, source)
        if field is None or not named(source, zero) or key in (taken or {}):
            continue
        current = number(entry.get("dps"))
        others = [(number(r.get(field)), r.get("name")) for r in rows if not named(r.get("name"), zero)]
        best, who = max(others, default=(0.0, None))
        scale = min(best / current, 1.0) if current > 0 else 0.0
        scales[key] = scale
        notes.append({"label": f"{name}: not from {source}", "value": round(current * scale, 1),
                      "basis": (f"PoB's best {field[:-3]} source is {source}, which the build uses 0 times a second (its "
                                f"own model), so its {current:,.0f} doesn't count; "
                                + (f"the next best, {who}'s {best:,.0f}, does instead" if best > 0 else
                                   "no other Full DPS skill deals it: 0")),
                      "confidence": "theory"})
    return scales, notes


# A pressed skill with no cooldown, no duration and nothing else setting its use (MECH55; THE USER, 12 Nov, card: "Search
# picks the rate"): the search chooses how often it's pressed as a play strategy, its time charged against the main
# skill (press_model's busy share), with a "without it" row in the play guide. SEARCH sets the choice on
# build.objective.press_choices ({skill name as useRates names it: uses per second}; PRESS_CHOICES). Until it does, such
# a skill is pressed 0 times, labelled (the user's flat-rate rule: no source, 0). conditions.skill_use_rate
# (Marks and other "you use" events, consumers beside the main skill) reads the same choice since MECH56.
PRESS_CHOICES = "press_choices"


def press_choices(build) -> dict[str, float]:
    """The search's chosen press rates for the build ({} when it chose none)."""
    return dict(getattr(getattr(build, "objective", None), PRESS_CHOICES, None) or {})


def press_choice(rate: dict, choices: dict[str, float] | None) -> float | None:
    """The chosen uses per second for a useRates row (its name, or its name before a stat set's label), or None."""
    name = str(rate.get("name") or "")
    for skill, uses in (choices or {}).items():
        if name == skill or name.startswith(f"{skill} ") or name.startswith(f"{skill}:"):
            return number(uses)
    return None


# A duration skill pressed more often than once per its duration (MECHB39; SEARCH28 item 4a, the manager 14:25): a skill
# that can hold several instances at once (the bridge's useRates instanceLimit: its own "number_of_X_allowed" stat plus
# "+N to Limit" lines; Lightning Rod's 10 rods of 20 s) can be pressed up to limit / duration times a second and each
# press adds one; the search's chosen rate (press_choice: a play strategy under the button cap, its time charged by
# press_model) counts up to that. One instance (no limit stat): pressing again only replaces it, so once per its
# duration, as before. Pressing it less often than once per its duration isn't offered here (the old rate is the floor).
# A Projectile skill with no instance limit (the bridge's useRates projectile: PoB's SkillType.Projectile; Spark's 2 s,
# Ball Lightning's) carries its projectiles' life as Duration: pressing again adds projectiles, so the chosen rate counts
# (only its own speed caps it; MECHB39, the manager 17:55: an UNDERCOUNT before, held to once per that life). Which
# duration skills hold one instance only (buffs, Marks, a placed wall) vs add one a press without a limit stat is read
# from these two fields alone: a non-Projectile skill with no limit stat stays at once per its duration (the cautious
# side, said).
def duration_press_rate(rate: dict, chosen: float | None) -> tuple[float, str]:
    """(presses per second, how) of a duration skill with no cooldown: once per its duration, or the chosen rate up to
    its instance limit / duration (see above)."""
    duration = number(rate.get("duration"))
    once = 1.0 / duration
    limit = number(rate.get("instanceLimit"))
    if chosen is None or chosen <= once:
        return once, f"once per its {duration:.2f} s duration, to keep it up"
    if limit <= 1 and rate.get("projectile"):  # (MECHB39: its Duration is its projectiles' life; each press adds more)
        return chosen, (f"{chosen:.3g} presses a second*, the rate the search chose (a way to play the build; its "
                        f"{duration:.2f} s duration is its projectiles' life, not a thing kept up, so pressing again adds "
                        f"projectiles; without it, once per that duration: {once:.3g} a second)")
    if limit <= 1:
        return once, (f"once per its {duration:.2f} s duration (the search chose {chosen:.3g} presses a second, but it "
                      "holds one instance: pressing again only replaces it)")
    most = limit / duration
    presses = min(chosen, most)
    return presses, (f"{presses:.3g} presses a second*, the rate the search chose (a way to play the build: up to "
                     f"{limit:g} at once, each lasting {duration:.2f} s, so at most {most:.3g} a second"
                     + (f"; it chose {chosen:.3g}" if chosen > most else "")
                     + f"; without it, once per its duration: {once:.3g} a second)")


def press_use_rate(rate: dict, chosen: float | None = None) -> tuple[float, str, str]:
    """A pressed skill's uses per second from one bridge `useRates` row: on its cooldown, else once per its duration
    (or the chosen rate up to its instance limit, duration_press_rate), else the rate the search chose (`chosen`,
    press_choice), else 0 (labelled); never faster than PoB's speed. (uses/s, how, confidence)."""
    speed, repeats = number(rate.get("speed")), number(rate.get("repeats")) or 1.0
    cooldown, duration = number(rate.get("cooldown")), number(rate.get("duration"))
    if cooldown > 0:
        real, how, confidence = repeats / cooldown, f"on its {cooldown:.2f} s cooldown", "MEDIUM"
    elif duration > 0:
        presses, how = duration_press_rate(rate, chosen)
        real, confidence = repeats * presses, "MEDIUM"
    elif chosen is not None and chosen > 0:
        real, how, confidence = repeats * chosen, (f"{chosen:.3g} times a second*, the rate the search chose (a way to "
                                                   "play the build; without it, it adds nothing)"), "MEDIUM"
    else:
        real, how, confidence = 0.0, ("0 times* (no cooldown or duration sets how often it's pressed, and the search "
                                      "chose no rate: no source, 0)"), "LOW"
    # (MECHB47) a Warcry's ceiling is its castRate (1 / WarcryCastTime): PoB's Speed counts the action speed twice for a
    # warcry (CalcOffence 2978 then 2985; probe POE2T4710: 0.334/s for a 1.547 s cry). Rows flagged by Assumptions.
    ceiling = max(speed, number(rate.get("castRate"))) if rate.get("warcry") else speed
    return min(real, ceiling), how, confidence


def warcry_use_rate(rate: dict, speed: float) -> tuple[float, str]:
    """(uses a second, how) of a Warcry used nonstop (GEM28, the manager 18:20 from MECHB47): its castRate (the bridge's
    useRates: 1 / WarcryCastTime), not PoB's Speed, which counts the action speed twice for a warcry (probe POE2T4710:
    0.334/s for a 1.547 s cry); held to its cooldown (PoB's repeats / cooldown); PoB's `speed` where no castRate."""
    cast = number(rate.get("castRate"))
    if cast <= 0:
        return max(number(speed), 0.0), "at PoB's Speed (no castRate read)"
    used, how = max(cast, number(speed)), f"at its castRate {cast:.3g}/s (PoB's Speed {number(speed):.3g}/s counts the action speed twice)"
    cooldown = number(rate.get("cooldown"))
    if cooldown > 0:
        held = (number(rate.get("repeats")) or 1.0) / cooldown
        if held < used:
            used, how = held, f"on its {cooldown:.2f} s cooldown"
    return used, how


def press_group_rate(rate: dict, pace: float | None = None, cap: "PressCap | None" = None,
                     chosen: float | None = None) -> tuple[float, str, str]:
    """A pressed group's uses per second as press_model counts its damage: press_use_rate, held to Cadence's pace
    (`pace`) and to the most uses the build can feed it (`cap`, Assumptions.press_caps). The one rate for its benefit
    and its side effects (conditions.side_consumes reads it too; MECH54, CLAUDE.md's flat-rate rule)."""
    real, how, confidence = press_use_rate(rate, chosen)
    if pace is not None and real > pace:
        real, how = pace, how + (f", held to Cadence's {pace:g} uses/s (at most 5 uses in any 4 s: a 6th locks the "
                                 "skill for 10 s; game files SupportCadencePlayer)")
    if cap is not None and real > cap.uses:
        real, how = cap.uses, how + f", held to {cap.uses:.3g} uses/s by {cap.how}"
    return real, how, confidence


def press_action(rate: dict) -> float:
    """The main skill's time one press of a `useRates` row takes: 1/speed, unless the cooldown capped PoB's speed: then
    its own use time (PoB's HitTime where shorter than the capped interval), else its base cast time.
    (MECH94, an UNDERCOUNT since MECH37: PoB sets Time = 1 / Speed AFTER the cooldown cap (CalcOffence 3008 then 3052),
    so the row's `time` of a capped skill is its whole cooldown interval, not one use: a pressed Frost Bomb (6 s
    cooldown, 0.8 s cast) charged 6 s a press and left the main skill 0% of the fight (probe POE2T5059). A `time` as
    long as the capped interval is now dropped for the base cast time (cast speed not read: a press reads a little long
    where the build casts faster, LOW).)
    (MECHB47) The row's `castRate` (PoB's CastRate: the rate before the cooldown cap, with the build's cast / attack,
    action, totem or warcry speed) gives that use time exactly where the bridge has it; the two readings above stay as
    the fallback for a row without it."""
    speed, repeats, cooldown = number(rate.get("speed")), number(rate.get("repeats")) or 1.0, number(rate.get("cooldown"))
    if speed <= 0:
        return 0.0
    cast_rate = number(rate.get("castRate"))
    if cast_rate > 0:  # (uncapped too: a Warcry's PoB Speed counts the action speed twice, probe POE2T4710: Ancestral
        return min(1 / speed, 1 / cast_rate)  # Cry, no cooldown, 2.99 s for its 1.55 s WarcryCastTime)
    capped = cooldown > 0 and speed >= repeats / cooldown * (1 - 1e-6)
    if not capped:
        return 1 / speed
    time = number(rate.get("time"))
    uncapped = time if 0 < time < (1 / speed) * (1 - 1e-6) else number(rate.get("castTime"))
    return min(1 / speed, uncapped)


# (MECHB30, for MECHC26's play-guide row) the switch for "the player casts Spells near the side Orb" (MECHB28's play
# strategy): with it off (near=False, or build.orb_near = False: ORB_NEAR, read by Assumptions.rate_presses) the casts
# beside the Orb fire no bolts and each Orb fires its timer bolts only, so the guide's "without it" row is the same code
ORB_NEAR = "orb_near"


def side_orbs(rates: list[dict], main_index: int | None, pressed: set[int],
              paced: dict[int, float] | None = None, caps: dict[int, "PressCap"] | None = None,
              choices: dict[str, float] | None = None, near: bool = True) -> dict[int, tuple[float, float, dict]]:
    """{group: (presses/s, bolts/s, note)} for each pressed side Orb of Storms (orb_cycle), from the same inputs as
    press_model: the main skill's casts near it are what it's left after the other presses (MECHB28)."""
    main_rate = next((r for r in rates if r["index"] == main_index), None)
    orbs = {r["index"]: r for r in rates if r["index"] in pressed and r["index"] != main_index
            and r.get("name") == ORB_OF_STORMS and number(r.get("orbMaxHits")) > 0 and number(r.get("speed")) > 0}
    if not orbs:
        return {}

    def press_rate(rate: dict) -> float:  # (its presses a second, as press_model counts them)
        cap = (caps or {}).get(rate["index"])
        return press_group_rate(rate, (paced or {}).get(rate["index"]), cap, press_choice(rate, choices))[0]

    def press_time(rate: dict) -> float:  # (the main skill's time each other press takes, as press_model counts it)
        cap = (caps or {}).get(rate["index"])
        return press_rate(rate) * (press_action(rate) + (cap.moving if cap is not None else 0.0))
    side = [r for r in rates if r["index"] in pressed and r["index"] != main_index and r["index"] not in orbs
            and number(r.get("speed")) > 0]
    others = sum(press_time(r) for r in side)
    # (MECHB29) the other pressed Spells the player casts fire bolts too ("when you cast a Spell near the Orb")
    spells = {str(r.get("name")): press_rate(r) for r in side if r.get("spell") and not r.get("triggered")
              and not r.get("channel")}
    return {index: orb_cycle(orb, main_rate, others, (paced or {}).get(index), (caps or {}).get(index), spells, near)
            for index, orb in orbs.items()}


def orbs_per_second(rates: list[dict], main_index: int | None, pressed: set[int],
                    paced: dict[int, float] | None = None, caps: dict[int, "PressCap"] | None = None,
                    choices: dict[str, float] | None = None, near: bool = True) -> dict[int, float]:
    """(MECHB29, for MECH-C's Remnant supply) {group: Orbs of Storms cast a second} for each pressed side Orb, at the
    rate press_model scores it: each Orb lasts its duration, or less once the main Spell's casts near it and its timer
    bolts reach its maximum hits (orb_cycle), and is recast at once, so each Orb cast is one Orb that expires. Takes the
    same inputs as press_model (Assumptions.rate_presses builds them: the bridge's useRates rows, the main group's index,
    the pressed groups, Cadence's pace, the press caps, press_choices). The main skill's own Orb isn't here (its recasts
    replace a live Orb: PoB's Speed, orb_of_storms_note)."""
    return {index: presses for index, (presses, _, _) in
            side_orbs(rates, main_index, pressed, paced, caps, choices, near).items()}


def press_model(rates: list[dict], main_index: int | None, pressed: set[int],
                paced: dict[int, float] | None = None, caps: dict[int, "PressCap"] | None = None,
                choices: dict[str, float] | None = None, near: bool = True) -> tuple[dict[str, float], list[dict]]:
    """Full DPS entry scales ({SkillDPS name: x}) and notes for the pressed non-main groups `pressed`, from the bridge's
    `useRates` (each group's skill as if it were the main one: its speed, capped by its cooldown as PoB does, its
    cooldown after recovery, repeats, duration and base cast time). `paced` ({group: most uses per second}): a group
    held to a pace (Cadence's 5 uses per 4 s, CADENCE_PACE; MECHB4, COVE6's open item). `caps` ({group: PressCap}): the
    most uses a second the build can feed it (Combo, walking between uses, flask charges for a throw; MECHB5), and the
    seconds of walking each use costs the main skill."""
    scales: dict[str, float] = {}
    notes: list[dict] = []
    busy, users = 0.0, []
    main_rate = next((r for r in rates if r["index"] == main_index), None)
    orb_rates: dict[int, tuple[float, float]] = {}  # (MECHB28) {group: (presses/s, bolts/s)}, orb_cycle
    for index, (presses, bolts, orb_note) in side_orbs(rates, main_index, pressed, paced, caps, choices, near).items():
        orb_rates[index] = (presses, bolts)
        notes.append(orb_note)
    for rate in rates:
        if rate["index"] not in pressed or rate["index"] == main_index:
            continue
        speed = number(rate.get("speed"))
        if speed <= 0:
            continue
        cap = (caps or {}).get(rate["index"])
        real, how, confidence = press_group_rate(rate, (paced or {}).get(rate["index"]), cap, press_choice(rate, choices))
        if rate["index"] in orb_rates:  # (MECHB28: its presses from the Orb's cycle, its damage from its bolts below)
            real, how, confidence = orb_rates[rate["index"]][0], "once each Orb's life (orb_cycle)", "MEDIUM"
        if cap is not None and cap.moving > 0:
            busy += real * cap.moving  # (no skill is used while walking between its uses)
        action = press_action(rate)
        busy += real * action
        # (MECHB28: a side Orb of Storms' damage is its bolts, orb_cycle: PoB's entry is one bolt per cast)
        ratio = (orb_rates[rate["index"]][1] if rate["index"] in orb_rates else real) / speed
        scales[rate["name"]] = scales.get(rate["name"], 1.0) * ratio
        users.append(rate["name"])
        # Its ailments: PoB counts min(stacks, the most that count), stacks = chance x duration x its speed (its
        # StackPotential = stacks / most); at the real rate there are that x ratio
        ailing = []
        for entry, ailment in PRESS_AILMENTS.items():
            potential = number((rate.get("stackPotential") or {}).get(ailment))
            if potential > 0:
                share = min(potential * ratio, 1.0) / min(potential, 1.0)
                scales[press_key(entry, rate["name"])] = share
                if entry != "Best Burning Ground DPS":
                    ailing.append(f"{ailment} x{share:.3f} ({potential:.2f} of its most stacks nonstop)")
        notes.append({
            "label": f"{rate['name']}: pressed beside the main skill*", "value": f"x{ratio:.3f}",
            "basis": f"PoB's Full DPS counts it used nonstop ({speed:.2f}/s); it's pressed {how}, {real:.2f} uses/s, "
                     f"each taking {action:.2f} s from the main skill"
                     + (f". Its ailments, where it's their best source in Full DPS, at the stacks those presses keep "
                        f"up (PoB's chance x duration x rate, capped at the most that count): {'; '.join(ailing)}"
                        if ailing else ""),
            "confidence": confidence})
    main = main_rate["name"] if main_rate else None
    if users and main is not None and busy > 0:
        share = max(0.0, 1.0 - busy)
        scales[main] = scales.get(main, 1.0) * share
        for entry, ailment in PRESS_AILMENTS.items():  # (its ailments' stacks shrink with it, as above)
            potential = number((main_rate.get("stackPotential") or {}).get(ailment))
            if potential > 0:
                scales[press_key(entry, main)] = min(potential * share, 1.0) / min(potential, 1.0)
        notes.append({
            "label": f"{main}: time left beside {', '.join(users)}*", "value": f"{share:.1%}",
            "basis": f"the presses take {busy:.1%} of the fight (their uses x time per use); its ailments' stacks "
                     "shrink with it (PoB's chance x duration x rate, capped at the most that count)",
            "confidence": "MEDIUM"})
    return scales, notes


# The boss's Power raised by the build (MECH67; RESEARCH22 #130, research/abyssal-wasting-sources.md; plans/
# kw-abyssal-wasting.md C). A pinnacle boss has 20 Power (KeywordPopups Power: "Unique monsters always have 20 Power";
# PoB's Boss config: WarcryPower and Multiplier:EnemyPower BASE 20). Every player stat that raises an enemy's Power
# (checked: Stats.json ids with "power" and "enemy|monster|target", their Mods users, game 26476662; PoB's uniques; poe2db
# not checked: UNVERIFIED that no other source exists):
# - unique_redblade_banner_enemies_in_presence_monster_power_+%_final 100 (UniqueEnemiesInPresenceMonsterPower1, Redblade
#   Banner): "Enemies in your Presence count as having double Power". PoB: ModCache parses it to nothing.
# - enemies_in_your_presence_with_abyssal_wasting_have_doubled_power (PassageUniqueAmanamuAbyssalWastingDoubledPower; a
#   Desecrated line of the Grip of Kulemak, MEDIUM): "Targets affected by Abyssal Wasting in your Presence have double
#   Power". Abyssal Wasting: "Inflict Abyssal Wasting on Hit" (the Abyssal Signet ring's implicit, Grip of Kulemak), 6 s
#   per Hit (KeywordPopups AbyssalWasting): Wasted while the main skill hits at least once per 6 s, else that share
#   (hits x 6 s); "Abyssal Wasting you inflict has Infinite Duration": any hit. PoB: ModCache parses it to nothing.
# - monsters_in_your_presence_have_additional_power_equal_to_their_gruelling_madness_stacks (Sadist's Mercy): "Enemies in
#   your Presence have additional Power equal to their Gruelling Madness". Gruelling Madness (KeywordPopups): at most 10
#   on a target, "lose 1 Gruelling Madness every 2 seconds that passes without more being inflicted". Fed by "Hits with
#   this Weapon inflict N Gruelling Madness" (the main skill an Attack hitting at least once per 2 s: 10; slower: N, LOW)
#   or "Enemies in your Presence gain 1 Gruelling Madness each second" (Sculpted Suffering: 10). The ramp isn't counted.
# - Not read here: Echoing Cry's less Power for its Warcry (echoing_power_model; PoB reads no such stat: MECHB40 checked
#   vendor PoB src, the id only in Data/Skills/sup_str.lua); monster-side stats
#   (monster_power_doubled_if_afflicted_by_abyssal_wasting: no Mods row uses it); adds' Power (ADD_POWER) isn't doubled.
# Both doublings together: counted once (x2), the lower reading (UNVERIFIED whether "double" twice is x4); the Madness
# Power added after the doubling (UNVERIFIED order; the lower reading). All need the boss in your Presence (the boss's
# distance vs PoB's PresenceRadius). Read by energy_gain, glory_plan, roar_model / roar_break and PoB's own EnemyPower /
# WarcryPower (power_mods, from Assumptions.models). Not yet: Siphon Elements' Cold Remnant chance (5% per Power, already
# 100% at 20 Power: no change).
POWER_DOUBLED = re.compile(r"^Enemies in your Presence count as having double Power$", re.I)
POWER_DOUBLED_WASTED = re.compile(r"^Targets affected by Abyssal Wasting in your Presence have double Power$", re.I)
WASTING_ON_HIT = re.compile(r"^Inflict Abyssal Wasting on Hit$", re.I)
WASTING_INFINITE = re.compile(r"^Abyssal Wasting you inflict has Infinite Duration$", re.I)
WASTING_DURATION = 6.0
MADNESS_POWER = re.compile(r"^Enemies in your Presence have additional Power equal to their Gruelling Madness$", re.I)
MADNESS_ON_HIT = re.compile(r"^Hits with this Weapon inflict (\d+) Gruelling Madness$", re.I)
MADNESS_PER_SECOND = re.compile(r"^Enemies in your Presence gain (\d+) Gruelling Madness each second$", re.I)
MADNESS_MAX, MADNESS_DECAY = 10, 2.0
POWER_FALLBACK_DISTANCE = 50.0  # (units: conditions.RANGED_DISTANCE 5 m, when the boss's distance isn't known: the far
# reading, so a Presence line counts only when the Presence reaches 5 m)

# Runefather's Challenge (MECH68; the user's catch, 13 Nov ~21:55, an UNDERCOUNT). KeywordPopups RunefathersChallenge:
# "Runefather's Challenge is a [Debuff] which raises the [Power] of affected targets by 5" (stat
# monster_power_+_from_ancients_challenge; the game's internal name is Ancient's Challenge). The sources (checked: every
# Stats.json id with "ancients_challenge" (5 ids), each looked up in Mods, PassiveSkills, GrantedEffectStatSets,
# GrantedEffectStatSetsPerLevel, GrantedEffectQualityStats and SoulCoreStats, game 26476662; second source poe2db's
# Runefathers_Challenge and Eyes_of_the_Runefather pages, which list the same three):
# - Eyes of the Runefather (Venerable Defender): UniqueAncientsChallengeOnOffHandDamage1 "Off-hand Hits inflict
#   Runefather's Challenge" and UniqueRaiseShieldAncientsChallenge1 "Inflicts Runefather's Challenge on enemies 6 metres
#   in front of you when raised, no more than once every 2 seconds";
# - the soul core Legacy of A Worthy Foe (an Aldur's Legacy, SoulCoreStats 522, socketed in a shield, limit 3): the same
#   off-hand line (off_hand_apply_ancients_challenge_on_hit). (The manager's "only the shield's two mods" missed it.)
# - local_apply_ancients_challenge_on_hit and has_ancients_challenge_buff: no user in those tables.
# PoB parses none of the lines (ModCache). Off-hand hits with a shield in the off hand: the skills PoB flags shieldAttack
# (its only way to set weapon2Attack with a shield, CalcActiveSkill 515-517; a shield isn't a weapon to getWeaponFlags):
# SHIELD_HITTERS below (Raise Shield's own Shield Bash after a block: RAISE_SHIELD_GRANT below). Only the main skill's hits are read (another
# skill's shield hits pressed beside it aren't: a small undercount). Raise Shield: the boss within 6 m (PoB's
# enemyDistance) and the shield raised once per Challenge duration (a button the player presses to feed it: the time
# raised isn't taken from the main skill, a small overcount, named). Its duration: no game data we have (BuffDefinitions
# not extracted) and poe2db states none, nor any "until the target dies" (its neighbour Runefather's Boast's definition
# says outright it "does not have a duration"; the Challenge's doesn't); CHALLENGE_DURATION 10 s from poe2wiki
# ("approximately 10 seconds") and Mobalytics ("appears to expire after a 10 second period", guides/runefathers-
# challenge-runefathers-boast) (AUDIT32 A32-9): LOW, a flat number; the user may check it in game. The +5 is added after any doubling (UNVERIFIED order: the lower reading, 20 x 2 + 5 = 45, not (20 + 5) x 2).
CHALLENGE_POWER = 5
CHALLENGE_DURATION = 10.0  # LOW: poe2wiki "approximately 10 seconds" and Mobalytics; no game data (AUDIT32 A32-9)
CHALLENGE_RAISE_RANGE = 60.0  # units: "6 metres in front of you when raised"
CHALLENGE_OFF_HAND = re.compile(r"^Off-hand Hits inflict Runefather's Challenge$", re.I)
CHALLENGE_RAISE = re.compile(r"^Inflicts Runefather's Challenge on enemies ([\d.]+) metres in front of you when raised", re.I)
# Raise Shield's own hit (AUDIT31 A31-5, an UNDERCOUNT): "Release immediately after Blocking when an enemy is close to
# perform a Shield Bash, damaging and Stunning enemies" (PoB's ShieldBlockPlayer description; it's a shieldAttack skill):
# an off-hand Hit per blocked hit. Blocks against the boss: one telegraphed hit every PARRY_EVERY s (the user's Parry
# cadence). Every shield base granting it says "Grants Skill: Raise Shield" (PoB's bases). "Close": its reach (MECHB34;
# RESEARCH26 R26-63, MEDIUM, was a LOW 2 m): the unarmed base reach 0.8 m (Characters MaxAttackDistance 8 for all 12
# classes; the bash uses the off-hand unarmed attack with the shield's stats, replace_off_hand_unarmed_attack_stats_with_
# shield_type, and shields have no reach of their own: ShieldTypes holds only Block, WeaponTypes no shield) + Raise
# Shield's melee_strike_bonus_attack_distance 14 (1.4 m) = 2.2 m, plus the build's "+N metres to Melee Strike Range"
# lines, unconditional or "while Holding a Shield" (stat_descriptions melee_range_+_while_wielding_shield; conditional
# ones, e.g. "while Unarmed" or after a Projectile hit, not counted). Measured edge to edge or centre to centre:
# UNVERIFIED (centre to centre taken, the shorter).
RAISE_SHIELD_GRANT = re.compile(r"Grants Skill:[^.;]*\bRaise Shield\b", re.I)
SHIELD_BASH_RANGE = 22.0  # units: 0.8 m unarmed + 1.4 m Raise Shield
SHIELD_BASH_REACH_LINE = re.compile(r"^\+([\d.]+) metres to Melee Strike Range(?: while Holding a Shield)?$", re.I)


def shield_bash_reach(texts: list[str]) -> float:
    """Raise Shield's Shield Bash reach in units: SHIELD_BASH_RANGE + the build's Melee Strike Range lines (see above)."""
    return SHIELD_BASH_RANGE + 10 * sum(float(m.group(1)) for t in texts if (m := SHIELD_BASH_REACH_LINE.match(t.strip())))
SHIELD_HITTERS = frozenset({"Shield Wave", "Magma Spray", "Resonating Shield", "Shield Charge", "Shield Wall", "Parry",
                            "Soaring Midnight", "Embrace The Fall"})  # PoB's shieldAttack skills (Data/Skills)


def challenge_share(texts: list[str], stats: dict, distance: float | None, main: str | None) -> tuple[float, str]:
    """(The share of the fight the boss has Runefather's Challenge, its basis; "" when no line)."""
    raise_line = next((m for t in texts if (m := CHALLENGE_RAISE.match(t))), None)
    off_hand = any(CHALLENGE_OFF_HAND.match(t) for t in texts)
    if not (raise_line or off_hand):
        return 0.0, ""
    far = POWER_FALLBACK_DISTANCE if not distance else distance
    if raise_line and far <= float(raise_line.group(1)) * 10:
        return 1.0, (f"you raise your shield once every {CHALLENGE_DURATION:g} s with the boss {far / 10:g} m away "
                     f"(within {raise_line.group(1)} m): the boss stays Challenged")
    if off_hand:
        hits = hits_per_second(stats) if main in SHIELD_HITTERS else 0.0
        reach = shield_bash_reach(texts)
        bash = (1 / PARRY_EVERY if any(RAISE_SHIELD_GRANT.search(t) for t in texts) and far <= reach else 0.0)
        if hits + bash > 0:
            share = min(1.0, (hits + bash) * CHALLENGE_DURATION)
            how = [f"{main} hits with the shield, {hits:.2f} hits/s"] if hits else []
            if bash:
                how.append(f"a Shield Bash after blocking one telegraphed boss hit every {PARRY_EVERY:g} s with Raise "
                           f"Shield (the Parry cadence the user called fair; the boss within the bash's {reach / 10:g} m "
                           "reach, MEDIUM: 0.8 m unarmed + Raise Shield's 1.4 m + the build's Melee Strike Range lines, "
                           "RESEARCH26 R26-63; the time raised isn't taken from the main skill)")
            return share, "; ".join(how) + f": Challenged {share:.0%} of the fight"
    why = [f"no off-hand (shield) hits from {main or 'the main skill'}"] if off_hand else []
    if raise_line:
        why.append(f"the boss {far / 10:g} m away, beyond the raised shield's {raise_line.group(1)} m")
    return 0.0, " and ".join(why) + ": not Challenged"


def boss_power(texts: list[str], stats: dict, distance: float | None = None,
               attack: bool | None = None, main: str | None = None) -> tuple[float, str]:
    """(The boss's Power with the build's Power lines, its basis). `distance`: the boss's distance in units (PoB's
    enemyDistance; POWER_FALLBACK_DISTANCE if None); `attack`: whether the main skill is an Attack (for "Hits with this
    Weapon"; None: from stats["_main_types"], else not counted); `main`: the main skill's name (for Runefather's
    Challenge from off-hand hits; None: stats["_main_name"])."""
    power, basis = presence_power(texts, stats, distance, attack)
    share, why = challenge_share(texts, stats, distance, main if main is not None else stats.get("_main_name"))
    if not why:
        return power, basis
    power += CHALLENGE_POWER * share
    told = (f"+{CHALLENGE_POWER * share:g} from Runefather's Challenge ({why}; +{CHALLENGE_POWER} while Challenged, "
            f"{CHALLENGE_DURATION:g} s each, LOW: poe2wiki and Mobalytics, no game data; added after any doubling, the lower reading, "
            "UNVERIFIED)")
    return power, (f"the boss's Power {power:g} ({basis}; {told})" if basis else f"the boss's Power {power:g} (20; {told})")


def presence_power(texts: list[str], stats: dict, distance: float | None = None,
                   attack: bool | None = None) -> tuple[float, str]:
    """boss_power's Presence lines: the doublings and Gruelling Madness."""
    doubled = any(POWER_DOUBLED.match(t) for t in texts)
    wasted_line = any(POWER_DOUBLED_WASTED.match(t) for t in texts)
    madness_line = any(MADNESS_POWER.match(t) for t in texts)
    if not (doubled or wasted_line or madness_line):
        return float(BOSS_POWER), ""
    radius = number(stats.get("PresenceRadius"))
    far = POWER_FALLBACK_DISTANCE if not distance else distance
    if radius < far:
        return float(BOSS_POWER), (f"the boss {far / 10:g} m away, outside your {radius / 10:.1f} m Presence: its Power "
                                   f"lines don't apply ({BOSS_POWER})")
    hits = hits_per_second(stats)
    parts = []
    share = 1.0 if doubled else 0.0
    if doubled:
        parts.append("Enemies in your Presence count as having double Power")
    elif wasted_line:
        if not any(WASTING_ON_HIT.match(t) for t in texts):
            parts.append("the Abyssal Wasting double-Power line with nothing inflicting Abyssal Wasting: no change")
        elif hits <= 0:
            parts.append("Abyssal Wasting from your hits, but the main skill doesn't hit: no change")
        else:
            share = 1.0 if any(WASTING_INFINITE.match(t) for t in texts) else min(1.0, hits * WASTING_DURATION)
            parts.append(f"double while the boss has Abyssal Wasting ({share:.0%} of the fight: {hits:.2f} hits/s, "
                         f"{WASTING_DURATION:g} s each)")
    power = BOSS_POWER * (1 + share)
    if madness_line:
        if attack is None:
            attack = "Attack" in (stats.get("_main_types") or set())
        stacks, why = madness_stacks(texts, stats, attack)  # (MECH96: shared with the Slowing Potency, + minions)
        power += stacks
        parts.append(f"+{stacks:g} from Gruelling Madness ({why})")
    return power, (f"the boss's Power {power:g} (20; " + "; ".join(parts) + f"; in your {radius / 10:.1f} m Presence, "
                   f"the boss {far / 10:g} m away; two doublings counted once and Madness added after, the lower "
                   "readings, UNVERIFIED)")


# Ice Crystal Life per Cold Resistance (MECH96; the open row "Ice Crystals have #% reduced maximum Life per #% Cold
# Resistance you have", 13.1 + 0.9). Eventide Petals' "(-3-3)% reduced" per 5% (PoB's amulet.lua 107; a negative roll
# reads as increased). PoB parses none of it (ModCache 8260-8261: nil) and has no "per N% Cold Resistance" tag
# (ModParser has only the missing-resistance form, 1658). PoB's crystal Life is IceCrystalLifeBase x the IceCrystalLife
# mods (CalcOffence 1724-1726; ModParser 692 "ice crystal life"), so the line is IceCrystalLife INC -N x floor(Cold
# Resistance / 5), at PoB's ColdResist (the resistance you have: capped; MEDIUM that "you have" means the capped value,
# not the uncapped total: UNVERIFIED, the line's sign decides which reading is the lower one). It moves the crystals'
# Life wherever a model reads PoB's IceCrystalLife (Creeping Chill's Chill from the crystal's Life, conditions'
# creeping_chill; Frost Wall / Frozen Locus / Midnight Zenith crystals). Floor per whole 5%: PoB's PerStat rounding.
CRYSTAL_LIFE_PER_RES = re.compile(r"^Ice Crystals have (-?\d+(?:\.\d+)?)% (reduced|increased) maximum Life per "
                                  r"(\d+)% Cold Resistance you have$", re.I)


def crystal_life_mods(texts: list[str], cold_res: float) -> tuple[list[dict], list[dict]]:
    """(mods, notes) for CRYSTAL_LIFE_PER_RES (the note above), at the build's Cold Resistance."""
    total, parts = 0.0, []
    for t in texts:
        m = CRYSTAL_LIFE_PER_RES.match(t.strip())
        if not m or float(m.group(3)) <= 0:
            continue
        each = float(m.group(1)) * (-1 if m.group(2).lower() == "reduced" else 1)
        steps = math.floor(max(0.0, cold_res) / float(m.group(3)))
        total += each * steps
        parts.append(f"{each:+g}% per {m.group(3)}% x {steps}")
    if not parts or total == 0:
        return [], []
    return [raw_mod("IceCrystalLife", "INC", total)], [{
        "label": "Ice Crystal Life from Cold Resistance*", "value": f"{total:+g}%", "confidence": "MEDIUM",
        "basis": (f"{'; '.join(parts)} at {cold_res:g}% Cold Resistance (PoB's ColdResist, capped): PoB parses none of "
                  "the line; it scales the crystals' Life (Creeping Chill's Chill, the crystals' durability)")}]


# Way of the Stonefist's "All damage with Attacks Contributes to Electrocution Buildup" (MECH97; HandWrapsUniqueLightning
# DamageCanElectrocute1, game stat all_attack_damage_can_electrocute, Stats 26250; COV48's carrier row). PoB parses none
# of it (ModCache 5612: the whole line left over), so it counted 0: an UNDERCOUNT for an Attack build (PoB's Electrocute
# ScalesFrom is empty, Data.lua buildupTypes, so without a "can Electrocute" source nothing builds it). (checked: every
# game table row holding stat 26250: Mods only HandWrapsUniqueLightningDamageCanElectrocute1 and its ModType
# AllAttackDamageElectrocutes; no passive or skill stat set; poe2db NOT checked.) No PoB wording parses whole with an
# Attack limit (a special line must match whole, ModParser 6666-6667), so the model adds PoB's own flags, the ones
# canDoAilment reads (CalcOffence 5012: <Type>CanElectrocute), one per damage type, on Attacks only (KeywordFlag Attack,
# CalcActiveSkill 659): all damage of an Attack Hit then builds Electrocute through PoB's own buildup.
ELECTROCUTE_ALL_ATTACK = re.compile(r"^All damage with Attacks Contributes to Electrocution Buildup$", re.I)


def electrocute_attack_mods(texts: list[str]) -> tuple[list[dict], list[dict]]:
    """(mods, notes) for ELECTROCUTE_ALL_ATTACK (the note above)."""
    if not any(ELECTROCUTE_ALL_ATTACK.match(t.strip()) for t in texts):
        return [], []
    return ([raw_mod(f"{kind}CanElectrocute", "FLAG", 1, keywords=["Attack"]) for kind in DAMAGE_TYPES],
            [{"label": "All Attack damage builds Electrocute*", "value": "on", "confidence": "MEDIUM",
              "basis": ("Way of the Stonefist's line, which PoB parses none of: every damage type of an Attack Hit counts "
                        "toward Electrocute buildup through PoB's own buildup (its <Type>CanElectrocute flags on Attacks)")}])


# Way of the Stonefist's "Attack Damage with Hits is Lucky while you are Surrounded" (MECH97; HandWrapsUniqueIncreased
# PhysicalDamagePercent1, group LuckyAttackDamageWhileSurrounded; COV48's carrier row). PoB parses it with leftover text
# (ModCache 6611), so it never applies it: an UNDERCOUNT where the build is Surrounded. PoB sets Condition:Surrounded itself
# (CalcPerform 525-527: only when the enemies needed come down to 1, "Require N fewer enemies to be Surrounded", and the
# boss stands within your Surrounded radius; KeywordPopups Surrounded: "at least 5 enemies within 3 metres"), so the model
# adds the mod PoB gives the same game stat on the Defy supports (SkillStatMap 1034, attack_damage_is_lucky_if_surrounded:
# LuckyHits FLAG under Condition:Surrounded), on Attacks only (the line's own words), and PoB decides when it holds; 5 adds
# within 3 m of you aren't modelled (the lower reading). (checked: every game table row holding stat 20945: Mods only
# HandWrapsUniqueIncreasedPhysicalDamagePercent1 and its ModType; GrantedEffectStatSets SupportDefyPlayer /
# SupportDefyPlayerTwo, which PoB reads itself through SkillStatMap; poe2db NOT checked.)
LUCKY_WHILE_SURROUNDED = re.compile(r"^Attack Damage with Hits is Lucky while you are Surrounded$", re.I)


def lucky_surrounded_mods(texts: list[str]) -> tuple[list[dict], list[dict]]:
    """(mods, notes) for LUCKY_WHILE_SURROUNDED (the note above)."""
    if not any(LUCKY_WHILE_SURROUNDED.match(t.strip()) for t in texts):
        return [], []
    return ([raw_mod("LuckyHits", "FLAG", 1, keywords=["Attack"], condition="Surrounded")],
            [{"label": "Attack damage Lucky while Surrounded*", "value": "while PoB counts you Surrounded",
              "confidence": "MEDIUM",
              "basis": ("Way of the Stonefist's line, which PoB parses none of: Attack Hit damage is Lucky while PoB's own "
                        "Surrounded condition holds (one enemy needed after 'Require N fewer enemies to be Surrounded', the "
                        "boss within your Surrounded radius; a lone boss alone doesn't Surround you otherwise)")}])


# Dexterity's Accuracy (MECH97; RESEARCH39 R39-14 and THE USER'S RULING, 21 Nov 2026 03:18, card: "tooltip ingame says
# +8, I trust that over PoB"). The game's own Dexterity tooltip says +8 Accuracy per point; PoB counts 6
# (Data.lua AccuracyPerDexBase = 6, CalcPerform 512, as 0.3.0's patch note does). Headline: the user's +8, through
# PoB's own per-point hook DexAccBonusOverride (CalcPerform 512: Dex x it x the inherent-attribute multiplier, so
# "Doubled inherent attribute bonuses" and "no Dexterity bonuses" lines keep working; minions' copy of your Accuracy,
# CalcPerform 1073, reads it too). Not set where a line of the build already sets the per-point value ("Dexterity's
# Accuracy Bonus instead grants +N to Accuracy Rating per Dexterity", ModParser 5686: that line wins). Tagged
# DEX_ACCURACY_TAG, so a play-guide row can leave it out for PoB's +6 (MECH-C's). The user's 88-Dex character's 1080
# Accuracy doesn't decide the per-point value (level, tree and gear add Accuracy too).
DEX_ACCURACY_USER = 8.0  # the user's rate, 21 Nov 2026 (the game's tooltip)
DEX_ACCURACY_POB = 6.0  # PoB's AccuracyPerDexBase (and 0.3.0's patch note): the row
DEX_ACCURACY_TAG = "DexAccuracyUser"
DEX_ACCURACY_LINE = re.compile(r"^Dexterity's Accuracy Bonus instead grants \+?\d+ to Accuracy Rating per Dexterity$", re.I)


def dex_accuracy_mods(texts: list[str], dex: float) -> tuple[list[dict], list[dict]]:
    """(mods, notes) for Dexterity's Accuracy at the user's +8 a point (the note above); none where a line sets it."""
    if any(DEX_ACCURACY_LINE.match(t.strip()) for t in texts):
        return [], []
    extra = (DEX_ACCURACY_USER - DEX_ACCURACY_POB) * max(dex, 0.0)
    return ([raw_mod("DexAccBonusOverride", "OVERRIDE", DEX_ACCURACY_USER, tag=DEX_ACCURACY_TAG)],
            [{"label": "Dexterity's Accuracy at +8 a point*", "value": f"+{extra:,.0f} Accuracy over PoB's",
              "confidence": "MEDIUM (the user's ruling, 21 Nov 2026: the game's tooltip)",
              "basis": (f"{dex:g} Dexterity x +{DEX_ACCURACY_USER:g} Accuracy each, the in-game tooltip the user trusts; "
                        f"PoB and 0.3.0's patch note give +{DEX_ACCURACY_POB:g} ({extra:,.0f} less Accuracy): the row")}])


# Gruelling Madness on the boss (MECH96; the open rows "Minions have N% chance to inflict Gruelling Madness on Hit" and
# the plan kw-gruelling-madness.md). KeywordPopups GruellingMadness: "The first Gruelling Madness on a target Slows their
# movement speed by 15%. Each additional Gruelling Madness instead increases the Slowing Potency of Debuffs on the
# targets by 10%, which affects both the first Gruelling Madness and any other Debuffs that are Slowing the target. A
# maximum of 10 ... Targets will lose 1 Gruelling Madness every 2 seconds that passes without more being inflicted."
# Sources (checked: Stats.json ids holding "gruelling", their Mods / PassiveSkills / skill stat-set users, game 26476662,
# kw-gruelling-madness.md; PoB's uniques: body.lua 188 The Auspex, mace.lua 98 Sadist's Mercy, staff.lua 64 the minion
# staff; nine more ids no Mod, passive or skill uses; poe2db not re-checked (UNVERIFIED that none is live elsewhere)):
# - "Enemies in your Presence gain N Gruelling Madness each second": kept at 10 while the boss is in your Presence;
# - "Hits with this Weapon inflict N Gruelling Madness": the main skill an Attack hitting at least once per 2 s: 10;
#   slower: N (LOW);
# - "Minions have N% chance to inflict Gruelling Madness on Hit" (an UNDERCOUNT before: read by nothing): N% x the
#   build's minion hits a second (stats["_minion_hits"], conditions.minion_hits: every group's minions; else the main
#   skill's PoB Minion.Speed x hit chance, one minion: the lower reading); at least one inflict per 2 s on average: 10
#   (MEDIUM: random gaps over 2 s drop a stack now and then, not counted); slower: the mean of one stack held 2 s per
#   inflict (LOW). One stack per minion hit (the line names no count).
# The ramp to 10 isn't counted (a fight's first seconds). PoB parses none of these lines (ModCache 7313, 8255-8257, 8719,
# 8728: nil or leftover text).
MADNESS_MINION = re.compile(r"^Minions have (\d+(?:\.\d+)?)% chance to inflict Gruelling Madness on Hit$", re.I)
MADNESS_POTENCY_MOD = "MECH_MADNESS_POTENCY"  # (bridge installBossSlow reads it on the player)
MADNESS_POTENCY_PER = 10.0


def madness_stacks(texts: list[str], stats: dict, attack: bool | None = None,
                   in_presence: bool = True) -> tuple[float, str]:
    """(Gruelling Madness held on the boss, how) from the build's sources (the note above). `in_presence`: whether the
    boss is in your Presence (the per-second line needs it); `attack` as boss_power's."""
    if attack is None:
        attack = "Attack" in (stats.get("_main_types") or set())
    hits = hits_per_second(stats)
    per_second = (max([int(m.group(1)) for t in texts if (m := MADNESS_PER_SECOND.match(t.strip()))] or [0])
                  if in_presence else 0)
    per_hit = (max([int(m.group(1)) for t in texts if (m := MADNESS_ON_HIT.match(t.strip()))] or [0])
               if attack and hits > 0 else 0)
    chance = sum(float(m.group(1)) for t in texts if (m := MADNESS_MINION.match(t.strip()))) / 100
    minion_hits = 0.0
    if chance > 0:
        if "_minion_hits" in stats:
            minion_hits = number(stats["_minion_hits"])
        else:
            hit_chance = number(stats.get("Minion.HitChance")) / 100 if stats.get("Minion.HitChance") is not None else 1.0
            minion_hits = number(stats.get("Minion.Speed")) * hit_chance
    inflicts = min(1.0, chance) * minion_hits
    if per_second:
        return float(MADNESS_MAX), f"kept at its {MADNESS_MAX} maximum (it gains {per_second} a second in your Presence)"
    if per_hit and hits >= 1 / MADNESS_DECAY:
        return float(MADNESS_MAX), f"kept at its {MADNESS_MAX} maximum ({per_hit} per hit, {hits:.2f} hits/s)"
    if inflicts >= 1 / MADNESS_DECAY:
        return float(MADNESS_MAX), (f"kept at its {MADNESS_MAX} maximum (minions: {chance:.0%} x {minion_hits:.2f} "
                                    f"hits/s = {inflicts:.2f} a second; MEDIUM)")
    if per_hit:
        return float(min(MADNESS_MAX, per_hit)), f"{per_hit} per hit, hits too slow to stack it (LOW)"
    if inflicts > 0:
        held = min(1.0, inflicts * MADNESS_DECAY)
        return held, (f"{held:.2f} on average (minions inflict {inflicts:.2f} a second, each held "
                      f"{MADNESS_DECAY:g} s: LOW)")
    return 0.0, "nothing inflicts it on the boss"


def madness_slow_mods(texts: list[str], stats: dict, distance: float | None = None,
                      attack: bool | None = None) -> tuple[list[dict], list[dict]]:
    """(mods, notes): Gruelling Madness's Slowing Potency on the boss (the note above): +10% per stack past the first,
    on every Slow on it (bridge installBossSlow: x(1 + N%) on the boss's own potency, its Unique 50% less included,
    before the 25% floor; MEDIUM that the two multiply: an increase to the target's potency and the Unique's "less").
    The first stack's own 15% movement Slow moves no hit rate: not counted. Defence only (the boss's hits)."""
    if not any(MADNESS_PER_SECOND.match(t.strip()) or MADNESS_ON_HIT.match(t.strip()) or MADNESS_MINION.match(t.strip())
               for t in texts):
        return [], []
    far = POWER_FALLBACK_DISTANCE if not distance else distance
    stacks, why = madness_stacks(texts, stats, attack, number(stats.get("PresenceRadius")) >= far)
    value = MADNESS_POTENCY_PER * max(0.0, stacks - 1)
    if value <= 0:
        return [], [{"label": "Gruelling Madness on the boss*", "value": f"{stacks:.2g} stacks", "confidence": "LOW",
                     "basis": f"{why}: no stack past the first, so no Slowing Potency (the first slows movement only)"}]
    return [raw_mod(MADNESS_POTENCY_MOD, "INC", value)], [{
        "label": "Gruelling Madness's Slowing Potency on the boss*", "value": f"+{value:g}%", "confidence": "MEDIUM",
        "basis": (f"{stacks:.3g} Gruelling Madness ({why}): +{MADNESS_POTENCY_PER:g}% Slowing Potency per stack past "
                  "the first on the boss's Chill, Temporal Chains and other Slows (PoB parses none of these lines: 0 "
                  "before); x the Unique boss's 50% less Slow, before the 25% speed floor; the first stack's movement "
                  "Slow not counted. It slows the boss's hits (survival, 'when Hit' sources), no damage")}]


def power_of(stats: dict, texts: list[str] | None = None) -> float:
    """The boss's Power for a model: stats["_boss_power"] (set by Assumptions.models / Conditions.evidence) when there,
    else boss_power from `texts` (or stats["_texts"]) at the fallback distance, else 20."""
    if "_boss_power" in stats:
        return float(stats["_boss_power"][0])
    found = texts if texts is not None else stats.get("_texts")
    return boss_power(list(found), stats)[0] if found else float(BOSS_POWER)


def power_mods(power: float) -> list[dict]:
    """PoB's own Power readers (warcry Power, "per enemy Power" lines, Harbinger of Madness) at the boss's Power."""
    extra = power - BOSS_POWER
    return [raw_mod("WarcryPower", "BASE", extra), raw_mod("Multiplier:EnemyPower", "BASE", extra)] if extra > 0 else []


# Commiserate (MECH98; PLANS7's plans/gs-commiserate-self-ailment.md, RESEARCH42 R42-13 HIGH (text) / MEDIUM (order);
# an OVERCOUNT where your self-ailment box was on, an UNDERCOUNT where none was). SupportCommiseratePlayer: "Ailments
# inflicted by Supported Skills have 40% more Magnitude if you are afflicted with that Ailment when inflicting it" and
# "When inflicting an Ailment with Supported Skill, remove that Ailment from yourself". Nothing is reflected (R42-13): the
# boost goes on the instance inflicted while you had that ailment, then yours is removed, so later ones get none until
# the boss puts it on you again. PoB (sup_dex.lua 1382-1388) gives the 40% MORE under your Condition:Bleeding / Ignited /
# Poisoned / Shocked / Chilled / Frozen, at whatever share our self-ailment box carries, and reads no removal. Per
# ailment X, from the boss's own applications on you (boss_hits.ailments_on_you: E landed a second, L s on you, the
# user's movement-dodge rate; worst case "lowest", a gain) and a = your main skill's applications a second (hits x PoB's
# <X>ChancePerHit; Chill's ChanceOnHit):
#   - boosted applications a second B = E (1 - e^(-a L)) (the first application while you're afflicted);
#   - Ignite, Shock, Chill, Bleed: the boosted instance is taken to hold the boss's X for min(1, B x its duration) (the
#     strongest one counts; Bleed's strongest-only UNVERIFIED); Poison stacks: B / a of the instances;
#   - your afflicted time a boss application drops from L to E[min(L, the wait for your next application)] = (1 -
#     e^(-a L)) / a: conditions' _self_ignited scales its boss and Grinning Immolation parts by (1 - e^(-a L)) / (a L).
# Mods: PoB's conditional 40% cancelled (x1/1.4 under the same Condition and KeywordFlag) and 40% x that share added,
# both on the main skill. PoB rounds each mod store's MORE product to 2 decimals (ModDB.lua MoreInternal) and the
# cancel sits in another store than the gem's 40%, so it lands as x0.71: up to 0.7% low while the box is on (probe
# POE2T5145, LOW). Where the build reflects X back to you (Self Immolation's Ignites, Overcharge's Shocks, the
# reflected-Poison line), each application re-afflicts you right after removing yours, so nearly every one is boosted:
# PoB's reading (the box's share) is kept there, labelled. Freeze on you stops your skills (you can't inflict while
# Frozen): not boosted (0). Your own non-reflect self sources (Grinning Immolation's crits) aren't added to E (an
# undercount, LOW).
COMMISERATE = "Commiserate"
COMMISERATE_MORE = 40.0
# ailment: (your PoB condition, chance field, duration field on the boss, PoB mod, KeywordFlag, stacks)
COMMISERATE_AILMENTS = {
    "Ignite": ("Ignited", "IgniteChancePerHit", "IgniteDuration", "AilmentMagnitude", "Ignite", False),
    "Shock": ("Shocked", "ShockChancePerHit", "ShockDuration", "EnemyShockMagnitude", None, False),
    "Chill": ("Chilled", "ChillChanceOnHit", "ChillDuration", "EnemyChillMagnitude", None, False),
    "Bleed": ("Bleeding", "BleedChancePerHit", "BleedDuration", "AilmentMagnitude", "Bleed", False),
    "Poison": ("Poisoned", "PoisonChancePerHit", "PoisonDuration", "AilmentMagnitude", "Poison", True),
}
COMMISERATE_FIELDS = tuple(sorted({"Speed", "HitChance"} | {f for v in COMMISERATE_AILMENTS.values() for f in v[1:3]}))


def commiserate_shares(rate_on_you: float, seconds_on_you: float, applies: float, duration: float, stacks: bool
                       ) -> tuple[float, float]:
    """(share of your X on the boss that is boosted, the factor on your afflicted time) for one ailment."""
    if rate_on_you <= 0 or seconds_on_you <= 0 or applies <= 0:
        return 0.0, 1.0
    first = 1 - math.exp(-applies * seconds_on_you)
    boosted = rate_on_you * first
    held = min(1.0, boosted / applies) if stacks else min(1.0, boosted * max(duration, 0.0))
    return held, first / (applies * seconds_on_you)


def commiserate_model(main_gems: set[str], main: Skill | None, stats: dict, on_you: dict[str, dict],
                      reflected: set[str]) -> tuple[list[dict], list[dict], dict[str, float]]:
    """(mods, notes, {your condition: factor on your afflicted time}) for Commiserate on the main skill (the note above).
    `stats`: COMMISERATE_FIELDS of the main skill; `on_you`: boss_hits.ailments_on_you; `reflected`: the ailments the
    build reflects back to you."""
    if COMMISERATE not in main_gems or main is None:
        return [], [], {}
    hps = number(stats.get("Speed")) * min(number(stats.get("HitChance")) or 100.0, 100.0) / 100.0
    mods, parts, cut = [], [], {}
    for ailment, (cond, chance, dur, name, keyword, stacks) in COMMISERATE_AILMENTS.items():
        if ailment in reflected:
            parts.append(f"{ailment}: reflected back to you, so nearly every application is boosted (PoB's reading, at "
                         "your self-ailment box's share)")
            continue
        got = on_you.get(ailment) or {}
        applies = hps * min(number(stats.get(chance)), 100.0) / 100.0
        held, factor = commiserate_shares(number(got.get("rate")), number(got.get("seconds")), applies,
                                          number(stats.get(dur)), stacks)
        kw = [keyword] if keyword else None
        mods.append(raw_mod(name, "MORE", 100 * (1 / (1 + COMMISERATE_MORE / 100) - 1), skill=main.name, condition=cond,
                            keywords=kw))
        if held > 0:
            mods.append(raw_mod(name, "MORE", COMMISERATE_MORE * held, skill=main.name, keywords=kw))
        if factor < 1:
            cut[cond] = factor
        parts.append(f"{ailment}: the boss's {number(got.get('rate')) * 60:.1f} a minute on you ({number(got.get('seconds')):g}"
                     f" s each), yours {applies:.2f} a second: {held:.0%} of the boss's {ailment} boosted"
                     + (f", your own afflicted time x{factor:.2f}" if factor < 1 else ""))
    note = {"label": "Commiserate: 40% more Magnitude on the Ailment you inflict while you have it*",
            "value": f"{sum(1 for m in mods if not m.get('condition'))} of {len(COMMISERATE_AILMENTS)} ailments boosted",
            "confidence": "MEDIUM (R42-13); the boss's ailments on you MEDIUM-LOW (ailments_on_you)",
            "basis": ("the boost goes on the instance you inflict while afflicted, then yours is removed (R42-13: no "
                      "reflection): " + "; ".join(parts) + ". PoB's 40% under your own condition is replaced by these "
                      "shares. Freeze on you stops your skills: not boosted"),
            "play": "Let the boss's ailments land on you and answer each with the supported skill"}
    return mods, [note], cut


# Soaring Ground's Evasion and Full-Life damage (MECH98; the manager 04:00 from MECHC49: "Sacred Unity's trail's Evasion
# and Full-Life damage are yours (reuse conditions.sacred_unity_onslaught's uptime)"; an UNDERCOUNT: PoB parses the
# trail line to nothing). KeywordPopups SoaringGround: "30% increased Evasion Rating, 40% increased damage while on Full
# Life, and Onslaught to you or Allies standing on it. These effects Linger for 1 second". At the trail's share of the
# fight (conditions.sacred_unity_onslaught: one empowered Projectile use per Owl Feather, 6 s + 1 s Linger, standing on
# it, MEDIUM-LOW): "N% increased Evasion Rating" x the share (an average of increased Evasion: the lower bound of the
# Evade chance's mean, LOW) and "N% increased Damage while on Full Life" x the share, which PoB applies under your own
# Full Life condition (the conditionFullLife box's share; the two taken as independent, LOW).
SOARING_EVASION, SOARING_FULL_LIFE = 30.0, 40.0


def soaring_ground_mods(trail: tuple[float, str] | None) -> tuple[list[dict], list[dict]]:
    """(mods, notes) for Soaring Ground's Evasion and Full-Life damage at `trail` (sacred_unity_onslaught's (share, how))."""
    if trail is None:
        return [], []
    share, how = trail
    note = {"label": "Soaring Ground: Evasion and Full-Life damage*", "confidence": "MEDIUM-LOW",
            "value": f"{share:.0%} of the fight on the trail",
            "basis": (f"{how}; on it {SOARING_EVASION:g}% increased Evasion Rating and {SOARING_FULL_LIFE:g}% increased "
                      "damage while on Full Life (KeywordPopups SoaringGround), each x that share; the damage under your "
                      "Full Life box (independent of the trail, LOW). PoB parses the trail to nothing (0 before)"),
            "play": ("Fire your Owl-Feather-empowered Projectile skill and stand on its trail: without it +0%; with it "
                     f"+{SOARING_EVASION * share:.0f}% Evasion and +{SOARING_FULL_LIFE * share:.0f}% damage on Full Life")}
    if share <= 0:
        return [], [note]
    return [line("1% increased Evasion Rating", SOARING_EVASION * share),
            line("1% increased Damage while on Full Life", SOARING_FULL_LIFE * share)], [note]


# Varashta's Blessing (MECH98; PLANS7's plans/gs-varashtas-blessing.md, RESEARCH41 R41-10; an UNDERCOUNT: nothing read
# it, PoB has no statMap, sup_int.lua 8513). SupportVarashtasBlessingPlayer's constant stat
# support_djinn_lineage_damage_+%_final_per_different_command_in_last_8_seconds 10, whose displayed text (gem_stat_
# descriptions) is "Supported Skills deal {0}% more Damage for each different Command Skill you have used in the last 15
# seconds": the text is what the game shows (R41-10, MEDIUM): 15 s the headline, the stat id's 8 s a row. The count, from
# the build (CLAUDE.md's no-flat-rate rule; a build that takes the support presses its Commands, a play strategy):
#   - Commands the build already presses (build.item_presses: the djinn Commands djinn_commands_model found worth their
#     cast) count min(1, window x their presses a second), at no extra cost;
#   - the build's other Commands (its djinns' Commands not pressed for their own damage; its minions' Commands, COMMANDS,
#     on their cooldown over your Cooldown Recovery) are pressed once per max(cooldown, window) just to stay counted:
#     each counts 1 and costs the main skill its cast (DJINN_COMMAND_CAST 0.4 s; a minion Command its own cast, as
#     COMMANDS lists) a period; pressed only where the gain beats that cost (x1.10 against the time lost), each a press
#     under the button cap (returned for build.item_presses). Ruzhan's Zealotry isn't pressed (the djinn's own): not a
#     Command you use (not counted, labelled). A Command whose minion is fallen isn't counted out (a small overcount for
#     death-fed builds, as MECHB39).
# x(1 + 10% x the count) more Damage on the supported main skill (its own line, skill-scoped). Only the main skill's
# group is read (a side skill's support: not counted, an undercount).
VARASHTA = "Varashta's Blessing"
VARASHTA_MORE = 10.0  # % per different Command (the gem's constant stat; every level)
VARASHTA_WINDOW, VARASHTA_WINDOW_ROW = 15.0, 8.0  # s: the displayed text (headline) and the stat id (a row): R41-10


def _varashta_count(window: float, pressed: dict[str, float], others: list[tuple[str, float, float]], speed_share: float
                    ) -> tuple[float, float, dict[str, float], list[str]]:
    """(count, main-skill time lost, extra presses {Command: a second}, how) at a `window` s reading."""
    count, lost, presses, how = 0.0, 0.0, {}, []
    for name, rate in sorted(pressed.items()):
        share = min(1.0, window * rate)
        count += share
        how.append(f"{name} (pressed for its own damage, every {1 / rate:.3g} s" + (f", {share:.0%} of windows)" if share < 1 else ")"))
    for name, cooldown, cast in others:
        if name in pressed:
            continue
        period = max(cooldown, window, cast)
        cost = cast / period * speed_share
        if (1 + VARASHTA_MORE / 100 * (count + 1)) * (1 - lost - cost) <= (1 + VARASHTA_MORE / 100 * count) * (1 - lost):
            how.append(f"{name}: its {cast:g} s cast a {period:.3g} s costs more than it gains (not pressed)")
            continue
        count, lost = count + 1, lost + cost
        presses[name] = 1 / period
        how.append(f"{name} pressed every {period:.3g} s ({cast:g} s cast: {cost:.1%} of the main skill's time)")
    return count, lost, presses, how


def varashta_blessing_model(main_gems: set[str], main: Skill | None, skills: list[Skill], texts: list[str],
                            pressed: dict[str, float], main_share: float = 1.0
                            ) -> tuple[list[dict], list[dict], dict[str, tuple[float, str]]]:
    """(mods, notes, presses {Command: (a second, how)}) for Varashta's Blessing on the main skill (see the note above).
    `pressed`: the Commands the build already presses {name: a second} (build.item_presses); `main_share`: the main
    skill's share of the fight (its time a cast takes from)."""
    if VARASHTA not in main_gems or main is None:
        return [], [], {}
    others: list[tuple[str, float, float]] = []
    djinns = {s.name for s in skills if s.name in DJINNS.values()}
    for command in djinn_commands_available(djinns, texts):
        if command.pressed:
            others.append((command.name, command.cooldown or BRAND_DETONATION / BRAND_LIMIT, DJINN_COMMAND_CAST))
    seen: set[str] = set()
    for skill in skills:
        if not skill.summon or not number(skill.summon.get("limit")):
            continue
        for minion, commands in COMMANDS.items():
            if minion in skill.name and minion not in seen:
                seen.add(minion)
                others += [(n, cd / (skill.cooldown_recovery or 1.0), cast) for n, cd, cast in commands]
    pressed = {n: r for n, r in pressed.items() if r > 0 and any(n == o[0] for o in others)}
    share = min(max(main_share, 0.0), 1.0)
    count, lost, extra, how = _varashta_count(VARASHTA_WINDOW, pressed, others, share)
    row, row_lost, _, _ = _varashta_count(VARASHTA_WINDOW_ROW, pressed, others, share)
    more = VARASHTA_MORE * count
    row_more = VARASHTA_MORE * row
    net = (1 + more / 100) * (1 - lost) - 1
    net_row = (1 + row_more / 100) * (1 - row_lost) - 1
    note = {"label": "Varashta's Blessing: more Damage per different Command used*", "value": f"{net:+.1%} on the main skill",
            "confidence": "MEDIUM (the count from the build's Commands); 15 s vs 8 s MEDIUM (R41-10)",
            "basis": (f"{VARASHTA_MORE:g}% more a different Command used in the last {VARASHTA_WINDOW:g} s (the game's "
                      f"displayed text; the stat id says 8 s): {count:.2f} Commands, +{more:.0f}% more"
                      + (f", less {lost:.1%} of the main skill's time for the casts" if lost else "") + ": "
                      + ("; ".join(how) if how else "the build has no Command to press")
                      + f". The 8 s reading (the stat id): {row:.2f} Commands, {net_row:+.1%}. PoB has no mapping "
                      "for the stat (0 before)"),
            "play": (f"Use each of your {count:.0f} Commands at least once every {VARASHTA_WINDOW:g} s: without them "
                     f"+0%; with them {net:+.1%} damage on {main.name}" if count else
                     "No Command to use: Varashta's Blessing adds nothing here")}
    if count <= 0:
        return [], [note], {}
    mods = [line("1% more Damage", more, skill=main.name)]
    if lost > 0:
        mods.append(line("1% more Attack and Cast Speed", -100 * lost, skill=main.name))
    presses = {n: (r, f"{n} every {1 / r:.3g} s for Varashta's Blessing") for n, r in extra.items()}
    return mods, [note], presses


# Blind while the Shield is raised (MECHC21, 14 Nov 2026; plans/term-blind-enemies.md G4 with term-raised.md). Bastion of
# Light (notable): "Blind Enemies 3 metres in front of you every 0.25 seconds while your Shield is raised"
# (inflict_blind_on_enemies_within_x_meters_while_shield_is_raised; PoB leaves it as text, ModCache's {nil}, so it never
# set the Blinded box: 0 before, an UNDERCOUNT). Raise Shield (ActiveSkills shield_block, every PoB shield base's
# "Grants Skill: Raise Shield") raises it; the share of the fight it's raised is the build's own play: a player who takes
# the line taps the shield once per Blind (KeywordPopups Blind: 4 s by default, x the build's Blind Duration lines,
# duration_scale), each pulse renewing it, so the boss is Blinded all fight while it stands within the line's reach, and
# each tap takes RAISE_TAP s of the main skill's time. The boss further than the reach (the build's distance choice): no
# taps, 0. No Raise Shield (no shield): 0, labelled. Raise Shield is item-granted, so it isn't a button
# (constraints.player_buttons). The tap's own defence (Block all blockable hits, no Evasion while raised) and its shield
# bash's damage aren't counted (LOW). Bastion's other line (Raise Shield inflicts Parried) is the ledger's
# (bastion-of-light-parried), which assumes the same one raise per 4 s.
RAISE_SHIELD = "Raise Shield"
RAISED_BLIND = re.compile(r"\bblind\b.*\bwhile (?:your )?shield is raised", re.I)
RAISED_REACH = re.compile(r"(\d+(?:\.\d+)?) metres in front of you", re.I)
# A tap: the shield bash's 550 ms (PoB ShieldBlockPlayer attackTime; the game files give its channel CastTime 1000 ms),
# taken as one raise and release; a pulse every 0.25 s needs at least 0.25 s held. How long a tap really takes: LOW
# (UNVERIFIED in game)
RAISE_TAP = 0.55
BLIND_SECONDS = 4.0  # KeywordPopups Blind (conditions.DEBUFF_DURATION)
# The taps are presses (THE USER, 14 Nov ~02:30: an item-granted skill the build actually presses counts toward the button
# cap, "Count it if used"; AUDIT31 A31-4). The search can turn them off on a build (build.objective.raised_taps = False,
# RAISED_TAPS: a build at its cap drops Bastion's Blind and the taps' time); with them on, the build's tap rate is on
# build.item_presses ({skill: (uses a second, how)}; ITEM_PRESSES, set by Assumptions) for constraints.player_buttons
# (SEARCH18) to count Raise Shield as a button. The play guide's "with the taps / without the taps" row: play_guide.raised_row.
RAISED_TAPS = "raised_taps"
ITEM_PRESSES = "item_presses"


def raised_taps_on(build) -> bool:
    """Does the build tap Raise Shield for its raised-shield lines (the search's switch, RAISED_TAPS; on unless set)?"""
    return getattr(getattr(build, "objective", None), RAISED_TAPS, True) is not False


# Window to Paradise's Exposure while raised (MECH98; PLANS6's plans/un-window-to-paradise.md, an OVERCOUNT before):
# "Inflict Elemental Exposure to Enemies 3 metres in front of you / for 4 seconds, every 0.25 seconds while raised"
# (Mods UniqueRaiseShieldApplyExposure1, stat unique_shield_window_of_paradise_apply_elemental_exposure_while_raised;
# PoB's unique text splits it in two lines, Uniques/shield.lua 135-136, and parses neither). Before, conditions.
# _exposure_source read the first half alone and gave the boss Exposure ALL FIGHT within 3 m, shield raised or not, with
# no tap, time or button. Now it is a raised-shield line like Bastion of Light's Blind: one Raise Shield tap per
# Exposure duration (the line's own "for N seconds", 4 s; Exposure Duration lines not read, as conditions.
# EXPOSURE_DURATION: more taps, the lower reading), each tap RAISE_TAP s of the main skill's time and a button press;
# both lines worn: one tap renews both (the shorter duration sets the period). A main skill that holds the shield
# raised all fight (recovery.ACTIVE_BLOCK_CHANNELS, `held`) needs no taps. The boss beyond the line's reach (the
# build's distance): none. (checked: Stats.json ids holding "exposure" with raise / front / metre / shield / block: only
# that one stat, build 26650308; PLANS6: one mod in stat.py; poe2db's Window to Paradise page agrees on every line)
RAISED_EXPOSURE = re.compile(r"\bexposure\b.*\bmetres in front of you", re.I)
RAISED_WHILE = re.compile(r"\bevery \d+(?:\.\d+)? seconds while raised\b", re.I)
RAISED_EXPOSURE_FOR = re.compile(r"\bfor (\d+(?:\.\d+)?) seconds, every \d+(?:\.\d+)? seconds while raised", re.I)
EXPOSURE_SECONDS = 4.0  # KeywordPopups Exposure (conditions.EXPOSURE_DURATION)


def raised_exposure_lines(texts: list[str]) -> list[str]:
    """Window to Paradise's Exposure line(s), when its "every N seconds while raised" half is there too (split or joined)."""
    if not any(RAISED_WHILE.search(t) for t in texts):
        return []
    return [t for t in texts if RAISED_EXPOSURE.search(t) and not RAISED_BLIND.search(t)]


def raised_lines(texts: list[str]) -> bool:
    """Does the build hold a line that needs its shield raised (Bastion of Light's Blind, Window to Paradise's Exposure)?"""
    return any(RAISED_BLIND.search(t) for t in texts) or bool(raised_exposure_lines(texts))


@dataclass(frozen=True)
class RaisedPlan:
    blind: float  # share of the fight the boss is Blinded by the raised-shield line
    lost: float  # share of the main skill's time spent raising the shield
    how: str
    taps: float = 0.0  # Raise Shield presses a second (a button: ITEM_PRESSES)
    exposure: float = 0.0  # share of the fight the boss is Exposed by Window to Paradise (MECH98)
    raised_exposure: bool = False  # the build holds Window to Paradise's raised Exposure line


def raised_plan(skills: list[Skill], texts: list[str], metres: float, taps: bool = True,
                held: str = "") -> RaisedPlan:
    """How the build raises its shield for its raised-shield lines ("Blind ... while your Shield is raised", Bastion of
    Light; "Inflict Elemental Exposure ... every 0.25 seconds while raised", Window to Paradise): one tap per debuff
    duration while the boss is within a line's reach (`metres`, the build's distance), else none; `held`: the main skill
    that holds the shield raised all fight (no taps)."""
    lines = [t for t in texts if RAISED_BLIND.search(t)]
    exposed = raised_exposure_lines(texts)
    if not lines and not exposed:
        return RaisedPlan(0.0, 0.0, "")
    what = " and ".join(w for w, on in (("Blind", lines), ("Exposure", exposed)) if on)
    label = f"{what} while your Shield is raised"

    def plan(blind: float, lost: float, how: str, tap: float = 0.0, exposure: float = 0.0) -> RaisedPlan:
        return RaisedPlan(blind, lost, how, tap, exposure, bool(exposed))

    if not any(s.name == RAISE_SHIELD for s in skills):
        return plan(0.0, 0.0, f"{label}: the build has no Raise Shield (no shield), so 0")

    def reach_of(found: list[str]) -> float:
        if not found:
            return -math.inf
        return max((float(m.group(1)) for t in found if (m := RAISED_REACH.search(t))), default=math.inf)

    reach_blind, reach_exposure = reach_of(lines), reach_of(exposed)
    near_blind, near_exposure = metres <= reach_blind, metres <= reach_exposure
    reach = max(reach_blind, reach_exposure)
    if not (near_blind or near_exposure):
        return plan(0.0, 0.0, f"{label} reaches {reach:g} m in front of you and the boss stands {metres:g} m away: no "
                              f"taps, 0 (closer: up all fight)")
    if held:
        return plan(float(near_blind), 0.0, f"{label}: the main skill ({held}) holds the shield raised all fight, so the "
                                             f"boss within reach ({metres:g} m away) is under it all fight with no taps",
                    exposure=float(near_exposure))
    if not taps:
        return plan(0.0, 0.0, f"{label}: the build doesn't tap Raise Shield (a button: the search left it out, e.g. at "
                              "the button cap), so 0 and no time lost")
    blind_for = BLIND_SECONDS * duration_scale(texts, "blind") if near_blind else 0.0
    exposure_for = max((float(m.group(1)) for t in texts if (m := RAISED_EXPOSURE_FOR.search(t))),
                       default=EXPOSURE_SECONDS) if near_exposure else 0.0
    periods = [(d, n) for d, n in ((blind_for, "Blind"), (exposure_for, "Exposure")) if d > 0]
    if not periods:
        return plan(0.0, 0.0, f"{label}: Blind lasts 0 s with the build's lines, so 0")
    duration, which = min(periods)
    lost = min(RAISE_TAP / duration, 1.0)
    under = " and ".join(w for w, d in (("Blinded", blind_for), ("Exposed", exposure_for)) if d > 0)
    renewed = " and ".join(n for _, n in periods)
    return plan(1.0 if blind_for > 0 else 0.0, lost, (
        f"tap Raise Shield once every {duration:g} s (the {which}'s duration) with the boss within "
        f"{'' if reach == math.inf else f'{reach:g} m '}in front of you ({metres:g} m away): each pulse renews the "
        f"{renewed}, so the boss is {under} all fight; each tap takes {RAISE_TAP:g} s ({lost:.1%} of the main skill's "
        f"time, counted; LOW: a tap's length is UNVERIFIED). Raise Shield is a button here (pressed {1 / duration:.2f} "
        f"times a second). Without the taps: no {what} and no time lost"),
        1 / duration, 1.0 if exposure_for > 0 else 0.0)


# Bastion of Light's other line, "Raise Shield inflicts Parried for N seconds on Hit" (MECHC25; COV27's item (d)): each
# tap of raised_plan leaves the boss Parried N s (PARRIED_MORE, 50% more Attack damage taken), so the main skill's
# Attack hits land on a Parried boss min(1, N / the tap period) of the time; a main skill that consumes Parried
# (PARRY_CONSUMERS) gains on one hit per tap. With the boss out of reach or the taps off: none (before, the ledger's
# bastion-of-light-parried gave "25% more Attack Damage while holding a Shield" always: an OVERCOUNT then). Counted only
# while that pob_gap entry no longer translates the line (ledger.translate is None: COV-A turns it into a model entry),
# so it is never counted twice. With Parry / Refutation in the build too: not counted here (one Parried debuff; the
# parry model's box is kept), an undercount, LOW. The tap period is the Blind's (raised_plan): MEDIUM-LOW, as there.
RAISED_PARRIED = re.compile(r"^raise shield inflicts parried for (\d+(?:\.\d+)?) seconds on hit$", re.I)


def raised_parried(plan: RaisedPlan, texts: list[str], main: Skill, hps: float = 0.0,
                   consumes: bool = False, keep: float = 0.0) -> tuple[float, str]:
    """(share of the main skill's hits on a Parried boss, how) from "Raise Shield inflicts Parried ..." at the plan's taps."""
    from builder.ledger import translate

    found = [(t, float(m.group(1))) for t in texts if (m := RAISED_PARRIED.search(t.strip()))]
    if not found or plan.taps <= 0:
        return 0.0, ""
    if translate(found[0][0]) is not None:
        return 0.0, "Raise Shield inflicts Parried: counted by the ledger's entry (bastion-of-light-parried), not here"
    if not main.attack:
        return 0.0, "Raise Shield inflicts Parried: Parried raises only Attack damage taken, and the main skill isn't an Attack"
    seconds = max(n for _, n in found)
    share = min(1.0, seconds * plan.taps)
    per = 1 / (1 - min(max(number(keep), 0.0), 0.99))  # (MECH89: hits a tap's Parried feeds, parried_keep)
    box = min(share, plan.taps * per / hps) if consumes and hps > 0 else share
    return box, (f"each Raise Shield tap ({plan.taps:.2f} a second) leaves the boss Parried {seconds:g} s: "
                 f"{box:.0%} of the main skill's hits land on a Parried boss (50% more Attack damage taken)"
                 + ((" (the main skill consumes Parried: " + (f"{per:.2f} hits per tap gain)" if per > 1
                                                                  else "one hit per tap gains)")) if consumes else "")
                 + "; without the taps: none")


def raised_model(skills: list[Skill], texts: list[str], metres: float, main: Skill | None,
                 taps: bool = True, hps: float = 0.0, consumes: bool = False,
                 keep: float = 0.0, held: str = "") -> tuple[list[dict], list[dict]]:
    """The main skill's time spent tapping the shield (raised_plan; the Blinded box itself is conditions'), and the
    Parried its taps inflict (raised_parried)."""
    if main is None or main.name == RAISE_SHIELD:
        return [], []
    plan = raised_plan(skills, texts, metres, taps, held)
    if not plan.how:
        return [], []
    blinds = any(RAISED_BLIND.search(t) for t in texts)
    what = "Blind / Exposure" if blinds and plan.raised_exposure else "Exposure" if plan.raised_exposure else "Blind"
    notes = [{"label": f"{what} while your Shield is raised (how the build raises it)",
              "value": f"{max(plan.blind, plan.exposure):.0%} of the fight",
              "basis": plan.how, "confidence": "LOW" if plan.lost > 0 else "theory"}]
    mods = []
    if any(s.name in PARRY_SKILLS for s in skills):
        box, how = 0.0, ("Raise Shield inflicts Parried: the build's Parry / Refutation already Parries the boss (one "
                         "debuff), so its taps add none here (an undercount, LOW)") if any(
            RAISED_PARRIED.search(t.strip()) for t in texts) else ""
    else:
        box, how = raised_parried(plan, texts, main, hps, consumes, keep)
    if box > 0:
        mods.append(line("1% more Attack Damage", 100 * PARRIED_MORE * box, skill=main.name))
    if how:
        notes.append({"label": "Parried from Raise Shield (Bastion of Light)", "value": f"{box:.0%} of the main skill's hits",
                      "basis": how, "confidence": "LOW" if box > 0 else "theory"})
    if plan.lost > 0:
        mods.append(line("1% more Attack and Cast Speed", -100 * plan.lost, skill=main.name))
    return mods, notes


# ===================================================================================================================
# MECH-B (skills and damage sources: projectiles, triggered skills, repeats, minions, totems). New MECH-B models go below.
# ===================================================================================================================

# Returning projectiles on a lone boss (MECHB1, 12 Nov 2026; FIX_QUEUE "Chain / fork / split / pierce / return").
# Game files, KeywordPopups Return: "Projectiles which Return will Return to the entity which originated them after
# reaching the end of their travel, or on hitting a final target". PoB counts one boss hit per projectile and never sets
# its ReturningProjectile condition, so a return's second hit is missing (an undercount). The sources (checked: every
# Stats.json id holding "return" with "projectile" or "arrow" (12 ids), each looked up in Mods, PassiveSkills,
# GrantedEffectStatSets and GrantedEffectStatSetsPerLevel; ActiveSkills descriptions holding "return"; PoB's ModCache;
# second source: the FIX_QUEUE research of 11 Nov (poe2db, poe2wiki, stratlore 0.5.4)):
#   - Breachlord's Amalgam (support; projectiles_return + returning_projectiles_always_pierce; it adds a 6 s cooldown
#     with 3 uses, which PoB already charges);
#   - Soaring Midnight (Nightfall's granted skill; the same two stats; pierces 3 targets base);
#   - Cadiro's Gambit: "Each Arrow fired is a Crescendo, Splinter, Reversing, Diamond, Covetous, or Blunt Arrow", and
#     KeywordPopups UniqueArrowModifierPierceReturn: "Reversing Arrows Pierce all targets and Return to you" (1 arrow in
#     6, the six assumed equally likely: UNVERIFIED);
#   - Ironbound's "Arrows Return if they have Pierced a target which had Fully Broken Armour" (counted while the boss's
#     Armour is Fully Broken, through PoB's own condition, which the search weighs by its uptime);
#   - Drillneck's "Attack Projectiles Return if they Pierced at least N times" (N = 3 or 4): 0 on a lone boss, since a
#     projectile pierces each target once (checked: KeywordPopups Pierce "pass through a target while still damaging
#     them" and Chain "Enemies cannot be targeted more than once"; poe2wiki via the FIX_QUEUE research: copies can't hit
#     a previous target).
#   Stats with no user in the current game files (checked: the same four tables plus GrantedEffectQualityStats):
#   attack_projectiles_return, arrows_that_pierce_also_return, arrows_from_third_firing_point_return,
#   projectile_return_%_chance, ice_spear_and_ball_lightning_projectiles_return, support_return_projectile_damage_+%_final,
#   active_skill_returning_projectile_damage_+%_final. Spectral Throw and Venom Gyre return in their ActiveSkills
#   descriptions but have no skill gem (SkillGems x BaseItemTypes) and no PoB skill; Spiral Throw's gem is "[DNT-UNUSED]".
# The rule (LOW, UNVERIFIED: stratlore 0.5.4 says a return allows one more collision with targets already hit; no game
# file says so): a returning projectile hits the boss a second time only if it passed through it on the way out (it
# pierced it), at the outgoing pierce chance (PoB's PierceCount, capped at 1). One that stops on the boss returns from
# it and isn't counted again. The returned hit has pierced the boss, so the "after piercing" gem lines apply to it:
# Pierce I's -20% (support_pierce_projectile_damage_+%_final_if_pierced_enemy), Pierce III's -20% per pierced target,
# and Frostbolt's and High Velocity Rounds' quality (+1% per quality, active_skill_projectile_damage_+%_final_if_pierced_
# enemy, GrantedEffectQualityStats). Drillneck's increased damage per pierce isn't read on the returned hit (a small
# undercount).
BREACHLORDS_AMALGAM = "Breachlord's Amalgam"
SOARING_MIDNIGHT = "Soaring Midnight"
CADIRO_ARROWS = re.compile(r"^Each Arrow fired is a Crescendo, Splinter, Reversing, Diamond, Covetous, or Blunt Arrow$", re.I)
CADIRO_REVERSING_SHARE = 1 / 6
IRONBOUND_RETURN = re.compile(r"^Arrows Return if they have Pierced a target which had Fully Broken Armour$", re.I)
PIERCE_TIMES_RETURN = re.compile(r"^Attack Projectiles Return if they Pierced at least (\d+) times", re.I)
# (MECHB37; COV40's route) Passthrough Rounds' "Projectiles Pierce enemies with Fully Broken Armour": PoB reads it as
# PierceCount +1 under the PLAYER's Condition ArmourFullyBroken (ModCache 8987), which nothing sets (checked: PoB sets only
# the enemy's, ConfigOptions 1688-1694; builder/ and bridge.lua: no "ArmourFullyBroken"), so it never applies. On a lone
# boss a pierce adds a hit only through a return (above), so it is read here: while the boss's Armour is Fully Broken
# every projectile pierces it, so Ironbound's row (already only against Fully Broken Armour) pierces at 100%, and the other
# return sources get the missing pierce share as "1% more Damage against Enemies with Fully Broken Armour" (the search
# weighs it by the boss's Fully Broken uptime, as Ironbound's).
PIERCE_BROKEN = re.compile(r"^Projectiles Pierce enemies with Fully Broken Armour$", re.I)
AFTER_PIERCE_MORE = {"Pierce I": -20.0, "Pierce III": -20.0}  # the gems' game-file values, at one pierced target
AFTER_PIERCE_QUALITY = frozenset({"Frostbolt", "High Velocity Rounds"})  # +1% more per quality after piercing
# (MECHB63; RESEARCH59 R59-1, research/return-rehit-r59.md, MEDIUM: a 0.5.4 projectile guide, three 0.5.x build guides
# and the PoE1 rule agree, none disagrees; no GGG statement) the rule above stands, and projectiles fired together get at
# most ONE return hit on a target between them. The "1% more Damage" here adds one returned hit per hit PoB's base
# counts, and PoB's base counts one projectile a set for every skill that can Return (checked: the only skillData
# dpsMultiplier in PoB's skill data is Bonestorm's stages (act_int 1866), a Physical skill Breachlord's Amalgam can't
# support (minion.lua 1404 only resets it); PoB's Modules also set it: CalcMirages 379 (x 1 / cooldown on a mirage's
# main skill) and ConfigOptions 538-539 (two Blade Vortex spectres' skills), none a Return skill's simultaneous set: the manager,
# 25 Nov 03:05); Barrage's "DPS" MORE counts sequential repeats, each its own set with its own return: UNVERIFIED). So one
# return a set. (MECHB65, MECHB63's leftover) the models that count more SIMULTANEOUS projectiles of one use on the boss:
# the Merging crossbow fragments (shotgun_fragments_share: x N on the hit, the main skill) are the ones a return source
# meets (Breachlord's Amalgam on Galvanic Shards / Permafrost Bolts, Cold / Lightning; Cadiro's and Ironbound's arrows
# are Bow attacks, no fragments) (checked: every ProjectileCount reader in models.py, 25 Nov; a model counting
# projectiles without reading ProjectileCount would be missed: UNVERIFIED past that grep); Salvo's random directions and
# the Nova circle count at most one projectile a group (the group rule); Frost Darts' / crossbow sequences are fired one
# after another (each its own set and return, as Barrage's). For the fragments the return's "1% more" multiplied their
# x N too: N fragments returning merged. Whether returned fragments Merge again is UNVERIFIED (RESEARCH question), so
# the headline takes R59-1's rule as written, ONE returned fragment for the fragments fired together (the return's more
# / N, the lower reading), and all N merged on the return the row.
RETURN_RULE = ("a returned projectile hits the boss again only if it pierced it on the way out, at most one returned hit "
               "for projectiles fired together (MEDIUM: RESEARCH59 R59-1, guides and the PoE1 rule; no game file or GGG "
               "statement says so)")


def returned_hit_factor(main: Skill, group_gems: list[dict]) -> tuple[float, list[str]]:
    """A returned hit's damage against the outgoing hit's: the "after piercing" lines of the main skill's group."""
    factor, why = 1.0, []
    for gem in group_gems:
        if not gem.get("enabled", True):
            continue
        name = gem.get("name")
        if name in AFTER_PIERCE_MORE:
            factor *= 1 + AFTER_PIERCE_MORE[name] / 100
            why.append(f"{name} {AFTER_PIERCE_MORE[name]:+g}% after piercing")
        elif name == main.name and name in AFTER_PIERCE_QUALITY and gem.get("quality"):
            factor *= 1 + float(gem["quality"]) / 100
            why.append(f"{name}'s quality +{float(gem['quality']):g}% after piercing")
    return factor, why


def return_share(texts: list[str], main: Skill | None, main_types: set[str], group_gems: list[dict],
                 weapon_types: set[str]) -> tuple[float, str]:
    """(MECHB55; the manager 12:00, the Witchhunter Frostbolt loop: GEM's mirror_of_refraction_model the mirror side,
    MECH-B the return side) (the share of the main skill's projectiles that Return, why): each one that returns flies
    back to you, a second pass through the space your Mirrors of Refraction appear in (your Presence). The same sources
    as return_model: Soaring Midnight 1, Breachlord's Amalgam 1 (a Cold / Lightning, self-used skill), Cadiro's Gambit's
    Reversing Arrows 1 in 6 (UNVERIFIED odds). Ironbound's (only on a Fully Broken target) left out: 0 there."""
    if main is None or "Projectile" not in main_types:
        return 0.0, ""
    names = {g.get("name") for g in group_gems if g.get("enabled", True)}
    if main.name == SOARING_MIDNIGHT:
        return 1.0, "Soaring Midnight returns at the end of its flight"
    if (BREACHLORDS_AMALGAM in names and {"Cold", "Lightning"} & main_types
            and not {"Triggered", "Persistent"} & main_types):
        return 1.0, "Breachlord's Amalgam makes its projectiles return"
    if main.attack and "Bow" in weapon_types and any(CADIRO_ARROWS.search(t.strip()) for t in texts):
        return CADIRO_REVERSING_SHARE, ("Cadiro's Gambit: 1 arrow in 6 is a Reversing Arrow, which Pierces all targets "
                                        "and Returns (the six kinds assumed equally likely, UNVERIFIED)")
    return 0.0, ""


# (MECHB65; RESEARCH60 R60-9 (b), research/mirror-copies-return-loop-r60.md, GEM44's note) Mirror of Refraction's copies
# carry the supported skill's Return (MEDIUM) and a copy's return can re-hit the boss (MEDIUM-LOW, one a nova), but
# whether the way back re-crosses the boss is geometry no source measures (a mirror well to the side, a small boss:
# LOW). The headline keeps every copy returning (this more on the copies too, GEM's mirror model multiplying it); a LOW
# row takes about half of the copies' returns: R60-9's 0.5 (a number the game's geometry decides, no data: LOW, named).
MIRROR_RETURN_ROW = 0.5


def return_model(texts: list[str], stats: dict, main: Skill | None, main_types: set[str], group_gems: list[dict],
                 weapon_types: set[str], mirror: bool = False) -> tuple[list[dict], list[dict]]:
    """Returning projectiles' second boss hit (the rule above): `1% more Damage` on the main skill for the share of its
    projectiles that pierce the boss and return, times the returned hit's own factor; Ironbound's part only against
    Fully Broken Armour. A note for each source, counted or not. `mirror`: Mirror of Refraction in the build (R60-9's
    LOW row on its copies' returns)."""
    if main is None or "Projectile" not in main_types:
        return [], []
    names = {g.get("name") for g in group_gems if g.get("enabled", True)}
    arrows = main.attack and "Bow" in weapon_types
    pierce = min(1.0, max(0.0, number(stats.get("PierceCount"))))
    notes: list[dict] = []
    always, why = 0.0, ""
    if main.name == SOARING_MIDNIGHT:
        always, why = 1.0, "Soaring Midnight returns at the end of its flight"
    elif (BREACHLORDS_AMALGAM in names and {"Cold", "Lightning"} & main_types
          and not {"Triggered", "Persistent"} & main_types):
        always, why = 1.0, "Breachlord's Amalgam makes its projectiles return"
    if not always and arrows and any(CADIRO_ARROWS.search(t.strip()) for t in texts):
        always, why = CADIRO_REVERSING_SHARE, ("Cadiro's Gambit: 1 arrow in 6 is a Reversing Arrow, which Pierces all "
                                               "targets (the six kinds assumed equally likely, UNVERIFIED)")
        pierce = 1.0
    ironbound = arrows and always < 1.0 and any(IRONBOUND_RETURN.search(t.strip()) for t in texts)
    for t in texts:
        if m := PIERCE_TIMES_RETURN.search(t.strip()):
            notes.append({"label": f"Projectiles return after {m.group(1)} pierces (Drillneck)", "value": 0,
                          "confidence": "HIGH",
                          "basis": "a projectile pierces each target once, so it never returns off a lone boss: none"})
    if not always and not ironbound:
        return [], notes
    factor, parts = returned_hit_factor(main, group_gems)
    returned = f"; the returned hit x{factor:.2f} ({', '.join(parts)})" if parts else ""
    mods: list[dict] = []
    broken = any(PIERCE_BROKEN.search(t.strip()) for t in texts)  # (Passthrough Rounds: see PIERCE_BROKEN)
    rows = [(always, f"Returning projectiles ({main.name})", "1% more Damage", why, pierce),
            ((1 - always) if ironbound else 0.0, "Ironbound: arrows return after piercing a Fully Broken target",
             "1% more Damage against Enemies with Fully Broken Armour",
             "counted while the boss's Armour is Fully Broken (the search weighs its uptime)"
             + ("; Passthrough Rounds makes every projectile pierce it then" if broken else ""),
             1.0 if broken else pierce)]
    if broken and always and pierce < 1.0:
        rows.append((always, f"Returning projectiles ({main.name}): Passthrough Rounds' pierce",
                     "1% more Damage against Enemies with Fully Broken Armour",
                     f"{why}; while the boss's Armour is Fully Broken, Passthrough Rounds makes every projectile pierce it "
                     "(the search weighs that uptime)", 1.0 - pierce))
    frags = 0.0  # (MECHB65: the Merging fragments' x N, see RETURN_RULE's comment)
    if main.name in SHOTGUN_SKILLS and main.name != "Ice Fragments":
        frags = _shotgun_count(main, stats, main)[0]
    for share, label, text, how, pierce in rows:
        if not share:
            continue
        more = 100.0 * share * pierce * factor
        if frags > 1:
            how += (f"; one returned fragment for the {frags:g} fired together (R59-1's rule; whether returned "
                    f"fragments Merge again is UNVERIFIED, RESEARCH60 R60-15 leaning to a merged hit, MEDIUM-LOW): the "
                    f"return's more / {frags:g}, the pierced fragments merged on the return (all {frags:g}) a row: "
                    f"+{more:.1f}%")
            more /= frags
        if more <= 0:
            notes.append({"label": label, "value": 0, "confidence": "MEDIUM",
                          "basis": f"{how}, but its projectiles don't pierce the boss on the way out: {RETURN_RULE}: none"})
            continue
        mods.append(line(text, more, skill=main.name))
        mirror_row = (f"; Mirror of Refraction's copies return too (R60-9 (a), MEDIUM) and re-hit the boss at most once "
                      f"a nova ((b), MEDIUM-LOW); row, about {MIRROR_RETURN_ROW:.0%} of the copies' returns re-cross the "
                      f"boss (LOW, no source measures the geometry): +{more * MIRROR_RETURN_ROW:.1f}% on the copies"
                      if mirror else "")
        notes.append({"label": label, "value": round(more, 1), "confidence": "MEDIUM",
                      "basis": f"{how}: {share:.3g} of projectiles x {pierce:.0%} pierce the boss on the way out{returned} "
                               f"= {more:.1f}% more damage; {RETURN_RULE}{mirror_row}"})
    return mods, notes


# Cadiro's Gambit's other five arrow kinds (MECHB22; COV20's note: only the Reversing Arrow was read). PoB doesn't
# parse the line at all (ModCache 7232: no mod, the whole text left over), so none of the six counted. KeywordPopups
# (build 26476662), each 1 arrow in 6 (the six assumed equally likely, UNVERIFIED, as CADIRO_REVERSING_SHARE):
#   - UniqueArrowModifierCrit, "All Hits with Diamond Arrows are Critical Hits with 60% increased Critical Damage
#     Bonus": counted (an UNDERCOUNT before): a Diamond arrow's hit is PoB's crit average, the rest keep PoB's average
#     hit at its crit chance, so the main skill's damage x (5/6 + 1/6 x crit average / average hit). The 60% increased
#     Critical Damage Bonus isn't added (its size needs the build's other increases: a lower bound, labelled); effects
#     that need a Critical Hit (on-crit lines) aren't raised by it either (an undercount).
#   - UniqueArrowModifierChain, Crescendo: "Chain 6 additional times and deal 60% increased Damage for each time they
#     have Chained": 0 on a lone boss (KeywordPopups Chain: "Enemies cannot be targeted more than once in the same
#     Chain"; its first hit has Chained 0 times).
#   - UniqueArrowModifierSplit, Splinter: "Split towards 6 targets": 0 more hits on a lone boss (KeywordPopups Split:
#     the copies "aim at different targets ... If there aren't enough targets, the rest will be aimed in random
#     directions"; LOW: a random copy reaching the boss isn't counted).
#   - UniqueArrowModifierStun, Blunt: "600% increased Stun Buildup": not counted here (Heavy Stun on the boss is MECH-A's
#     / MECH-D's; named in the note as an undercount).
#   - UniqueArrowModifierRarity, Covetous: item rarity on kill, no damage.
#   - UniqueArrowModifierPierceReturn, Reversing: return_model.
CADIRO_DIAMOND_SHARE = 1 / 6
CADIRO_FIELDS = [*(f"MainHand.{t}HitAverage" for t in DAMAGE_TYPES), *(f"MainHand.{t}CritAverage" for t in DAMAGE_TYPES),
                 "MainHand.CritChance"]


def cadiro_model(texts: list[str], stats: dict, main: Skill | None, main_types: set[str],
                 weapon_types: set[str], returned: float = 0.0) -> tuple[list[dict], list[dict]]:
    """Cadiro's Gambit's Diamond Arrows (see above) as "1% more Damage" on a main bow attack's projectiles, and a note for
    the kinds that add nothing on a lone boss. `stats`: the main skill's per-type hit and crit averages and crit chance
    (top level, else MainHand.). `returned`: the Reversing Arrows' own "% more Damage" (return_model's line): one arrow
    is never both, so the two shares add (1 + d + r) rather than multiply, and this line is d / (1 + r)."""
    if main is None or not main.attack or "Bow" not in weapon_types or "Projectile" not in main_types \
            or not any(CADIRO_ARROWS.search(t.strip()) for t in texts):
        return [], []

    def read(field: str) -> float:
        return sum(number(stats.get(f"{t}{field}")) for t in DAMAGE_TYPES) \
            or sum(number(stats.get(f"MainHand.{t}{field}")) for t in DAMAGE_TYPES)

    hit, crit = read("HitAverage"), read("CritAverage")
    chance = min(max(number(stats.get("CritChance")) or number(stats.get("MainHand.CritChance")), 0.0), 100.0) / 100
    average = hit * (1 - chance) + crit * chance
    others = ("Crescendo (its chains need other enemies: none on a lone boss), Splinter (its splits aim at other "
              "targets, else random directions: none counted, LOW), Covetous (rarity only); Blunt's 600% increased Stun "
              "Buildup isn't counted (an undercount); Reversing: the returning-projectile note")
    if average <= 0 or crit <= average:
        return [], [{"label": "Cadiro's Gambit's arrow kinds", "value": 0, "confidence": "LOW",
                     "basis": "PoB gave no crit average above the average hit for the main skill, so the Diamond "
                              f"Arrows add nothing here; {others}"}]
    factor = 1 - CADIRO_DIAMOND_SHARE + CADIRO_DIAMOND_SHARE * crit / average
    more = 100.0 * (factor - 1) / (1 + max(returned, 0.0) / 100)
    return [line("1% more Damage", more, skill=main.name)], [{
        "label": "Cadiro's Gambit: Diamond Arrows always Critically Hit*", "value": round(more, 1),
        "confidence": "LOW",
        "basis": f"1 arrow in 6 is a Diamond Arrow (the six kinds assumed equally likely, UNVERIFIED), which always "
                 f"Critically Hits: its hit {crit:.4g} (PoB's crit average) against the average {average:.4g} at "
                 f"{chance:.0%} crit chance, x{factor:.3f}"
                 + (f" (added to the Reversing Arrows' +{returned:.3g}%, not multiplied: {more:.3g}%)" if returned > 0 else "")
                 + f"; its 60% increased Critical Damage Bonus isn't added (a lower "
                 f"bound) and on-crit effects aren't raised; PoB doesn't read the line at all. {others}"}]


# Hazards set off in their first half second (MECHB2, 12 Nov 2026; FIX_QUEUE, COVC2's finding). Seven player stat sets
# carry "-80% ... damage if destroyed within 0.5 seconds by something other than you" (stat description; checked: every
# Stats.json id with "first_500_ms" (3: hazard_, ice_crystals_, shield_wall_damage_+%_final_for_first_500_ms_when_not_
# killed_by_self), looked up in GrantedEffectStatSets / PerLevel, Mods, PassiveSkills, GrantedEffectQualityStats: only
# skill stat sets use them: Spearfield, Ice Shards' shards, Grim Pillars, Brambles (Briarpatch), Frost Wall, Glacial
# Bolt's wall, Shield Wall; second source: PoB's Data/Skills holds the same -80 on the same sets). PoB maps the stat to
# nothing (checked: SkillStatMap.lua and each set's statMap), so it counts every hazard at full damage: an overcount
# wherever the boss sets one off at once. The bridge reads it from the scored stat set (Glacial Bolt's Projectile set
# and Ice Shards' Projectile set don't carry it) with what delays the trigger:
#   - an arming time of 0.5 s or more (Ice Shards' shards arm in 1.5 s: never early; Brambles' 0.4 s doesn't help);
#   - Controlled Hazard ("can't trigger for 3 seconds after creation") or Delayed Reaction ("trigger at the end of
#     their duration instead", whose -70% duration still leaves Spearfield 3 s): never early.
# Who sets it off (LOW, a play assumption; KeywordPopups Hazard: "destroyed when traversed by an enemy"):
#   - hazards (Spearfield, Brambles): placed where the boss stands, so it traverses them at once: all early (x0.2).
#     Laying them in the boss's path at least 0.5 s ahead avoids it: the play guide's "with it" row.
#   - Ice Crystals (any skill with a set typed is_ice_crystal_explosion: Frost Wall, Glacial Bolt's wall, and Grim
#     Pillars, whose "Ice-Crystal spears ... can be destroyed for an explosion" carry the hazard_ stat id) and Shield
#     Wall: broken by the player's own hits (KeywordPopups
#     IceCrystals: Consume-Freeze skills shatter them; Shield Wall's own "more damage when slammed"), which the penalty
#     doesn't touch ("something other than you"): none early; the boss breaking them is the "without it" row.
#   - (MECHB36, RESEARCH26 R26-43, ASSUMED LOW-MEDIUM: research/grim-pillars-totem-r26.md) Ice Crystals and Shield Wall
#     count as broken by you only when the build has its own breaker: another skill that hits (its gem's types hold
#     Attack or Damage, not a minion's; an item-granted skill with no gem entry counts if it is an Attack). Without one
#     only the boss breaks them, by walking or hitting through them ("larger monsters will destroy Ice Crystals in their
#     path", KeywordPopups / 0.3.0): all early, x0.2 (LOW); spears never broken may never explode (UNVERIFIED, not
#     counted). Whether "something other than you" means the totem that made them, so a totem's crystals broken early by
#     your own hit still take the penalty: UNVERIFIED, said in the note (a breaker hitting after 0.5 s avoids it).
# Rearm (PoB: DPS x (1 + rearm chance)): a rearmed hazard's later trigger is taken as after 0.5 s, so at full damage
# (UNVERIFIED: whether the window restarts on rearming isn't in the game files' text).
EARLY_HAZARD_WINDOW = 0.5  # seconds (the stats' "first_500_ms")
EARLY_HAZARD_BY_BOSS = {"hazard": True, "ice_crystals": False, "shield_wall": False}
EARLY_HAZARD_ENTRY = "hazard-early-trigger"


def hazard_early_share(early: dict, breaker: bool = True) -> tuple[float, str]:
    """The share of the skill's hazards the boss sets off in their first 0.5 s, and why. `breaker`: the build has
    another skill that hits, to break Ice Crystals / Shield Wall itself (MECHB36, R26-43)."""
    arming = number(early.get("arming")) / 1000
    if arming >= EARLY_HAZARD_WINDOW:
        return 0.0, f"they arm after {arming:g} s, past the 0.5 s window"
    if early.get("atEnd"):
        return 0.0, f"{early['atEnd']} sets them off at the end of their duration instead"
    if number(early.get("delay")) >= EARLY_HAZARD_WINDOW:
        return 0.0, f"{early.get('delayBy') or 'a support'}: they can't trigger for {number(early['delay']):g} s"
    if EARLY_HAZARD_BY_BOSS.get(early.get("kind"), True):
        return 1.0, "placed where the boss stands, it sets them off at once (LOW, a play assumption)"
    if not breaker:
        return 1.0, ("the build has no other skill that hits to break them, so only the boss does, walking or hitting "
                     "through them, at once (LOW, RESEARCH26 R26-43; ones never broken may never explode: not counted)")
    return 0.0, ("you break them with your own hits, which the penalty doesn't touch (LOW, a play assumption; RESEARCH26 "
                 "R26-43: UNVERIFIED whether a totem's crystals count your hits as 'something other than' the totem)")


def hazard_early_model(skills: list[Skill], stats: dict, forbidden: set[str] = frozenset(),
                       hitters: set[str] | None = None) -> tuple[list[dict], list[dict]]:
    """`hitters`: the build's skills that hit (assumptions: gem types Attack or Damage, no minion); None = not known,
    taken as a breaker present (the old reading)."""
    if EARLY_HAZARD_ENTRY in forbidden:
        return [], []
    mods, notes, seen = [], [], set()
    rearm = min(1.0, max(0.0, number(stats.get("HazardRearmChance")) / 100))
    for skill in skills:
        early = skill.early_hazard
        if not early or skill.name in seen:
            continue
        seen.add(skill.name)
        less = number(early.get("more")) / 100  # -0.8
        share, why = hazard_early_share(early, hitters is None or bool(hitters - {skill.name}))
        factor = (1 + less * share + rearm) / (1 + rearm)
        by_boss = (1 + less + rearm) / (1 + rearm)
        if factor != 1:
            mods.append(line("1% more Damage", 100 * (factor - 1), skill=skill.name))
        crystals = early.get("kind") != "hazard" and share == 0
        unbroken = early.get("kind") != "hazard" and share > 0  # (MECHB36: crystals with no breaker in the build)
        notes.append({
            "label": f"{skill.name}: {abs(less):.0%} less if set off in its first 0.5 s", "value": round(factor, 4),
            "basis": f"{why}; PoB counts every one at full damage"
                     + (f"; rearms ({rearm:.0%}) taken as later, at full damage (UNVERIFIED)" if rearm else ""),
            "play": (f"Add a skill that hits to break them yourself after 0.5 s: x{1 / by_boss:.2f} on {skill.name}'s "
                     f"damage. Without it (the boss breaks them): x{by_boss:.2f}" if unbroken else
                     f"{'Break them yourself' if crystals else 'Lay them in the boss path at least 0.5 s before it gets there'}"
                     f": x{1 if crystals else 1 / by_boss:.2f} on {skill.name}'s damage. Without it (the boss "
                     f"{'breaks them' if crystals else 'sets them off at once'}): x{by_boss:.2f}"
                     if share or crystals else ""),
            "confidence": "LOW: who sets the hazard off is how it's played; the -80% is the game files' (datamined)"})
    return mods, notes


# Channel wind-up (MECHB3; FIX_QUEUE MECHB2 handover / AUDIT6) ----------------------------------------------------------
# Player stat sets with a channel start time (game files 26476662, GrantedEffectStatSets): OilBarragePlayer
# channel_start_duration_as_%_of_attack_time 350 (and channel_end 1000, display_attack_time_+% 350),
# BearFuryOfTheMountainPlayer 36 (attack time), MetaHollowFormPlayer 30 (attack time), VolcanoPlayer 50 (cast time),
# RunicReprievePlayer 200 (cast time). PoB reads none of these stats (checked: grep of PoB's src, outside its skill data
# and stat descriptions, for channel_start and display_attack_time finds no use). Not counted: how much of each channel
# is wind-up depends on how long the channel lasts (Oil Barrage's channelled barrage consumes a Power Charge per 1.5 s, so its length is the build's Power Charge
# supply, MECH-C's), and whether PoB's attack time already holds the 350% (display_attack_time_+% 350) is UNVERIFIED. No
# honest lower bound exists without them, so the note says the DPS may be too high instead of guessing a channel length.
# (MECHB46: Oil Barrage's plain use is now counted, wind-up and group, by oil_barrage_volley_model: no note for it.)
CHANNEL_WINDUP = {"Oil Barrage": (350, "attack"), "Fury of the Mountain": (36, "attack"), "Hollow Form": (30, "attack"),
                  "Volcano": (50, "cast"), "Runic Reprieve": (200, "cast")}


# (MECHB50; GEM29's triage rows, the manager 01:22: a small OVERCOUNT) How long a channel lasts in a boss fight: the
# player holds it, so the wind-up is paid once a channel, and a channel ends when the player stops to dodge. The user's
# rate (20 Nov: a melee player dodges about half of a pinnacle's telegraphed Cold attacks; extended to all its attacks,
# as Volcanic Steps' row, LOW) gives the restarts: half the boss's skill uses a second, at the fewest hits the boss tables
# allow (bosses.benefit_skill_time: the smallest cut; the defence cadence, enemySkillTime, a row). Each restart costs
# channel_start_duration_as_%_of_X_time of PoB's attack / cast time (1 / Speed), when the channel deals nothing; the
# channel_end share is cut off by the dodge (UNVERIFIED: a row with it paid too). A channel the build ends on its own
# (Oil Barrage's Power Charges: oil_barrage_volley_model) is not this.
CHANNEL_WINDUP_ENTRY = "model-mechb50-channel-windup"
CHANNEL_WINDUP_END = {"Fury of the Mountain": 36, "Hollow Form": 30, "Volcano": 50}  # (channel_end_duration_as_%_of_X_time, 26650308)


DODGE_SHARE_ROWS = (0.5, 0.75)  # (MECHB51: the user's ruling, 21 Nov 05:20: rows at 1/2 and 3/4 around the 2 in 3)
DODGE_HOW_DEFAULT = "the user's rate, 21 Nov (videos)"


def dodge_rows(head: float, value) -> str:
    """'; 50% dodged (a row): ...' for each of DODGE_SHARE_ROWS but the headline's own share; `value(share)` the row's
    text."""
    return "".join(f"; {d:.0%} dodged (a row): {value(d)}" for d in DODGE_SHARE_ROWS if abs(d - head) > 1e-9)


def channel_windup_model(main: Skill | None, speed: float, every: float, every_row: float, dodge_share: float,
                         forbidden: set[str] = frozenset(), dodge_how: str = DODGE_HOW_DEFAULT
                         ) -> tuple[list[dict], list[dict]]:
    """A held channel's wind-up once a restart, a restart each dodged boss attack (see above). `speed` PoB's uses a
    second of the main skill, `every` / `every_row` seconds between boss skill uses (the fewest hits / the defence
    cadence), `dodge_share` the share dodged (boss_hits.ON_YOU_DODGE, the user's rate; `dodge_how` its label)."""
    if main is None or main.name not in CHANNEL_WINDUP or main.name in (OIL_BARRAGE, VOLCANO):  # (MECHB46: oil_barrage_
        return [], []                                         # volley_model counts Oil Barrage's; MECHB50: volcano_channel_model)
    pct, kind = CHANNEL_WINDUP[main.name]
    if CHANNEL_WINDUP_ENTRY in forbidden or speed <= 0 or every <= 0:
        return [], [{"label": f"{main.name}'s channel wind-up (not counted)", "value": f"{pct}% of its {kind} time",
                     "basis": (f"the game files' channel_start_duration_as_%_of_{kind}_time {pct}, which PoB doesn't "
                               "read; no use rate or boss cadence to place the restarts: the DPS may be too high"),
                     "confidence": "UNVERIFIED"}]
    windup = pct / 100.0 / speed

    def kept(gap: float, cost: float, share: float = dodge_share) -> float:
        return max(0.0, 1.0 - share / gap * cost) if gap > 0 else 1.0
    head = kept(every, windup)
    end = CHANNEL_WINDUP_END.get(main.name, 0) / 100.0 / speed
    rows = f"; at the boss's defence cadence ({every_row:.2f} s): x{kept(every_row, windup):.3f}" if every_row > 0 else ""
    if end:
        rows += f"; the {CHANNEL_WINDUP_END[main.name]}% end paid too: x{kept(every, windup + end):.3f}"
    rows += dodge_rows(dodge_share, lambda d: f"x{kept(every, windup, d):.3f}")
    return [raw_mod("DPS", "MORE", 100 * (head - 1), main.name, tag=CHANNEL_WINDUP_ENTRY)], [{
        "label": f"{main.name}: a channel wind-up each dodge*", "value": f"x{head:.3f}", "confidence": "LOW",
        "entry": CHANNEL_WINDUP_ENTRY,
        "basis": (f"PoB scores the channel's hits nonstop and never reads channel_start_duration_as_%_of_{kind}_time "
                  f"{pct}. The player holds it and restarts it after each dodge: {dodge_share:.0%} of the boss's "
                  f"attacks ({dodge_how}: one rate for every telegraphed attack), one every "
                  f"{every:.2f} s (the fewest hits the boss tables allow), each restart a {windup:.3f} s wind-up "
                  f"({pct}% of its {1 / speed:.3f} s {kind} time) with no hit: x{head:.3f}{rows}"),
        "play": (f"Hold {main.name} through the fight and restart it only after a dodge: each restart costs "
                 f"{windup:.2f} s of wind-up.")}]


# Warcry Echoes (MECHB3; AUDIT6 A6-2) -------------------------------------------------------------------------------------
# Echoing Cry: "Supported Warcries Echo 2 times" with a 1.3 s delay (SupportEchoingCryPlayer: base_warcry_echo_X_times 2,
# warcry_echo_delay_ms_from_support 1300, warcry_echo_area_of_effect_+%_final_per_repeat 100; game files 26476662). Its
# 40% less Damage and 50% less Area (COVE2's ledger entries) are on the Warcry, so each Echo repeats the penalised hit:
# a damaging Warcry deals (1 + 2) x 0.6 = 1.8x, not 0.6x. PoB counts no Echo. The part is COV-E's "warcry_echo"
# (support_part_scale, ledger supports-parts.yaml on cov5: WarcryEchoes, EchoAreaMorePercentPerEcho, WarcryEchoDelayMs);
# until that lands, WARCRY_ECHO holds the same game-file values. Each Echo hits the same targeted location again
# (SETTLED, MEDIUM-HIGH: KeywordPopups Cascadable; RESEARCH26 R26-44 (a)), 1.3 and 2.6 s later, repeating the damage at
# the support's 40% less and reaching a boss that stays near the shout spot (ASSUMED, MEDIUM: R26-42 (b); the Echoes'
# areas x2, x3), with the x1 "without it" row in the note. Not read: the Echoes' larger area (a lone boss is in the area
# or not), whether a new use cancels Echoes still pending (UNVERIFIED), the Echoes' Warcry buffs, and Echoing Cry's
# "travel a distance before each use" (COV-C's, usage).
WARCRY_ECHO = {"WarcryEchoes": 2.0, "EchoAreaMorePercentPerEcho": 100.0, "WarcryEchoDelayMs": 1300.0}
ECHOING_SUPPORTS = ("Echoing Cry",)


def warcry_echo_model(skills: list[Skill], supports: dict[int, list[str]], warcries: set[str],
                      part_scale: Callable[[Skill, str], tuple[dict[str, float], list[dict]]] | None = None
                      ) -> tuple[list[dict], list[dict]]:
    """Each Warcry supported by Echoing Cry deals its (penalised) hit 1 + Echoes times. `warcries`: the names of the
    build's Warcry skills; `part_scale`: COV-E's support_part_scale when it exists."""
    mods: list[dict] = []
    notes: list[dict] = []
    for skill in skills:
        if skill.name not in warcries or skill.group is None:
            continue
        if not any(n in ECHOING_SUPPORTS for n in supports.get(skill.group, [])):
            continue
        scale, part_notes = part_scale(skill, "warcry_echo") if part_scale else ({}, [])
        echoes = scale.get("WarcryEchoes") or WARCRY_ECHO["WarcryEchoes"]
        delay = (scale.get("WarcryEchoDelayMs") or WARCRY_ECHO["WarcryEchoDelayMs"]) / 1000
        mods.append(line("1% more Damage", 100 * echoes, skill=skill.name))
        notes += part_notes
        notes.append({"label": f"{skill.name}: Echoing Cry's Echoes", "value": f"x{1 + echoes:g} hits",
                      "basis": f"\"Supported Warcries Echo {echoes:g} times\", {delay:g} s apart, each with the support's 40% "
                               "less Damage (counted on the Warcry); PoB counts no Echo. Each Echo hits the first use's "
                               "location again (KeywordPopups Cascadable, MEDIUM-HIGH) and is counted as hitting a boss that "
                               f"stays near it (MEDIUM, RESEARCH26 R26-42 / -44). Without the Echoes: x1, "
                               f"x{1 / (1 + echoes):.2f} on this number",
                      "confidence": "MEDIUM"})
    return mods, notes


# Echoing Cry's "50% less Power" for the Warcry it supports (MECHB40; plans/kw-monster-power.md, an OVERCOUNT). The
# support's support_echoing_cry_warcry_monster_power_+%_final -50 (game files SupportEchoingCryPlayer; PoB sup_str.lua
# 2704) is read by no PoB code (checked: the stat id appears in vendor PoB src only in Data/Skills/sup_str.lua and its
# stat descriptions; MECHB2's check of SkillStatMap / Modules the same), and PoB's Warcry Power is one global number
# (CalcPerform 2201), so a Warcry with Echoing Cry Empowered as many attacks as at the boss's full Power:
# floor(min(Power, cap) / per) (Infernal Cry 1 per 10 up to 50, Seismic Cry 1 per 10 up to 50, Arctic Howl 1 per 5 up to
# 50, Ferocious Roar 1 per 8 up to 64). Now: Power x (1 + stat / 100) for that Warcry, the difference taken off PoB's
# Num<Warcry>Empowers as "<Warcry>EmpoweredAttacks" BASE (CalcPerform 2205 adds it), which Infernal Cry's uptime and
# Assumptions.empowered_uses both read. Not counted: the Echoes' own Empowers (whether an Echo Empowers again is
# UNVERIFIED). MECHB41, the other readers of a Warcry's Power: PoB's per-N-Power Warcry buffs (warcryPowerBonus,
# CalcPerform 2224-2229) and Rallying Cry's ally bonus (2259-2261) are reached by no PoE2 skill (checked: no mod in vendor
# PoB Data/Skills/*.lua or SkillStatMap.lua carries effectType "Warcry" with a div; RallyingCryAllyDamageBonusPer5Power is
# set by nothing; rallying_cry_weapon_damage_%_for_allies_per_5_monster_power has no carrier in game 26650308's
# GrantedEffectStatSets / PerLevel, Mods, PassiveSkills or SoulCoreStats), so nothing to halve there. Ferocious Roar's Rage
# per Power and Armour-Breaking Empowered hits now take the halved Power (echo_power: roar_model, roar_break). Still
# unscored at any Power (PoB maps none of them; checked: their ids appear in vendor PoB src only in Data/Skills and stat
# descriptions, except warcry_grant_X_rage_per_5_power, mapped to a CanGainRage flag only): Arctic Howl's added Cold per 5
# Power (wolf_warcry_*_cold_damage_*_per_5_power_up_to_cap), Raging Cry's Rage per 5 Power, Fortifying Cry's Shield Waves
# per Power and Guard per 5 Power: undercounts, open.
ECHO_POWER_STAT = "support_echoing_cry_warcry_monster_power_+%_final"


def echo_empowers(n: float, attacks: float) -> tuple[float, str]:
    """(Empowered attacks a use, how) for a Warcry with Echoing Cry Empowering `n` a use (its halved Power's count), the
    main skill attacking `attacks` times a second. RESEARCH33 R33-13 (echoing-cry-power-rage-and-echo-empower.md): the
    Echoes Empower too (MEDIUM: 0.5.0's fix "Arctic Howl could empower you in human form while using Echoing Cry"); how
    the counts combine is UNVERIFIED, the headline (MEDIUM-LOW) each Echo resetting the count to its own n: n + min(n,
    attacks in each 1.3 s gap) x 2 Echoes; rows 3n (adding) and n (Echoes don't Empower)."""
    echoes, gap = WARCRY_ECHO["WarcryEchoes"], WARCRY_ECHO["WarcryEchoDelayMs"] / 1000
    used = min(n, max(attacks, 0.0) * gap)
    total = n + echoes * used
    return total, (f"its {echoes:g} Echoes Empower too (R33-13, MEDIUM; each resets the count to its own {n:g}, "
                   f"MEDIUM-LOW, UNVERIFIED): {n:g} + {echoes:g} x min({n:g}, {attacks:.2f} attacks/s x {gap:g} s) = "
                   f"{total:.3g} a use (rows: adding, {n * (1 + echoes):g}; Echoes not Empowering, {n:g})")


def echoing_power_model(skills: list[Skill], rows: dict[str, dict], attacks: float = 0.0) -> tuple[list[dict], list[dict]]:
    """(mods, notes): each Warcry with Echoing Cry Empowers floor(min(Power', cap) / per) attacks a use with its less Power
    (not PoB's floor(min(Power, cap) / per)), plus its Echoes' Empowers (echo_empowers: the main skill's `attacks` a
    second). `rows`: {warcry name: its useRates row (warcryPower, warcryPowerPer, warcryPowerCap)}."""
    mods, notes = [], []
    for skill in skills:
        less = number(skill.support_stats.get(ECHO_POWER_STAT))
        row = rows.get(skill.name) or {}
        per, cap, power = (number(row.get(k)) for k in ("warcryPowerPer", "warcryPowerCap", "warcryPower"))
        if less >= 0 or per <= 0 or power <= 0 or skill.name in UNBUFFED_WARCRIES:  # (MECHB41: the Howl's own count
            # is unbuffed_warcry_empowers'; an ArcticHowlEmpoweredAttacks mod reads nothing in PoB)
            continue
        mine = power * max(0.0, 1 + less / 100)
        pob = math.floor(min(power, cap) / per)
        own = math.floor(min(mine, cap) / per)
        target, echo_how = echo_empowers(own, attacks)  # (MECHB42, R33-13)
        if abs(target - pob) < 1e-9:
            continue
        name = skill.name.replace(" Cry", "").replace("'s", "").replace(" ", "")
        mods.append(raw_mod(f"{name}EmpoweredAttacks", "BASE", _round(target - pob)))
        notes.append({"label": f"{skill.name}: Echoing Cry's {-less:g}% less Power and its Echoes",
                      "value": f"{target:.3g} Empowered a use, not {pob}",
                      "basis": (f"Echoing Cry: \"{-less:g}% less Power\" for the supported Warcry, which PoB never applies "
                                f"(its Power is one global number): {power:g} Power -> {mine:g}, one Empowered attack per "
                                f"{per:g} up to {cap:g}: {own} a use, not PoB's {pob} (an OVERCOUNT before); {echo_how}. "
                                "Its buffs scaled per N Power keep the full Power (an overcount left)"),
                      "confidence": "MEDIUM"})
    return mods, notes



# Arctic Howl's Empowered attacks (MECHB41, an UNDERCOUNT). Arctic Howl (act_str.lua WolfArcticHowlPlayer; game 26650308
# GrantedEffectStatSets WolfArcticHowlPlayer) is a Warcry that "Empowers your attacks with added Cold damage" "If an enemy
# is Frozen or a Frozen enemy is Hit": warcry_empowers_per_X_monster_power 5 up to warcry_empowers_per_X_monster_power_mp_cap
# 50 (PoB maps both, SkillStatMap 611 / 614), and wolf_warcry_empowered_attack_cold_damage_min / max_per_5_power_up_to_cap
# (level 20: 121-186; arctic_howl.csd: "Empowered Attacks deal {0} to {1} additional Cold damage"). PoB makes no Warcry buff
# for it (its stat sets lack warcry_count_power_from_enemies; GEM14 / MECHB33), so its Num ArcticHowlEmpowers is 0 and
# none of its Empowered attacks' Cold is scored; PoB maps neither Cold stat (checked: the ids appear in vendor PoB src only
# in Data/Skills/act_str.lua). Assumptions.empowered_uses counted it one Empowered use per use (LOW). Now: floor(min(Power,
# 50) / 5) a use (4 at the boss's 20 Power; Echoing Cry's less Power first), at the share the boss is Frozen
# (warcry_empowers), and each Empowered attack of the main skill adds the Cold. The id says "per 5 Power up to cap", the
# text gives a flat range: the text is taken (the lower reading, as Vruun's Aftermath's), the id's reading (x Power / 5) in
# the note (UNVERIFIED which holds). Its buff's added Cold to Allies' Attacks (minions): arctic_howl_buff below
# (MECHB42). Not counted (open): Empowered Slams' Chilled Ground (MECH-A's grounds). warcry_minimum_benefit_if_monster_power_present
# (an implicit of Infernal, Seismic, Fortifying Cry, Ferocious Roar and Arctic Howl; no stat description, PoB maps it to
# nothing) is read as nothing; its likely meaning, at least one step of benefit while any Power is present, is
# UNVERIFIED, and it can't bind against the boss presets (MECHB43; checked: every preset is a Unique, BOSS_POWER 20; the
# Power stats in game 26650308 Stats / Mods / PassiveSkills (ids with "power" and monster / warcry / enemy): the only cut
# is Echoing Cry's support_echoing_cry_warcry_monster_power_+%_final -50, the rest raise it (warcry_monster_power_+% 5-55,
# Redblade's +100% final), so Power' >= 10, and the steps are 10 (Infernal, Seismic), 8 (Roar), 5 (Howl, Fortifying):
# floor(Power' / step) >= 1 already. Second source: poe2db Monster_Power "Unique monsters always have 20 Power").
ARCTIC_HOWL = "Arctic Howl"
UNBUFFED_WARCRIES = {ARCTIC_HOWL}  # (Warcries PoB makes no buff for, so no Num<Name>Empowers: GEM14's find, by name)
ARCTIC_HOWL_COLD = ("wolf_warcry_empowered_attack_cold_damage_min_per_5_power_up_to_cap",
                    "wolf_warcry_empowered_attack_cold_damage_max_per_5_power_up_to_cap")


def unbuffed_warcry_empowers(row: dict, less: float = 0.0) -> tuple[int, str]:
    """(Empowered attacks a use, how) for a Warcry PoB makes no buff for (Arctic Howl): floor(min(Power', cap) / per) from
    its useRates row (warcryPower / warcryPowerPer / warcryPowerCap), Power' with Echoing Cry's less Power (`less`, the
    support stat, negative)."""
    per, cap, power = (number(row.get(k)) for k in ("warcryPowerPer", "warcryPowerCap", "warcryPower"))
    if per <= 0:
        return 0, "no Empowers per Power"
    mine = power * max(0.0, 1 + less / 100) if less < 0 else power
    n = int(min(mine, cap if cap > 0 else mine) // per)
    echo = f" (Echoing Cry's {-less:g}% less Power: {power:g} -> {mine:g})" if less < 0 else ""
    return n, f"one per {per:g} of {mine:g} Power{echo}, up to {cap:g}: {n}"


def howl_power_row(lo: float, hi: float, power: float) -> str:
    """R33-11's row (RESEARCH33, arctic-howl-cold-per-power.md): the stat ids' "per 5 Power up to cap" reading, x min(Power,
    50) / 5, beside the flat headline (MEDIUM-LOW: the game text, poe2db and the wikis show a flat range)."""
    if power <= 0:
        return ""
    k = min(power, 50.0) / 5
    return (f"; R33-11's row, the stat id's per-5-Power reading: x{k:g} at {power:g} Power = {lo * k:g} to {hi * k:g} "
            "(the flat range stays the headline, MEDIUM-LOW)")


def arctic_howl_cold(howl: Skill, main: Skill, uses: float, empowered: float, how: str,
                     power: float = 0.0) -> tuple[list[dict], list[dict]]:
    """(mods, notes): the main Attack's share of uses Empowered by Arctic Howl (`empowered` a second of its `uses`) adds
    the Howl's Empowered-attack Cold (its level's range) as a scaled "Adds" line on the main skill."""
    lo, hi = (number(howl.level_stats.get(k)) for k in ARCTIC_HOWL_COLD)
    if main is None or not main.attack or hi <= 0 or uses <= 0:
        return [], []
    share = min(1.0, max(0.0, empowered / uses))
    note = {"label": "Arctic Howl: Empowered attacks' added Cold*", "value": f"{share:.0%} of {main.name}'s uses",
            "confidence": "LOW",
            "basis": (f"Arctic Howl's Empowered Attacks deal {lo:g} to {hi:g} additional Cold (the text's flat range; the "
                      "stat id says per 5 Power up to its cap: RESEARCH33 R33-11 keeps the flat range, MEDIUM-LOW, "
                      f"UNVERIFIED){howl_power_row(lo, hi, power)}; PoB scores none of it (no Warcry buff for the Howl). "
                      f"{how}"),
            "play": "Howl when the boss is Frozen (or Freeze it with the Howl), then attack: its Empowered attacks add Cold."}
    if share <= 0:
        return [], [note]
    return [line(f"Adds {lo:g} to {hi:g} Cold Damage to Attacks", share, skill=main.name)], [note]


# Arctic Howl's buff to Allies (MECHB42, an UNDERCOUNT for minion builds; MECHB41's open item 4). arctic_howl.csd:
# wolf_warcry_buff_cold_damage_min / max_per_5_power_up_to_cap "[Buff] grants [Allies] {0} to {1} added [Cold] damage to
# [Attack|Attacks]" (level 20: 37 to 56, GrantedEffectStatSetsPerLevel 26650308 / act_str.lua), base_skill_effect_duration
# "[Buff] duration is {0} seconds" (8 s), and the skill's description: "If an enemy is Frozen or a Frozen enemy is Hit,
# this Skill ... grants your Allies added Cold damage". KeywordPopups Allies: "Your allies include other players,
# Minions ... You do not count as your own Ally": so the build's minions, not you. PoB maps neither stat (checked: the ids
# appear in vendor PoB src only in Data/Skills/act_str.lua's stat list and the arctic_howl stat description file), so
# it counted 0. Now: "Minions' Attacks deal 37 to 56 additional Cold Damage" (ModParser's "^minions' attacks deal "
# prefix, Attack flag) x the buff's uptime: min(1, the Howl's uses/s x its buff duration, PoB's useRates speed and
# Duration with the build's modifiers) x the share of the fight the boss is Frozen (the same lower reading as its
# Empowers, warcry_empowers: a use also buffs when the boss is Frozen later in its window; LOW). The id says "per 5 Power
# up to cap", the text a flat range: the text taken (the lower reading, as its Empowered attacks'), UNVERIFIED (RESEARCH).
# Not counted: the quality's increased Freeze buildup for Allies (wolf_warcry_buff_freeze_buildup_+%; MECH-A's buildup);
# the Endurance-Charge cooldown bypass (more uses: an undercount where uptime is under 1).
ARCTIC_HOWL_BUFF = ("wolf_warcry_buff_cold_damage_min_per_5_power_up_to_cap",
                    "wolf_warcry_buff_cold_damage_max_per_5_power_up_to_cap")


def arctic_howl_buff(howl: Skill, uses: float, duration: float, frozen: float, frozen_how: str,
                     minions: list[str], power: float = 0.0) -> tuple[list[dict], list[dict]]:
    """(mods, notes): Arctic Howl's buff of added Cold to Allies' Attacks for the build's `minions` (their skills' names),
    at its uptime (`uses` a second x its buff `duration` s, at most 1) x the boss's Frozen share (`frozen`, why
    `frozen_how`)."""
    lo, hi = (number(howl.level_stats.get(k)) for k in ARCTIC_HOWL_BUFF)
    if not minions or hi <= 0:
        return [], []
    cover = min(1.0, max(0.0, uses) * max(0.0, duration))
    up = cover * min(1.0, max(0.0, frozen))
    note = {"label": "Arctic Howl: its buff's added Cold to your minions' Attacks*", "value": f"{up:.0%} of the fight",
            "confidence": "LOW",
            "basis": (f"Arctic Howl's buff grants Allies (your minions: {', '.join(minions)}) {lo:g} to {hi:g} added Cold "
                      f"to Attacks for {duration:g} s, if the boss is Frozen (or a Frozen boss is Hit): {uses:.3f} uses/s "
                      f"x {duration:g} s covers {cover:.0%} of the fight, x the boss Frozen {frozen:.0%} ({frozen_how}; a "
                      "lower reading: a use also counts when the boss is Frozen later in its window). The text's flat "
                      "range taken (RESEARCH33 R33-11: the headline, MEDIUM-LOW, UNVERIFIED; the stat id says per 5 Power "
                      f"up to its cap){howl_power_row(lo, hi, power)}. PoB scores none of it."),
            "play": ("Howl when the boss is Frozen (or Freeze it) so your minions' Attacks get its added Cold: "
                     f"without it 0, with it {lo:g} to {hi:g} added Cold for {duration:g} s a use.")}
    if up <= 0:
        return [], [note]
    return [line(f"Minions' Attacks deal {lo:g} to {hi:g} additional Cold Damage", up)], [note]


# Living Lightning (MECHB42, an OVERCOUNT where its group is in Full DPS; probe POE2T4627: Lightning Arrow 61 DPS, PoB's
# "Living Lightning" entry 304). The game (triggered_living_lightning.csd, TriggeredLivingLightningPlayer /
# ...PlayerTwo, GrantedEffectStatSets 26650308): "This Skill is [Trigger|Triggered] on dealing [Lightning] Damage with
# Supported Skill" (chance_to_trigger_living_lightning_on_lightning_damage_% 100), a 0.2 s cooldown (5 stored uses; II:
# 8), "[Limit] 5 [Minion|Minions]" (II: 8), "[Minion|Minions] [Attack] every 0.14 seconds"
# (living_lightning_beam_attack_time_ms 140) and "[Minion|Minions] disperse after 3 [Attack|Attacks]"
# (living_lightning_maximum_number_of_attacks 3). PoB scores the minion as one that never disperses: its Zap at PoB's own
# minion speed all fight, with the 3 mapped to RepeatCount (sup_int.lua's statMap). So each minion is worth its 3
# attacks: Zaps a second = 3 x the minions made a second, R = min(the supported skill's hits a second (PoB's speed x hit
# chance, one hit on the boss a use: a lower reading for a skill that hits it more than once a use), 1 / its trigger's
# cooldown (PoB's, with the build's cooldown recovery), the limit / (3 x 0.14 s) (never binding below ~12 a second)),
# and 0 when the supported skill deals no Lightning hit damage. One Zap's damage: PoB's own minion AverageDamage for the
# Zap (bridge minionSkillHit; the hit chance in). Counted as an added damage source; PoB's own entry goes to 0 in Full
# DPS (Objective.entry_scales, as Ice Fragments'). MEDIUM: the 3 attacks and the trigger are the game's text; the Zap's
# chains don't hit a lone boss again (KeywordPopups Chain: "Enemies cannot be targeted more than once in the same
# Chain"), so one hit an attack. Probe POE2T4628: PoB's Zap AverageDamage 42.56 x its minion Speed 7.14/s = its 304 entry.
LIVING_LIGHTNING = "Living Lightning"
LIVING_LIGHTNING_ZAP = "LivingLightningZap"
LL_ATTACKS = ("living_lightning_maximum_number_of_attacks", 3.0)
LL_ATTACK_MS = ("living_lightning_beam_attack_time_ms", 140.0)
LL_LIMIT = ("base_number_of_living_lightning_allowed", 5.0)
# (Living Lightning II's trigger has its 0.2 s Cooldown and 8 stored uses on its level-1 row only, levels 2-40 0 / 0:
# GrantedEffectsPerLevel 26650308 TriggeredLivingLightningPlayerTwo; it is a SingleLevelSkill, so the game uses level 1,
# but the bridge's granted-level copy hands PoB its level-20 row: no cooldown, probe POE2T4628. So a missing cooldown
# is the level-1 row's 0.2 s, MEDIUM. No other player skill PoB scores has a level-1-only cooldown or limit (checked,
# MECHB43: game 26650308 GrantedEffectsPerLevel, every field of every effect, level 1 against level 20 (or its top level):
# only this one and a monster's, MDExpeditionHermitSpiderFireball; GrantedEffectStatSetsPerLevel, every additional,
# float, implicit stat and flag, crit and multiplier: Soulbreaker's 11% crit (no PoB skill data: PoB scores it 0), Demon
# Magus's triggered_by_meta_minion flag and the unused "[DNT-UNUSED] Shadow Thief Slash" (neither in PoB), the curses' and
# Thunderstorm's target-level caps (rising per level, none from 18: MECH33's and GEM15's notes); PoB's Data/Skills: MECHB42's
# SingleLevelSkill scan, the same one. Second source: poe2db Living_Lightning_II "Cooldown Time: 0.20 s (8 Times)" and
# patch 0.4.0 "Cooldown count of 8", RESEARCH34 R34-5; poe2db not searched for other skills' level-1-only rows.)
LL_COOLDOWN = 0.2
# One minion per Lightning HIT, not per use (RESEARCH34 R34-5, MEDIUM-HIGH: "Trigger Living Lightning on dealing Lightning
# Damage", 100% chance; chayula-tornado-living-lightning-lightning-stun.md): a use hitting the boss k times makes up to k,
# capped by the cooldown (0.2 s, Cooldown Recovery applies since 0.3.1) and the limit. k = the hits on the boss PoB itself
# scores a use: its TotalDPS / (AverageHit x hit chance x Speed), its own projectile count / DPS multipliers in (CullMultiplier
# divided out), at least 1 (MEDIUM: Repeats PoB doesn't score aren't counted, an undercount there). One per use as a row.


def ll_hits_a_use(row: dict) -> float:
    """Hits on the boss a use of the skill whose useRates row this is, as PoB scores them (see above); 1 when unreadable."""
    speed, hit = number(row.get("speed")), number(row.get("AverageHit"))
    if hit <= 0:
        # (MECHB44) an Attack's hit is per hand (bridge.useRates' MainHand. / OffHand.AverageHit): dual wielding, PoB's
        # TotalDPS alternates the hands, so their mean stands for one hit (MEDIUM); one hand alone is that hand's
        hands = [h for h in (number(row.get("MainHand.AverageHit")), number(row.get("OffHand.AverageHit"))) if h > 0]
        hit = sum(hands) / len(hands) if hands else 0.0
    chance = min(number(row.get("HitChance")) or 100.0, 100.0) / 100
    dps = number(row.get("TotalDPS")) / max(number(row.get("cullMultiplier")) or 1.0, 1.0)
    if speed <= 0 or hit <= 0 or chance <= 0 or dps <= 0:
        return 1.0
    return max(1.0, dps / (hit * chance * speed))


def living_lightning_model(parts: list[dict]) -> tuple[float, list[dict]]:
    """(added DPS, notes) for the build's Living Lightning groups. Each part: source (the supported skill), hits (its
    hits on the boss a second), uses (its uses that hit, a second; default hits), lightning (whether it deals Lightning hit damage), cooldown (the trigger's, s), level (its level
    stats), zap (PoB's AverageDamage of one Zap) and pob (PoB's own Full DPS entry, or None)."""
    total, row, dispersed, parts_how = 0.0, 0.0, 0.0, []
    for p in parts:
        level = p.get("level") or {}
        attacks = number(level.get(LL_ATTACKS[0])) or LL_ATTACKS[1]
        every = (number(level.get(LL_ATTACK_MS[0])) or LL_ATTACK_MS[1]) / 1000
        limit = number(level.get(LL_LIMIT[0])) or LL_LIMIT[1]
        hits, cooldown, zap = number(p.get("hits")), number(p.get("cooldown")), number(p.get("zap"))
        caps = [(hits, f"{p.get('source')}'s {hits:.2f} hits/s")]
        if cooldown <= 0:
            cooldown, cd_how = LL_COOLDOWN, "its level-1 0.2 s cooldown (PoB reads none at this level)"
        else:
            cd_how = f"its {cooldown:.3g} s cooldown"
        caps.append((1 / cooldown, cd_how))
        caps.append((limit / (attacks * every), f"{limit:g} alive at {attacks:g} x {every:g} s each"))
        made, why = min(caps, key=lambda c: c[0]) if p.get("lightning") else (0.0, f"{p.get('source')} deals no Lightning hit")
        dps = made * attacks * zap
        total += dps
        dispersed += made
        uses = number(p.get("uses")) if p.get("uses") is not None else hits
        per_use = min([uses] + [c[0] for c in caps[1:]]) if p.get("lightning") else 0.0
        row += per_use * attacks * zap
        pob = p.get("pob")
        parts_how.append(f"{made:.2f} minions/s ({why}; {hits / uses if uses > 0 else 1:.2f} hits on the boss a use) x "
                         f"{attacks:g} Zaps x {zap:,.1f} a Zap = {dps:,.1f} DPS"
                         + (f" (PoB's own entry: {number(pob):,.1f}, as one minion attacking all fight)" if pob else ""))
    if not parts:
        return 0.0, []
    note = {"label": "Living Lightning: 3 Zaps a minion, one minion per Lightning hit*", "value": f"{total:,.1f} DPS",
            "basis": ("Triggered on dealing Lightning damage with the supported skill, its minions Attack every 0.14 s "
                      "and disperse after 3 Attacks (the game's text): " + "; ".join(parts_how) + ". PoB scores a minion "
                      "that never disperses: its entry is replaced (an OVERCOUNT before, where it was in Full DPS). "
                      "One minion per Lightning hit on the boss (RESEARCH34 R34-5, MEDIUM-HIGH), the hits a use as PoB "
                      "scores them (MEDIUM), up to the cooldown's and the limit's caps; one minion per use instead: "
                      f"{row:,.1f} DPS (a row). Its minions aren't Persistent, so their dispersal feeds no minion-death "
                      "model (Cast on Minion Death needs Persistent minions since 0.2.0, HIGH; 'Killed' effects never; "
                      f"'dies' effects: no, MEDIUM-LOW, RESEARCH34 R34-4); if a dispersal counted as a death: "
                      f"{dispersed:.2f} a second (a row, not counted)"),
            "play": "Living Lightning needs the supported skill to deal Lightning damage; its minions fire 3 Zaps each",
            "confidence": "MEDIUM", "full_dps": {LIVING_LIGHTNING: 0.0}}
    return total, [note]


# Dark Effigy's Vile Effusion (MECHB43, an OVERCOUNT of one projectile a volley; RESEARCH34 R34-7, research/dark-effigy-
# debuff-count.md). The game (ActiveSkills / poe2db Dark_Effigy): "Fire a Projectile at every nearby enemy that is afflicted
# by a Chaos damage over time Debuff. Fires multiple Projectiles at enemies afflicted by multiple Debuffs": on a lone boss,
# a volley = the distinct Chaos-DoT debuff TYPES on it (the Debuff keyword: "Debuffs of the same type do not stack"; Poison
# stacks add none, MEDIUM; forum 3626927 / 3773666 / 3775944), 0 with none. PoB (act_int.lua 4920): DPS MORE 100 per the
# enemy's Multiplier:ChaosDebuff, which Contagion, Essence Drain, Profane Ritual, Soulrend (each skill's GlobalEffect
# Debuff, act_int.lua 4008 / 6657 / 16053 / 19825), Decaying Hex (sup_int.lua 2861) and Vile Effusion's own Poison line
# (under the PLAYER's Condition Poisoned, not the boss's: counted in PoB's k when that box is on) each set to 1: x (1 + k), one more
# projectile than the game's k, always on (probe POE2T4635: Essence Drain alone, PoB's TotalDPS / AverageHit / Speed = 2).
# Here: k' = the sum, over the debuff types the build keeps on the boss, of each one's uptime: a skill's min(1, its uses
# a second (PoB's use rate x the press model's share) x its Duration) (MEDIUM); Poison 1 while the resolver has the boss
# Poisoned (MEDIUM); Decaying Hex 1 when a curse it supports is in the build (curses are kept up: MECH33's curse_uses;
# R34-7's headline MEDIUM-LOW; the row: it doesn't count). Vile Effusion's DPS x k' / (1 + k) as a DPS MORE on it.
# Withered never counts (a damage-taken debuff, HIGH). Other Chaos-DoT debuffs (a chaos ground, an item's) aren't counted:
# an UNDERCOUNT where a build has one (R34-7: MEDIUM-LOW that they count). Rows: Decaying Hex not counting; one per Poison
# stack (LOW).
VILE_EFFUSION = "Vile Effusion"
EFFIGY_DEBUFF_SKILLS = ("Contagion", "Essence Drain", "Profane Ritual", "Soulrend")  # (PoB's ChaosDebuff setters)
DECAYING_HEX = "Decaying Hex"


def dark_effigy_model(debuffs: list[tuple[str, float, str]], pob_debuffs: int, hex_up: float,
                      poisoned: float) -> tuple[list[dict], list[dict]]:
    """(mods, notes) for Vile Effusion: `debuffs` (skill, its uptime on the boss, how) for the build's Chaos-DoT debuff
    skills, `pob_debuffs` the ChaosDebuff count PoB uses (its k), `hex_up` Decaying Hex's (1 or 0), `poisoned` the boss's
    Poisoned share (1 / 0)."""
    skills_up = sum(min(1.0, max(0.0, up)) for _, up, _ in debuffs)
    game = skills_up + hex_up + poisoned
    pob = 1 + max(0, pob_debuffs)
    factor = game / pob
    parts = [f"{name} {min(1.0, up):.0%} ({how})" for name, up, how in debuffs]
    parts += [f"Decaying Hex {hex_up:.0%} (a curse it supports, kept up; R34-7 MEDIUM-LOW)"] if hex_up else []
    parts += ["Poison 100% (the boss Poisoned; once, not per stack)"] if poisoned else []
    note = {"label": "Dark Effigy: one Vile Effusion projectile per Chaos-DoT debuff on the boss*",
            "value": f"{game:.2f} a volley, not PoB's {pob}",
            "basis": ("Vile Effusion fires one projectile per Chaos damage-over-time Debuff type on the boss (RESEARCH34 "
                      "R34-7, MEDIUM; same-type debuffs don't stack, Poison stacks add none): "
                      + ("; ".join(parts) if parts else "none on the boss: no projectiles")
                      + f" = {game:.2f}. PoB fires 1 + its {pob_debuffs} debuff(s) = {pob} (an OVERCOUNT of one a volley; "
                      f"0 debuffs: 1, not 0): x{factor:.2f}. Rows: Decaying Hex not counting, {game - hex_up:.2f}; one per "
                      "Poison stack (LOW, not computed). Not counted: Chaos-DoT debuffs from grounds or items (an "
                      "UNDERCOUNT where the build has one)"),
            "play": ("Keep your Chaos damage-over-time debuffs (" + ", ".join(n for n, _, _ in debuffs) + ") on the boss: "
                     "each adds a Vile Effusion projectile" if debuffs else ""),
            "confidence": "MEDIUM"}
    if abs(factor - 1) < 1e-9:
        return [], [note]
    mod = raw_mod("DPS", "MORE", 100 * (factor - 1), VILE_EFFUSION)
    mod[HIT_CUT_PER_USE] = factor  # (MECHB53, MECH99's split: projectiles a volley, the skill used as often)
    return [mod], [note]


# Verisium Manifestations (MECHB42; RESEARCH33 R33-10, research/verisium-manifestation-numbers.md; an UNDERCOUNT: PoB had
# no minion for it, 0). ActiveSkills 1129: "While active, Hitting with an Attack will spend Runic Ward to summon a
# Verisium Manifestation, a short-lived Temporary Minion that rapidly Attacks nearby enemies". Manifest Rune
# (TriggeredManifestRunePlayer): limit 10 (base_number_of_verisium_runes_allowed), 8 s each (base_skill_effect_duration),
# a 0.5 s cooldown with 5 stored uses, Ward 30 a summon at level 20 (HIGH, game tables and PoB). The minion and its
# attack are added to PoB by engine/bridge.lua (Physical x0.70 x1.5, 1.0 s attack: MEDIUM / MEDIUM-LOW), so PoB scores
# ONE Manifestation with the build's minion modifiers. Here: summons a second planned = min(the main Attack's hits a
# second (PoB's speed x hit chance; other attack skills' hits not counted, an undercount), 1 / its cooldown (PoB's, with
# recovery)), handed to PoB as Manifest Rune's trigger rate, which ward_paid holds to what the build's Runic Ward
# recovery pays for (30 a summon); alive = min(the limit, the paid summons a second x its Duration, PoB's with the
# build's modifiers); PoB's one-minion Full DPS entry x alive (Objective.entry_scales), its group into Full DPS. 0 with
# no Attack main skill or no Runic Ward recovery.
VERISIUM = "Verisium Manifestations"
MANIFEST_RUNE = "Manifest Rune"
VERISIUM_LIMIT = 10.0  # base_number_of_verisium_runes_allowed
VERISIUM_SECONDS = 8.0  # its base_skill_effect_duration
VERISIUM_COOLDOWN = 0.5


def verisium_model(rune: Skill, hits: float, cooldown: float, duration: float, paid: float | None,
                   paid_how: str = "", texts: list[str] = ()) -> tuple[list[dict], list[dict], set[int]]:
    """(mods, notes, Full DPS groups) for Manifest Rune: `hits` the main Attack's hits a second, `cooldown` its (s, PoB's),
    `duration` each Manifestation's (s, PoB's), `paid` the summons a second the build's Runic Ward paid for last round
    (ward_paid; None: the planned rate), why `paid_how`."""
    cooldown = cooldown if cooldown > 0 else VERISIUM_COOLDOWN
    seconds = duration if duration > 0 else VERISIUM_SECONDS
    limit = number(rune.level_stats.get("base_number_of_verisium_runes_allowed")) or VERISIUM_LIMIT
    limit, _, limit_how = temporary_minion_limit(list(texts), limit)  # (MECHB63, R59-11: its "+N to Limit" lines)
    planned = min(max(hits, 0.0), 1 / cooldown)
    made = planned if paid is None else min(planned, max(paid, 0.0))
    alive = min(limit, made * seconds)
    note = {"label": "Verisium Manifestations: Manifestations alive*", "value": f"{alive:.2f} of {limit:g}",
            "basis": (f"one a {cooldown:.3g} s cooldown on an Attack hit ({hits:.2f} hits/s of the main skill): {planned:.2f} "
                      f"a second planned, {made:.2f} paid for by Runic Ward (30 a summon at level 20{'; ' + paid_how if paid_how else ''}), "
                      f"x {seconds:g} s each = {alive:.2f} alive (limit {limit:g}{': ' + limit_how if limit_how else ''}); "
                      "PoB scores one Manifestation (the minion "
                      "added from the game's rows: Physical x0.70 x1.5, R33-10; a 1.0 s attack, MEDIUM: RESEARCH34 R34-8, "
                      "its attack_01 timeline 1.0 s with the launch at 0.4 s, matching AttackSpeed 1000), its entry x "
                      "that. 0 before (PoB had no minion for it: an UNDERCOUNT). Row: a 0.5 s attack (a LOW what-if, no "
                      f"source supports it): twice that, {2 * alive:.2f} Manifestations' worth"),
            "play": ("Keep Runic Ward recovering and attack: each Attack hit summons a Manifestation while Ward pays for it "
                     f"(without Ward: 0; with it: {alive:.1f} of {limit:g} up)"),
            "confidence": "MEDIUM-LOW", "full_dps": {MANIFEST_RUNE: alive}}
    if planned <= 0 or rune.group is None:
        return [], [note], set()
    return trigger_rate(MANIFEST_RUNE, planned), [note], {rune.group}


# Chayula's Will, Archon of Chayula's tornado (MECHB42, an UNDERCOUNT: probe POE2T4627, PoB gives the triggered attack
# speed 0, so 0 DPS, and its group isn't in Full DPS). PoB other.lua / game 26650308 ArchonOfChayulaPlayer:
# archon_of_chayula_spawn_chaos_tornado_interval_ms 3000 (skill_stat_descriptions: "[Trigger] Chayula's Will every 3
# seconds"); ArchonOfChayulaTornadoPlayer: "Conjure a Chaos tornado that chases down and Slows enemies",
# base_skill_effect_duration 8000, archon_of_chayula_tornado_attack_interval_ms 200, 70% Physical to Chaos. So each Archon
# makes floor(D / 3) tornadoes (none at the moment it starts: the lower reading), each attacking the boss every 0.2 s for
# its Duration (PoB's, with the build's modifiers; it chases the boss, so taken to stay on it: MEDIUM). D: KeywordPopups
# Archon, "By default, each Archon Buff lasts 10 seconds", and poe2db's Archon of Chayula page, its Archon buff block:
# "Duration: 10" (fetched 19 Nov; the game's stats list have_archon_of_chayula beside have_archon_fire / _undeath).
# When the first tornado spawns isn't stated anywhere (UNVERIFIED; none at the start taken, the lower reading). Archons a second: glory_caps (MECH-C's glory_plan on the build's Chaos hits). The rate
# goes to PoB as the tornado's trigger rate (attacks a second), its group into Full DPS. Not counted: the tornadoes'
# Slow; the Archon's 20% more Physical and Chaos on the tornado hits made while it lasts (MECH-C's Archon buff).
CHAYULAS_WILL = "Chayula's Will"
ARCHON_OF_CHAYULA = "Archon of Chayula"
CHAYULA_TORNADO_EVERY = 3.0  # archon_of_chayula_spawn_chaos_tornado_interval_ms 3000
CHAYULA_TORNADO_ATTACK = 0.2  # archon_of_chayula_tornado_attack_interval_ms 200
CHAYULA_TORNADO_SECONDS = 8.0  # its base_skill_effect_duration (when PoB gives none)
ARCHON_BUFF_SECONDS = 10.0  # KeywordPopups Archon: "By default, each Archon Buff lasts 10 seconds"


def chayulas_will_model(tornado: Skill, archons: float, archons_how: str, duration: float = 0.0,
                        archon_seconds: float = 0.0, moving: tuple[float, str] = (0.0, "")
                        ) -> tuple[list[dict], list[dict], set[int]]:
    """(mods, notes, Full DPS groups): Chayula's Will's attacks a second as its trigger rate, from `archons` (Archon of
    Chayula uses a second, how `archons_how`), the tornado's `duration` (PoB's; 0: its base 8 s), the Archon's own
    `archon_seconds` (the build's Archon duration; 0: the base 10 s) and the boss preset's `moving` ceiling (a row)."""
    seconds = duration if duration > 0 else CHAYULA_TORNADO_SECONDS
    lasts = archon_seconds if archon_seconds > 0 else ARCHON_BUFF_SECONDS
    per_archon = math.floor(lasts / CHAYULA_TORNADO_EVERY + 1e-9)
    hits = max(0.0, archons) * per_archon * seconds / CHAYULA_TORNADO_ATTACK
    at_start = max(0.0, archons) * (per_archon + 1) * seconds / CHAYULA_TORNADO_ATTACK
    share, share_how = moving
    note = {"label": "Chayula's Will: Archon of Chayula's tornadoes*", "value": f"{hits:.2f} attacks/s",
            "basis": (f"{archons:.4f} Archons a second ({archons_how}) x {per_archon} tornadoes an Archon (one every "
                      f"{CHAYULA_TORNADO_EVERY:g} s of its {lasts:g} s: 10 s at base, KeywordPopups Archon and poe2db's "
                      "Archon buff 'Duration: 10', with the build's Archon duration lines; the first at 3 s, none as it "
                      "starts: RESEARCH34 R34-3, MEDIUM-LOW, UNVERIFIED) x one attack every "
                      f"{CHAYULA_TORNADO_ATTACK:g} s for its {seconds:g} s (each tornado chases the boss and Slows it "
                      "near it: taken to stay on a lone boss its whole Duration, outliving the Archon, R34-3 MEDIUM). "
                      "PoB gives the triggered tornado no rate (0 before: an UNDERCOUNT). Rows: one at the start too, "
                      f"{per_archon + 1} an Archon: {at_start:.2f} attacks/s"
                      + (f"; the boss moving at its most ({share_how}): {hits * (1 - share):.2f} attacks/s"
                         if share > 0 else "")),
            "play": ("Become the Archon whenever your Glory is full: each one conjures Chaos tornadoes that chase the "
                     f"boss (without it 0; with it {per_archon} tornadoes an Archon)"),
            "confidence": "MEDIUM-LOW"}
    if hits <= 0 or tornado.group is None:
        return [], [note], set()
    return trigger_rate(CHAYULAS_WILL, hits), [note], {tornado.group}


# Archon of Chayula's cycle (MECH101, on loan from MECH-B / MECH-C: the manager 21:55 from RESEARCH48 R48-10..12; an
# OVERCOUNT before: glory_plan took one Archon per (its 10 s instance + the Glory refill), so the tornadoes and every
# reader of the Archon's uses skipped the Archon recovery period). R48-10 (MEDIUM-HIGH): Archon of Chayula is an Archon
# Buff (BuffDefinitions archon_of_chayula, built as the other six; KeywordPopups Archon: "You cannot gain any Archon Buff
# while you already have one, or during a recovery period after you lose one, which lasts 20 seconds by default", the
# "Archon Recovery" buff archon_delay; nothing exempts it). One cycle: the Archon lasts D (10 s x the build's Archon
# duration lines x "Buffs on you expire slower"), then the next comes after the later of the Glory refill (no Glory while
# the Archon is up: refill = 1 / the Glory plan's uses - its 10 s instance) and the recovery period (20 s, faster with
# "Archon Recovery expires N% faster" lines; none with "Archon Buffs have no recovery period", ArchonNoRecovery). The
# Archon-wide modifiers taken to apply to it (R48-10, MEDIUM). Readers: Assumptions.glory_caps caps Archon of Chayula's
# uses with it (so press_caps, chayulas_will_model's tornadoes and the Withered reader all take the capped rate); the
# Withered reader and the 20% more reader (chayula_more_model) take its uptime.
def chayula_cycle(glory_uses: float, duration_inc: float = 0.0, recovery_faster: float = 0.0, expiry: float = 1.0,
                  no_recovery: bool = False) -> tuple[float, float, float, str]:
    """(Archons a second, the share of the fight it is up, that share with no recovery period (a row), how) from the
    Glory plan's `glory_uses` a second and the build's Archon modifiers (the note above)."""
    lasts = ARCHON_BUFF_SECONDS * max(0.0, 1 + duration_inc / 100) * expiry
    if glory_uses <= 0 or lasts <= 0:
        return 0.0, 0.0, 0.0, "no Archon of Chayula (its Glory never fills)"
    refill = max(0.0, 1.0 / glory_uses - GLORY_INSTANCE.get(ARCHON_OF_CHAYULA, 0.0))
    recovery = 0.0 if no_recovery else ARCHON_RECOVERY / max(1 + recovery_faster / 100, 1e-9)
    cycle = lasts + max(refill, recovery)
    row = lasts / (lasts + refill)
    how = (f"one Archon of Chayula every {cycle:.1f} s: it lasts {lasts:g} s, then the later of its Glory refill "
           f"({refill:.1f} s) and the Archon recovery period ("
           + ("none: 'Archon Buffs have no recovery period'" if no_recovery else f"{recovery:.1f} s")
           + "; RESEARCH48 R48-10, MEDIUM-HIGH): up "
           f"{lasts / cycle:.0%} of the fight (without the recovery period: {row:.0%})")
    return 1.0 / cycle, lasts / cycle, row, how


# The Archon's own damage (MECH101 on loan, the manager 21:55 from RESEARCH48 R48-12, HIGH; an UNDERCOUNT: no reader, PoB
# maps no archon_of_chayula stat): archon_of_chayula_physical_and_chaos_damage_+%_final 20 becomes the buff's
# physical_damage_+%_final_from_archon_buff and chaos_damage_+%_final_from_archon_buff, "You deal more Physical and Chaos
# Damage" (the buff's text): 20% more Physical and 20% more Chaos damage with all your damage while it is up. Counted at
# the Archon's share of the fight (chayula_cycle): x(1 + 0.2 up) on each, exact as a time average for a more multiplier
# on damage dealt (the ailments' and the tornado's timing within the Archon not weighed: Chayula's Will deals half its
# hits during it at the defaults, so its share is undercounted, the lower reading). Scaled by the build's "increased
# effect of Archon Buffs on you" lines (ArchonEffect; an Archon-wide modifier, MEDIUM).
CHAYULA_MORE = 20.0


def chayula_more_model(up: float, how: str, effect_inc: float = 0.0) -> tuple[list[dict], list[dict]]:
    """(mods, notes): the Archon of Chayula's 20% more Physical and Chaos damage at its share of the fight `up`."""
    more = CHAYULA_MORE * max(0.0, 1 + effect_inc / 100)
    scale = more * max(0.0, min(1.0, up))
    note = {"label": "Archon of Chayula: 20% more Physical and Chaos damage while it is up*",
            "value": f"{scale:.1f}% more on average",
            "basis": (f"{more:g}% more Physical and Chaos damage (RESEARCH48 R48-12: the buff's physical_ / "
                      f"chaos_damage_+%_final_from_archon_buff" + (f", x{1 + effect_inc / 100:.2f} Archon effect" if
                                                                   effect_inc else "")
                      + f") for the {up:.0%} of the fight it is up ({how}): without the Archon +0%, while it is up "
                      f"+{more:g}%"),
            "play": "Become the Archon whenever your Glory is full and the recovery period has passed",
            "confidence": "MEDIUM-HIGH"}
    if scale <= 0:
        return [], [note]
    return [line("1% more Physical Damage", scale), line("1% more Chaos Damage", scale)], [note]


# Moment of Vulnerability (MECH102; the manager 01:15, THE USER's Oracle build review: "ascendancy skills must be used";
# RESEARCH49 R49-8, research/oracle-skills-notables-megalomaniac-r49.md: numbers HIGH, the boss model MEDIUM-LOW). The
# Oracle's Converging Paths grants it; nothing read it, so it added nothing (an UNDERCOUNT). The game's text: "Hitting
# enemies that are Primed for Stun, Electrocution, or Freeze causes a visage of them to appear, lasting as long as the
# original target would have been affected by the form of Immobilisation used to create the visage. A portion of the
# damage dealt to visages is also dealt to the original" (MomentOfVulnerabilityPlayer: cooldown 1 s, cast 0.65 s, a 4 m
# Nova, its own hit negligible; time_rip_damage_share_% 98 at gem 20; rip_from_time_immunity_duration_ms 10000, "10
# second delay before enemy can be affected again"). Primed (KeywordPopups PrimedStun / PrimedFreeze /
# PrimedElectrocution): 70% buildup for Unique enemies (PRIMED_FREEZE_UNIQUE). Model, per kind (Freeze, Electrocute,
# Heavy Stun), from the build's OWN buildup (no flat rate: the user's rule): its cycle P and duration D (immobilise_period
# / immobilise_duration; heavy_stun_rate and the boss preset's heavy_stun_s, MECH-D's, read only); in a cycle the boss is
# Primed from 70% of the refill (P - D, taken as linear: MEDIUM, the x6 window after a real one makes it uneven) until the
# bar fills; a visage at the first Primed moment, the next at the first Primed moment after the 10 s immunity
# (mov_visages, walked through the fight: boss_pool / FullDPS, at most 30 min; a bar that never reaches 70% in it makes
# none). The visage up (visages x D) / the fight; the best kind counts (the immunity is the skill's, whatever kind: mixing kinds
# not counted, the lower reading). The boss takes x(1 + share x up x b), b the share of the build's damage that hits
# both: 1 for an Area main skill, else 0 (where the visage stands isn't in any file: the lower reading, with the b = 1 row).
# Less its cast time once per visage (you press it when the boss is Primed). Labelled, UNVERIFIED (R49-8): whether making
# the visage spends the buildup or stops the real immobilisation (neither taken), whether the visage has the boss's
# resistances (taken as the same), buildup decay (not modelled, as everywhere).
MOV = "Moment of Vulnerability"
MOV_SHARE_STAT = "time_rip_damage_share_%"
MOV_IMMUNE_STAT = "rip_from_time_immunity_duration_ms"
MOV_SHARE = 98.0  # % at gem 20 (R49-8), when the level stats aren't read
MOV_IMMUNE = 10.0  # s
MOV_CAST = 0.65  # s (PoB's castTime), when the skill's own isn't read
MOV_ENTRY = "model-mech102-moment-of-vulnerability"


MOV_FIGHT_CAP = 1800.0  # s, the longest fight read (as Assumptions' fight readers)


def mov_visages(period: float, duration: float, fight: float | None, immune: float = MOV_IMMUNE,
                primed: float = PRIMED_FREEZE_UNIQUE, lasts: float | None = None) -> tuple[float, int]:
    """(the share of the fight a visage is up, visages made) (see the note above): the bar refills from empty at each
    cycle's start (k x `period`, the refill `period` - `duration`), the boss Primed from `primed` of the refill until it
    fills (then the real immobilisation); a visage at the first Primed moment at least `immune` s after the last, each
    lasting `duration`, within a `fight` of that many s (None: MOV_FIGHT_CAP). A bar that doesn't reach `primed` within
    the fight makes none (MECH102's probe POE2T6483: a 4,000,000 s cycle counted a visage every 10 s before, an
    OVERCOUNT, since buildup that slow never Primes a boss in a real fight). `lasts` (MECH103): how long a visage takes
    damage, if not the immobilisation's `duration` (it dies sooner: mov_visage_life)."""
    fight = min(fight, MOV_FIGHT_CAP) if fight and fight > 0 else MOV_FIGHT_CAP
    each = duration if lasts is None else max(0.0, min(lasts, duration))
    if period <= 0 or not math.isfinite(period):
        return 0.0, 0
    refill = max(period - duration, 0.0)
    total, made, last, k = 0.0, 0, -math.inf, 0
    while k < 100000:
        start, end = k * period + primed * refill, k * period + refill
        if start >= fight:
            break
        t = max(start, last + immune)
        while t <= min(end, fight):
            total += min(each, fight - t)
            made, last = made + 1, t
            t += immune
        k += 1
    return min(1.0, total / fight), made


# MECH103 (the manager 06:50, PRIORITY; RESEARCH52 R52-3, research/moment-of-vulnerability-visage-r52.md: two possible
# OVERCOUNTS in MECH102's model). (1) WHERE IT STANDS: never on the boss (HIGH: patch 0.4.0b "could fail to create
# Visages if there's no unoccupied area nearby"); it falls away behind the boss (players, MEDIUM: "builds with large
# amounts of aoe ... will hit the visage the moment it spawns"; "Projectile builds that aren't piercing will be
# completely unable to use moment of vulnerability more often than not"). So "every Area main skill reaches both" was
# the HIGH reading: now b = 1 for an Area main skill of radius >= MOV_REACH_RADIUS (PoB's AreaOfEffectRadius) or a
# projectile that pierces or chains (PierceCount / ChainMax: it passes the boss into the visage), 0.5 for a smaller
# area (LOW: in reach about half the time), else 0; rows at 1 / 0.5 / 0. (2) IT CAN DIE: the visage is a monster
# (Metadata/Monsters/Clone/RipFromTimeClone.ot, "Life { on_death = {Delete();} }"; MonsterVarieties "Vision"
# LifeMultiplier 100; its MonsterType no resistances, no armour): a normal monster's Life at the boss's level
# (pob_monster_life; whether the skill raises it: UNVERIFIED, taken: no), so it takes damage only until the hits that
# kill it land: ceil(Life / the main skill's hit) hits at its hits a second (mov_visage_life), the damage of those hits
# shared (overkill counted, "only that hit is shared": R52-3's one-hit row; without the overkill, its Life only: a row).
# Its resistances: none by its own data, so the hit on it is the unmitigated one; whether the boss's resistances cut the
# shared part again is UNVERIFIED (taken: yes, the lower reading; without it x 1 / (1 - the boss's resistance), a row in
# words). Whether making it spends the buildup: still UNVERIFIED (the one-a-cycle row kept).
MOV_REACH_RADIUS = 3.0  # m (R52-3: an area of ~3 m centred on the boss reaches the visage beside it; LOW)
MOV_SMALL_REACH = 0.5  # (R52-3, LOW: a smaller area reaches it about half the time)


def mov_reach(area: bool, radius: float, passes: bool) -> tuple[float, str]:
    """(the share of the main skill's damage that also hits the visage, why) (see MECH103's note above): `radius` the
    main skill's area radius in m (0 unread), `passes` its projectiles pierce or chain."""
    if passes:
        return 1.0, "its projectiles pierce or chain, passing the boss into the visage behind it (R52-3)"
    if area and radius >= MOV_REACH_RADIUS:
        return 1.0, f"an Area skill of {radius:.1f} m radius around the boss reaches the visage beside it (R52-3)"
    if area:
        return MOV_SMALL_REACH, (f"an Area skill of {radius:.1f} m radius (under {MOV_REACH_RADIUS:g} m) reaches the "
                                 "visage about half the time (R52-3, LOW)" if radius > 0 else
                                 "an Area skill, its radius not read: in reach about half the time (R52-3, LOW)")
    return 0.0, ("neither an Area skill nor a piercing / chaining projectile: the visage falls away behind the boss, out "
                 "of its reach (R52-3)")


def mov_visage_life(life: float, hit: float, hits: float, duration: float) -> tuple[float, float, str]:
    """(seconds a visage takes damage with the overkill counted, without it, why): it dies after ceil(`life` / `hit`)
    hits at `hits` a second (MECH103's note); `duration` if the Life or the hit isn't read."""
    if life <= 0 or hit <= 0 or hits <= 0:
        return duration, duration, "its Life or the main skill's hit not read: up for the immobilisation's duration"
    needed = math.ceil(life / hit)
    with_over = min(duration, needed / hits)
    without = min(duration, life / hit / hits)
    plural = "s" if needed > 1 else ""
    return with_over, without, (f"a normal monster's {life:,.0f} Life at the boss's level (no resistances, R52-3): "
                                f"{needed} hit{plural} of {hit:,.0f} kill it, {with_over:.2f} s of its {duration:g} s "
                                f"at {hits:.2f} hits/s")


def moment_of_vulnerability_model(main: Skill | None, stats: dict, area: bool, level_stats: dict | None = None,
                                  cast_time: float = 0.0, fight: float | None = None, radius: float = 0.0,
                                  passes: bool = False, life: float = 0.0) -> tuple[list[dict], list[dict]]:
    """(mods, notes): the visage's repeated damage on the boss (see the note above). `area`: the main skill is an Area
    skill; `level_stats`: Moment of Vulnerability's (the bridge's levelStats); MECH103: `radius` its area radius in m,
    `passes` its projectiles pierce or chain (mov_reach), `life` the visage's Life (mov_visage_life; 0 unread)."""
    level_stats = level_stats or {}
    share = number(level_stats.get(MOV_SHARE_STAT)) or MOV_SHARE
    immune = number(level_stats.get(MOV_IMMUNE_STAT)) / 1000 or MOV_IMMUNE
    cast = cast_time if cast_time > 0 else MOV_CAST
    kinds = []
    for kind in ("Freeze", "Electrocute"):
        period = immobilise_period(stats, kind)
        if period > 0:
            kinds.append((kind, period, immobilise_duration(stats, kind)))
    stuns, _ = heavy_stun_rate(stats)
    if stuns > 0:
        kinds.append(("Heavy Stun", 1.0 / stuns, bosses.of(stats).heavy_stun_s))
    seconds = min(fight, MOV_FIGHT_CAP) if fight and fight > 0 else MOV_FIGHT_CAP
    rows = []
    for kind, period, duration in kinds:
        up, made = mov_visages(period, duration, fight, immune)
        rows.append((up, kind, period, duration, seconds / made if made else math.inf))
    note = {"label": f"{MOV}: the boss's visage takes your damage too*", "entry": MOV_ENTRY,
            "confidence": "MEDIUM-LOW (R49-8)"}
    if not rows or max(r[0] for r in rows) <= 0:
        return [], [{**note, "value": "+0%",
                     "basis": ("the build's Freeze, Electrocute and Heavy Stun buildup doesn't bring the boss to 70% (Primed, "
                               f"a Unique enemy) within the {seconds:.0f} s fight, so it is never Primed and no visage "
                               "appears: 0 (the user's no-flat-rate rule)"),
                     "play": f"Build Freeze, Electrocute or Heavy Stun on the boss to Prime it, then use {MOV}"}]
    up_full, kind, period, duration, every = max(rows)
    reach, reach_why = mov_reach(area, radius, passes)
    hits = hits_per_second(stats)
    lasts, lasts_bare, life_why = mov_visage_life(life, number(stats.get("AverageHit")), hits, duration)
    up = mov_visages(period, duration, fight, immune, lasts=lasts)[0]  # (MECH103: until it dies)
    gain = share / 100 * up * reach
    cost = min(1.0, cast / every) if gain > 0 else 0.0
    total = (1 + gain) * (1 - cost) - 1

    def at(b: float, u: float) -> float:
        return (1 + share / 100 * u * b) * (1 - (min(1.0, cast / every) if u * b > 0 else 0.0)) - 1
    reach_rows = ", ".join(f"{b:g}: {at(b, up):+.1%}" for b in (1.0, MOV_SMALL_REACH, 0.0) if b != reach)
    up_bare = mov_visages(period, duration, fight, immune, lasts=lasts_bare)[0]
    # (the other reading of R49-8's open point: making the visage spends the buildup, so one visage a cycle at most)
    spent = mov_visages(period, duration, fight, max(period, immune), lasts=lasts)[0]
    row_spent = at(reach, spent)
    others = "; ".join(f"{k}: every {e:.1f} s, up {u:.0%}" for u, k, _, _, e in sorted(rows, reverse=True)[1:])
    basis = (f"Primed by {kind}: the build's own cycle {period:.1f} s ({duration:g} s each, the boss Primed from 70% of "
             f"the refill), so a visage every {every:.1f} s on average over the {seconds:.0f} s fight (its {immune:g} s "
             f"immunity), up {up_full:.0%} of the fight if it lived its whole {duration:g} s; it dies sooner: "
             f"{life_why} (R52-3: a monster with its own Life, deleted when it dies; whether the skill raises its Life: "
             f"UNVERIFIED), so it takes damage {up:.1%} of the fight; {share:g}% of the damage dealt to it also dealt "
             f"to the boss (its overkill counted, 'only that hit is shared'; without the overkill: "
             f"{at(reach, up_bare):+.1%}; if it lived its whole duration: {at(reach, up_full):+.1%})"
             + (f"; the other kinds: {others}" if others else "")
             + f"; reach {reach:g}: {reach_why} (other reach rows {reach_rows})"
             + f"; less one {cast:g} s cast every {every:.1f} s. Its resistances: none by its own data (R52-3), so the "
               "hit on it is unmitigated; the boss's resistances taken to cut the shared part again (UNVERIFIED; if "
               "not, higher by 1 / (1 - the boss's resistance)). Whether the visage spends the buildup (taken: it "
               f"doesn't, so a Primed boss allows one every {immune:g} s until its bar fills; if it does, one a cycle: "
               f"{row_spent:+.1%}) or stops the real immobilisation: UNVERIFIED")
    play = (f"Keep the boss Primed for {kind} and use {MOV} when it is (once every {every:.1f} s); without it: +0%, "
            f"with it: {total:+.1%}")
    if total <= 0 < gain:  # (MECH103: the cast costs more than the visage gives back: a player doesn't press it)
        return [], [{**note, "value": "+0%", "basis": basis + f"; net {total:+.1%}, so it isn't pressed: 0",
                     "play": f"Don't press {MOV} here: its cast costs more than the visage gives back ({total:+.1%})"}]
    out = [{**note, "value": f"{total:+.1%}", "basis": basis, "play": play}]
    if abs(total) < 1e-9:
        return [], out
    return [line("1% more Damage", 100 * total)], out


# "Empowered Attacks Gain N% of [Physical] Damage as Extra <Type> Damage" (MECHB41, an UNDERCOUNT; the coverage audit's
# notables Hail "16% of Damage as Extra Cold" and Cremating Cries "15% of Physical Damage as Extra Fire"). PoB leaves both
# unparsed (ModCache 7252-7253: nil), so they counted nothing. Now the same gain on the main skill at the share of its
# uses that are Empowered (Assumptions.empowered_uses, every Empowering skill of the build; MECH86's empowered_buildup
# form), for an Attack main skill: "Gain N% of [Physical] Damage as Extra <Type> Damage" scaled by that share (gain-as is
# linear in its %, so the average over uses is right).
EMPOWERED_GAIN = re.compile(r"^empowered attacks gain (\d+(?:\.\d+)?)% of (physical )?damage as extra "
                            r"(cold|fire|lightning|chaos|physical) damage$", re.I)


def empowered_gain(texts: list[str]) -> dict[tuple[str, str], float]:
    """{("Physical " or "", "Cold"): summed %} from the build's "Empowered Attacks Gain ..." lines."""
    out: dict[tuple[str, str], float] = {}
    for t in texts:
        if m := EMPOWERED_GAIN.match(t.strip()):
            key = ("Physical " if m.group(2) else "", m.group(3).title())
            out[key] = out.get(key, 0.0) + float(m.group(1))
    return out


def empowered_gain_model(gains: dict[tuple[str, str], float], main: str, share: float,
                         how: str) -> tuple[list[dict], list[dict]]:
    """(mods, notes): each gain on `main` at the Empowered `share` of its uses."""
    mods, notes = [], []
    for (of, kind), pct in gains.items():
        text = f"Gain 1% of {of}Damage as Extra {kind} Damage"
        if share > 0:
            mods.append(line(text, pct * share, skill=main))
        notes.append({"label": f"Empowered Attacks gain {of.lower()}damage as {kind}*",
                      "value": f"+{pct * share:.3g}% on {main} ({pct:g}% x {share:.0%})",
                      "basis": f"{share:.0%} of {main}'s uses are Empowered: {how} (without Empowering skills: 0; PoB "
                               "leaves the line unparsed)",
                      "confidence": "MEDIUM (the Empowered share, Assumptions.empowered_uses)"})
    return mods, notes


# "Skills which Empower an Attack have N% chance to not count that Attack" (MECHB41, an UNDERCOUNT; the coverage audit's
# Serle's Grit, unique one-hand mace (10-20)%, and its rune Legacy of Serle's Grit's bonded 20%: game 26650308 Mods
# UniqueChanceForExertedAttackToNoteReduceCount1, stat chance_for_exerted_attacks_to_not_reduce_count_%), and the Tireless
# support's same stat (25%, Warcries only: "Attacks Empowered by Supported Skills have a chance not to lower the
# Empowerment count of Supported Skills"). PoB reads none of it (checked: ModCache 9407-9409 nil; the stat id appears in
# vendor PoB src only in Data/Skills act_str.lua's altQualityStats and sup_str.lua's Tireless). Each Empowered Attack that
# doesn't count leaves the count for another: n counted become n / (1 - p) Empowered Attacks (a geometric count; chances
# from the sources added). The items' lines go to PoB as ExtraEmpoweredAttacks MORE (CalcPerform 2209-2210 multiplies
# every Warcry's Empower count by it: Infernal Cry's Exerted uptime and empowered_uses read it); Tireless' is one Warcry's
# only, which a skill-scoped MORE can't reach there (CalcPerform asks with no skill cfg), so empowered_uses counts it in
# Python, and the non-Warcry Empowering skills of an Attack too (PoB's own Exerted uptime misses Tireless': labelled).
EMPOWER_KEEP_STAT = "chance_for_exerted_attacks_to_not_reduce_count_%"
EMPOWER_KEEP = re.compile(r"^skills which empower an attack have (\d+(?:\.\d+)?)% chance to not count that attack$", re.I)
EMPOWER_KEEP_MAX = 0.99  # (a chance of 100% or more would never end an Empowerment: held below it, the count capped at
#                           the main skill's uses anyway)


def empower_keep(texts: list[str]) -> float:
    """The summed % of the build's "Skills which Empower an Attack have N% chance to not count that Attack" lines."""
    return sum(float(m.group(1)) for t in texts if (m := EMPOWER_KEEP.match(t.strip())))


def keep_factor(pct: float) -> float:
    """Empowered Attacks per counted one at a `pct` % chance not to count: 1 / (1 - p)."""
    return 1.0 / (1.0 - min(max(pct, 0.0) / 100.0, EMPOWER_KEEP_MAX))


def empower_keep_model(texts: list[str]) -> tuple[list[dict], list[dict]]:
    """(mods, notes): the items' chance as ExtraEmpoweredAttacks MORE on every Warcry's Empower count."""
    pct = empower_keep(texts)
    if pct <= 0:
        return [], []
    factor = keep_factor(pct)
    return [raw_mod("ExtraEmpoweredAttacks", "MORE", (factor - 1) * 100)], [{
        "label": "Empowering skills: chance not to count an Attack*", "value": f"x{factor:.3g} Empowered Attacks a use",
        "basis": (f"a {pct:g}% chance each Empowered Attack doesn't count: n counted become n / (1 - {pct / 100:g}) "
                  "(PoB reads none of the line; on Warcries through PoB's own count, on other Empowering skills of an "
                  "Attack in the tool's Empowered-use count)"),
        "confidence": "MEDIUM"}]


# Commanding Rage (MECHB41, an UNDERCOUNT; the coverage audit's notable minion_attack5): "Every five Rage also grants you 2%
# increased Minion Attack Speed" (minion_attack_speed_+%_per_five_rage) and "Every Rage also grants you 1% increased Minion
# Damage" (minion_damage_+%_per_rage); PoB leaves both unparsed (ModCache 7427-7428: nil). The only carrier of either stat
# (checked: Stats ids holding minion and rage, their carriers in game 26650308 GrantedEffectStatSets / PerLevel, Mods,
# PassiveSkills, SoulCoreStats: minion_attack5 alone; minion_attack_speed_+%_per_rage, _from_rage and
# minion_damage_+%_from_rage have none). PoB's own "Every N Rage also grants" lines read its RageEffect (ModCache 7415:
# Multiplier RageEffect, div 5), the build's Rage x Rage effect, set only when the build can gain Rage (CalcPerform
# 784-791): so the lines go to PoB as "Minions have 1% increased Attack Speed" / "Minions deal 1% increased Damage" x the
# build's RageEffect, 0 without a Rage source. A fixed number from the build's stats, not a PerStat tag: PoB adds minion
# modifiers (CalcPerform 1880 / 3149) before it sets RageEffect (doActorMisc, 3267), so a tag would read 0. "Every
# five": counted per Rage / 5, not floored to whole fives (at most 1.6% Attack Speed high between multiples of 5; LOW).
COMMANDING_RAGE = re.compile(r"^every (five |\d+ )?rage also grants you (\d+(?:\.\d+)?)% (increased|reduced) minion "
                             r"(attack speed|damage)$", re.I)


def commanding_rage(texts: list[str], rage: float) -> tuple[list[dict], list[dict]]:
    """(mods, notes): the build's "Every [five] Rage also grants you N% increased Minion Attack Speed / Damage" lines as
    minion modifiers at `rage`, PoB's RageEffect."""
    mods, notes = [], []
    for t in texts:
        if not (m := COMMANDING_RAGE.match(t.strip())):
            continue
        every = 1.0 if not m.group(1) else (5.0 if m.group(1).strip().lower() == "five" else float(m.group(1)))
        pct = float(m.group(2)) * (1 if m.group(3).lower() == "increased" else -1)
        text = "Minions have 1% increased Attack Speed" if m.group(4).lower() == "attack speed" else "Minions deal 1% increased Damage"
        if rage > 0:
            mods.append(line(text, pct / every * rage))
        notes.append({"label": f"Rage grants Minion {m.group(4).title()}*", "value": f"{pct / every * rage:+.3g}%",
                      "basis": (f"\"{t.strip()}\" at the build's {rage:g} Rage (PoB's RageEffect: Rage x Rage effect, 0 "
                                "without a Rage source); PoB leaves the line unparsed"
                                + ("; counted per Rage / 5, not whole fives (LOW)" if every > 1 else "")),
                      "confidence": "MEDIUM"})
    return mods, notes

# Cadence on a pressed skill (MECHB4; COVE6's open item) ------------------------------------------------------------------
# A pressed (non-main) skill with Cadence: COV-E's cadence_share counts its stacks only on the main skill; the press model
# holds a pressed Cadence skill to the same pace that avoids the 10 s lockout ("unusable for 10 seconds after being used 6
# or more times within four seconds": at most 5 uses in any 4 s; game files SupportCadencePlayer, maximum_stacks 6).
CADENCE_SUPPORTS = ("Cadence",)
CADENCE_PACE = (6 - 1) / 4.0


# Rapid Shot's Heat (MECHB4; RESEARCH18 #94, research/rapid-shot-heat.md, plans/kw-heat.md) ------------------------------
# "Cannot fire or reload for 10 seconds on reaching maximum Heat" (rapid_shot.csd; RapidShotPlayer's
# skill_specific_stat_description_mode 10000; poe2db, 0.3.0 notes: HIGH). Maximum Heat: maximum_number_of_crossbow_heat_stacks
# (45 at level 20; quality adds up to 15). Heat per attack: 1 (0.3.0 notes "generates Heat once per attack", poe2wiki;
# hard-coded, MEDIUM-HIGH). Decay: starts 4 s after the last gain, 10 Heat/s (0.3.0 notes; the heat_base_* stats have no
# user: MEDIUM-HIGH). Spenders: consume_X_heat_on_skill_use 15 (Explosive Grenade, Cluster Grenade, Incendiary Shot; game
# files). PoB reads none of it (plans/kw-heat.md: no Module reads Heat), so Rapid Shot as the main skill fires nonstop.
# Cycle: firing gains r x h - (Heat spent per second by the build's spenders); at maximum it stops for L s, in which the
# spenders keep spending and decay empties the rest after 4 s; then it fires again until full. Share firing = refill time
# / (refill + L). Counted as "more Damage" on Rapid Shot (not attack speed: the rate it reads would move with it), so the
# average over the fight is right; Freeze/Electrocute buildup from fewer, full hits isn't modelled (small). Not counted:
# what the player does in the lockout (other skills, unscored). The spenders' "if Heat consumed" bonuses: heat_side_spenders
# (beside a main Rapid Shot, on their own Full DPS entries; MECHB36) and heat_consumed_model (a main spender).
RAPID_SHOT = "Rapid Shot"
HEAT_PER_ATTACK = 1.0
HEAT_LOCKOUT = 10.0  # seconds (skill_specific_stat_description_mode 10000 ms; read from the gem when the bridge has it)
HEAT_DECAY_DELAY, HEAT_DECAY_RATE = 4.0, 10.0
HEAT_MAX = 45.0  # level 20, no quality (fallback when the gem's stats aren't read)
HEAT_SPENDERS = {"Explosive Grenade": 15.0, "Cluster Grenade": 15.0, "Incendiary Shot": 15.0}


# Heat consumed by the main skill (MECHB35; GEM15's routed item, the Heat model's "next"). The spenders' own stats (game
# 26650308 GrantedEffectStatSets; PoB maps none, checked SkillStatMap.lua / Modules for "heat_is_consumed"): Explosive
# Grenade and Cluster Grenade consume_X_heat_on_skill_use 15 + active_skill_all_damage_%_as_fire_if_heat_is_consumed 50;
# Incendiary Shot 15 + ignite_effect_+%_final_if_heat_is_consumed 100 (patch 0.4.0, the newest entry: "consumes 15 Heat to
# gain 100% more Ignite Magnitude"). Heat's only player source is Rapid Shot, 1 per attack (checked: the Heat stats'
# carriers in GrantedEffectStatSets / PerLevel / QualityStats, Mods Stat1-8, PassiveSkills, SoulCoreStats: only
# RapidShotPlayer's levels carry maximum_number_of_crossbow_heat_stacks, beside two monster sets; no item or passive Heat
# line). So a main spender finds 15 Heat on min(1, Rapid Shot's attacks a second / (15 x its own uses a second)) of its
# uses, Rapid Shot pressed beside it at the rate the build gives it (press_use_rate: the search's chosen rate, else 0: no
# flat rate); that share of the bonus counts (gain-as and "more" are linear in their %). Rapid Shot's time is press_model's.
HEAT_BONUS = {"Explosive Grenade": ("Gain 1% of Damage as Extra Fire Damage", 50.0),
              "Cluster Grenade": ("Gain 1% of Damage as Extra Fire Damage", 50.0),
              "Incendiary Shot": ("1% more Ignite Magnitude", 100.0)}


def heat_consumed_model(main: Skill | None, stats: dict, heat: float, heat_how: str) -> tuple[list[dict], list[dict]]:
    """The main Heat spender's "if Heat is consumed" bonus at the share of its uses that find 15 Heat (see above).
    `heat`: Heat made a second (the build's pressed Rapid Shot's attacks), `heat_how` how."""
    if main is None or main.name not in HEAT_BONUS:
        return [], []
    text, value = HEAT_BONUS[main.name]
    uses = number(stats.get("Speed"))
    cost = HEAT_SPENDERS.get(main.name, 15.0)
    share = min(1.0, heat / (cost * uses)) if uses > 0 and heat > 0 else 0.0
    bonus = text.replace("1%", f"{value:g}%")
    note = {"label": f"{main.name}: Heat consumed on its uses*", "value": f"{share:.0%} of uses",
            "basis": (f"{heat:.2f} Heat/s ({heat_how or 'no Rapid Shot pressed in the build: no Heat'}) for "
                      f"{uses:.2f} uses/s at {cost:g} Heat each: {share:.0%} of uses get \"{bonus}\" (PoB counts "
                      "none; the bonus is linear in its share, MEDIUM)"),
            "play": (f"Press Rapid Shot to build Heat, then use {main.name}: without it +0; with it {share:.0%} of uses "
                     f"get {bonus}" if share > 0 else f"Press Rapid Shot beside {main.name} to give it Heat"),
            "confidence": "MEDIUM"}
    return ([line(text, value * share, skill=main.name)] if share > 0 else []), [note]


def heat_model(main: Skill | None, stats: dict, rapid: Skill | None, spenders: list[tuple[str, float, str]]
               ) -> tuple[list[dict], list[dict]]:
    """Rapid Shot as the main skill fires only part of the fight: lockout at maximum Heat. `rapid`: its Skill with
    level_stats (maximum Heat, lockout); `spenders`: (name, uses per second, how) for the build's Heat spenders."""
    if main is None or main.name != RAPID_SHOT:
        return [], []
    level = (rapid.level_stats if rapid is not None else {}) or {}
    most = number(level.get("maximum_number_of_crossbow_heat_stacks")) or HEAT_MAX
    lockout = (number(level.get("skill_specific_stat_description_mode")) / 1000) or HEAT_LOCKOUT
    attacks = number(stats.get("Speed"))
    if attacks <= 0:
        return [], []
    spent = sum(HEAT_SPENDERS.get(name, 15.0) * uses for name, uses, _ in spenders)
    gain = attacks * HEAT_PER_ATTACK - spent
    who = "; ".join(f"{name} {uses:.2f}/s ({how}) spends {HEAT_SPENDERS.get(name, 15.0) * uses:.1f} Heat/s"
                    for name, uses, how in spenders) or "nothing in the build spends Heat"
    play = (f"Rapid Shot gains {HEAT_PER_ATTACK:g} Heat per attack ({attacks:.2f}/s) up to {most:g}; at {most:g} it can't fire "
            f"for {lockout:g} s. {who}.")
    if gain <= 0:
        side_mods, side_notes = heat_side_spenders(attacks, spenders)
        return side_mods, [{"label": "Rapid Shot: Heat never reaches maximum", "value": "x1",
                            "basis": play + " The spenders take at least what it makes, so it never locks out (needs them "
                                     "used at that rate: a play strategy*)", "confidence": "MEDIUM"}] + side_notes
    drained = min(most, HEAT_DECAY_RATE * max(0.0, lockout - HEAT_DECAY_DELAY) + spent * lockout)
    refill = drained / gain
    share = refill / (refill + lockout) if refill > 0 else 0.0
    side_mods, side_notes = heat_side_spenders(attacks * share, spenders)
    mods = [line("1% more Damage", -100 * (1 - share), skill=RAPID_SHOT)] + side_mods
    return mods, side_notes + [{"label": "Rapid Shot: share of the fight it can fire (Heat lockout)*", "value": f"{share:.1%}",
                   "basis": play + f" Heat rises {gain:.2f}/s while firing; in each {lockout:g} s lockout {drained:.0f} Heat "
                            f"drains (decay {HEAT_DECAY_RATE:g}/s from {HEAT_DECAY_DELAY:g} s after the last gain, and the "
                            f"spenders), refilled in {refill:.2f} s of firing: {share:.1%} of the fight firing (PoB: 100%). "
                            "Counted as less Damage on Rapid Shot (the fight's average). Heat per attack and the decay "
                            "are from the 0.3.0 notes (MEDIUM-HIGH); the time locked out is free for other skills, not "
                            "counted. With a Grenade or Incendiary Shot spending 15 Heat per use, it locks out less",
                   "confidence": "MEDIUM"}]


def heat_side_spenders(made: float, spenders: list[tuple[str, float, str]]) -> tuple[list[dict], list[dict]]:
    """The side Heat spenders' "if Heat is consumed" bonus beside a main Rapid Shot (MECHB36; the undercount the Heat
    model's comment named). `made`: Heat a second over the fight (Rapid Shot's attacks x the share of the fight it fires);
    `spenders`: (name, uses a second, how), as heat_model gets them. The spenders share what is made in proportion to
    their demand: each finds 15 Heat on min(1, made / (sum of 15 x uses)) of its uses (decay's loss while they wait is
    left out: a small overcount, MEDIUM), and that share of its bonus (HEAT_BONUS: gain-as and "more" are linear in their
    %) goes on its own skill (SkillName), so its Full DPS entry, which press_model scales, carries it."""
    demand = sum(HEAT_SPENDERS.get(name, 15.0) * uses for name, uses, _ in spenders if name in HEAT_BONUS and uses > 0)
    if demand <= 0:
        return [], []
    share = min(1.0, made / demand) if made > 0 else 0.0
    mods, notes = [], []
    for name, uses, how in spenders:
        if name not in HEAT_BONUS or uses <= 0:
            continue
        text, value = HEAT_BONUS[name]
        bonus = text.replace("1%", f"{value:g}%")
        if share > 0:
            mods.append(line(text, value * share, skill=name))
        notes.append({"label": f"{name} beside Rapid Shot: Heat consumed on its uses*", "value": f"{share:.0%} of uses",
                      "basis": (f"Rapid Shot makes {made:.2f} Heat/s over the fight (its attacks x the share it fires); "
                                f"the spenders ask {demand:.2f} Heat/s; {name} {uses:.2f} uses/s ({how}) gets \"{bonus}\" "
                                f"on {share:.0%} of them (PoB counts none; decay while it waits left out, MEDIUM)"),
                      "play": (f"Use {name} while Rapid Shot has Heat: without it +0; with it {share:.0%} of its uses "
                               f"get {bonus}"),
                      "confidence": "MEDIUM"})
    return mods, notes


# Guiding Palm's Guided Shrines (MECHB36; RESEARCH26 R26-39 (b), research/shrine-proc-rates-r26.md). The three Guiding
# Palm sceptres' "Grants effect of Guided Meteoric / Freezing / Tempest Shrine" (has_unique_fire / cold /
# lightning_shrine_effect) trigger the player shrine skills GTShrineFirePlayer / ColdPlayer / LightningPlayer (game files
# GrantedEffects 6283 / 6293 / 6286); the Meteoric one at most once per 2.5 s (GrantedEffectsPerLevel: Cooldown 2500 ms,
# 1 stored use; HIGH), the other two ASSUMED the same (LOW). PoB has no skill for them (its sceptre.lua carries the lines;
# no Data/Skills entry for any shrine skill, checked), so their damage is 0 in every score: a small UNDERCOUNT (the
# buff "does not scale with character modifiers", poe2wiki), kept as a labelled 0 until built (R26-39's instruction).
GUIDED_SHRINE = re.compile(r"^Grants effect of Guided (Meteoric|Freezing|Tempest) Shrine$", re.I)


# (MECHB50; RESEARCH39 R39-19, RESEARCH40 R40-1 / R40-21) The rates now: Meteoric one per 2.5 s (its Cooldown, the
# files); Freezing and Tempest have no cooldown (Cooldown 0 and a 1,000 ms cast animation: at most one a second, "the
# files' ceiling"); the Tempest Shrine timed from one video at ~2 bolts a second landing at random around the player
# (MEDIUM-LOW: boss hits ~2 x (bolt radius + boss radius)^2 / zone radius^2 a second, the zone ~3-6 m and the bolt size
# LOW); the Freezing Shrine untimed (2.5 s headline LOW, as the Meteoric; rows 1 s and Tempest's 2 a second). The bursts'
# damage is in the game files (GrantedEffectStatSets GSShrineFirePlayer BaseEffectiveness 20, GSShrineLightningPlayer
# 10, MPSShrineColdPlayer 0.6; spell base damage 0.8-1.2 / 0.5-1.5) but PoB has no skill for them, so the damage stays
# 0 until one is built (an engine task, named for the manager).
GUIDED_SHRINE_RATES = {
    "Meteoric": "one burst per 2.5 s while enemies are in range (its Cooldown, game files)",
    "Freezing": ("one per 2.5 s ASSUMED like the Meteoric (LOW: no cooldown in the files, the rate is server-side; "
                 "R39-19 / R40-1); rows: once a second (the files' ceiling: a 1 s cast, Cooldown 0) and 2 a second "
                 "like the Tempest (R40-21)"),
    "Tempest": ("~2 bolts a second at random spots around you (RESEARCH40 R40-21, one video, MEDIUM-LOW), hitting the "
                "boss ~2 x (bolt radius + boss radius)^2 / zone radius^2 a second (about 0.5 for a 1 m bolt and boss "
                "in a 4 m zone, LOW)"),
}


def guided_shrine_notes(texts: list[str]) -> list[dict]:
    """A labelled 0 for each Guided Shrine the build's items grant (see above)."""
    out = []
    for kind in sorted({m.group(1).title() for t in texts if (m := GUIDED_SHRINE.search(t.strip()))}):
        out.append({"label": f"Guided {kind} Shrine's damage (not counted)*", "value": 0,
                    "basis": (f"Guiding Palm's Guided {kind} Shrine triggers a shrine skill PoB doesn't have; "
                              f"{GUIDED_SHRINE_RATES[kind]}: its damage isn't counted, a small UNDERCOUNT (RESEARCH26 "
                              "R26-39; the bursts' damage is in the game files, but no PoB skill scores it)"),
                    "confidence": "LOW"})
    return out


def cooldown_trigger_rate(uses: float, chance: float, cooldown: float) -> float:
    """Triggers a second from `uses` a second each triggering with `chance` (0-1), at most one per `cooldown` s (MECHB37):
    after a trigger the next use past the Cooldown, then the uses until one triggers: uses / (ceil(cooldown x uses) +
    1 / chance - 1). Exact for evenly spaced uses; min(uses x chance, 1 / cooldown), what item_trigger_model used before,
    overstates it whenever the two are close (4 uses a second at 25%, 0.5 s: 0.8 a second, not 1.0)."""
    if uses <= 0 or chance <= 0:
        return 0.0
    chance = min(chance, 1.0)
    if cooldown <= 0:
        return uses * chance
    return uses / (math.ceil(cooldown * uses - 1e-9) + 1 / chance - 1)


# Skills an item triggers (MECHB36; the catalog's "Skills triggered by items and passives", the coverage ranking's #106
# and #141). PoB parses the unique's "Grants Skill: Level N X" line (ModCache ExtraSkill: Choir of the Storm's
# UniqueBreachLightningBoltPlayer, Brutus' Lead Sprinkler's TriggeredMoltenShowerPlayer), so the granted skill has its own
# group (fromItem), but not its trigger line (Molten Shower's ModCache 5942 is {{}, leftover}; neither line in ModParser
# or CalcTriggers, checked), and the search never puts an item's group in Full DPS (inner.include_in_full_dps skips
# fromItem groups): so each scored 0, an UNDERCOUNT. The model gives the granted skill its trigger rate from the build
# (models.trigger_rate) and counts its group in Full DPS:
#   - Choir of the Storm, "Trigger Lightning Bolt Skill on Critical Hit": the main skill's crits a second
#     (crits_per_second: Speed x HitChance x CritChance), at most one per its Cooldown, 0.5 s (GrantedEffectsPerLevel
#     UniqueBreachLightningBoltPlayer: Cooldown 500, 5 stored uses that only buffer bursts). Side skills' crits not read
#     (an undercount, said). MEDIUM.
#   - Brutus' Lead Sprinkler, "Hits with this Weapon have 5% chance to Trigger Molten Shower per 25 Strength": chance =
#     5% x floor(Strength / 25), at most 100%, x the main skill's hits a second when it is an Attack (taken as using this
#     weapon: an attack skill the build presses with its weapon), at most one per 0.25 s (TriggeredMoltenShowerPlayer
#     Cooldown 250). A main skill that isn't an Attack: 0 (no flat rate). MEDIUM.
# Not here (their own models are next): Dusk Vigil's Ember Fusillade (an Ember a spell cast, its limit and launch delay:
# ember_fusillade_model's maths), Tempest Caller's Elemental Storm (a storm with a duration on a 3 s Cooldown), Double
# Vision's Gemini Surge (it grants Surges, a resource: MECH-C's topic, not damage).
ITEM_TRIGGERS = (
    (re.compile(r"^Trigger Lightning Bolt Skill on Critical Hit$", re.I), "Lightning Bolt", "crit", 0.5, None),
    (re.compile(r"^Hits with this Weapon have (\d+(?:\.\d+)?)% chance to Trigger Molten Shower per (\d+) Strength$", re.I),
     "Molten Shower", "weapon_hit", 0.25, "Str"),
)


def item_trigger_model(texts: list[str], stats: dict, skills: list[Skill], main: Skill | None
                       ) -> tuple[list[dict], list[dict], set[int]]:
    """Item-triggered skills' rates from the build (see above): (lines, notes, groups to count in Full DPS)."""
    mods: list[dict] = []
    notes: list[dict] = []
    groups: set[int] = set()
    for pattern, name, event, cooldown, per in ITEM_TRIGGERS:
        match = next((m for t in texts if (m := pattern.search(t.strip()))), None)
        if match is None:
            continue
        granted = next((s for s in skills if s.name == name and s.group is not None
                        and (main is None or s.group != main.group)), None)
        if granted is None:
            continue
        if event == "crit":
            rate = crits_per_second(stats) if main is not None else 0.0
            how = (f"the main skill's crits ({rate:.2f} a second: speed x hit chance x crit chance)" if rate > 0 else
                   "the main skill doesn't crit: 0")
        else:
            chance = min(100.0, float(match.group(1)) * math.floor(number(stats.get(per)) / float(match.group(2))))
            hits = hits_per_second(stats) if main is not None and main.attack else 0.0
            rate = hits * chance / 100
            how = (f"{chance:g}% a hit ({match.group(1)}% per {match.group(2)} Strength, {number(stats.get(per)):g} "
                   f"Strength) x the main attack's {hits:.2f} hits a second" if hits > 0 else
                   "the main skill isn't an Attack with this weapon: 0 (no flat rate)")
        uses = number(stats.get("Speed"))  # (MECHB37: the cooldown's dead time, not min(rate, 1 / Cooldown))
        capped = cooldown_trigger_rate(uses, rate / uses, cooldown) if uses > 0 and rate > 0 else 0.0
        mods += trigger_rate(name, capped)
        if capped > 0:
            groups.add(granted.group)
        notes.append({"label": f"{name} triggered by your item, per second*", "value": round(capped, 3),
                      "basis": (f"{how}" + (f", with its {cooldown:g} s Cooldown (after each trigger, the next use past the "
                                                "Cooldown, then the uses until one triggers)" if rate > capped else "")
                                + "; PoB makes the skill but never triggers it, and its group wasn't in Full DPS (0 "
                                "before); side skills' events not counted (an undercount)"),
                      "play": (f"{name} triggers on its own from your item: without it +0; with it {capped:.2f} a second"
                               if capped > 0 else f"Nothing in the build sets off {name}"),
                      "confidence": "MEDIUM" if capped > 0 else "HIGH"})
    return mods, notes, groups


# Double Vision's Gemini Surge (MECHB53; plans/un-double-vision-surges.md, PLANS6; an UNDERCOUNT: its blasts counted 0).
# The unique crossbow (Mods UniqueColdFireSurgeOnReload: gain_X_instilling_cold_on_reload / _fire_on_reload, 2-6; PoB
# parses its line to nothing, ModCache 9794-9796, and splits it in two: neighbouring lines are read joined) "When you
# reload, triggers Gemini Surge to alternately gain N Cold Surges or N Fire Surges", and grants Gemini Surge
# (GeminiSurgePlayer: Cold Surge / Fire Surge sets, maximum_number_of_instilling_stacks 10, 15 s,
# surge_can_apply_to_X_number_of_projectiles_per_skill_use 1), which PoB makes but never rates. KeywordPopups Surge:
# Surges "are consumed when you use a non-Melee Projectile Attack to suffuse the Projectiles fired by that Attack,
# causing them to trigger a Surging Blast when they reach the end of their flight ... Projectiles which Split or Fork do
# not gain the benefits". So:
# - reloads a second R = FiringRate x (1 - its chance not to consume a bolt) / BoltCount (PoB's clip cycle, the inputs
#   reloaded_recently_model reads); a main skill that doesn't reload (no FiringRate): 0, said;
# - alternating, so each type gains N every other reload: R / 2 events of N, at most its cap 10 (R40-11, HIGH: Gemini's
#   own maximum_number_of_instilling_stacks; the default 6 a row) a batch, MECH-C's conditions.surge_rate;
# - qualifying uses: the main skill's uses if it is a non-Melee Projectile Attack (other such skills not counted: the
#   lower reading); one Surge a use (RESEARCH46 R46-7, MEDIUM: Gemini Surge's stat reads "No more than once per Skill
#   use", players saw them spent in turn; one of each type present a row, the reading R46-7 disfavours);
#   so blasts a second = min(uses, Cold supply + Fire supply), one projectile a use carrying it (HIGH);
# - Split / Fork: a main skill with a Fork or Split count from PoB (ForkCountMax / SplitCount) gets none (the text);
# - the blast (1.6 m) goes off where the projectile's flight ends (R46-8, MEDIUM): at the boss for a bolt that stops on
#   hit; a bolt that Pierces (PierceCount > 0) flies on past a lone boss: 0 (MECHB54, R46-8: unconfirmed in game, so the
#   old count is a LOW row, "if it stops within the 1.6 m"; an OVERCOUNT fixed). Which type a use spends first when
#   both are held is unconfirmed (R46-7: about half each, LOW): the Cold set is scored for every blast.
# Gemini Surge's group counts through Full DPS at that rate, its Cold set PoB's default scored for every blast (the Fire
# set is the same blast with Fire instead of Cold: the build's Fire-only scaling not read, LOW).
GEMINI_SURGE = "Gemini Surge"
GEMINI_LINE = re.compile(r"^When you reload, triggers Gemini Surge to alternately gain (\d+) Cold Surges? or (\d+) Fire "
                         r"Surges?$", re.I)
GEMINI_CAP = 10
GEMINI_ENTRY = "model-mechb53-gemini-surge"


def double_vision_model(texts: list[str], stats: dict, skills: list[Skill], main: Skill | None, main_types: set[str],
                        surge_rate: Callable, forbidden: set[str] = frozenset()
                        ) -> tuple[list[dict], list[dict], set[int]]:
    """Double Vision's Gemini Surge blasts a second (see above): (lines, notes, groups to count in Full DPS). `stats` the
    main skill's PoB output (FiringRate, BoltCount, ChanceToNotConsumeAmmo, Speed, ForkCountMax, SplitCount,
    PierceCount); `surge_rate` conditions.surge_rate (MECH-C's)."""
    texts = [t.strip() for t in texts]
    joined = texts + [f"{x} {y}" for x, y in zip(texts, texts[1:])]
    match = next((m for t in joined if (m := GEMINI_LINE.search(t))), None)
    granted = next((s for s in skills if s.name == GEMINI_SURGE and s.group is not None), None)
    if match is None or granted is None or GEMINI_ENTRY in forbidden:
        return [], [], set()
    cold, fire = float(match.group(1)), float(match.group(2))
    rate, bolts = number(stats.get("FiringRate")), number(stats.get("BoltCount"))
    keep = min(1.0, max(number(stats.get("ChanceToNotConsumeAmmo")) / 100, 0.0))
    reloads = rate * (1 - keep) / bolts if rate > 0 and bolts > 0 else 0.0
    # (MECHB54, probe POE2T4826: a crossbow skill's gem types hold CrossbowAmmoSkill, not Projectile; the bridge's
    # projectileAttack flag, Attack with Projectile / CrossbowSkill / GroundTargetedProjectile, is the test)
    qualifies = (main is not None and main.attack and not main.melee
                 and (main.projectile_attack or bool({"Projectile", "CrossbowAmmoSkill"} & set(main_types))))
    forks = number(stats.get("ForkCountMax")) > 0 or number(stats.get("SplitCount")) > 0
    uses = number(stats.get("Speed")) if qualifies and not forks else 0.0
    c_rate, c_how = surge_rate(reloads / 2, cold, uses, 0.0, GEMINI_CAP)
    f_rate, f_how = surge_rate(reloads / 2, fire, uses, 0.0, GEMINI_CAP)
    supply = (reloads / 2) * (min(cold, GEMINI_CAP) + min(fire, GEMINI_CAP))
    pierce = number(stats.get("PierceCount")) > 0
    stopped = min(uses, supply)  # (a bolt that stops on hit: the blast at the boss)
    blasts = 0.0 if pierce else stopped  # (MECHB54, R46-8: a piercing bolt's flight ends past a lone boss)
    upper = c_rate + f_rate
    six = min(uses, (reloads / 2) * (min(cold, 6) + min(fire, 6)))
    if reloads <= 0:
        why = "the main skill doesn't reload a crossbow (no FiringRate / BoltCount from PoB): no Surges, 0"
    elif not qualifies:
        why = (f"{main.name if main else 'the main skill'} isn't a non-Melee Projectile Attack: nothing consumes the "
               "Surges, 0 (other such skills not counted)")
    elif forks:
        why = "its projectiles Fork or Split, which gain no Surge benefit (the keyword): 0"
    else:
        why = (f"{reloads:.3f} reloads a second (FiringRate {rate:.2f} x (1 - {keep:.0%}) / {bolts:g} bolts), alternately "
               f"{cold:g} Cold / {fire:g} Fire Surges (cap {GEMINI_CAP}): {supply:.2f} Surges a second against "
               f"{uses:.2f} uses a second, one a use: {blasts:.3f} blasts a second. Rows: a use taking one of each type "
               f"present, {upper:.3f} (R46-7: unlikely; Cold: {c_how}; Fire: {f_how}); the default cap 6, {six:.3f}")
        if pierce:
            why += (f". Its bolts Pierce (PierceCount {number(stats.get('PierceCount')):g}): the blast goes off where the "
                    f"flight ends, past a lone boss (R46-8, MEDIUM; unconfirmed in game): 0 counted; row, a piercing bolt "
                    f"stopping within the blast's 1.6 m of the boss: {stopped:.3f} (LOW)")
    mods = trigger_rate(GEMINI_SURGE, blasts)
    groups = {granted.group} if blasts > 0 else set()
    return mods, [{
        "label": "Double Vision: Gemini Surge's Surging Blasts, per second*", "value": round(blasts, 3),
        "confidence": ("MEDIUM" if blasts > 0 or pierce else "HIGH"), "entry": GEMINI_ENTRY,
        "basis": (why + ". PoB grants Gemini Surge but never rates it (0 before); each blast scored as its Cold set "
                  "(the Fire set's Fire-only scaling not read, LOW); the blast goes off at the projectile's end of flight, "
                  + ("which a piercing bolt carries past the boss (R46-8: 0 counted)" if pierce
                     else "at the boss for a bolt that stops on hit (R46-8, MEDIUM)")),
        "play": (f"Reload Double Vision as you go: each reload gives Surges, and your next {main.name if main else ''} "
                 f"shots blast at the end of their flight ({blasts:.2f} a second)" if blasts > 0 else "")}], groups


# (MECHB54; MECH99's step 3, 1d621062 on main since train 119, the manager 01:28) A MECH-B model whose "DPS" MORE ADDS
# hits a use that land on the boss within the use (Spell Cascade's areas, Zarokh's / Freezing Salvo's / Lioneye's
# Repeats, crossbow shots in sequence, Primal Bounty's Empowered projectiles)
# tags it HIT_CUT_PER_USE = those hits a use (over PoB's one), so ailment_uptime reads the use's chance 1 - (1 - c)^k
# (MECH99's hits_raise) and the readers that opt in (raise_hits=True) count them; `time` (a use made longer by its
# Repeats, KeywordPopups Repeat: 5% each) goes on as its "hit_cut" (time) part where PoB's Speed doesn't already hold it.
def with_hits_per_use(mod: dict, hits: float, time: float | None = None) -> dict:
    """`mod` tagged with its hits a use (`hits`) and, if given, its time part (see above)."""
    mod[HIT_CUT_PER_USE] = max(0.0, number(hits))
    if time is not None:
        mod["hit_cut"] = max(0.0, number(time))
    return mod


# Spell Cascade's side areas on a boss (MECHB36; the manager 01:43 / 02:08, RESEARCH29 turns 4-5, an UNDERCOUNT). The
# support (SupportSpellCascadePlayer, game files 26650308): support_spell_cascade_number_of_cascades_per_side 1, 20% less
# Area and 30% less Damage on every area (PoB applies both, sup_int.lua), the Cascades 20% less Area again
# (support_spell_cascade_area_of_effect_+%_for_cascade -20: COV-E's part:cascade entry). PoB counts the centre area only
# (checked: no cascade spacing or extra hit in PoB's Modules or SkillStatMap, PoE2 or PoE1). Placement: the side areas sit
# on either side of the target along an axis, each centre one main-area radius from the target ("the center of one spell
# touches the outside perimeter of another", the user's play observation, 17 Nov ~01:50; Kieren_GGG, PoE1 patch thread, 22
# Aug 2023: Spell Cascade "calculates the spacing of the areas based on how big they actually are" to "prevent areas from
# overlapping too much", since 3.1.0; PoE2 using the same code UNVERIFIED): MEDIUM. With PoB's radius R (already the
# 20%-less main area: 0.894 x R0), a side area of radius R x sqrt(0.8) (0.8 x R0) centred R away covers a boss of radius
# r on the target when R - R x sqrt(0.8) <= r, i.e. 0.106 R <= r: then each Cascade is one more hit of the same damage
# (1 + 2 x per side hits a cast), else only the centre. The lower row: areas edge to edge (centres R + R x sqrt(0.8) apart):
# no side area reaches a boss smaller than that, 1 hit. Main skill only (its PoB radius is the one read).
CASCADE_PLAY = "Target the boss's centre with the Spell Cascade spell so its side areas overlap it too"
# (MECHB65, the manager's build 4 walk, an OVERCOUNT: x3 before on Bone Cage) A NOVA spell (PoB SkillType Nova: its area
# is centred on you, Bone Cage "Raise a ring of bone spikes around you. The spikes are destroyed when enemies touch them,
# damaging and Pinning those enemies", ActiveSkills bone_cage) has no target under the boss: its Cascades land on either
# side of YOU "along a random axis" (Spell Cascade's text), and the boss stands beside you where the main ring reaches it.
# So each side area reaches the boss only for the axes that pass near it. Counted: the boss's centre anywhere the main
# area touches it (distance D uniform over that band, MEDIUM-LOW), the axis uniform over the turn; a side area centred
# one main radius R from you (the spacing above) reaches the boss when its own area overlaps the boss's hit radius r.
# The area: a disc of PoB's radius, each side area x sqrt(0.8) (RESEARCH61 R61-3: a skill's secondary radius is its own
# thing, Bone Cage's the spikes' explosion, not an inner edge; Bone Cage's ring is BONE_CAGE_RING's model below). The main area's own hit: PoB's (at a boss distance past its reach the main
# ring misses too: the distance is conditions' / inner.choose_distance's, routed).
CASCADE_NOVA_STEPS = 72  # (the axis and distance grid for the share)
# (MECHB65, THE USER 25 Nov ~14:05: "the astral projection support lets you cast spells normally at your location
# anywhere, make sure to take that into account") A Nova that LANDS AT THE TARGET takes the targeted rule above (the
# boss on the target, every side area overlapping it), not the about-you share: Astral Projection in its group
# (SupportAstralProjectionPlayer's nova_skills_cast_at_target_location: "Supports Nova Skills, causing those Skills to
# take place at the targeted location when used instead of around you"; read from the support's stat, never its name),
# the lines "Nova Spells Cast at the targeted location instead of around you" (nova_spells_cast_at_target_location) and
# "Discharge and Voltaxic Burst are Cast at the targeted location instead of around you" (for those two), and Ice Nova
# with a Frostbolt in the build ("Casting Ice Nova targeting near a Frostbolt Projectile will cause it to originate from
# the Frostbolt instead of you": the play casts it at a Frostbolt on the boss, MEDIUM-LOW). A TRIGGERED Nova with one
# lands on the trigger's target (RESEARCH61 R61-6 (a), MEDIUM: KeywordPopups Trigger "usually targets the cause of the
# trigger"; no exception stat): the boss in the headline, the about-you share a row.
NOVA_AT_TARGET_STAT = "nova_skills_cast_at_target_location"
NOVA_AT_TARGET_LINE = re.compile(r"^Nova Spells Cast at the targeted location instead of around you$", re.I)
NOVA_AT_TARGET_NAMED = re.compile(r"^Discharge and Voltaxic Burst are Cast at the targeted location instead of around "
                                  r"you$", re.I)
NOVA_AT_TARGET_SKILLS = ("Discharge", "Voltaxic Burst")


def nova_lands_at_target(main: Skill | None, support_stats: dict, texts: list[str], names: set[str],
                         spell: bool = True) -> str:
    """Why the main Nova skill lands at the target instead of around you (above), or "" when it lands around you."""
    if main is None:
        return ""
    if number(support_stats.get(NOVA_AT_TARGET_STAT)) > 0:
        return "a support in its group makes it take place at the targeted location (nova_skills_cast_at_target_location)"
    lines = [x.strip() for x in texts]
    if spell and any(NOVA_AT_TARGET_LINE.match(x) for x in lines):
        return "'Nova Spells Cast at the targeted location instead of around you'"
    if main.name in NOVA_AT_TARGET_SKILLS and any(NOVA_AT_TARGET_NAMED.match(x) for x in lines):
        return "'Discharge and Voltaxic Burst are Cast at the targeted location'"
    if main.name == "Ice Nova" and "Frostbolt" in names:
        return "cast at a Frostbolt on the boss, it originates from the Frostbolt (MEDIUM-LOW)"
    return ""


# Bone Cage's ring (MECHB65; RESEARCH61 R61-3, research/bone-cage-spikes-geometry-r61.md, HIGH on the shape; corrects
# 3bfb02c2's ring reading, a possible OVERCOUNT). bone_cage.csd (26650308): active_skill_base_area_of_effect_radius 18
# "Cage radius is 1.8 metres", active_skill_base_secondary_area_of_effect_radius 10 "Explosion radius is 1 metre" (a
# touched spike's explosion, not the ring's inner edge); ActiveSkills bone_cage: "Raise a ring of bone spikes around you.
# The spikes are destroyed when enemies touch them". So a ring hits the boss when its spikes' circle crosses the boss's
# body: |distance from the ring's centre - R| <= the boss's hit radius (a spike's own size isn't in the data: not added,
# the lower reading), R = PoB's AreaOfEffectRadius (area modifiers scale it). PoB counts one hit a cast, as a disc.
# - Landing at the target (Astral Projection, nova_lands_at_target): the main ring is centred on the boss and passes R
#   from its centre: a stationary boss smaller than R isn't touched (HIGH by geometry; the boss's ObjectSize MEDIUM). It
#   touches it only by the boss's own movement, which no data gives (the boss preset has no repositioning rate): 0, said.
#   Spell Cascade's side rings (R61-6 (b): a random axis through the target, HIGH; spacing one main radius, MEDIUM) are
#   centred k R from the boss with radius R x sqrt(0.8) each: they cross it when |k R - R sqrt(0.8)| <= r, the axis
#   not mattering (both sides symmetric about the boss).
# - Around you: the main ring crosses the boss when you stand R from it (the play; the distance is MECH110's), each side
#   ring for the axes nova_side_share's outer line gives (the boss anywhere along the main ring's band).
# The touch reading (a spike raised inside a standing boss counts as touched, a hit at once) is UNVERIFIED (R61-3: a
# lean, MEDIUM-LOW, from build 4's author killing bosses with it): the headline. Row: only when the boss moves (0, no data
# on its movement). One hit per ring crossing the boss (several spikes in it, several explosions: an UNVERIFIED upper
# reading). A triggered Nova landing at the target lands on the trigger's target (R61-6 (a), MEDIUM): the around-you
# reading is a row.
BONE_CAGE_RING = {"Bone Cage"}  # (the skills whose area is a ring of spikes; ring_of_bone_maximum_number_of_rings 1)


def ring_nova_hits(radius: float, boss_radius: float, per_side: int, side_scale: float,
                   at_target: bool) -> tuple[float, str]:
    """(rings crossing a standing boss a cast, how) for a ring Nova (above): its main ring and Spell Cascade's
    `per_side` side rings a side; `at_target`: the ring centred on the boss, else around you."""
    r = max(boss_radius, 0.0)
    side = radius * side_scale
    if at_target:
        main = 1.0 if radius <= r else 0.0
        sides = sum(2.0 for k in range(1, per_side + 1) if abs(k * radius - side) <= r)
        return main + sides, (f"the main ring {radius:.2f} m round the boss {'crosses' if main else 'misses'} its "
                              f"{r:g} m body" + (f"; side rings {side:.2f} m centred {radius:.2f} m out pass "
                                                 f"{abs(radius - side):.2f} m from its centre: "
                                                 f"{'both cross it' if sides else 'neither crosses it'}"
                                                 if per_side else ""))
    shares = [nova_side_share(radius, radius, r, side_scale, k * radius) for k in range(1, per_side + 1)]
    return 1.0 + 2 * sum(shares), ("the main ring crosses the boss with you standing its radius away (the play)"
                                   + (f"; each side ring on a random axis through you crosses it "
                                      f"{shares[0]:.0%} of the time" if per_side else ""))


def bone_cage_ring_model(main: Skill, stats: dict, boss_radius: float, boss_how: str, at_target: str,
                         per_side: int, side_scale: float) -> tuple[list[dict], list[dict]]:
    """Bone Cage's rings against PoB's one hit a cast (above): (mods, notes)."""
    radius = number(stats.get("AreaOfEffectRadius")) / 10
    if radius <= 0:
        return [], []
    hits, how = ring_nova_hits(radius, boss_radius, per_side, side_scale, bool(at_target))
    rows = []
    if at_target and main.triggered:
        around, _ = ring_nova_hits(radius, boss_radius, per_side, side_scale, False)
        rows.append(f"if the triggered cast lands around you instead (R61-6 (a): on the trigger's target, MEDIUM): "
                    f"x{around:.2f}")
    rows.append("if a spike must be walked into (the boss's movement, no data): 0")
    where = f"at the target ({at_target})" if at_target else "around you"
    note = {"label": f"{main.name}: its spike rings crossing the boss*", "value": f"x{hits:.2f}",
            "basis": (f"{main.name}'s spikes stand on a circle of radius {radius:.2f} m (PoB's, area modifiers in; "
                      f"'Cage radius'; the 1 m secondary radius is a touched spike's explosion: RESEARCH61 R61-3, "
                      f"HIGH), cast {where}; a ring hits when its circle crosses the boss ({boss_how}; a spike's own "
                      f"size not in the data, not added): {how}: x{hits:.2f} hits a cast against PoB's one (a spike "
                      "raised inside a standing boss taken as touched: UNVERIFIED, MEDIUM-LOW). Rows: "
                      + "; ".join(rows)),
            "play": (f"Cast {main.name} so its spike circle crosses the boss: x{hits:.2f} hits a cast"
                     + ("; with Astral Projection the main ring circles the boss and only the Cascade's side rings "
                        "cross it" if at_target else "")),
            "confidence": "MEDIUM-LOW"}
    if abs(hits - 1.0) < 1e-9:
        return [], [note]
    return [with_hits_per_use(raw_mod("DPS", "MORE", 100 * (hits - 1), main.name), hits)], [note]


def nova_side_share(radius: float, inner: float, boss_radius: float, side_scale: float, spacing: float) -> float:
    """The chance a Nova's side area (centred `spacing` from you on a random axis; its radii the main area's x
    `side_scale`) overlaps a boss of hit radius `boss_radius` standing where the main area [inner, radius] touches it."""
    r = max(boss_radius, 0.0)
    lo, hi = max(0.0, inner - r), radius + r
    s_in, s_out = inner * side_scale, radius * side_scale
    hits = total = 0
    for i in range(CASCADE_NOVA_STEPS):
        d = lo + (hi - lo) * (i + 0.5) / CASCADE_NOVA_STEPS
        for j in range(CASCADE_NOVA_STEPS):
            theta = math.pi * (j + 0.5) / CASCADE_NOVA_STEPS  # (0-180 degrees; the other half mirrors it)
            far = math.sqrt(max(0.0, d * d + spacing * spacing - 2 * d * spacing * math.cos(theta)))
            total += 1
            if far - r <= s_out and far + r >= s_in:
                hits += 1
    return hits / total if total else 0.0


def spell_cascade_model(main: Skill | None, stats: dict, boss_radius: float, boss_how: str, nova: bool = False,
                        at_target: str = "") -> tuple[list[dict], list[dict]]:
    """Spell Cascade's side areas as extra hits on a boss at the target (see above); `nova`: the main skill's area is
    centred on you (PoB SkillType Nova: the side areas on a random axis through you, MECHB65); `at_target`: why that
    Nova lands at the target instead (nova_lands_at_target; then the targeted rule, a triggered one's about-you a row)."""
    if main is None:
        return [], []
    per_side = number(main.support_stats.get(CASCADES_PER_SIDE))
    radius = number(stats.get("AreaOfEffectRadius")) / 10
    if main.name in BONE_CAGE_RING and nova and radius > 0:  # (MECHB65, R61-3: its ring, with or without the support)
        scale, part_notes = support_part_scale(main, "cascade") if per_side > 0 else ({}, [])
        mods, notes = bone_cage_ring_model(main, stats, boss_radius, boss_how, at_target, int(per_side),
                                           math.sqrt(number(scale.get("Area of Effect")) or 0.8))
        return mods, notes + (part_notes if mods else [])
    if per_side <= 0 or radius <= 0:
        return [], []
    scale, part_notes = support_part_scale(main, "cascade")
    side_scale = math.sqrt(number(scale.get("Area of Effect")) or 0.8)
    side = radius * side_scale
    about_row = ""
    if nova and at_target:  # (the user, 14:05: Astral Projection; the targeted rule below, a triggered one's row here)
        share = sum(nova_side_share(radius, 0.0, boss_radius, side_scale, k * radius) for k in range(1, int(per_side) + 1))
        about_row = (f"; it's a Nova landing at the target ({at_target})"
                     + (f"; a triggered one lands on the trigger's target (RESEARCH61 R61-6 (a), MEDIUM: KeywordPopups "
                        f"Trigger 'usually targets the cause of the trigger'); around you, its side areas "
                        f"x{1 + 2 * share:.2f} (the row)" if main.triggered else ""))
        nova = False
    if nova:
        inner = 0.0  # (R61-3: a disc; the ring skills are BONE_CAGE_RING's above)
        shares = [sum(nova_side_share(radius, inn, boss_radius, side_scale, k * radius) for k in range(1, int(per_side) + 1))
                  for inn in (inner, 0.0)]
        line_share = sum(nova_side_share(radius, radius, boss_radius, side_scale, k * radius)
                         for k in range(1, int(per_side) + 1))
        hits, disc, thin = (1 + 2 * x for x in (shares[0], shares[1], line_share))
        shape = f"a disc of {radius:.2f} m"
        note = {"label": f"{main.name}: Spell Cascade's side areas on the boss*", "value": f"x{hits:.2f}",
                "basis": (f"{main.name} is a Nova (its area centred on you), so its Cascades land on either side of you "
                          f"along a random axis, not around the boss: {shape}, side areas x{side_scale:.3f} the size "
                          f"centred {radius:.2f} m out; with the boss ({boss_how}) anywhere the main area touches it and "
                          f"the axis at random, a side area reaches it {shares[0] / max(per_side, 1):.0%} of the time: "
                          f"x{hits:.2f} hits a cast (MEDIUM-LOW; an OVERCOUNT before: every side area taken to hit, "
                          f"x{1 + 2 * per_side:g}). Rows: a full disc x{disc:.2f}; the ring as a line at its outer edge "
                          f"x{thin:.2f}"),
                "play": (f"Stand so {main.name}'s ring reaches the boss; the side areas land at random about you: "
                         f"x{hits:.2f} on average"),
                "confidence": "MEDIUM-LOW"}
        if hits <= 1 + 1e-9:
            return [], [note]
        return [with_hits_per_use(raw_mod("DPS", "MORE", 100 * (hits - 1), main.name), hits)], [note] + part_notes
    reach = radius - side
    hits = 1 + 2 * per_side if reach <= boss_radius else 1.0
    note = {"label": f"{main.name}: Spell Cascade's side areas on the boss*", "value": f"x{hits:g}",
            "basis": (f"main area {radius:.2f} m (PoB's, with the support's 20% less Area), side areas {side:.2f} m centred "
                      f"{radius:.2f} m from the target: they cover the boss's centre to within {reach:.2f} m, against "
                      f"{boss_how}: {'all ' + format(1 + 2 * per_side, 'g') + ' areas hit' if hits > 1 else 'only the centre area hits'}"
                      " (MEDIUM: spacing from the user's play observation and Kieren_GGG's PoE1 post; PoB counts the "
                      "centre only). Row: areas edge to edge, x1" + about_row),
            "play": (f"{CASCADE_PLAY}: with it x{hits:g}; areas edge to edge (the lower reading) x1" if hits > 1 else
                     f"The side areas land too far out for this boss (spell area {radius:.1f} m): x1"),
            "confidence": "MEDIUM"}
    if hits <= 1:
        return [], [note]
    return [with_hits_per_use(raw_mod("DPS", "MORE", 100 * (hits - 1), main.name), hits)], [note] + part_notes


# Spell Echo's Echoes as hits, and Mystic Avalanche's side areas (MECHB58; the manager's MECHB58 brief item 2, RESEARCH51
# R-B23, research/mystic-avalanche-r51.md; an UNDERCOUNT). An Echo affects "the same targeted location again after a
# delay" (KeywordPopups Cascadable, 26650308): one more hit of the cast on a boss in the area. Spell Echo
# (SupportSpellEchoPlayer: support_spell_echo_number_of_echo_cascades 1, 30% less cast speed, Echoes 40% increased Area)
# and Zarokh's Refrain (3 Echoes, a 5 s Cooldown). PoB maps the stat to RepeatCount (SkillStatMap 290) and then only
# averages the repeat-scaled modifiers (area, "Repeat" damage) and, for a skill with a Cooldown, caps its Speed at
# (1 + Echoes) / Cooldown (CalcOffence 3008); it adds an Echo's hit to the DPS of traps and mines only (CalcOffence
# 1229-1231). PROBE_NOTE. So a Spell Echo spell (no Cooldown) is scored one hit a cast at 30% less cast speed (the
# Echo's hit missing), and Zarokh's Refrain at min(cast rate, 4 / 5 s) hits a second, which is the real 4 hits a
# Cooldown only while the cast rate is at least 0.8 a second. Counted: real hits a second = min(cast rate, 1 /
# Cooldown) x (1 + Echoes) (cast rate = PoB's CastRate, before the Cooldown cap) over PoB's Speed, as hits a use (a
# "DPS" MORE tagged HIT_CUT_PER_USE: the Echo is part of the same use, no extra cast). An Echo counted as a full hit of
# the cast (MEDIUM: no less-damage stat on either support; PoB's own average of the Echo's larger area kept).
# Mystic Avalanche (Delirium anoint, PassiveSkills DeliriumAnoint_MysticAvalanche:
# cascadable_spells_final_echo_also_cascades_to_sides 1, "Final Echo of Cascadable Spells also Cascades to either side of
# the targeted Area along a random axis"; PoB ignores the line): the last Echo of a cast also lands two side areas,
# each the Echo's own size and damage (R-B23 2, MEDIUM: no area or damage stat for the cascade), centred one radius from
# the target (R-B23 3, R29-5's spacing, MEDIUM-LOW), so a boss on the target is inside both: two more hits for each cast
# that Echoes. A cast Echoes with Spell Echo / Zarokh's Refrain always; else at the chance lines (Now and Again, Comet /
# Skyfall quality: passive_models.echo_chance) and Tul's Avalanche's Seals (passive_models.seal_rate). The side hits are
# taken over the hits a cast already counted (1 + support Echoes; a chance Echo as the ledger's now-and-again-echo 0.95;
# Tul's Echoes as seal_echo_share), a chance Echo's side areas at the same 0.95. Rows: areas edge to edge (the side
# areas miss unless the area's radius is at most the boss's hit radius); not counted with Spell Cascade on the same
# spell (R-B23: whether its final Echo adds sides twice is UNVERIFIED; the lower reading, said).
ECHO_COUNT_STAT = "support_spell_echo_number_of_echo_cascades"
MYSTIC_AVALANCHE = re.compile(r"^Final Echo of Cascadable Spells also Cascades to either side of the targeted Area "
                              r"along a random axis$", re.I)
ECHO_CHANCE_WEIGHT = 0.95  # (the ledger's now-and-again-echo: a chance Echo as 0.95 of a hit)
ECHO_PLAY = "Target the boss's centre so the Echo and its side areas land on it"


def spell_echo_model(main: Skill | None, main_types: set[str], stats: dict, texts: list[str],
                     chance: tuple[float, str] = (0.0, ""), seals: float = 0.0, boss: tuple[float, str] = (0.0, "")
                     ) -> tuple[list[dict], list[dict]]:
    """Spell Echo's / Zarokh's Refrain's Echoes as hits and Mystic Avalanche's side areas (see above). `chance`: the
    main spell's chance a cast Echoes and from what (passive_models.echo_chance); `seals`: Tul's Avalanche's Seals a
    second (passive_models.seal_rate); `boss`: (hit radius in m, how) for the edge-to-edge row."""
    if main is None or not main.spell or "Cascadable" not in main_types:
        return [], []
    echoes = max(0.0, number(main.support_stats.get(ECHO_COUNT_STAT)))
    speed = number(stats.get("Speed"))
    if speed <= 0:
        return [], []
    cooldown = number(stats.get("Cooldown"))
    cast = number(stats.get("CastRate")) or speed
    casts = min(cast, 1 / cooldown) if cooldown > 0 else cast
    notes: list[dict] = []
    factor = 1.0
    if echoes > 0:
        factor = casts * (1 + echoes) / speed
        how = (f"{echoes:g} Echo{'es' if echoes != 1 else ''} a cast"
               + (f", one cast per its {cooldown:.2f} s Cooldown" if cooldown > 0 else "")
               + f": {casts:.3f} casts/s x {1 + echoes:g} hits = {casts * (1 + echoes):.3f} hits/s against PoB's "
               f"{speed:.3f} (PoB adds no Echo hit for a spell: RepeatCount only averages modifiers"
               + (" and caps its Speed at the Cooldown" if cooldown > 0 else "") + ")")
        if factor > 1.0 + 1e-6:
            notes.append({"label": f"{main.name}: its Echoes as hits*", "value": f"x{factor:.3f}", "confidence": "MEDIUM",
                          "basis": how + ". An Echo counted as a full hit of the cast (no less-damage stat on the "
                                         "support); the boss taken to stay in the area for the Echo's delay"})
        else:
            factor = 1.0
    if any(MYSTIC_AVALANCHE.search(t.strip()) for t in texts):
        label = f"{main.name}: Mystic Avalanche's side areas on the final Echo*"
        p_chance, chance_how = max(0.0, min(1.0, number(chance[0]))), chance[1]
        tul = min(1.0, max(0.0, seals) / casts) if casts > 0 else 0.0
        p = 1.0 if echoes > 0 else p_chance + (1 - p_chance) * tul
        cascade = number(main.support_stats.get(CASCADES_PER_SIDE)) > 0
        radius = number(stats.get("AreaOfEffectRadius")) / 10
        edge = 0 < radius <= boss[0]
        if cascade or p <= 0:
            notes.append({"label": label, "value": "not counted", "confidence": "MEDIUM",
                          "basis": ("Spell Cascade on the same spell: whether its final Echo adds side areas twice is "
                                    "UNVERIFIED (R-B23), the lower reading, 0" if cascade else
                                    "nothing makes the main spell Echo (Spell Echo, Zarokh's Refrain, a chance to "
                                    "Echo, Tul's Avalanche's Seals): no final Echo")})
        else:
            if echoes > 0:
                counted, side = 1 + echoes, 2.0
            else:  # (a chance Echo at the ledger's 0.95, its side areas too; Tul's Echoes as seal_echo_share's 1)
                counted = 1 + ECHO_CHANCE_WEIGHT * p_chance + (1 - p_chance) * tul
                side = 2 * (ECHO_CHANCE_WEIGHT * p_chance + (1 - p_chance) * tul)
            gain = 1 + side / counted
            factor *= gain
            source = ("Spell Echo / Zarokh's Refrain" if echoes > 0 else
                      "; ".join(x for x in (chance_how if p_chance > 0 else "",
                                            f"Tul's Avalanche {seals:.3f} Seals/s" if tul > 0 else "") if x))
            notes.append({"label": label, "value": f"x{gain:.3f}", "confidence": "MEDIUM-LOW",
                          "basis": (f"{p:.0%} of casts Echo ({source}); the final Echo also lands 2 side areas, each the "
                                    f"Echo's size and damage, centred one radius from the target (R-B23, RESEARCH51: "
                                    f"MEDIUM-LOW spacing), so a boss on the target is inside both: +{side:.2f} hits over "
                                    f"the {counted:.2f} a cast already counted. Row, areas edge to edge: the side areas "
                                    + (f"still reach the boss ({radius:.2f} m area, {boss[1]})" if edge else
                                       f"miss ({radius:.2f} m area, {boss[1]}): x1")),
                          "play": f"{ECHO_PLAY}: with Mystic Avalanche x{gain:.2f}; areas edge to edge x"
                                  + (f"{gain:.2f}" if edge else "1")})
    if factor <= 1.0 + 1e-6:
        return [], notes
    return [with_hits_per_use(raw_mod("DPS", "MORE", 100 * (factor - 1), main.name), factor)], notes

# Dusk Vigil's Ember Fusillade (MECHB37; the catalog's "Skills triggered by items and passives", the coverage ranking's
# #103, an UNDERCOUNT: 0 before). Dusk Vigil (Ashen Staff, PoB Uniques/staff.lua) "Grants Skill: Level (1-20) Ember
# Fusillade" (PoB ModCache ExtraSkill EmberFusilladePlayer, its own group fromItem) and "Trigger Ember Fusillade Skill on
# casting a Spell" (ModCache {nil, leftover}: PoB never triggers it, and the search never counts a fromItem group). The
# game's own version (GrantedEffects UniqueDuskVigilTriggeredBlazingClusterPlayer, game files 26650308) has the gem's
# stats plus triggered_on_spell_cast_% 100, no Cooldown (GrantedEffectsPerLevel: none), and the gem's text: "Recasting
# this spell resets the duration for all active Embers" (ActiveSkills unique_dusk_vigil_triggered_blazing_cluster). So
# each spell cast adds an Ember and resets the wait; the Embers fire only once the player stops casting Spells for the
# Ember duration (1.3 s base). That a triggered Ember resets the wait like a cast: MEDIUM-HIGH (MECHB38: RESEARCH31
# R31-5, research/dusk-vigil-ember-reset.md: the triggered skill's own description plus forum 3896894).
# The play: k casts of the main spell (k / Speed s, one Ember each, up to the cap), then a pause of the Embers' duration D
# with no spell cast, when n = min(cap, k) Embers fire, the i-th at (1 + 5% x (i - 1)) (ember_fusillade_model's maths):
#   with the pause: (main DPS x k / Speed + Ember hit x n (1 + m (n - 1) / 2)) / (k / Speed + D)
#   without (casting nonstop): main DPS, no Ember fires.
# The model takes the best k, and the pause only if it beats casting nonstop; then the main skill's DPS is x (k / Speed)
# / (k / Speed + D) (it isn't cast during the pause) and Ember Fusillade's group gets that many Embers' worth a second
# (models.trigger_rate) in Full DPS. Inputs from the build: the main spell's Speed and damage a second, the Ember's hit
# (PoB's setRates AverageDamage for its group) and duration (PoB's, with the build's skill-duration modifiers, 0 when
# fully reduced; 1.3 s only when PoB gives none), its level's cap (6 / 7 / 8 / 9 / 10 at levels 1-4 / 5-10 / 11-15 /
# 16-19 / 20: the staff's level roll sets it) and more per Ember. MECHB38: each trigger adds PoB's ProjectileCount Embers
# for the group (patch 0.1.1f: "additional projectiles affect the number of Embers accumulated"); whether they raise the
# cap is UNVERIFIED (not counted; RESEARCH32 R32-2: MEDIUM-LOW that it stays). Casting the Ember Fusillade gem DOES
# reset the staff's Embers (R32-2, MEDIUM-HIGH: every Spell cast triggers the staff's skill, whose recast resets them), as
# any spell cast here does. With a "Projectiles in a circle" source for Spells (Sire of Shards; the cultivated "fire 8
# additional Projectiles in a circle"), the extra Embers fire radially and miss a lone boss (R32-2 (3), forum 3841032
# since 0.3.0b, MEDIUM-LOW): headline the base Ember a trigger only, "all hit" a row. Labelled: side spells' casts not counted (an undercount); the Embers' 100 ms launch spacing not counted as time and
# the pause filled by nothing else (dodging fits in it); a main skill that is Ember Fusillade itself, or not a Spell: no
# Embers counted (PoB's 0 kept, said).
DUSK_VIGIL = re.compile(r"^Trigger Ember Fusillade Skill on casting a Spell$", re.I)
# (MECHB49, COV50's lead via the manager 23:32) the cultivated "(5-10)% chance for Spell Skills to fire 8 additional
# Projectiles in a circle" is NOT a circle layout: only on that share of casts do its 8 extra projectiles fire in a circle
# (radially: they miss a lone boss, R32-2 (3)), the base projectiles fire as before, and PoB never adds the 8 (ModCache
# 5026: parsed only in part, not applied). Read as an always-on circle it cut Bonestorm to one spike a release and Dusk
# Vigil to one Ember a cast on every cast (an UNDERCOUNT), so a "chance" line is no circle layout here; its 8 extras add
# nothing on a lone boss. (MECHB50: SPELL_CIRCLE reads both lines again, as COV50's model-read entry and test have it
# (model-read-cov50-spell-projectiles-circle); spell_circle_layout keeps the chance line out of the layout.)
SPELL_CIRCLE = re.compile(r"\bSpell(?:s| Skills)\b.*\bProjectiles in a circle\b", re.I)  # (R32-2 (3))
SPELL_CIRCLE_CHANCE = re.compile(r"\bchance\b", re.I)


def spell_circle_layout(text: str) -> bool:
    """A line that makes every Spell cast fire its projectiles in a circle (not the cultivated chance line: above)."""
    return bool(SPELL_CIRCLE.search(text)) and not SPELL_CIRCLE_CHANCE.search(text)
DUSK_TAG = "dusk_vigil"  # the main skill's "less" carries it, so the next pass reads the main skill's damage without it


def dusk_vigil_model(texts: list[str], stats: dict, skills: list[Skill], main: Skill | None, main_dps: float,
                     ember_hit: float, ember_wait: float | None, per_cast: float = 1.0
                     ) -> tuple[list[dict], list[dict], set[int], float]:
    """Dusk Vigil's triggered Embers (comment above): (lines, notes, groups for Full DPS, the main skill's DPS scale)."""
    if not any(DUSK_VIGIL.search(t.strip()) for t in texts):
        return [], [], set(), 1.0
    granted = next((s for s in skills if s.name == EMBER_SKILL and s.group is not None
                    and (main is None or s.group != main.group)), None)
    if granted is None:
        return [], [], set(), 1.0
    label = "Ember Fusillade from Dusk Vigil*"
    speed = number(stats.get("Speed"))
    if main is None or not main.spell or main.triggered or main.name == EMBER_SKILL or speed <= 0:
        why = ("the main skill is Ember Fusillade itself (how the two sets of Embers share a Fusillade isn't modelled)"
               if main is not None and main.name == EMBER_SKILL else "the main skill isn't a Spell you cast")
        return (trigger_rate(EMBER_SKILL, 0), [{"label": label, "value": "0", "confidence": "MEDIUM-HIGH",
                                                "basis": f"{why}: no Embers counted (PoB's 0 kept; side spells not read)",
                                                "play": "Nothing in the build casts the Spells that trigger the Embers"}],
                set(), 1.0)
    cap = int(number(granted.level_stats.get(EMBER_CAP_STAT)) or EMBER_CAP)
    more = number(granted.level_stats.get(EMBER_MORE_STAT)) or EMBER_MORE
    wait = max(ember_wait, 0.0) if ember_wait is not None else EMBER_DURATION
    circle = any(spell_circle_layout(t) for t in texts) and per_cast > 1  # (R32-2 (3): extras fire radially)
    per = 1.0 if circle else max(per_cast, 1.0)
    best = None
    for casts in range(1, math.ceil(cap / per) + 1):
        embers = min(cap, casts * per)
        worth = embers * (1 + more / 100 * (embers - 1) / 2)
        cycle = casts / speed + wait
        total = (main_dps * casts / speed + ember_hit * worth) / cycle
        if best is None or total > best[0]:
            best = (total, casts, worth, cycle, embers)
    total, casts, worth, cycle, embers = best
    keep = casts / speed / cycle
    rows = (f"casting nonstop: {main_dps:,.1f} DPS, no Ember fires; {casts} casts then a {wait:.2f} s pause: "
            f"{total:,.1f} DPS ({main_dps * keep:,.1f} from the main skill, {ember_hit * worth / cycle:,.1f} from "
            f"{worth / cycle:.2f} Embers' worth a second)")
    if ember_hit <= 0 or total <= main_dps:
        return (trigger_rate(EMBER_SKILL, 0),
                [{"label": label, "value": "0", "confidence": "MEDIUM-HIGH",
                  "basis": (f"each spell cast adds {per:g} Ember(s) and resets their {wait:.2f} s wait (a triggered Ember "
                            f"too: MEDIUM-HIGH, RESEARCH31 R31-5), so they fire only in a pause from casting; no pause pays here ({rows})"),
                  "play": f"Keep casting {main.name}: pausing for the Embers loses more than they deal ({rows})"}],
                set(), 1.0)
    note = {"label": label, "value": f"{worth / cycle:.2f} Embers' worth a second", "confidence": "MEDIUM-HIGH",
            "basis": (f"each cast of {main.name} ({speed:.2f} a second) adds {per:g} Ember(s) and resets their {wait:.2f} s wait "
                      f"(the triggered skill's own text, MEDIUM-HIGH: RESEARCH31 R31-5, forum 3896894; the wait is PoB's Ember "
                      f"duration with the build's modifiers); {casts} casts then a pause: {embers:g} Embers ({per:g} a "
                      f"cast: extra projectiles add Embers, 0.1.1f), each {more:g}% more than the one before, cap {cap} "
                      f"(extra projectiles raising it: UNVERIFIED, not counted): {rows}. The main skill x{keep:.3f} (not "
                      "cast in the pause)"
                      + (f". Projectiles in a circle: the {per_cast - 1:g} extra Embers a cast fire radially and miss the "
                         "boss (RESEARCH32 R32-2, MEDIUM-LOW; all hitting: a row only)" if circle else "")
                      + ". Side spells not counted, the launch spacing not counted as time (LOW parts); casting the "
                      "Ember Fusillade gem resets the staff's Embers too (R32-2, MEDIUM-HIGH)"),
            "play": (f"Cast {main.name} {casts} times, then stop casting Spells for {wait:.1f} s so Dusk Vigil's "
                     f"Embers fire (dodge then). Without it (casting nonstop) {main_dps:,.1f} DPS; with it {total:,.1f}")}
    return (trigger_rate(EMBER_SKILL, worth / cycle) + [raw_mod("DPS", "MORE", 100 * (keep - 1), main.name, tag=DUSK_TAG)], [note],
            {granted.group}, keep)


# Tempest Caller's Elemental Storm (MECHB37; the coverage ranking's #88). Stormweaver's notable (PassiveSkills
# AscendancySorceress1Notable3, trigger_elemental_storm_on_crit; game files 26650308) grants Elemental Storm
# (ElementalStormPlayer: Cooldown 3 s, 1 stored use; base_skill_effect_duration 5000; tornado_base_damage_interval_ms 250,
# which PoB maps to hitTimeOverride; number_of_tornados_allowed 50; radius 1.8 m): "Create a stationary Fire, Cold or
# Lightning storm at a target location for a duration, based on the highest Elemental Damage type for the Hit that
# Triggered the storm. Hits which do not deal Elemental Damage will not Trigger the storm." PoB parses the grant
# (ExtraSkill) but not the trigger (ModCache 9662 {nil, leftover}): its group is marked fromItem, so the search never put it
# in Full DPS (0 before); as a group PoB scores one storm always up, TotalDPS = the hit / 0.25 s, Speed 0 (probe POE2T3315:
# Lightning set 30.8 a hit, 123.2). In the game: storms a second r from the main spell's casts a second s, each a crit
# with chance p, and the Cooldown T (PoB's, with recovery): r = cooldown_trigger_rate(s, p, T) (after each storm the next
# cast past the Cooldown, then the casts until one crits);
# each lasts D (PoB's Duration) and hits every 0.25 s, so r x D storms are up at once on average: storm DPS = the storm's
# hit x 4 x r x D, as DPS "more" on Elemental Storm against PoB's number. Its element: the main skill's highest Elemental
# damage type (PoB's FireHitAverage / ColdHitAverage / LightningHitAverage), the matching stat set. The boss stays in each storm all its
# duration (an OVERCOUNT where it walks out: MEDIUM). Side spells' crits not counted (an undercount); no Elemental
# damage on the main skill's hit: 0.
TEMPEST_CALLER = re.compile(r"^Trigger Elemental Storm on Critical Hit with Spells", re.I)
STORM_SKILL = "Elemental Storm"
STORM_INTERVAL, STORM_COOLDOWN, STORM_DURATION = 0.25, 3.0, 5.0
STORM_FIELDS = ("FireHitAverage", "ColdHitAverage", "LightningHitAverage")  # (PoB's per-type hit averages)


def storm_element(stats: dict) -> str | None:
    """The main skill's highest Elemental damage type for Elemental Storm (None: no Elemental damage)."""
    sums = {kind: number(stats.get(f"{kind}HitAverage")) for kind in ("Fire", "Cold", "Lightning")}
    kind = max(sums, key=sums.get)
    return kind if sums[kind] > 0 else None


def tempest_caller_model(texts: list[str], stats: dict, skills: list[Skill], main: Skill | None, storm: dict
                         ) -> tuple[list[dict], list[dict], set[int]]:
    """Tempest Caller's storms at the build's crit rate (comment above). `storm`: the storm group's PoB numbers,
    {"hit", "cooldown", "duration", "element"}: (lines, notes, groups for Full DPS)."""
    if not any(TEMPEST_CALLER.search(t.strip()) for t in texts):
        return [], [], set()
    granted = next((s for s in skills if s.name == STORM_SKILL and s.group is not None
                    and (main is None or s.group != main.group)), None)
    if granted is None:
        return [], [], set()
    label = "Elemental Storm from Tempest Caller*"
    crits = crits_per_second(stats) if main is not None and main.spell else 0.0
    element = storm.get("element")
    if crits <= 0 or element is None or number(storm.get("hit")) <= 0:
        why = ("the main skill isn't a Spell that crits" if crits <= 0 else
               "the main skill's hit deals no Elemental damage" if element is None else "PoB scores the storm 0")
        return ([raw_mod("DPS", "MORE", -100, STORM_SKILL)],
                [{"label": label, "value": "0", "confidence": "MEDIUM",
                  "basis": f"{why}: no storm counted (side spells' crits not read: an undercount)",
                  "play": "Nothing in the build triggers Elemental Storm"}], set())
    cooldown = number(storm.get("cooldown")) or STORM_COOLDOWN
    duration = number(storm.get("duration")) or STORM_DURATION
    rate = cooldown_trigger_rate(number(stats.get("Speed")), crits / number(stats.get("Speed")), cooldown)
    up = rate * duration
    dps = number(storm.get("hit")) / STORM_INTERVAL * up
    factor = up
    note = {"label": label, "value": f"{dps:,.1f} DPS", "confidence": "MEDIUM",
            "basis": (f"{rate:.3f} storms a second (the main spell's {crits:.2f} crits a second and the {cooldown:.2f} s "
                      f"Cooldown: the next cast past the Cooldown, then the casts until one crits), each {duration:.2f} s: {up:.2f} up at once, each hitting "
                      f"every {STORM_INTERVAL:g} s for {number(storm.get('hit')):,.1f} ({element}, the main hit's highest "
                      f"element); PoB counts one storm always up (hit / 0.25 s) and the search left the group out of Full "
                      f"DPS (0 before), so x{factor:.3f} on PoB's number. The boss taken to stay in each storm (an OVERCOUNT where it walks out); "
                      "side spells' crits not counted"),
            "play": (f"Storms come from {main.name}'s crits on their own; cast at the boss so it stands in them. Without "
                     f"Tempest Caller +0; with it +{dps:,.1f} DPS")}
    return [raw_mod("DPS", "MORE", 100 * (factor - 1), STORM_SKILL)], [note], {granted.group}


# Lioneye's Glare's Repeats out of Presence (MECHB37; the coverage ranking's #155-156, an UNDERCOUNT: 0 before). The
# bow (PoB Uniques/bow.lua, current variant): "Repeatable Attacks with this Bow Repeat +2 times if no enemies are in your
# Presence" (pre-0.4.0 +1). PoB leaves it unparsed (ModCache 9309-9311 {nil, leftover}; CalcTriggers' one "Lioneye" is a
# PoE1 comment), so it adds nothing. KeywordPopups (26650308): Presence "By default this has a 4 metre radius";
# Repeat: "perform the part of the skill where it fires off projectiles ... multiple times in quick succession from a
# single use"; "Trigger[ed] skills, Instant skills, and Channelling skills cannot Repeat"; "Skills take 5% longer to
# perform for each time they Repeat" (PoB applies no such time: checked, CalcOffence's Repeats code). So with the boss
# beyond the build's Presence radius (its distance: PoB's enemyDistance as the search set it, else the natural one), a
# Repeatable bow attack used yourself gets +N Repeats and N x 5% longer uses (a Speed "less"): x (1 + N) / (1 + 0.05 N) on
# its hits. PoB's RepeatCount is set too, so its own Repeat modifiers apply, but PoB counts a Repeat's hits only for
# traps and mines (CalcOffence 1229-1231: DPS "more" x Repeats there only; probe POE2T3316: RepeatCount alone moved no
# DPS), so the hits are a DPS "more" x (1 + N) here. Each Repeat taken to hit the boss as the use does
# (aimed where the use was: MEDIUM). Not counted (labelled): adds inside the Presence switch it off (one boss taken);
# Freezing Salvo's own Seal Repeats model isn't combined with it (an undercount there).
LIONEYE = re.compile(r"^Repeatable Attacks with this Bow Repeat \+(\d+) times? if no enemies are in your Presence$", re.I)
LIONEYE_SKIP = ("Freezing Salvo",)


def lioneye_model(texts: list[str], stats: dict, main: Skill | None, metres: float, bow_skill: bool
                  ) -> tuple[list[dict], list[dict]]:
    """Lioneye's Glare's extra Repeats while the boss stands outside the Presence (comment above)."""
    # (the bridge's sourceLines lists every variant's lines of a unique: both +1 and +2 here, probe POE2T3317; the
    # largest is the current one: game files 26650308 UniqueRepeatNoEnemyInPresence 2, patch 0.4.0 "previously 1")
    found = [float(m.group(1)) for t in texts if (m := LIONEYE.search(t.strip()))]
    if not found or main is None:
        return [], []
    repeats = max(found)
    radius = number(stats.get("PresenceRadius")) / 10
    label = f"{main.name}: Lioneye's Glare's +{repeats:g} Repeats*"
    if not (main.attack and bow_skill) or main.triggered or main.name in LIONEYE_SKIP:
        why = (f"{main.name}'s own Repeat model isn't combined with it (an undercount)" if main.name in LIONEYE_SKIP else
               "the main skill isn't a bow Attack you use yourself (triggered skills can't Repeat)")
        return [], [{"label": label, "value": "+0", "basis": why, "confidence": "MEDIUM",
                     "play": "Lioneye's Glare's Repeats don't apply to the main skill"}]
    if radius <= 0 or metres <= radius:
        return [], [{"label": label, "value": "+0", "confidence": "MEDIUM",
                     "basis": (f"the boss at {metres:g} m is inside your {radius:.1f} m Presence, so the bow doesn't "
                               "Repeat (standing further back is the search's distance choice)"),
                     "play": (f"Stand more than {radius:.1f} m from the boss for +{repeats:g} Repeats a use "
                              f"(x{(1 + repeats) / (1 + REPEAT_TIME * repeats):.2f})")}]
    factor = (1 + repeats) / (1 + REPEAT_TIME * repeats)
    note = {"label": label, "value": f"x{factor:.3f}", "confidence": "MEDIUM",
            "basis": (f"the boss at {metres:g} m, outside your {radius:.1f} m Presence: each use Repeats {repeats:g} more "
                      f"times, each Repeat {REPEAT_TIME:.0%} longer (KeywordPopups Repeat): x{1 + repeats:g} hits in "
                      f"x{1 + REPEAT_TIME * repeats:.2f} the time; each Repeat taken to hit the boss (MEDIUM); PoB "
                      "doesn't read the line (0 before); adds in the Presence would switch it off (one boss taken)"),
            "play": (f"Keep the boss more than {radius:.1f} m away (no enemy in your Presence): without it x1; with it "
                     f"x{factor:.3f}")}
    return [raw_mod("RepeatCount", "BASE", repeats, main.name),
            with_hits_per_use(raw_mod("DPS", "MORE", 100 * repeats, main.name), 1 + repeats),
            raw_mod("Speed", "MORE", 100 * (1 / (1 + REPEAT_TIME * repeats) - 1), main.name)], [note]


# Cannons, Ready! (MECHB37; the coverage ranking's #85, an OVERCOUNT). Tactician's notable (PoB's tree: "+1 to maximum
# number of Summoned Totems", "Skills used by Totems have 30% more Skill Speed", "Totems only use Skills when you fire an
# Attack Projectile"): PoB applies the first two and ignores the third (coverage: "PoB ignores the line"), so it scores
# every totem using its skill at its own speed whatever the player does. Patch notes: 0.2.1 and 0.5.0 fixed skills that
# fire projectiles upwards (Hailstorm Rounds, Siege Cascade; Molten Blast, Rolling Magma, Oil Barrage, Power Charged
# Falling Thunder) not setting them off: so any Attack the player fires a projectile with counts. Model: each totem uses
# its skill at most once per player projectile attack, so a totem skill's uses a second = min(its own, P), P = the
# player's projectile attacks a second: the fastest such skill the build has (useRates; item-granted ones included: a
# crossbow's Crossbow Shot, a bow's Bow Shot; MECHB54, RESEARCH46 R46-6: never a crossbow's LOAD part, Basic Bolt or
# "Load X", which fires nothing: the bridge's flag reads CrossbowSkill, not CrossbowAmmoSkill), which the player is taken to use between placements (a play strategy; its own
# damage counted only if it's in Full DPS). A totem skill: PoB's totem flag or UsedByTotem (Artillery Ballista's damage is
# its "Ballista Bolt"); an "attack projectile" skill: PoB's types Attack and Projectile, CrossbowSkill or
# GroundTargetedProjectile, not used by a totem, not triggered (bridge activeSkills byTotem / projectileAttack). Probe
# POE2T3329 (Artillery Ballista, a crossbow): Ballista Bolt 1.07 a second, Basic Bolt 2 a second (Basic Bolt, a LOAD
# part, was the player's rate there: an OVERCOUNT, R46-6, fixed by MECHB54; probe POE2T4843 / 4844). None: the totems never
# act (0, said). As a Speed
# "less" on each totem skill (its rate, ailments and all), divided back out on the next pass (tag cannons_ready).
# Labelled: a totem busy mid-use when the player fires is taken to catch the next one (the lower of the two rates);
# the player's attacks are taken as nonstop.
CANNONS_READY = re.compile(r"^Totems only use Skills when you fire an Attack Projectile$", re.I)
CANNONS_TAG = "cannons_ready"
def cannons_ready_model(texts: list[str], totems: list[tuple[str, float]], player: tuple[str, float] | None
                        ) -> tuple[list[dict], list[dict]]:
    """Totems acting only on the player's projectile attacks. `totems`: (skill, its own uses a second without this
    model's line); `player`: (skill, its uses a second) of the player's projectile attack, or None."""
    if not any(CANNONS_READY.search(t.strip()) for t in texts) or not totems:
        return [], []
    rate = player[1] if player else 0.0
    mods: list[dict] = []
    notes: list[dict] = []
    for skill, own in totems:
        if own <= 0:
            continue
        keep = min(1.0, rate / own)
        if keep <= 0:  # (no Speed of 0 for PoB to divide by: the damage instead)
            mods.append(raw_mod("DPS", "MORE", -100, skill, tag=CANNONS_TAG))
        elif keep < 1.0:
            mods.append(raw_mod("Speed", "MORE", 100 * (keep - 1), skill, tag=CANNONS_TAG))
        how = (f"you fire {player[0]} {rate:.2f} times a second" if player else
               "the build has no Attack you fire projectiles with")
        notes.append({"label": f"{skill}: Cannons, Ready! (totems act only when you fire)*", "value": f"x{keep:.3f}",
                      "confidence": "MEDIUM",
                      "basis": (f"each totem uses {skill} at most once per projectile Attack you fire: {how}, against its "
                                f"own {own:.2f} a second (PoB ignores the line and has it act nonstop); a totem busy when "
                                "you fire taken to catch the next one; your attacks taken as nonstop"),
                      "play": (f"Keep firing {player[0]} so the totems act: without it {skill} x0; with it x{keep:.3f}"
                               if player else f"Nothing in the build sets off the totems: {skill} x0")})
    return mods, notes


# Valako's Charge (MECHB38; GEM20's item (2), an OVERCOUNT as a main skill, an UNDERCOUNT beside one). Lightning Coil
# "Grants Skill: Level (1-20) Valako's Charge" (PoB Uniques/body.lua; skill ValakosChargePlayer, fromItem). The skill's
# text (PoB act_str.lua, the game's ActiveSkills): "While active, taking Lightning damage builds up charge on you.
# Reaching full charge expends all charge to Trigger this skill, creating a Chaining lightning bolt". Its Buff set's stats:
# cast_on_damage_taken_threshold (17 at level 1 .. 628 at 20 .. 2763 at 40, game files 26650308
# GrantedEffectStatSetsPerLevel), cast_on_damage_taken_only_tracks_lightning; Cooldown 1 s. PoB maps the threshold to
# skillData.triggeredByDamageTaken and its "cast when damage taken" trigger (CalcTriggers 1119-1133) returns the skill
# itself as the source: it fires once per Cooldown whatever the build takes (GEM18's 462 DPS: an OVERCOUNT unless the
# build takes threshold Lightning damage every second). Beside a main skill its group is fromItem, so the search never
# counted it (0, an UNDERCOUNT). Nothing changes the threshold (checked: game files 26650308 Mods Stat1-8,
# PassiveSkills, SoulCoreStats for cast_when_damage_taken_trigger_threshold_+% and every cast_on_damage_taken_* stat:
# only skill stat sets use them; PoB's own threshold modifier CWDTThreshold is read where it is the main skill).
# The rate: the boss's landed hits a second at the "when hit" pace (bosses.benefit_skill_time; the worst case's lowest
# real boss, boss_hits.gain_floor) that deal Lightning after the build's "taken as" lines, each a Lightning hit of the
# average size x after your mitigation. Per boss hit of type t (its share w_t, its average hit h_t, boss_hits): the part
# taken as Lightning f_t from PoB's own shift (its {Type}EnemyDamage -> {Type}TakenDamage: what each type loses, and what
# Lightning gains, split over the losing types by what they lose: exact when one type, e.g. Lightning Coil's Physical,
# feeds it), x PoB's LightningTakenHit / LightningTakenDamage (resistance, reduction, taken multipliers). A trigger needs
# k = ceil(threshold / that hit) Lightning hits ("expends all charge": a hit's excess taken as lost, MEDIUM; the smooth
# reading, damage a second / threshold, is in the note), and the next one past the Cooldown: uses = u / max(k, ceil(
# Cooldown x u)), u = those hits a second, at most PoB's own rate. Hits only (the skill has no
# cast_on_damage_taken_also_tracks_dot). As the main skill: a DPS "more" of rate / PoB's rate; beside it: the same on
# its group, counted in Full DPS with its Bolt set at that rate (PoB's own side calculation gives it speed 0, probe
# POE2T3338, so the rate goes in as its trigger rate, models.trigger_rate; capped at 1 / its Cooldown). No Lightning
# taken: 0, said.
VALAKO_SKILL = "Valako's Charge"
VALAKO_THRESHOLD = "cast_on_damage_taken_threshold"
VALAKO_TAG = "valakos_charge"
VALAKO_FIELDS = tuple(f"{t}{k}" for t in boss_hits.TYPES for k in ("EnemyDamage", "TakenDamage")) + (
    "LightningTakenHit", "EvadeChance", "EffectiveBlockChance", "enemySkillTime", "CWDTThreshold")


def lightning_taken_parts(stats: dict) -> tuple[dict[str, float], float]:
    """({type: the share of a boss hit of that type you take as Lightning}, Lightning's after-mitigation multiplier),
    from PoB's {Type}EnemyDamage / {Type}TakenDamage and LightningTakenHit (see above)."""
    enemy = {t: max(number(stats.get(f"{t}EnemyDamage")), 0.0) for t in boss_hits.TYPES}
    taken = {t: max(number(stats.get(f"{t}TakenDamage")), 0.0) for t in boss_hits.TYPES}
    lost = {t: max(enemy[t] - taken[t], 0.0) for t in boss_hits.TYPES}
    kept = enemy["Lightning"] - lost["Lightning"]
    gained = max(taken["Lightning"] - kept, 0.0)
    others = sum(v for t, v in lost.items() if t != "Lightning")
    parts = {"Lightning": kept / enemy["Lightning"] if enemy["Lightning"] > 0 else 1.0}
    for t in boss_hits.TYPES:
        if t != "Lightning":
            parts[t] = gained * lost[t] / others / enemy[t] if others > 0 and enemy[t] > 0 else 0.0
    mult = number(stats.get("LightningTakenHit")) / taken["Lightning"] if taken["Lightning"] > 0 else 0.0
    return parts, max(mult, 0.0)


def valako_rate(stats: dict, threshold: float, pob_rate: float, cooldown: float) -> tuple[float, str]:
    """(triggers a second, how) of Valako's Charge from the boss's Lightning hits (see above)."""
    parts, mult = lightning_taken_parts(stats)

    def one(read: dict) -> tuple[float, str]:
        name = boss_hits.boss_name(read)
        weights, sizes = boss_hits.type_shares(name), boss_hits.mean_hits(name)
        land = boss_hits.landing_hits({**read, "enemySkillTime": bosses.benefit_skill_time(read)})
        share = sum(w for t, w in weights.items() if parts.get(t, 0.0) > 0 and sizes.get(t, 0.0) > 0)
        if share <= 0 or mult <= 0 or land <= 0:
            return 0.0, f"{name}: no Lightning damage reaches you from its hits"
        hit = sum(weights[t] * sizes.get(t, 0.0) * parts.get(t, 0.0) for t in weights) * mult / share
        u = land * share
        k = max(1, math.ceil(threshold / hit - 1e-9)) if hit > 0 else 0
        rate = u / max(k, math.ceil(cooldown * u - 1e-9)) if k and cooldown > 0 else (u / k if k else 0.0)
        smooth = min(u * hit / threshold, 1 / cooldown if cooldown > 0 else math.inf)
        # (RESEARCH31 R31-7: charge building during the Cooldown leans yes, MEDIUM-LOW: the headline; the row without it:
        # the k hits only after the Cooldown ends)
        row = u / (k + math.ceil(cooldown * u - 1e-9)) if k and cooldown > 0 else rate
        return rate, (f"{name}: {u:.2f} landed hits a second carry Lightning ({share:.0%} of its hits, at the \"when "
                      f"hit\" pace), each {hit:,.0f} Lightning taken: {k} a charge, charge past full lost (MEDIUM, "
                      f"RESEARCH31 R31-7) and building during the Cooldown (MEDIUM-LOW); if it doesn't build then: "
                      f"{row:.3f} a second; the smooth reading, damage a second / threshold: {smooth:.3f} a second)")

    rate, how = boss_hits.gain_floor(stats, one)
    return (min(rate, pob_rate) if pob_rate > 0 else rate), how


def valako_model(skill: Skill | None, main: bool, stats: dict, threshold: float, pob_rate: float, cooldown: float
                 ) -> tuple[list[dict], list[dict], float]:
    """Valako's Charge at the rate the build's Lightning damage taken fills it (see above): (lines, notes, its uses a
    second); `main`: it is the main skill (PoB's DPS at its own rate), else a side group to count in Full DPS."""
    if skill is None or threshold <= 0 or pob_rate <= 0:
        return [], [], 0.0
    rate, how = valako_rate(stats, threshold, pob_rate, cooldown)
    keep = min(1.0, rate / pob_rate)
    where = "as the main skill" if main else "beside the main skill"
    before = ("PoB fires it once per Cooldown whatever you take (an OVERCOUNT)" if main else
              "PoB never counted its group beside the main skill (0 before)")
    note = {"label": f"{VALAKO_SKILL}: triggers from Lightning damage taken*", "value": f"{rate:.3f} a second",
            "confidence": "MEDIUM",
            "basis": (f"{how}; full charge at {threshold:,.0f} Lightning damage taken (its level's threshold), at most "
                      f"one per its {cooldown:g} s Cooldown ({pob_rate:.2f} a second, PoB's rate): {rate:.3f} a second "
                      f"{where} (x{keep:.3f} of PoB's); {before}. A hit's charge past full taken as lost (MEDIUM); "
                      "the boss's hits evenly spaced; damage over time doesn't charge it"),
            "play": (f"{VALAKO_SKILL} fires as you take Lightning hits: {rate:.2f} a second against this boss"
                     if rate > 0 else f"Nothing in the fight charges {VALAKO_SKILL}: 0")}
    if not main:  # (beside the main skill PoB gives it no speed at all (probe POE2T3338): its rate as a trigger rate)
        return (trigger_rate(VALAKO_SKILL, rate) if rate > 0 else []), [note], rate
    if keep >= 1.0:
        return [], [note], rate
    return [raw_mod("DPS", "MORE", 100 * (keep - 1), VALAKO_SKILL, tag=VALAKO_TAG)], [note], rate




# The Dark Defiler (MECHB38; the coverage ranking's section C, an UNDERCOUNT: 0 before). The sceptre's "Gain (3 / 5)% of
# Damage as Chaos Damage per Undead Minion" (PoB Uniques/sceptre.lua; Pre 0.1.1 3%, Current 5%): PoB's ModCache reads it
# as a MinionModifier with leftover text ("   per Undead  "), and PoB never applies a line parsed only in part, so 0.
# The player gains it (the line is on your sceptre; "Gain X% of Damage as Y" is extra damage, PoB's DamageGainAsChaos).
# Undead: the game's Monster Category (KeywordPopups MonsterCategory); a minion skill of PoB's CreatesUndeadMinion type is
# taken as summoning Undead (MEDIUM). Count: the build's Persistent undead minions at their limit, less the share dead
# (the build's own minion deaths a second, minion_deaths, their undead share, x the revive time, revive_seconds); no
# source kills them: all alive. Temporary undead minions (a duration) not counted (an UNDERCOUNT, said).
DARK_DEFILER = re.compile(r"^Gain (\d+(?:\.\d+)?)% of Damage as Chaos Damage per Undead Minion$", re.I)


def dark_defiler_model(texts: list[str], skills: list[Skill], main: Skill | None, stats: dict
                       ) -> tuple[list[dict], list[dict]]:
    """The Dark Defiler's Chaos gain per Undead minion alive on average (see above)."""
    pct = max((float(m.group(1)) for t in texts if (m := DARK_DEFILER.search(t.strip()))), default=0.0)
    if pct <= 0:
        return [], []
    reviving = [s for s in skills if s.summon and s.summon.get("persistent") and not number(s.summon.get("duration"))]
    undead = [s for s in reviving if s.summon.get("undead")]
    total = sum(number(s.summon.get("limit")) for s in reviving)
    count = sum(number(s.summon.get("limit")) for s in undead)
    temporary = sorted({s.name for s in skills if s.summon and s.summon.get("undead") and number(s.summon.get("duration"))})
    dead, how = 0.0, "nothing in the build kills them: all alive"
    if count > 0:
        deaths, death_how = minion_deaths(skills, main, stats)
        if deaths > 0:
            revive, _ = revive_seconds(reviving)
            dead = min(count, deaths * count / total * revive)
            how = f"{dead:.2f} down on average ({death_how}; {revive:.3g} s to revive)"
    alive = max(count - dead, 0.0)
    gain = pct * alive
    note = {"label": "The Dark Defiler: Chaos damage per Undead minion*", "value": f"+{gain:.1f}%",
            "confidence": "MEDIUM",
            "basis": (f"{pct:g}% of Damage as extra Chaos per Undead minion; {alive:.2f} Persistent undead minions alive "
                      f"on average ({count:g} at their limit: "
                      + (", ".join(f"{s.name} {number(s.summon.get('limit')):g}" for s in undead) or "none")
                      + f"; {how}); PoB reads the line as a minion modifier with leftover text and never applies it (0 "
                      "before). Undead: PoB's CreatesUndeadMinion skills (MEDIUM)"
                      + (f"; temporary undead minions not counted ({', '.join(temporary)}: an UNDERCOUNT)" if temporary
                         else "")),
            "play": (f"Keep your undead minions up: without them +0%; with them +{gain:.0f}% of Damage as Chaos"
                     if gain > 0 else "The build has no Persistent undead minions for The Dark Defiler: +0%")}
    return ([line("Gain 1% of Damage as Extra Chaos Damage", gain)] if gain > 0 else []), [note]

# Corpses consumed a second (MECHB37's draft, applied by MECHB38; COV40's route, the manager 00:08 18 Nov): "N% increased
# Damage if you have Consumed a Corpse Recently" (the Corpses jewel line, PoB ModCache) and PoB's other
# ConsumedCorpseRecently lines (ModParser 1999 / 2003 / 3214 / 4405) sit behind Condition:ConsumedCorpseRecently, which only
# PoB's config box sets (ConfigOptions 1545-1546) and the tool never did (checked: grep of builder/ and engine/bridge.lua
# for ConsumedCorpseRecently before this change, no hit): never on, an UNDERCOUNT. The rate from the build (CLAUDE.md's
# no-flat-rates rule): the build's corpse-consuming skills (the game's corpse skill types, Skill.corpses) take what the
# supply gives (models.corpse_supply: Sacrifice's undead Reviving minions, the boss preset's killed adds), at most their own
# uses a second (the main skill's Speed; another skill's PoB use rate, taken as used as often as it can: an upper bound that
# binds only below the supply). No corpse skill or no supply: 0, said. Published as build.corpses_consumed for the
# condition resolver (conditions._corpse_consumed_recently: the share of the fight with one consumed in the past 4 s).
CONSUMED_CORPSE = re.compile(r"consumed a corpse recently", re.I)


def corpses_consumed(consumers: list[tuple[str, float]], supply: float, supply_how: str) -> tuple[float, str]:
    """Corpses consumed a second and how (see above). `consumers`: (skill, its uses a second)."""
    if not consumers:
        return 0.0, "the build has no skill that consumes corpses"
    demand = sum(max(rate, 0.0) for _, rate in consumers)
    names = ", ".join(f"{name} {rate:.2f}/s" for name, rate in consumers)
    if supply <= 0:
        return 0.0, f"no corpse to consume on the boss ({supply_how}); corpse skills: {names}"
    rate = min(supply, demand)
    return rate, (f"{rate:.3f} corpses consumed a second: {supply:.3f} a second to take ({supply_how}), the corpse skills "
                  f"using up to {demand:.2f} a second ({names})")

# Different Non-Instant skills used per 8 s (MECHB4; AUDIT7 A7-2, research/cast-speed-per-different-spell.md) -------------
# Counts COV-B's Emboldening Casts / Enhancing Attacks read (PoB multipliers LedgerDifferentNonInstantSpells8s /
# LedgerDifferentNonInstantAttacks8s, passive_models.different_skills_model), and PoB's NonInstantSpellCastRecently, which
# Rapid Casting III ("for each different Non-Instant Spell you've Cast Recently") and the Kurgal wand suffix read and nothing
# set (0 before). A skill counts when the player uses it at least once per window: the main skill, and every other
# non-instant skill the build has that its cooldown allows that often (a skill in the build is used: a play strategy, with
# the "only the main skill" row in the note). Not counted: triggered skills (see below), Persistent skills (placed once),
# skills a totem uses, instant skills
# (base cast time 0, the bridge's own test). Triggered skills stay out: the game's Trigger definition says "Triggering a
# Skill does not count as using it" (AUDIT17 A17-x: HIGH). PoB's NonInstantSpellCastRecently (Rapid Casting III, the Kurgal
# suffix: "for each different Non-Instant Spell you've Cast Recently", ModParser.lua 1998, SkillStatMap.lua 630; no other
# reader, checked: grep of PoB's src and our builder) takes its own count over Recently, 4 s (MECHB6, AUDIT17 A17-2; before,
# the 8 s count: one spell more where a cooldown is 4-8 s).
DIFFERENT_WINDOW = 8.0


def different_skills_counts(skills: list[Skill], main: Skill | None, persistent: set[str]
                            ) -> tuple[list[dict], list[dict]]:
    """The different Non-Instant Spells and Attacks the build uses per 8 s, as model inputs (see above)."""
    def used(s: Skill, window: float = DIFFERENT_WINDOW) -> bool:
        if s.triggered or s.name in persistent or (s.cast_time or 0.0) <= 0 or cast_by_totem(skills, s):
            return False
        if main is not None and s.name == main.name:
            return True
        cooldown = number(s.cooldown) / (s.cooldown_recovery or 1.0)
        return cooldown <= window

    counts = {}
    for kind, test in (("Spells", lambda s: s.spell), ("Attacks", lambda s: s.attack and not s.spell)):
        counts[kind] = sorted({s.name for s in skills if test(s) and used(s)})
    mods = [derived("DifferentNonInstantSpells8s", "", len(counts["Spells"])),
            derived("DifferentNonInstantAttacks8s", "", len(counts["Attacks"]))]
    recent = sorted({s.name for s in skills if s.spell and used(s, RECENTLY)})
    if recent:
        mods.append(raw_mod("Multiplier:NonInstantSpellCastRecently", "BASE", len(recent)))
    notes = [{"label": f"Different Non-Instant {kind} used per {DIFFERENT_WINDOW:g} s", "value": len(names),
              "basis": (", ".join(names) if names else "none") + ": the main skill and every other non-instant one the "
                       f"build has whose cooldown lets you use it once per {DIFFERENT_WINDOW:g} s (a play strategy: use each "
                       "that often; with only the main skill: 1). Triggered, Persistent, totem and instant skills not "
                       "counted (\"Triggering a Skill does not count as using it\": the game's Trigger definition)",
              "confidence": "MEDIUM"} for kind, names in counts.items() if names]
    if recent:
        notes.append({"label": f"Different Non-Instant Spells Cast Recently ({RECENTLY:g} s)", "value": len(recent),
                      "basis": ", ".join(recent) + f": the same play, over Recently ({RECENTLY:g} s), for Rapid Casting III "
                               "and the Kurgal wand suffix (\"... you've Cast Recently\")", "confidence": "MEDIUM"})
    return mods, notes



# Casting Cascade (6%) / Effervescent (4%) (MECHB44; COV45's routed rows, an UNDERCOUNT): "N% increased Cast Speed for
# each different Spell you've Cast in the last eight seconds" (PassiveSkills cast_speed31 / cast_speed32, stat
# cast_speed_+%_per_num_unique_spells_cast_in_last_8_seconds, game 26650308). PoB parses it only in part (ModCache 4047 /
# 4761 leave "for each different  you've Cast in the last eight seconds"), so it never applies (Item.lua / PassiveTree.lua
# `not modLine.extra`: LANE_RULES). No "Non-Instant" in the wording, so instant Spells count too (the manager's routing,
# COV45 18:08). The count is different_skills_counts' play (the main skill and each other Spell whose cooldown allows a
# cast once per 8 s; triggered, Persistent and totem skills out), instant ones in: the line's % x that count as Cast Speed.
DIFFERENT_SPELL_SPEED = re.compile(r"^(\d+(?:\.\d+)?)% increased cast speed for each different spell you've cast in the "
                                   r"last eight seconds$", re.I)


def different_spells_cast_speed(texts: list[str], skills: list[Skill], main: Skill | None, persistent: set[str]
                                ) -> tuple[list[dict], list[dict]]:
    """(mods, notes) for the "Cast Speed for each different Spell you've Cast in the last eight seconds" lines."""
    pct = sum(float(m.group(1)) for m in (DIFFERENT_SPELL_SPEED.match(t.strip()) for t in texts) if m)
    if pct <= 0:
        return [], []

    def cast(s: Skill) -> bool:
        if not s.spell or s.triggered or s.name in persistent or cast_by_totem(skills, s):
            return False
        if main is not None and s.name == main.name:
            return True
        return number(s.cooldown) / (s.cooldown_recovery or 1.0) <= DIFFERENT_WINDOW

    names = sorted({s.name for s in skills if cast(s)})
    note = {"label": f"Cast Speed per different Spell cast in the last {DIFFERENT_WINDOW:g} s", "value": len(names),
            "basis": (f"{pct:g}% increased Cast Speed for each ({', '.join(names) if names else 'none'}): "
                      f"+{pct * len(names):g}%. The main skill and every other Spell of the build whose cooldown lets you "
                      f"cast it once per {DIFFERENT_WINDOW:g} s, instant ones included (the line says any Spell); "
                      "triggered, Persistent and totem skills not counted. PoB parses the line only in part, so it "
                      "applied nothing before"),
            "confidence": "MEDIUM",
            "play": (f"Cast each of your Spells at least once every {DIFFERENT_WINDOW:g} s: with it +{pct * len(names):g}% "
                     f"Cast Speed ({len(names)} Spells); with only the main skill +{pct if main is not None and main.spell else 0:g}%.")}
    return ([line("1% increased Cast Speed", pct * len(names))] if names else []), [note]


# Unstable Bond (MECHB44; routed from MECH91, the minion-death side of Volatility; an UNDERCOUNT: PoB reads no Volatility,
# ModCache 7626 leaves "Gain 3 Volatility when an Allied Persistent Reviving Minion is Killed" with leftover text). Stat
# gain_X_volatility_on_persistent_minion_death 3, on the anointable notable volatility1 only (checked: PassiveSkills,
# Mods, GrantedEffectStatSets of 26650308 for the stat: PassiveSkills volatility1 alone; PoB tree 0_5 node 18485; patch
# notes: no hit, which is not evidence of absence). Volatility (KeywordPopups, see volatility_model) explodes D s (4 s x the
# delay lines) after the last gain, then Volatile Power gives 1% of Damage as Chaos per Volatility exploded for 10 s.
# The deaths are models.minion_deaths' (your Persistent, Reviving minions Killed a second from the build's own sources:
# Sacrifice, Minion Pact, ...; 0 with none: CLAUDE.md's no-flat-rates rule). Deaths at most one per D s: each death's 3
# explode alone, each explosion's Volatile Power its own 10 s, adding (RESEARCH35 R35-8, MEDIUM): 3% x 10 r on average
# (row: a later one replaces it, 3% x min(1, 10 r)). Deaths more often than one per D s keep resetting the timer, so it never
# explodes (0; row: pace the deaths one per D s). With Inner Turmoil the ailment gains reset the timer too, and MECH-A's
# cycle (volatility_model; MECH92 af43dcbb) counts these gains in it, so this model gives +0 there (nothing counted
# twice). Without Inner Turmoil's "Take
# no Damage from Volatility" each explosion hits you for 100 Physical per Volatility (a defence cost, said, not modelled).
UNSTABLE_BOND = re.compile(r"^gain (\d+) volatility when an allied persistent reviving minion is killed$", re.I)
TAKE_NO_VOLATILITY = re.compile(r"^take no damage from volatility$", re.I)


def unstable_bond_model(texts: list[str], deaths: tuple[float, str]) -> tuple[list[dict], list[dict]]:
    """(mods, notes) for Unstable Bond's Volatility on your Persistent Reviving minions' deaths (the note above)."""
    each = sum(float(m.group(1)) for m in (UNSTABLE_BOND.match(t.strip()) for t in texts) if m)
    if each <= 0:
        return [], []
    label = "Unstable Bond: Volatile Power from minion deaths*"
    cap = min([float(m.group(1)) for t in texts if (m := VOLATILITY_MAX.match(t.strip()))] or [VOLATILITY_CAP])
    inc = sum(float(m.group(1)) * (1 if m.group(2).lower() == "increased" else -1)
              for t in texts if (m := VOLATILITY_DELAY.match(t.strip())))
    delay = VOLATILITY_SECONDS * max(0.0, 1 + inc / 100)
    rate, how = deaths
    rate = max(number(rate), 0.0)
    k = min(cap, each)
    hurt = "" if any(TAKE_NO_VOLATILITY.match(t.strip()) for t in texts) else (
        f"; each explosion hits you for {100 * k:g} Physical Damage (100 per Volatility: no 'Take no Damage from "
        "Volatility' in the build; a defence cost, not modelled)")
    paced = VOLATILE_POWER_SECONDS / delay * k if delay > 0 else k  # (one death per delay, Powers adding: R35-8)
    if any(INNER_TURMOIL.match(t.strip()) for t in texts):
        return [], [{"label": label, "value": "+0 here (counted in Inner Turmoil's cycle)", "confidence": "MEDIUM",
                     "basis": (f"{rate:.3f} deaths a second ({how}); with Inner Turmoil your ailments reset the "
                               "explosion timer too, and its attack-then-stop cycle (Inner Turmoil's note, MECH-A's "
                               "volatility_model) counts these gains with the ailments' own (MECH92 af43dcbb; before it lands, "
                               "nowhere: a lower reading): +0 here, so they aren't counted twice")}]
    if rate <= 0:
        return [], [{"label": label, "value": 0, "confidence": "MEDIUM",
                     "basis": f"no Persistent Reviving minion of yours is Killed ({how}): no Volatility, +0"}]
    if 1 / rate < delay:
        return [], [{"label": label, "value": "+0 (never explodes)", "confidence": "MEDIUM-LOW",
                     "basis": (f"{rate:.3f} deaths a second ({how}), one every {1 / rate:.2f} s: each gain resets the "
                               f"{delay:g} s explosion timer, so the Volatility never explodes (+0). Pacing the deaths "
                               f"to one every {delay:g} s: +{paced:g}% of Damage as Chaos" + hurt),
                     "play": (f"Let your minions die at most once every {delay:g} s so the Volatility explodes: with "
                              f"it +{paced:g}% of Damage as Chaos; without it +0")}]
    up = min(1.0, VOLATILE_POWER_SECONDS * rate)
    gain = k * VOLATILE_POWER_SECONDS * rate  # (R35-8: each explosion's Power its own 10 s, they add, no cap)
    replaced = k * up
    return [line("Gain 1% of Damage as Extra Chaos Damage", gain)], [{
        "label": label, "value": f"+{gain:.2f}% of Damage as Chaos", "confidence": "MEDIUM",
        "basis": (f"{rate:.3f} deaths a second ({how}), one every {1 / rate:.2f} s, at least the {delay:g} s explosion "
                  f"delay: each death's {k:g} Volatility explodes, and each explosion's Volatile Power ({k:g}% of Damage "
                  f"as Chaos) lasts its own {VOLATILE_POWER_SECONDS:g} s and adds to the others (RESEARCH35 R35-8, MEDIUM): "
                  f"{VOLATILE_POWER_SECONDS * rate:.2f} at once on average, +{gain:.2f}%. If a later one replaced the "
                  f"Power: +{replaced:.2f}%" + hurt + ". PoB reads no Volatility"),
        "play": (f"Your minions' deaths feed it (one every {1 / rate:.2f} s): with them +{gain:.2f}% of Damage as "
                 "Chaos; without them +0")}]

# Full Salvo and Demolitionist (MECHB43; routed from MECHC43 / MECH89's never-on rows; MECHB44: PoB counts 1, not 0,
# see AMMO_PLACEHOLDER; the model sets PoB's total to the build's count: an OVERCOUNT of one fixed). Full Salvo
# (Deadeye's notable, "Allocates Full Salvo" on items): "25% increased Damage with Crossbows for each type of Ammunition
# fired in the past 10 seconds"; Demolitionist: "Gain 4% of Damage as Extra Fire Damage for every different Grenade fired
# in the past 8 seconds". PoB parses both whole behind Multiplier:DifferentAmmoFired / DifferentGrenadeFired (ModParser
# 1557-1558), capped at the build's distinct ammo / grenade skills (AmmoTypes / GrenadeTypes, CalcPerform 1398-1407), and
# only its config boxes set the two multipliers (ConfigOptions 1657-1661; checked: grep of builder/ and engine/ for
# DifferentAmmoFired / DifferentGrenadeFired before this change: none). MECHB43 read that as 0; WRONG (MECHB44, probe
# POE2T4652: a plain 25% gives x1.25, the line with the model's +1 gave x1.50 = two types): both boxes' placeholder, 1, is
# applied while the input is unset (ConfigTab.lua 1186), so PoB counted 1 type of each. From the build (CLAUDE.md's
# no-flat-rates rule): the distinct gems typed CrossbowAmmoSkill / Grenade (the game's skill types, gem data) the player
# fires at least once a window: the main skill, and each other one of the build that isn't triggered, Meta or a totem's
# and whose cooldown allows a use per window (a play strategy: fire each that often; the "only the main skill" row in the
# note), as different_skills_counts reads its skills. Triggered ones (a Mortar Cannon's grenades) aren't counted: whether
# a grenade a Meta fires counts as yours is UNVERIFIED (the lower reading). MEDIUM. The window: the line's own number.
AMMO_FIRED = re.compile(r"for each type of ammunition fired in the past (\d+) seconds", re.I)
GRENADE_FIRED = re.compile(r"for every different grenade fired in the past (\d+) seconds", re.I)


AMMO_PLACEHOLDER = 1  # (PoB's multiplierDifferentAmmoFired / multiplierDifferentGrenadeFired placeholder, applied)


def ammo_grenade_counts(skills: list[Skill], main: Skill | None, persistent: set[str], types_of,
                        texts: list[str]) -> tuple[list[dict], list[dict]]:
    """(mods, notes): PoB's Multiplier:DifferentAmmoFired / DifferentGrenadeFired from the build's ammo and grenade skills
    (see above). `types_of(name)` gives a skill's game skill types (gem data)."""
    mods: list[dict] = []
    notes: list[dict] = []
    for kind, pattern, var, label in (("CrossbowAmmoSkill", AMMO_FIRED, "DifferentAmmoFired", "types of Ammunition"),
                                      ("Grenade", GRENADE_FIRED, "DifferentGrenadeFired", "different Grenades")):
        windows = [float(m.group(1)) for t in texts if (m := pattern.search(t))]
        if not windows:
            continue
        window = min(windows)
        typed = [x for x in skills if kind in (types_of(x.name) or ()) and "Meta" not in (types_of(x.name) or ())]
        fired, left = set(), set()
        for x in typed:
            if main is not None and x.name == main.name:
                fired.add(x.name)
            elif x.triggered or x.name in persistent or cast_by_totem(skills, x):
                left.add(x.name)
            elif number(x.cooldown) / (x.cooldown_recovery or 1.0) <= window:
                fired.add(x.name)
            else:
                left.add(x.name)
        count = len(fired)
        # (MECHB44, probe POE2T4652: an OVERCOUNT before) PoB's config box for the multiplier applies its placeholder, 1,
        # whenever its input is unset (ConfigOptions 1657 / 1660 defaultPlaceholderState = 1; ConfigTab 1186 applies a
        # placeholder like an input), which the tool never sets: so PoB already counted 1, and adding the count made it
        # count + 1 (Permafrost Bolts with Full Salvo: x1.50 = a plain 50%, POE2T4652). The mod is the count less it.
        if count != AMMO_PLACEHOLDER:
            mods.append(raw_mod(f"Multiplier:{var}", "BASE", count - AMMO_PLACEHOLDER))
        alone = 1 if main is not None and main.name in fired else 0
        notes.append({"label": f"{label.capitalize()} fired in the past {window:g} s*", "value": count,
                      "basis": ((", ".join(sorted(fired)) if fired else "none") + f": the main skill and each other one "
                                f"the build has whose cooldown lets you fire it once per {window:g} s (a play strategy: fire "
                                f"each that often; with only the main skill: {alone})"
                                + (f"; not counted (triggered, a totem's or a longer cooldown): {', '.join(sorted(left))}"
                                   if left else "") + f". PoB's config box counts {AMMO_PLACEHOLDER} by itself (its placeholder, applied): the model sets the total to "
                                     "the build's count (an OVERCOUNT of one before, POE2T4652)"),
                      "play": (f"Fire each of {', '.join(sorted(fired))} at least once every {window:g} s (without it: "
                               f"{alone}, with it: {count})" if count > 1 else ""),
                      "confidence": "MEDIUM"})
    return mods, notes


# Aftershock chance, summed (MECHB5, 12 Nov 2026; FIX_QUEUE COVD8's finding, RESEARCH7 aftershock-chance-stacking.md).
# KeywordPopups Aftershock: "If not otherwise specified, the Aftershock will deal the same damage as the initial impact, in
# the same area. Only Attack damage can cause Aftershocks." The game sums every chance source into one chance per hand
# (the virtual_*_slam_aftershock_chance_% stats) and rolls it once (RESEARCH7, MEDIUM-HIGH); over 100% is one extra
# Aftershock (SETTLED, MEDIUM-HIGH, RESEARCH26 R26-32: Hymn and Earthbreaker raise the same stat,
# your_slam_aftershock_chance_%, and KeywordPopups SurpassChance says chance stats cap at 100% unless they "surpass";
# all 41 aftershock stat ids checked; a Mobalytics "in addition" snippet disagrees with the files). The ledger turns each item / passive line into its own "more" (Hymn's
# "Slam Skills have 100% more DPS", the four aftershock-chance entries' "Slam Skills deal N% more Damage"), so:
#   - lines multiply instead of adding (Hymn + Earthbreaker x2.5 where the game gives x2: an overcount);
#   - the Aftershock I-III supports' slam_aftershock_chance_% (25 / 35 / 15, GrantedEffectStatSets) maps in PoB to
#     AftershockChance, which no calculation reads (checked: grep AftershockChance over vendor/PathOfBuilding-PoE2/src
#     finds SkillStatMap.lua only; RULE_AUDIT A6-29): an undercount;
#   - the ledger drops "you use yourself", so a triggered or totem slam gets those lines too (an overcount);
#   - in the DPS form PoB counts each Aftershock as its own ailment application (stacks x (1 + a), CalcOffence 5254),
#     but the impact and its Aftershock land together: with one Ignite / Bleed / Poison slot the second application only
#     refreshes the first, so applications per slam are 1 - (1 - p)(1 - A p) = p (1 + A - A p) (an overcount of up to
#     x1.33 on the ailment at p = 0.5, A = 1; none at full uptime). With more than one slot both count.
# The model sets the main slam's hits to 1 + A (A = min(1, summed chance)) with one DPS "more" against what the ledger
# already applied, and each one-slot ailment's applications to p (1 + A - A p) through its duration (an ailment's damage
# per second doesn't depend on its duration in PoB, so its uptime moves and a full-uptime ailment's damage doesn't).
# Left as they are (labelled): the "more Damage" form also makes each ailment application bigger (COV-A: switch the
# aftershock-chance entries to the DPS form); other slams in Full DPS keep the ledger's per-line mores; whether an
# Aftershock rolls its own damage (UNVERIFIED, COVD8).
# Tremors (MECHB9; COVE10's parts, support_part_scale(main, "aftershocks"): AftershockChanceOne / Two / Three = 30 / 15 /
# 10, SupportTremorsPlayer; gem_stat_descriptions: "Supported Skills have {0}% chance to cause an additional / two
# additional / three additional Aftershocks", no "you use yourself"). Expected extra Aftershocks a slam: 1 x 30% + 2 x 15%
# + 3 x 10% = 0.9, the same whether it's one roll or three independent ones that add up (only "the biggest one wins"
# would give less, 0.80). They're taken as added on top of the summed single-Aftershock chance (the 0.2.0 notes: "Fixed a
# bug where Tremors Support could interfere with aftershock chances from other sources", so they coexist), and as one roll
# for the one-slot ailments' applications: UNVERIFIED both, MEDIUM-LOW. PoB has no Tremors gem, so this reads nothing
# until gem resolution can socket a gem PoB lacks (COV-C); its 35% less Damage is a plain support line (COVE10).
TREMORS_PARTS = {"AftershockChanceOne": 1, "AftershockChanceTwo": 2, "AftershockChanceThree": 3}
# Counted since MECHB7 (AUDIT19 A19-2, an undercount): chance_to_aftershock_+%_per_250_ms_attack_time, 15 on both
# Aftershock III (SupportAftershockChancePlayerThree) and Reverberate (SupportReveberatePlayer, live), game files
# GrantedEffectStatSets (checked: the stat's index in Mods, PassiveSkills, SoulCoreStats and the GrantedEffect stat,
# per-level and quality tables: only those two stat sets; PoB's Data/Skills and ModCache agree; poe2db not checked). Its text
# (gem_stat_descriptions): "Supported Skills have {0}% increased chance to cause Aftershocks for every quarter second of
# Attack time": an increase to the slam's summed chance, 15% x attack time / 0.25 s. Attack time is taken as the main
# slam's 1 / Speed from PoB (its attack time after speed modifiers; whether the game uses the base time instead:
# UNVERIFIED, MEDIUM). Aftershock III supports only "Slams you use yourself"; Reverberate any slam with a chance.
AFTERSHOCK_SUPPORTS = {"Aftershock I": 25.0, "Aftershock II": 35.0, "Aftershock III": 15.0}  # slam_aftershock_chance_%
AFTERSHOCK_PER_QUARTER = {"Aftershock III": 15.0, "Reverberate": 15.0}  # chance_to_aftershock_+%_per_250_ms_attack_time
AFTERSHOCK_LINES = (  # (pattern, "self" = Slams you use yourself / "any", the condition it needs)
    (re.compile(r"^(\d+(?:\.\d+)?)% chance for Slam Skills you use yourself to cause an additional Aftershock$", re.I),
     "self", ""),
    (re.compile(r"^Slam Skills you use yourself cause an additional Aftershock$", re.I), "self", ""),
    (re.compile(r"^(\d+(?:\.\d+)?)% chance for Mace Slam Skills you use yourself to cause an additional Aftershock$",
                re.I), "self", "Mace"),
    (re.compile(r"^(\d+(?:\.\d+)?)% chance for Shapeshift Slam Skills you use yourself to cause an additional "
                r"Aftershock$", re.I), "self", "Shapeshift"),
    (re.compile(r"^(\d+(?:\.\d+)?)% chance for Slam Skills to cause an additional Aftershock$", re.I), "any", ""),
)
LEDGER_SLAM_MORE = re.compile(r"^Slam Skills (deal|have) (\d+(?:\.\d+)?)% more (Damage|DPS)(?: (while .*))?$", re.I)
ONE_SLOT_AILMENTS = ("Ignite", "Bleed", "Poison")


def aftershock_chance(texts: list[str], group_gems: list[dict], yourself: bool, mace: bool, shapeshift: bool,
                      attack_time: float = 0.0) -> tuple[float, list[str]]:
    """The main slam's summed Aftershock chance in % (uncapped) and its sources; attack_time (s) for the supports'
    "increased chance per quarter second of Attack time"."""
    total, why = 0.0, []
    for text in texts:
        t = text.strip()
        for pattern, who, needs in AFTERSHOCK_LINES:
            if m := pattern.search(t):
                if not ((who == "self" and not yourself) or (needs == "Mace" and not mace)
                        or (needs == "Shapeshift" and not shapeshift)):
                    value = float(m.group(1)) if m.groups() else 100.0
                    total += value
                    why.append(f"{value:g}% ({t})")
                break
    if yourself:
        for gem in group_gems:
            if gem.get("enabled", True) and gem.get("name") in AFTERSHOCK_SUPPORTS:
                total += AFTERSHOCK_SUPPORTS[gem["name"]]
                why.append(f"{AFTERSHOCK_SUPPORTS[gem['name']]:g}% ({gem['name']})")
    per_quarter = sum(AFTERSHOCK_PER_QUARTER[g["name"]] for g in group_gems
                      if g.get("enabled", True) and g.get("name") in AFTERSHOCK_PER_QUARTER
                      and (yourself or g["name"] != "Aftershock III"))
    if total > 0 and per_quarter > 0 and attack_time > 0:
        increase = per_quarter * attack_time / 0.25
        total *= 1 + increase / 100
        names = ", ".join(n for n in AFTERSHOCK_PER_QUARTER if any(g.get("name") == n for g in group_gems))
        why.append(f"x{1 + increase / 100:.2f}: {increase:.0f}% increased ({names}: {per_quarter:g}% per 0.25 s of a "
                   f"{attack_time:.2f} s attack time, MEDIUM)")
    return total, why


def ledger_slam_mores(texts: list[str], forbidden: set[str], mace: bool, shapeshift: bool,
                      translate: Callable[[str], tuple | None]) -> tuple[float, float]:
    """What the ledger already applies to a slam for the Aftershock lines: (product of its "more Damage" factors,
    product of its "more DPS" factors). A "while" condition the slam can't meet here (Mace, Shapeshifted) isn't counted."""
    damage = dps = 1.0
    for text in texts:
        t = text.strip()
        if not any(p.search(t) for p, _, _ in AFTERSHOCK_LINES):
            continue
        found = translate(t)
        if not found or found[0].id in forbidden:
            continue
        for out in found[1]:
            if m := LEDGER_SLAM_MORE.match(out.strip()):
                cond = (m.group(4) or "").lower()
                if ("mace" in cond and not mace) or ("shapeshift" in cond and not shapeshift):
                    continue
                factor = 1 + float(m.group(2)) / 100
                if m.group(3).lower() == "dps":
                    dps *= factor
                else:
                    damage *= factor
    return damage, dps


def aftershock_model(texts: list[str], stats: dict, main: Skill | None, main_types: set[str], group_gems: list[dict],
                     weapon_types: set[str], totem: bool = False, forbidden: set[str] = frozenset(),
                     translate: Callable[[str], tuple | None] | None = None) -> tuple[list[dict], list[dict]]:
    """The main slam's Aftershocks (see above): a DPS "more" bringing its hits to 1 + A against the ledger's, and each
    one-slot ailment's duration "more" bringing its applications to p (1 + A - A p). ([], []) for a non-slam."""
    if main is None or "Slam" not in main_types or not main.attack:
        return [], []
    if translate is None:
        from builder.ledger import translate
    yourself = not (main.triggered or totem or "Triggered" in main_types)
    mace = any("Mace" in w for w in weapon_types) if weapon_types else True
    shapeshift = any("Shapeshift" in t for t in main_types)
    speed = number(stats.get("Speed"))
    total, why = aftershock_chance(texts, group_gems, yourself, mace, shapeshift, 1 / speed if speed > 0 else 0.0)
    damage, dps = ledger_slam_mores(texts, forbidden, mace, shapeshift, translate)
    parts = support_part_scale(main, "aftershocks")[0]
    tremors = {k: min(1.0, max(0.0, number(parts.get(name)) / 100)) for name, k in TREMORS_PARTS.items()}
    tremors = {k: c for k, c in tremors.items() if c > 0}
    extra = sum(k * c for k, c in tremors.items())
    if total <= 0 and damage == 1.0 and dps == 1.0 and not extra:
        return [], []
    a = min(1.0, total / 100)
    target, applied = 1 + a + extra, damage * dps
    if extra:
        why.append(f"Tremors: {' + '.join(f'{k} x {c:.0%}' for k, c in sorted(tremors.items()))} = {extra:.2f} more "
                   "Aftershocks a slam, on top (one roll or several adding up give the same; UNVERIFIED how they meet "
                   "the other chances, MEDIUM-LOW)")
    mods: list[dict] = []
    correction = target / applied - 1
    if abs(correction) > 1e-6 or abs(target - 1) > 1e-9:
        # (MECHB57, the manager's MECHB57 brief item 1, an UNDERCOUNT for the hit readers: the slam's Aftershocks are
        # hits landing with the slam, `target` a use against PoB's one; the readers saw one. models.HIT_CUT_PER_USE:
        # the hit readers count them (Shock / Chill chance a use, buildup), the uses kept. The one-slot ailments'
        # duration mores below stay: they correct PoB's own count, which reads DpsMultiplier (x target / damage).)
        mods.append(with_per_use(raw_mod("DPS", "MORE", 100 * correction, main.name), target))
    whose = "used by you" if yourself else "triggered or a totem's, so only the \"Slam Skills\" lines count"
    notes = [{"label": f"Aftershock chance, summed ({main.name})",
              "value": f"{a:.0%}" + (f" + {extra:.2f} Aftershocks (Tremors)" if extra else ""),
              "basis": f"{'; '.join(why) or 'no source'}; the game sums the chances and rolls once (capped at one extra "
                       f"Aftershock, UNVERIFIED), so the slam's hits are x{target:.2f}; the ledger's per-line mores gave "
                       f"x{applied:.2f} (Damage x{damage:.2f}, DPS x{dps:.2f}), corrected by x{target / applied:.3f}; "
                       f"the slam is {whose}",
              "confidence": "MEDIUM"}]
    crit = min(max(number(stats.get("CritChance")) / 100, 0.0), 1.0)
    for ailment in ONE_SLOT_AILMENTS:
        p = min(1.0, (number(stats.get(f"{ailment}ChanceOnHit")) * (1 - crit)
                      + number(stats.get(f"{ailment}ChanceOnCrit")) * crit) / 100)
        if p <= 0:
            continue
        slots = number(stats.get(f"{ailment}StacksMax")) or 1.0
        # applications per slam against a slam without Aftershocks: P(any hit applies it) / p with one slot, where the
        # extra hits are the single roll (a) and Tremors' one roll (k more at chance c_k)
        miss = (1 - a * p) * (1 - sum(tremors.values()) + sum(c * (1 - p) ** k for k, c in tremors.items()))
        real = (1 - (1 - p) * miss) / p if slots <= 1 else target
        counted = target / damage  # what PoB counts after the DPS correction (the "more Damage" form adds none)
        if abs(real / counted - 1) <= 1e-6:
            continue
        mods.append(raw_mod(f"Enemy{ailment}Duration", "MORE", 100 * (real / counted - 1), main.name))
        slot = f"one {ailment} slot" if slots <= 1 else f"{slots:g} {ailment} slots"
        notes.append({"label": f"{ailment} applications with Aftershocks ({main.name})", "value": f"x{real / counted:.3f}",
                      "basis": f"{p:.0%} chance a hit; the impact and its Aftershock land together, so with {slot} a "
                               f"slam applies it {real:.3f} times as often as without Aftershocks (1 - (1-p)(1-Ap)), "
                               f"where PoB counts {counted:.3f}; set through its duration, so its uptime moves and a "
                               "full-uptime ailment's damage doesn't"
                               + (f"; the ledger's \"more Damage\" form still makes each application x{damage:.2f} "
                                  "bigger (COV-A)" if damage > 1 else ""),
                      "confidence": "MEDIUM"})
    return mods, notes


# Orb of Storms as the main skill (MECHB6; COVC9's finding, FIX_QUEUE "MECHB5's and COVC9's findings") -------------------
# The game (ActiveSkills orb_of_storms, OrbOfStormsPlayer's constant stats, build 26476662; poe2db's gem page): "Fires a
# bolt every 4 seconds, and when you cast a Spell near the Orb" (orb_of_storms_base_bolt_frequency_ms 4000), "Limit 1 Orb
# of Storms" (orb_of_storms_base_maximum_number_of_orbs 1), 12 s duration (base_skill_effect_duration 12000), "Orb expires
# after firing 6 bolts" (orb_of_storms_maximum_number_of_hits 6: HIGH, the game's own text "[Orb] expires after firing
# {0} bolts" in skill_stat_descriptions.csd, patch 0.3.0 and poe2db agree: RESEARCH26 R26-56; COVC9's "no game text"
# was wrong). The cast itself deals no hit; PoB prices each cast as one bolt (no statMap, no module reads the skill:
# COVC9's grep). What a recast does is not in any source: whether casting a new Orb is "a Spell cast near" the old one, and
# whether the old one is gone first (UNVERIFIED either way). With it, each cast fires one bolt from the orb it replaces,
# and the 6-bolt cap never binds (one bolt per orb): PoB's count. Without it, the orb fires on its timer only: 3 bolts
# per 12 s orb (at 4, 8, 12 s; the 12 s one at the edge, so 2-3), plus the recast. The headline keeps PoB's count (no
# zero or cut on an unverified point, CLAUDE.md rule 5) and the note gives the rate without it; the in-game check is
# held for the user. Orb as a side skill: orb_cycle below (MECHB28).
ORB_OF_STORMS = "Orb of Storms"
ORB_BOLT_EVERY, ORB_DURATION, ORB_MAX_BOLTS = 4.0, 12.0, 6


def orb_of_storms_note(main: Skill | None, stats: dict, orb: dict | None = None) -> list[dict]:
    """A labelled note on Orb of Storms as the main skill: PoB's one bolt per cast holds only if recasting fires a bolt.
    `orb`: the main group's bridge `useRates` row (MECHB29: its orbMaxHits, orbBoltFrequency and duration as PoB builds
    them, as orb_cycle reads them); without one, the game files' base 6 bolts, 4 s and 12 s."""
    if main is None or main.name != ORB_OF_STORMS:
        return []
    casts = number(stats.get("Speed"))
    if casts <= 0:
        return []
    hits = number((orb or {}).get("orbMaxHits")) or ORB_MAX_BOLTS
    every = number((orb or {}).get("orbBoltFrequency")) / 1000 or ORB_BOLT_EVERY
    duration = number((orb or {}).get("duration")) or ORB_DURATION
    read = "as PoB builds them, with the build's modifiers" if orb and number(orb.get("orbMaxHits")) > 0 else (
        "the game files' base values: no useRates row read")
    timer_bolts = min(hits, math.floor(duration / every + 1e-9))
    without = timer_bolts / (duration + 1 / casts)
    return [{"label": "Orb of Storms: bolts per second (one per cast, as PoB counts)*",
             "value": f"{casts:.2f}/s (without a bolt on recast: {without:.2f}/s, {without / casts:.0%} of the DPS)",
             "basis": f"the Orb fires a bolt every {every:g} s and when you cast a Spell near it, one Orb at a time, "
                      f"{duration:.3g} s, at most {hits:g} bolts ({read}; game files; poe2db). Kept: each recast fires "
                      "one bolt from the Orb it replaces (UNVERIFIED: no source says whether a recast counts as a Spell "
                      f"cast near the old Orb). Without it, {timer_bolts} timer bolts per {duration:.3g} s Orb plus the "
                      f"recast: {without:.2f} bolts/s. Bolts fed by other spells cast near the Orb aren't counted (an "
                      "undercount when it's a side skill)",
             "confidence": "UNVERIFIED"}]


# Orb of Storms as a side skill (MECHB28; GEM6's point 1, MECHB27's design): the main Spell's casts near the Orb fire its
# bolts. The game (OrbOfStormsPlayer's constant stats, GrantedEffectStatSets 92, build 26476662): a bolt every
# orb_of_storms_base_bolt_frequency_ms 4000 and "when you cast a Spell near the Orb", at most
# orb_of_storms_maximum_number_of_hits 6 a Orb, base_skill_effect_duration 12000, one Orb (base_maximum_number_of_orbs 1).
# None of these varies by gem level (checked: GrantedEffectStatSetsPerLevel holds no orb_of_storms stat for the set);
# quality's second stat (GrantedEffectQualityStats row 17, AltStats) adds 0.3 maximum hits per 1%, which PoB applies only
# with its GemlingQuality flag (CalcSetup 1142, CalcTools 170): the bridge reads the set's stats as PoB builds them
# (useRates' orbMaxHits / orbBoltFrequency). No item, passive or rune line grants any orb_of_storms_* stat (checked: the
# Stat fields of every game table for the 10 orb_of_storms_* stat ids: only ActiveSkills, ModType, the quality row and the
# set; PoB's ModCache names Orb of Storms only in "+3 to Level of all Orb of Storms Skills"; poe2db not checked:
# UNVERIFIED). Patch 0.3.0 (the newest entry naming its bolts; 0.3.0c only its supports): "Now triggers from casting any
# spell in its radius", "a maximum of 6 bolts at all Gem levels", "fires a bolt every 4 seconds, and when you use a
# Lightning Skill near the Orb" (the same note says both; the game text says any Spell, kept).
# PoB (COVC9's grep; MECHB28's probe POE2T1138): its "Orb of Storms" entry is one bolt per cast at the Orb's own Speed, and
# press_model counted one cast per Orb life, so one bolt per 12 s: the timer bolts and the near-cast bolts uncounted (an
# UNDERCOUNT). orb_cycle replaces that count (press_model's ratio for the Orb is its bolts / s over PoB's Speed, never
# added to it). A play strategy: the player keeps the Orb where they cast and casts the main Spell near it.
# Assumptions, labelled: every main-Spell cast is near the Orb (what "near" is, the Orb's radius around the caster or the
# spell's target, is not in the game text: UNVERIFIED); only a Spell the player casts counts: a triggered main Spell and a
# channelled one get timer bolts only (whether a triggered spell is "cast", and how a channelled one feeds the
# channelling bolt frequency stats, which the player set doesn't hold: UNVERIFIED, left uncounted, said in the note);
# the other pressed Spells the player casts (not triggered, not channelled) are cast near it too, at their press rates
# (MECHB29; the same 'near' assumption). The main skill's casts while an Orb is up are its
# Speed x (1 - the other presses' share): the Orb's own recast is between lives. An Orb fires its timer bolts at 4, 8 and
# 12 s (floor(duration / frequency): the one at 12 s at the edge counted, UNVERIFIED), and the casts' bolts on top;
# when the two reach the maximum before the duration ends, the Orb expires at max hits / (casts/s + 1/frequency) (bolts
# taken as spread evenly, MEDIUM) and is recast at once; each cycle is its life plus one cast of the Orb.
# (MECHB44, the user's in-game test, 20 Nov ~04:15: "orb of storms only fires a bolt when you yourself are standing in its
# radius") A cast fires a bolt only while the player stands in the Orb's radius, so the near casts count at the share of
# the fight the player stands there while the Orb can still bolt the boss (the user's 9 Nov conditional rule: a
# positioning the build leans into, in the headline, with the "without it" row: timer bolts only). From the build:
# - the Orb (OrbOfStormsPlayer, 26650308): active_skill_base_area_of_effect_radius 56 (5.6 m, the bolts' reach: "fires
#   Chaining Lightning bolts at nearby enemies") and active_skill_base_secondary_area_of_effect_radius 36 (3.6 m). Which
#   radius the player must stand in isn't in the game text: the smaller 3.6 m taken (UNVERIFIED; the 5.6 m reading a row);
# - the boss within the bolts' reach of the Orb and the player within the standing radius: the build's own distance to
#   the boss (PoB's enemyDistance, else conditions.natural_distance) must be at most 5.6 + 3.6 m, else 0;
# - the boss moving out of reach in its own dashes / leaps: bosses.moving_ceiling's share (an upper bound, LOW) is
#   taken out (a lower reading: a dash may stay in reach);
# - the player's dodge rolls (dodge_roll, every DODGE_EVERY s): a roll of d metres stays inside a circle of radius R when
#   d <= 2 R (rolled across it); a longer one leaves it for the roll and the way back (2 x the roll's time, MEDIUM-LOW).
# Triggered / channelled spells still don't fire it (UNVERIFIED, unchanged).
ORB_REACH, ORB_STAND = 5.6, 3.6  # m (radius 56 and secondary radius 36, OrbOfStormsPlayer, game 26650308)


def orb_stand_share(roll: dict, distance: float, moving: tuple[float, str], stand: float = ORB_STAND
                    ) -> tuple[float, str]:
    """(share of the fight the player casts standing in the Orb's radius while it can bolt the boss, how)."""
    if distance > ORB_REACH + stand:
        return 0.0, (f"the build fights {distance:g} m from the boss, beyond the Orb's {ORB_REACH:g} m bolt reach plus "
                     f"its {stand:g} m radius: it can't stand in its Orb with the boss in reach (0)")
    d, seconds = number(roll.get("metres")), number(roll.get("seconds")) or DODGE_ROLL_SECONDS
    out = 0.0 if d <= 2 * stand else min(1.0, 2 * seconds / DODGE_EVERY)
    share = max(0.0, (1 - out) * (1 - number(moving[0])))
    rolled = (f"its {d:.2f} m dodge roll fits inside the {2 * stand:g} m circle (rolled across it)" if out == 0 else
              f"its {d:.2f} m dodge roll leaves the {2 * stand:g} m circle: out {2 * seconds:g} s of every "
              f"{DODGE_EVERY:g} s (the roll and the way back, MEDIUM-LOW)")
    return share, (f"stands in the Orb's {stand:g} m radius {share:.0%} of the fight (the user's in-game test: a cast fires "
                   f"a bolt only while you stand in it; which radius: UNVERIFIED, the smaller taken): it fights "
                   f"{distance:g} m from the boss, within the Orb's {ORB_REACH:g} m reach plus its radius; {rolled}; "
                   f"the boss out of reach while it moves ({moving[1]})")


def orb_cycle(orb: dict, main: dict | None, others: float, pace: float | None = None,
              cap: "PressCap | None" = None, spells: dict[str, float] | None = None,
              near: bool = True) -> tuple[float, float, dict]:
    """A pressed side Orb of Storms' (presses/s, bolts/s, note), from its `useRates` row (orbMaxHits, orbBoltFrequency,
    duration, speed), the main skill's row (its Speed, spell / triggered / channel) and `others`, the share of the
    fight the other presses take from the main skill. Held to Cadence's `pace` and the `cap` as press_group_rate is.
    `spells` (MECHB29): {name: presses/s} of the other pressed Spells the player casts, near the Orb too."""
    hits = number(orb.get("orbMaxHits"))
    every = number(orb.get("orbBoltFrequency")) / 1000 or ORB_BOLT_EVERY
    duration = number(orb.get("duration")) or ORB_DURATION
    action = press_action(orb)
    # (MECHB44) `near`: True / False (the play-guide switch), or (share, how) from orb_stand_share
    stand, stand_how = (near if isinstance(near, tuple) else (1.0 if near else 0.0, ""))
    near = stand > 0
    casting = near and bool(main) and main.get("spell") and not main.get("triggered") and not main.get("channel")
    own = number(main.get("speed")) * max(0.0, 1.0 - others) * stand if casting else 0.0
    beside = sum(number(v) for v in (spells or {}).values()) * stand if near else 0.0  # (MECHB30: ORB_NEAR off: none)
    casts = own + beside
    timer = math.floor(duration / every + 1e-9)

    def cycle(rate: float) -> tuple[float, float, float]:  # (life, bolts an Orb, presses/s)
        if rate * duration + timer <= hits:
            life, bolts = duration, rate * duration + timer
        else:
            life, bolts = min(duration, hits / (rate + 1 / every)), hits
        return life, bolts, 1 / (life + action)

    life, per, presses = cycle(casts)
    _, alone, alone_presses = cycle(0.0)
    held = ""
    for limit, why in ((pace, f"Cadence's {pace} uses/s"), (cap.uses if cap is not None else None,
                                                            cap.how if cap is not None else "")):
        if limit is not None:
            if presses > limit:
                presses, held = limit, f", held to {limit:.3g} presses/s by {why}"
            alone_presses = min(alone_presses, limit)
    bolts, without = presses * per, alone_presses * alone
    name = main.get("name") if main else None
    besides = (f" and the other pressed Spells' {beside:.2f} casts/s ("
               + ", ".join(f"{k} {number(v):.2f}" for k, v in (spells or {}).items() if number(v) > 0) + ")"
               if beside > 0 else "")
    if casting:
        how = (f"{name}'s {own:.2f} casts/s{besides} near the Orb (a play strategy: stand in your Orb's radius*"
               + (f"; it {stand_how}" if stand_how else "") + f") plus {timer} timer bolts: {per:.2g} bolts an Orb, "
               f"which lasts {life:.2f} s")
    else:
        why = (("not cast standing in the Orb: it " + stand_how) if stand_how and not near else
               "not cast near the Orb (the play-guide switch is off: ORB_NEAR)" if not near else
               "a triggered Spell (whether it counts as cast near the Orb: UNVERIFIED, not counted)" if main and
               main.get("triggered") else "a channelled Spell (how it feeds the Orb: UNVERIFIED, not counted)" if main
               and main.get("channel") else "not a Spell (only casting a Spell fires a bolt)")
        lead = besides[len(" and "):] + " near the Orb plus " if beside > 0 else "timer bolts only: "
        how = f"{lead}{timer} timer bolts an Orb in its {duration:.2f} s; the main skill {name or '(none)'} is {why}"
    note = {"label": "Orb of Storms: bolts per second beside the main skill*",
            "value": f"{bolts:.2f}/s ({presses:.3f} Orbs/s); without casting near it {without:.2f}/s",
            "basis": (f"{how}{held}; at most {hits:g} bolts an Orb (game files, quality as PoB builds it), a bolt every "
                      f"{every:g} s and when you cast a Spell near it, {duration:.2f} s, recast at once ({action:.2f} s "
                      "each). Replaces PoB's one bolt per Orb cast. The casts of the main Spell and of the other "
                      "pressed Spells fire bolts only while you stand in the Orb's radius (the user's in-game test, 20 "
                      "Nov), counted at that share; a triggered or channelled side Spell isn't counted (UNVERIFIED "
                      "whether it feeds the Orb). "
                      f"Without it / with it: {without:.2f} / {bolts:.2f} bolts a second"),
            "confidence": "MEDIUM" if casting or beside > 0 else "UNVERIFIED" if main and (
                main.get("triggered") or main.get("channel")) else "MEDIUM"}
    return presses, bolts, note



# A side Orb of Storms' bolts as its hits for the other groups' hit readers (MECHB58; the manager 03:20 23 Nov from
# MECH102, an UNDERCOUNT, LOW-MEDIUM): conditions' side readers (ignite_others, shock_others, buildup_others,
# break_others, overcharge_sources, Galvanic Field's Shock feed) take a group's hits a second as its uses (PoB's trigger
# rate, else skill_use_rate: an Orb's duration, one cast per Orb life), so a side Orb read one bolt per Orb (~1 per 12 s)
# and its Shocks / Ignites / buildup stayed under every cut-off. Its hits are its bolts: the side-Orb cycle press_model
# scores (side_orbs / orb_cycle: the timer bolts plus the casts near it, to its maximum hits), published per group by
# Assumptions.rate_presses as build.orb_bolt_groups and read a round behind (MEDIUM, as MECHC44's build.orb_bolts). PoB's
# useRates row for the Orb is one bolt per cast (COVC9's grep; MECHB28), so its ShockChancePerHit, buildup and hit
# chance are a bolt's. The row's rate becomes the bolts a second, flagged as a set rate as Crackling Palm's is; its
# PoisonDPS (PoB's at its own Speed: one bolt a cast) is cut to the bolts' rate where that is lower. The charge readers
# (side_hit_rows) skip an Orb by name and count its bolts in _side_orb_gains already: unchanged. No cycle read yet
# (the first round, or no pressed side Orb): the row stays as it was.
def side_orb_hits(rows: dict, bolt_groups: dict | None, main_index=None) -> list[str]:
    """Set each side Orb of Storms row's rate in `rows` ({group index: useRates row}) to its bolts a second from
    `bolt_groups` ({group index: bolts/s}, Assumptions' build.orb_bolt_groups); [how] per row changed (see above)."""
    said = []
    for index, row in rows.items():
        if index == main_index or not str(row.get("name") or "").startswith(ORB_OF_STORMS):
            continue
        bolts = number((bolt_groups or {}).get(index))
        if bolts <= 0:
            continue
        own = number(row.get("speed"))
        if own > 0 and bolts < own and number(row.get("PoisonDPS")) > 0:
            row["PoisonDPS"] = number(row.get("PoisonDPS")) * bolts / own
        row["speed"], row["triggered"] = bolts, True
        row["how"] = (f"{ORB_OF_STORMS}'s {bolts:.2f} bolts a second, each a hit (MECH-B's side-Orb cycle, "
                      "models.side_orbs: its timer bolts plus the Spells cast near it; a round behind, MEDIUM)")
        said.append(row["how"])
    return said

# Danse Macabre's second skeleton (MECHB6; RESEARCH22 #133, research/danse-macabre-skeleton-use.md) -------------------------
# The gem (GemEffects DanseMacabreSupport, PoB's copy of it): Supported Offerings "will target an additional skeletal Minion
# when cast. If there is not an additional skeletal Minion to target, no damage or Buff effect will be granted"
# (skill_offering_targets_an_additional_skeleton; its 30% more damage and 30% increased Buff effect). Offerings use up the
# skeleton they target (KeywordPopups Offering; "Impale / Skewer a Skeleton on a bone spike"): with Danse Macabre each cast
# uses 2 (MEDIUM-HIGH). PoB applies the bonus with no check. The build's skeletons: its Persistent "Skelet..." minion
# skills' limits (other skeleton sources aren't counted: an undercount). They revive T s after the last one is used
# (revive_seconds; KeywordPopups Reviving: the delay resets on each death), so with N skeletons an Offering kept up every
# D s (its base spike duration, game files: Bone 8 s, Pain 6 s, Soul 6 s; duration modifiers not read, an undercount)
# casts k = N // 2 times per wave, then waits for the revive: up k D of every max(k D, (k - 1) D + T) s. That share of the
# Offering's damage and Buff effect counts (as less of both, MECHB6's play: cast it only when 2 skeletons are there);
# with fewer than 2 skeletons, none. The base Offering's own single skeleton isn't checked here (PoB's, unchanged).
OFFERING_SECONDS = {"Bone Offering": 8.0, "Pain Offering": 6.0, "Soul Offering": 6.0}
DANSE_MACABRE = "Danse Macabre"


def danse_share(every: float, skeletons: list[Skill], count: int, revive: float, how: str) -> tuple[float, str]:
    """(share of the fight a Danse Macabre Offering kept up every `every` s finds its 2 skeletons, why; see above)."""
    casts = count // 2
    if casts <= 0:
        return 0.0, (f"the build has {count} skeleton{'s' if count != 1 else ''}: each cast needs 2, so no cast gets "
                     "damage or Buff effect")
    cycle = max(casts * every, (casts - 1) * every + revive)
    return casts * every / cycle, (
        f"{count} skeletons ({', '.join(s.name for s in skeletons)}): {casts} cast{'s' if casts > 1 else ''} of 2 each, "
        f"one every {every:g} s (its base spike duration), then they revive {revive:.3g} s after the last ({how}): up "
        f"{casts * every:g} s of every {cycle:.3g} s")


def danse_macabre_model(skills: list[Skill], supports: dict[int, list[str]] | None) -> tuple[list[dict], list[dict]]:
    """Danse Macabre's Offerings count only the share of the fight the build's skeletons let them keep up (see above)."""
    offerings = [s for s in skills if s.name in OFFERING_SECONDS and s.group is not None
                 and DANSE_MACABRE in (supports or {}).get(s.group, [])]
    if not offerings:
        return [], []
    skeletons = [s for s in skills if s.summon and s.summon.get("persistent") and "Skelet" in s.name
                 and not number(s.summon.get("duration"))]
    count = int(sum(number(s.summon.get("limit")) for s in skeletons))
    revive, how = revive_seconds(skeletons) if skeletons else (RESUMMON_SECONDS, "no skeletons")
    mods, notes = [], []
    for offering in offerings:
        share, why = danse_share(OFFERING_SECONDS[offering.name], skeletons, count, revive, how)
        if share < 1:
            mods += [raw_mod("Damage", "MORE", -100 * (1 - share), skill=offering.name),
                     raw_mod("BuffEffect", "MORE", -100 * (1 - share), skill=offering.name)]
        notes.append({"label": f"{offering.name} with Danse Macabre: share of the fight it gives damage and Buff effect*",
                      "value": f"{share:.0%}",
                      "basis": f"each cast uses 2 skeletons, and without the second it gives no damage or Buff effect (the "
                               f"gem's text; PoB applies it without checking); {why}. Counted as less damage and Buff "
                               "effect on the Offering (MEDIUM-HIGH that each cast uses 2; skeletons from other sources "
                               "and duration modifiers not counted). Without Danse Macabre: one skeleton per cast, no 30%",
                      "confidence": "MEDIUM"})
    return mods, notes


# Offering spikes and the boss's hits (MECHB35; RESEARCH26 R26-38, offering-spike-life-r26.md, ASSUMED, LOW). An
# Offering's spike is itself a Minion and "If it dies, the effect ends immediately" (ActiveSkills pain_offering /
# soul_offering; Bone Offering's shields "disappear"); KeywordPopups Offering: "their Buffs are lost if they die". PoB
# keeps the buff up for the whole duration. No source gives a rate at which pinnacle hits kill a spike (bosses are
# reported to aim at the player: forum 3621704, 3596529, player reports, LOW-MEDIUM), so no rate is invented (the user's
# no-flat-rate rule): the uptime stays PoB's and the note labels it by placement. Pain Offering buffs Minions within its
# 6 m area (PainOfferingPlayer radius 60): melee minions at the boss put the spike inside the boss's areas, where early
# deaths are likely and not counted (an OVERCOUNT of unknown size); with ranged minions it can stand away. Soul Offering
# buffs you, Bone Offering shields minions from the spike's place: both can stand away from the boss (a play row).
OFFERING_PLACEMENT = {
    "Pain Offering": ("it buffs Minions within 6 m of the spike: next to melee minions at the boss it stands in the boss's "
                      "areas, where its early deaths aren't counted (an OVERCOUNT of unknown size, UNVERIFIED); with "
                      "ranged minions it can stand away from the boss"),
    "Soul Offering": "it buffs you, not your minions: the spike can stand away from the boss, out of the boss's areas",
    "Bone Offering": "its shields last while the spike stands: it can stand away from the boss, out of the boss's areas",
}


def offering_placement_notes(skills: list[Skill]) -> list[dict]:
    """A labelled note per Offering in the build: its spike's uptime is PoB's (no death rate known), by placement."""
    notes = []
    for name in dict.fromkeys(s.name for s in skills if s.name in OFFERING_PLACEMENT and s.group is not None):
        notes.append({"label": f"{name}: the spike's uptime against the boss*", "value": "PoB's (the whole duration)",
                      "basis": f"the spike is a Minion and the buff ends if it dies (game text); {OFFERING_PLACEMENT[name]}. "
                               "No source gives how often boss hits kill a spike, so none is counted (RESEARCH26 R26-38, "
                               "ASSUMED)",
                      "play": (f"Place {name}'s spike on a skeleton away from the boss's attacks: the counted uptime "
                               "assumes it survives its duration; a spike killed early loses its buff (not counted)"),
                      "confidence": "LOW"})
    return notes


# Lust for Sacrifice (MECHB39; the coverage ranking's section B, an UNDERCOUNT: 0 before). The notable's "50% increased
# Minion Damage while you have at least two different active Offerings" (PassiveSkills corpses17, stat
# minion_damage_+%_while_you_have_at_least_two_different_active_offerings): PoB's ModCache 4596 reads it as a MinionModifier
# with leftover text ("   while you have at least two different active Offerings "), and PoB never applies a line parsed
# only in part. (checked: game files 26650308, every Stats id holding "offering", their Mods, PassiveSkills and
# GrantedEffectStatSets rows: Lust for Sacrifice is the one source of this stat; the player-damage twin
# damage_+%_while_you_have_at_least_two_different_active_offerings has no source in those tables.) Counted when the build
# has two or more different Offering skills (Bone / Pain / Soul Offering, OFFERING_SECONDS) and at least two Persistent
# Skeletons for them to skewer (each Offering targets a Skeleton); then both are taken as up as PoB takes each Offering
# (its whole duration, recast as it ends: a play strategy under the button cap), times each one's Danse Macabre share
# when that support needs 2 Skeletons a cast (danse_share; both shares multiplied, as independent: MEDIUM-LOW). Not
# counted: the boss killing a spike early (offering_placement_notes, LOW), two Offerings and Danse Macabre sharing the
# same Skeletons beyond each one's own share (a possible small overcount, said), Unwilling Offering's cullable-enemy
# targets (UNVERIFIED on a boss), Blood Offering (a unique's granted skill, DisplayGrantsBloodOfferingUnique__1_) as one of
# the two (whether it is an Offering here is UNVERIFIED: an undercount if it is).
LUST_FOR_SACRIFICE = re.compile(
    r"^(\d+(?:\.\d+)?)% increased Minion Damage while you have at least two different active Offerings$", re.I)


def lust_for_sacrifice_model(texts: list[str], skills: list[Skill], supports: dict[int, list[str]] | None
                             ) -> tuple[list[dict], list[dict]]:
    """Lust for Sacrifice's Minion Damage at the share of the fight two different Offerings are up (see above)."""
    pct = sum(float(m.group(1)) for t in texts if (m := LUST_FOR_SACRIFICE.search(t.strip())))
    if pct <= 0:
        return [], []
    offerings = {s.name: s for s in skills if s.name in OFFERING_SECONDS and s.group is not None}
    skeletons = [s for s in skills if s.summon and s.summon.get("persistent") and is_skeleton(s)
                 and not number(s.summon.get("duration"))]
    count = int(sum(number(s.summon.get("limit")) for s in skeletons))
    share, parts = 0.0, []
    if len(offerings) < 2:
        why = (f"the build has {len(offerings)} Offering skill{'s' if len(offerings) != 1 else ''} "
               f"({', '.join(offerings) or 'none'}): two different ones are needed")
    elif count < 2:
        why = (f"two Offerings ({', '.join(offerings)}) but {count} Persistent Skeleton{'s' if count != 1 else ''} to "
               "skewer: each Offering needs one, so both are never up together")
    else:
        revive, how = revive_seconds(skeletons)
        share = 1.0
        for name, s in offerings.items():
            if DANSE_MACABRE in (supports or {}).get(s.group, []):
                own, own_why = danse_share(OFFERING_SECONDS[name], skeletons, count, revive, how)
                share *= own
                parts.append(f"{name} with Danse Macabre up {own:.0%} ({own_why})")
        why = (f"{', '.join(offerings)} kept up as PoB keeps each (recast as it ends), {count} Persistent Skeletons to "
               "skewer" + (f"; {'; '.join(parts)} (taken as independent, MEDIUM-LOW)" if parts else ""))
    gain = pct * share
    note = {"label": "Lust for Sacrifice: Minion Damage with two different Offerings up*", "value": f"+{gain:.0f}%",
            "confidence": "MEDIUM" if share in (0.0, 1.0) else "MEDIUM-LOW",
            "basis": (f"{pct:g}% increased Minion Damage while two different Offerings are active, up {share:.0%} of the "
                      f"fight: {why}. PoB reads the line with leftover text and never applies it (0 before). Not "
                      "counted: the boss killing a spike early (LOW), Offerings sharing Skeletons beyond each one's own "
                      "share (a possible small overcount), Blood Offering as one of the two (UNVERIFIED)"),
            "play": (f"Keep two different Offerings up: without them +0%; with them +{gain:.0f}% Minion Damage"
                     if gain > 0 else "Lust for Sacrifice needs two different Offerings up and Skeletons to skewer: +0%")}
    return ([line("Minions deal 1% increased Damage", gain)] if gain > 0 else []), [note]


# Frost Darts over one cast (MECHB35; MECHB33's finding, plans/term-explode.md D). ActiveSkills frost_darts: "Conjures a
# number of icy Projectiles that launch towards the target. Projectiles that Hit a Chilled or Frozen target create chunks
# of ice that deal additional damage on impacting the ground. Consumes a Cold Infusion if possible to cause each
# Projectile to lodge into the enemy then explode" (unchanged since 0.3.0; 0.4.0c only let Spell Totem take it). PoB
# (act_int.lua FrostDartsPlayer) has three stat sets and scores one: "Projectile" (base_number_of_projectiles 3),
# "Explosion" (radius 1.8 m, frost_darts_explode_creates_X_mortars 3: "Each explosion creates 3 Ice Chunks") and "Ice
# Chunk" (2 a hit, base_number_of_projectiles 2, number_of_projectiles_cannot_be_modified, random_projectile_direction,
# landing skill_mortar_minimum / maximum_projectile_distance 0.5-1.7 m from the hit, radius 0.8 m). The search keeps the
# best set, so PoB scores e.g. the Explosion on every cast whatever the Infusions (an OVERCOUNT when they don't cover every
# cast), or the darts alone (an UNDERCOUNT of the chunks and explosions). Here one cast is:
#   h x (Projectile + chilled x 2 x q x Chunk + infused x (Explosion + 3 x q x Chunk)),
# each set's per-cast damage PoB's (setRates TotalDPS / Speed: one dart, one explosion, one chunk), against the scored
# set's, as DPS "more" on the main skill.
# - h, darts on the boss a cast: ALL of them (max(PoB's ProjectileCount, the base 3); MECHB44: the user's in-game test,
#   20 Nov ~04:15, "all darts from frost darts can hit a single target": HIGH). R29-1's one dart (KeywordPopups 74's
#   group rule) is dropped: that rule caps projectiles fired "from the same source at the same time" (the manager, 04:30,
#   R35-15), and the darts leave in sequence. PoB scores one dart a cast, so the whole cast is h x the per-dart sum.
# - chilled: the boss Chilled or Frozen. Frost Darts never Chills (never_freeze_or_chill), so from the build's Chilled
#   Ground (MECH-A's chilled_ground_up) and its Freeze uptime, taken as independent; other skills' Chills not counted (an
#   undercount, labelled). No source: 0.
# - infused: the share of casts that find a Cold Infusion (Assumptions.infusion_share, MECH-C's supply over the casts).
# - q: a chunk lands on the boss when it falls within 0.8 m + the boss's radius (bosses.hit_radius) of its centre; it
#   lands 0.5-1.7 m from the hit (uniform in distance, any direction, UNVERIFIED), the hit taken at the boss's edge
#   (projectile_uses_contact_position) and the explosion's chunks from the same point: 48% on the 0.3 m default boss.
# - an Infused dart still deals its own hit, then explodes (its text: "lodge into the enemy then explode": MEDIUM-LOW).
# LOW overall (the chunk spread's distribution, the darts' count on one target).
FROST_DARTS = "Frost Darts"
FROST_SETS = ("Projectile", "Explosion", "Ice Chunk")
FROST_BASE_DARTS = 3.0  # the Projectile set's base_number_of_projectiles (the all-darts row; PoB's count if higher)
FROST_CHUNKS_A_HIT, FROST_CHUNKS_AN_EXPLOSION = 2, 3
FROST_CHUNK_RADIUS, FROST_CHUNK_NEAR, FROST_CHUNK_FAR = 0.8, 0.5, 1.7  # metres: radius 8, mortar distance 5-17 units
FROST_ENTRY = "model-mechb35-frost-darts-cast"


def frost_chunk_chance(radius: float, steps: int = 90, area: bool = False) -> float:
    """The chance an Ice Chunk lands on a boss of `radius` metres (see above), by a grid over distance and direction;
    `area`: landing spots uniform over the ring's area instead of its distance (RESEARCH28 R28-8's other reading)."""
    reach = FROST_CHUNK_RADIUS + radius
    hit = 0
    for i in range(steps):
        u = (i + 0.5) / steps
        d = (math.sqrt(FROST_CHUNK_NEAR ** 2 + u * (FROST_CHUNK_FAR ** 2 - FROST_CHUNK_NEAR ** 2)) if area
             else FROST_CHUNK_NEAR + (FROST_CHUNK_FAR - FROST_CHUNK_NEAR) * u)
        for j in range(2 * steps):
            a = math.pi * (j + 0.5) / steps
            x, y = radius + d * math.cos(a), d * math.sin(a)
            hit += x * x + y * y <= reach * reach
    return hit / (2 * steps * steps)


def frost_darts_model(main: str | None, scored: str | None, sets: list[dict], projectiles: float, chilled: float,
                      chill_how: str, infused: float, infused_how: str, radius: float,
                      forbidden: set[str] = frozenset()) -> tuple[list[dict], list[dict]]:
    """Frost Darts' whole cast (see above) against the one stat set PoB scores."""
    if main != FROST_DARTS or FROST_ENTRY in forbidden:
        return [], []
    per = {s.get("label"): (number(s.get("TotalDPS")) / number(s.get("Speed")) if number(s.get("Speed")) > 0 else 0.0)
           for s in sets}
    if scored not in per or per[scored] <= 0 or per.get("Projectile", 0) <= 0:
        return [], [{"label": "Frost Darts: its whole cast", "value": "not counted", "confidence": "theory",
                     "entry": FROST_ENTRY, "basis": "PoB gave its scored set or its Projectile set no damage: PoB's kept"}]
    dart, blast, chunk = (per.get(label, 0.0) for label in FROST_SETS)
    chilled, infused = min(max(chilled, 0.0), 1.0), min(max(infused, 0.0), 1.0)
    q, q_area = frost_chunk_chance(radius), frost_chunk_chance(radius, area=True)
    each = (dart + chilled * FROST_CHUNKS_A_HIT * q * chunk
            + infused * (blast + FROST_CHUNKS_AN_EXPLOSION * q * chunk))
    each_area = (dart + chilled * FROST_CHUNKS_A_HIT * q_area * chunk
                 + infused * (blast + FROST_CHUNKS_AN_EXPLOSION * q_area * chunk))
    every = max(projectiles, FROST_BASE_DARTS)  # (PoB's count on the Explosion set reads 1.2: probe POE2T3261)
    factor = every * each / per[scored]  # (MECHB44: all darts, the user's test)
    note = {"label": "Frost Darts: darts, Ice Chunks and Infused explosions over one cast*", "value": f"x{factor:.3f}",
            "entry": FROST_ENTRY, "confidence": "LOW",
            # (GEM23: strongest_ailment_model; each set's uses a cast, at PoB's casts a second)
            "set_shares": {"Projectile": every, "Explosion": infused * every,
                           "Ice Chunk": (chilled * FROST_CHUNKS_A_HIT + infused * FROST_CHUNKS_AN_EXPLOSION) * q * every},
            "basis": (f"all {every:g} darts on the boss a cast ({dart:,.0f} each; the user's in-game test, 20 Nov: \"all "
                      "darts from frost darts can hit a single target\", HIGH); per dart, Ice Chunks "
                      f"{FROST_CHUNKS_A_HIT} a hit on a Chilled or "
                      f"Frozen boss, {chilled:.0%} of the fight ({chill_how}); a Cold Infusion on {infused:.0%} of casts "
                      f"({infused_how}): its explosion ({blast:,.0f}) and {FROST_CHUNKS_AN_EXPLOSION} more chunks; each "
                      f"chunk ({chunk:,.0f}) lands on the boss {q:.0%} of the time (a {radius:g} m boss; 0.5-1.7 m from "
                      f"the hit, 0.8 m radius): {each:,.0f} a dart, {every * each:,.0f} a cast against PoB's {scored} "
                      f"set alone ({per[scored]:,.0f}). Row: chunks spread evenly over the ring's area, {q_area:.0%} land: "
                      f"x{every * each_area / per[scored]:.3f} (R28-8). Other skills' Chills not counted"),
            "play": (f"Frost Darts' chunks need a Chilled boss (Chilled Ground, or another skill that Chills) and its "
                     f"explosions a Cold Infusion: as built x{factor:.3f}; without either, the darts alone "
                     f"x{every * dart / per[scored]:.3f}.")}
    return [raw_mod("DPS", "MORE", 100 * (factor - 1), main)], [note]


# Coursing Current against a lone boss (MECHB6; RESEARCH22 #129, research/coursing-current-lone-boss.md) ---------------------
# "Sends a Chaining Lightning Projectile from the Shocked enemy towards a nearby Drenched enemy" with
# cannot_chain_to_previous_targets and projectile_only_collide_with_wet_targets (GrantedEffectStatSets, game files): alone,
# the Shocked boss is its previous target, so it has none (MEDIUM; poe2db has no single-target note). PoB scores it 0 too:
# its player trigger calculation is commented out (CalcPerform.lua 3434) and a 0 s cast with no trigger rate gets Speed 0
# (CalcOffence.lua 2708), and no model of ours gives it a rate (checked: grep of builder for Coursing Current, 12 Nov). The
# note says why it stays 0; against adds it would hit.
COURSING_CURRENT = "Coursing Current"


def coursing_current_note(skills: list[Skill]) -> list[dict]:
    if not any(s.name == COURSING_CURRENT for s in skills):
        return []
    return [{"label": "Coursing Current: hits on a lone boss", "value": 0,
             "basis": "its projectile starts from the Shocked enemy and can't chain to previous targets (its stat set, game "
                      "files): with no second Drenched enemy it has no target. PoB scores it 0 as well (its player trigger "
                      "calculation is off). It would hit adds (not counted). In-game test held for the user",
             "confidence": "MEDIUM"}]


# Apocalypse's disasters (MECHB7; plans/kw-unleash.md item 1, RESEARCH20 #114, RESEARCH #103). ApocalypsePlayer (PoB
# Data/Skills/other.lua 895; game files): "When you have maximum Glory, you may become the walking Apocalypse for a
# duration, Triggering one of multiple powerful Elemental Skills at an interval while this Buff lasts":
# unleash_the_elements_base_trigger_frequency_ms 750, unleash_the_elements_trigger_frequency_+% (0.75 per quality),
# 12 s buff, 100 Glory a use (GLORY_SKILLS). The gem grants three hidden sub-skills, castTime 0, InbuiltTrigger:
# Hailstorm (cold, unleash_blizzard_number_of_bolts 9), Meteor (fire, one impact after 2 s) and Crash Lightning
# (lightning: 3 pulses, set 1, then a "Final Strike", set 2, after 3 s). PoB gives all three Speed 0 (its player trigger
# calculation is switched off, CalcPerform.lua 3514-3515; CalcOffence 2848): 0 DPS, a pure undercount (RESEARCH20 #114,
# HIGH from the code). The model:
#   - the buff's share of the fight U = min(1, Apocalypse's uses per second (glory_uses, from the build's own elemental
#     hits: no flat rate) x 12 s); increased skill duration isn't read (an undercount, labelled);
#   - triggers per second while it's up = (1 + frequency %) / 0.75 s (HIGH: game files);
#   - each disaster a third of them (RESEARCH #103: no rule anywhere says which fires; 1/3 holds for random or a cycle,
#     MEDIUM; in-game test #109);
#   - hits on the boss per trigger: Meteor 1; Hailstorm 9 bolts, all on the boss (LOW: each bolt lands at a random spot
#     in the 2 m area, a 0.8 m blast; "Targets an area or an enemy", where they land is UNVERIFIED #109), counted as 9
#     hits; Crash Lightning 1 of whichever set PoB calculates (an undercount: the pulses' other 2 and the other set aren't
#     counted, since one rate covers both sets and the gem search switches between them).
# Each sub-skill gets that rate as its trigger rate, so PoB's own average hit x the rate is its DPS (Full DPS sums them;
# a sub-skill picked as the main skill counts alone).
# (MECHB67; GEM44 via the manager 20:06: an UNDERCOUNT) Crash Lightning now counts its whole trigger: 3 pulses of its
# first set (unleash_static_field_number_of_pluses 3, "a rapid buildup of pulsing Lightning damage in an area that
# culminates in a powerful final Lightning strike": ApocalypseLightningPlayer, PoB other.lua 1270 / the game's text) and
# 1 hit of its "Final Strike" set (unleash_static_field_time_till_final_strike_ms 3000; base effectiveness 3 against the
# pulses' 1.05), both PoB's own average hits (bridge setRates on its group). One trigger rate covers both sets, so the
# hits a trigger are written in the calculated set's units: pulses calculated, 3 + Final / pulse; Final Strike
# calculated, 1 + 3 pulse / Final. All of them on the boss: it targets the boss and its 1.6 m area stays where it was
# cast (MEDIUM: a boss that leaves the area in the 3 s before the Final Strike loses it, a row). Sets unread: 1 (as before).
APOCALYPSE = "Apocalypse"
APOCALYPSE_SUBS = {"Hailstorm": 9, "Meteor": 1, "Crash Lightning": 1}  # hits on the boss per trigger
APOCALYPSE_DURATION = 12.0
APOCALYPSE_INTERVAL = 0.75
APOCALYPSE_FREQUENCY = "unleash_the_elements_trigger_frequency_+%"
CRASH_PULSES, CRASH_FINAL = 3.0, "Final Strike"  # (unleash_static_field_number_of_pluses; the second set's label)


def crash_lightning_hits(pulse: float, final: float, chosen: str) -> tuple[float, float, str]:
    """(hits a Crash Lightning trigger in the calculated set's units, the same without the Final Strike (the row), the
    words) from PoB's two sets' average hits (see above); (1, 1, "") when either is unread."""
    if pulse <= 0 or final <= 0:
        return 1.0, 1.0, ""
    if chosen == CRASH_FINAL:
        hits, row = 1 + CRASH_PULSES * pulse / final, CRASH_PULSES * pulse / final
    else:
        hits, row = CRASH_PULSES + final / pulse, CRASH_PULSES
    return hits, row, (f"Crash Lightning: {CRASH_PULSES:g} pulses of {pulse:,.0f} and a Final Strike of {final:,.0f} a "
                       f"trigger (PoB's two sets; {chosen or 'the pulses'} calculated: {hits:.2f} of its hits a trigger; "
                       f"the boss out of the area before the Final Strike, a row: {row:.2f})")


def apocalypse_model(uses: float, basis: str, frequency: float = 0.0,
                     present: set[str] | frozenset[str] = frozenset(APOCALYPSE_SUBS),
                     crash: tuple[float, float, str] | None = None) -> tuple[list[dict], list[dict]]:
    """Trigger rates for Apocalypse's sub-skills from its uses per second (`uses`, glory_uses; `basis` says how) and its
    trigger frequency increase in % (quality). `crash`: crash_lightning_hits' input (MECHB67)."""
    share = min(1.0, max(uses, 0.0) * APOCALYPSE_DURATION)
    per_second = (1 + frequency / 100) / APOCALYPSE_INTERVAL
    each = share * per_second / len(APOCALYPSE_SUBS)
    mods: list[dict] = []
    crash_hits, _, crash_words = crash_lightning_hits(*(crash or (0.0, 0.0, "")))
    for name, hits in APOCALYPSE_SUBS.items():
        if name in present:
            mods += trigger_rate(name, each * (crash_hits if name == "Crash Lightning" else hits))
    notes = [{"label": "Apocalypse's disasters per second", "value": round(share * per_second, 3),
              "basis": (f"the buff is up {share:.0%} of the fight ({uses:.3f} uses/s x {APOCALYPSE_DURATION:g} s; {basis}); "
                        f"one disaster every {APOCALYPSE_INTERVAL / (1 + frequency / 100):.2f} s while it's up "
                        f"({frequency:g}% increased frequency); a third each Hailstorm, Meteor, Crash Lightning "
                        "(MEDIUM: no rule says which fires); Hailstorm's 9 bolts all counted on the boss (LOW: where they "
                        "land is UNVERIFIED); "
                        + (crash_words + " (MEDIUM)" if crash_words else "Crash Lightning counts one hit of the set "
                           "calculated (its two sets unread: an undercount)")
                        + "; increased duration isn't read (an undercount)"),
              "play": "Use Apocalypse whenever you have 100 Glory; its disasters fire by themselves while it lasts.",
              "confidence": "LOW"}]
    return mods, notes


# Doedre's Undoing's Witchtoads (MECHB8; FIX_QUEUE #95 / MECHB7's Handover). The lineage support (game files
# GrantedEffectStatSets SupportDoedresUndoingPlayer; PoB sup_int.lua 3087): "Supported Skills create an area which Curses
# Enemies within it, and spawns Witchtoads in that area. Witchtoads leap at enemies that get close ... Dark Consequences
# will be Triggered when they hit enemies with their leap, violently exploding the Witchtoad" (curse_apply_as_curse_zone,
# spawn_doedre_toads_on_cursed_ground; maximum_curse_zones_allowed 2, max_toads_per_doedre_cursed_ground 4,
# doedre_cursed_ground_toad_spawn_interval_ms 250). PoB (engine probe POE2T1015) rates Dark Consequences at one explosion
# per spawn interval, castTime 1 x hitTimeMultiplier 0.25 = 4 a second, whether or not a cursed area is up, and only in
# Full DPS if the curse's group is in it (no model put it there: checked, every extra_groups source in
# Assumptions.models (energy, mirage, Spirit Vessel, Expression groups); a group the player marks keeps PoB's flag). The model:
#   - explosions per second = (1 / spawn interval) x the share of the fight the boss stands in one area: the curse's
#     own share (curse_uses: a meta's rate x its duration, else recast by hand each duration). A trigger rate r gives PoB
#     4r hits a second (its hit time is the use time x 0.25), so r = that share;
#   - every toad spawned leaps at the boss and explodes ("leap at enemies that get close"; a boss is close while it
#     stands in the area). The Limit of 4 live toads an area (max_toads_per_doedre_cursed_ground; poe2db 14 Nov: "a
#     Witchtoad every 0.25 seconds, up to a Limit of 4") caps explosions at 4 / (a toad's seconds from spawn to
#     explosion): below 4 a second whenever that takes over 1 s. No source gives that time (checked, MECHB28: every game
#     table naming toad / Witchtoad / frog holds no Witchtoad monster or leap skill, only the support's stats and Dark
#     Consequences' set GSDoedreToadExplosion; PoB marks the limit "Display Only", sup_int.lua 3110; poe2db's page names
#     no leap time, speed or toad lifetime; patch notes --history "Doedre's Undoing": 0.5.0's rework names none), so 4 a
#     second is kept and labelled LOW: an OVERCOUNT if the toads take over 1 s (2 s: half). Held for the user;
#   - a second area (the support allows 2) isn't counted: an undercount, labelled, since keeping both on the boss costs a
#     second cast each duration and whether toads from both reach it is UNVERIFIED;
#   - each explosion is a Witchtoad dying ("died", minion_died_rate; KeywordPopups MinionDeath).
DOEDRE = "Doedre's Undoing"
DARK_CONSEQUENCES = "Dark Consequences"
TOAD_SPAWN_SECONDS = 0.25  # doedre_cursed_ground_toad_spawn_interval_ms 250
TOADS_PER_AREA = 4  # max_toads_per_doedre_cursed_ground
CURSE_AREAS = 2  # maximum_curse_zones_allowed (on Doedre's Undoing; Cursed Ground and Hayoxi's Binding carry it too)
# (MECHB52; RESEARCH44 R44-13, research/witchtoad-timing-r44.md, MEDIUM-LOW; the manager 17:27, a small OVERCOUNT) a toad
# takes about 1.1-1.2 s from spawning to exploding (it rises 0.833 s, then its leap hits at 0.265 s; Despair's 3.1 m area
# means little running), so with the Limit of 4 an area makes min(4, 4 / T) a second: T = 1.2 s the headline (3.33, x0.83
# on the flat 4), 1.1 s a row (3.64); two areas kept on the boss a row (twice that).
TOAD_SECONDS, TOAD_SECONDS_ROW = 1.2, 1.1
# (GEM43, routed by the manager 25 Nov 08:40; touches MECH-B's toad_model / annihilation_model, structure kept; an
# UNDERCOUNT) The game's text for maximum_curse_zones_allowed is "[Limit] {0} areas of [Curse|Cursed] Ground"
# (gem_stat_descriptions.csd, 26650308), and the three supports carrying it (Cursed Ground, Doedre's Undoing, Hayoxi's
# Fulmination) give the curse the Limit skill type (PoB sup_int.lua 2739 / 3093 / 5397), so Overabundance can support it.
# So the build's Limit sources (Assumptions.stat_limit: Overabundance's base_limit_+ / double Limit, LIMIT_LINES' "Skills
# have +N to Limit" and, for an elemental curse, "+N to Limit for Elemental Skills") are read into the area count
# (Assumptions.curse_area_limits: {curse: (areas, how)}), MEDIUM-LOW: that those lines reach a Limit the support gives
# is read from the [Limit] tag, not stated. The support's own 2 stays a row. MECHB29's "no item, passive, rune or jewel
# line grants any of them" was checked by the stat ids, not by the [Limit] keyword. Doom Blast's rate doesn't depend on
# the count (past the Limit one area goes per cast), so doom_blast_model is unchanged.
CURSE_AREAS_WHY = ("the build's Limit sources read into Cursed Ground's '[Limit] 2 areas' (MEDIUM-LOW: from the [Limit] "
                   "tag, GEM43)")


def curse_areas(areas: dict[str, tuple[float, str]] | None, curse: str | None) -> tuple[float, str]:
    """(GEM43) A curse's Cursed Ground area Limit with the build's Limit sources, and how; the support's 2 without."""
    got = (areas or {}).get(curse or "")
    if got is None or got[0] <= CURSE_AREAS:
        return float(CURSE_AREAS), ""
    return float(got[0]), got[1]


def toads_per_second(seconds: float = TOAD_SECONDS) -> float:
    """Explosions a second from one cursed area: a toad every TOAD_SPAWN_SECONDS, at most TOADS_PER_AREA alive."""
    return min(1 / TOAD_SPAWN_SECONDS, TOADS_PER_AREA / seconds)


def toad_model(skills: list[Skill], curses: list[CurseUse],
               areas: dict[str, tuple[float, str]] | None = None) -> tuple[list[dict], list[dict], set[int], float]:
    """Dark Consequences' rate from the share of the fight its curse's area is up (see above): (lines, notes, groups to
    count in Full DPS, Witchtoads dying per second). `areas`: the curses' area Limits with the build's Limit lines
    (GEM43, curse_areas; its rows only)."""
    toads = [s for s in skills if s.name == DARK_CONSEQUENCES and s.group is not None]
    if not toads:
        return [], [], set(), 0.0
    mods: list[dict] = []
    notes: list[dict] = []
    groups: set[int] = set()
    died = 0.0
    shares = {c.name: c for c in curses}
    for toad in toads:
        curse = next((shares[s.name] for s in skills if s.group == toad.group and s.name in shares), None)
        share = curse.share if curse is not None else 0.0
        how = f"{curse.name} {curse.how}" if curse is not None else "no curse in its group is applied (0)"
        per_second = share * toads_per_second()
        limit, limit_how = curse_areas(areas, curse.name if curse is not None else None)  # (GEM43: the rows' areas)
        mods += trigger_rate(DARK_CONSEQUENCES, per_second * TOAD_SPAWN_SECONDS)  # (PoB: 4 hits a second per unit rate)
        if share > 0:
            groups.add(toad.group)
        died += per_second
        notes.append({"label": "Dark Consequences (Doedre's Undoing's Witchtoads) explosions per second*",
                      "value": round(per_second, 3),
                      "basis": (f"a Witchtoad every {TOAD_SPAWN_SECONDS:g} s in the cursed area while the boss stands in it: "
                                f"{share:.0%} of the fight ({how}); every toad leaps at the boss and explodes (the toads "
                                f"'leap at enemies that get close'), about {TOAD_SECONDS:g} s from spawn to explosion "
                                f"(RESEARCH44 R44-13: it rises 0.833 s, its leap hits at 0.265 s), so the Limit of "
                                f"{TOADS_PER_AREA} live toads holds an area to {toads_per_second():.2f} a second (PoB alone: "
                                f"4 a second whether or not an area is up). Rows: {TOAD_SECONDS_ROW:g} s a toad, "
                                f"{share * toads_per_second(TOAD_SECONDS_ROW):.2f} a second; {limit:g} areas kept on the "
                                f"boss, {limit * per_second:.2f} (another cast each duration for each; UNVERIFIED whether "
                                "every area's toads reach it)" + (f"; {limit:g} areas: {limit_how}" if limit_how else "")),
                      "play": (f"Keep the cursed area under the boss: recast the curse as it runs out. Casting it "
                               f"{limit:g} times each duration keeps {limit:g} areas up: up to {limit:g}x the toads (not "
                               "counted)."),
                      "confidence": "MEDIUM-LOW"})
    return mods, notes, groups, died


# Impending Doom's Doom Blast (MECHB12; SEARCH7's probe POE2T764: 71,251 of 2b75b's reference Full DPS, an OVERCOUNT).
# The support (game files GrantedEffects ViciousHexSupportPlayer; gem_stat_descriptions.csd): "Trigger Doom Blast when
# Curses from Supported Skills expire"; it supports AppliesCurse skills and excludes UsedByProxy, Triggered, Persistent
# and Aura ones (the same table's ExcludedActiveSkillTypes; PoB sup_int.lua: "Supports Curse skills you cast yourself").
# DoomBlastPlayer: cooldown 150 ms, 3-4 stored uses: no rate of its own. PoB has no trigger for it, so it scored Doom Blast
# at its own cast speed whenever its curse's group was in Full DPS (toad_model put Doedre's Undoing's group there, MECHB8).
# The model: one Doom Blast each time the curse expires on the boss:
#   - a curse cast by hand (curse_uses' by_hand) is recast each duration (CurseUse.duration: PoB's, with the build's
#     modifiers, AUDIT25 A25-41), landing as the last one runs out (its 1.5 s delay), so it expires once a cast:
#     1 / duration a second (MEDIUM: whether a curse replaced at the
#     moment it ends counts as expiring is UNVERIFIED; a player can let it lapse first, at the cost of curse uptime);
#     a Cursed Ground area (Doedre's Undoing) is counted the same (when its curse expires on the boss);
#   - (MECHB34, RESEARCH26 R26-78 (b), MEDIUM: poe-vault's 0.5 Impending Doom Gemling guide, "As new areas overwrite
#     existing ones, the previous Curse expires and immediately triggers Doom Blast"; Cursed Ground's Limit 2,
#     maximum_curse_zones_allowed) a curse laid as Cursed Ground (Cursed Ground, Doedre's Undoing, Hayoxi's Fulmination)
#     recast faster than its duration: each cast past the Limit removes the oldest area, one Doom Blast a cast, at most
#     one per DOOM_BLAST_COOLDOWN (its 3-4 stored uses only buffer bursts). Counted at the press rate the search chose
#     for the curse (press_choices); with none, the per-duration rate, and the overwrite play as a note row. A plain
#     recast of a curse still on the boss refreshes it, no Doom Blast (forum 3324070, a PoE1 test: ASSUMED for PoE2);
#   - "Curses you inflict have infinite Duration" (CURSE_FOREVER): the curse never expires on a boss that lives, 0;
#   - any other application (a meta's trigger, Blasphemy's Aura, an item's curse on hit): the support excludes it, 0;
#   - its curse's group is counted in Full DPS when the rate is above 0 (before, only if another model put it there).
#   - (MECHB36, R26-78 (b): "Spell Cascade creates multiple overlapping Curse areas. As new areas overwrite existing ones,
#     the previous Curse expires and immediately triggers Doom Blast", poe-vault; a Doedre's Undoing build guide, seen
#     only as a web-search summary (16 Nov, page not read): "Spell Cascade causes 3 Cast of Despair, the 3rd one
#     replacing the original Cursed Ground") Spell
#     Cascade on a Cursed Ground curse lays 1 + 2 x support_spell_cascade_number_of_cascades_per_side areas a cast
#     (SupportSpellCascadePlayer: 1 a side, game files 26650308); past the Limit of 2 each new area removes the oldest,
#     so a cast removes that many: that many Doom Blasts a cast (MEDIUM-LOW: whether the boss's curse "expires" when it
#     still stands in a newer area of the same curse rests on the guide's words), still at most one per cooldown.
DOOM_BLAST = "Doom Blast"
DOOM_BLAST_COOLDOWN = 0.15  # DoomBlastPlayer Cooldown 150 ms (GrantedEffectsPerLevel)
CASCADES_PER_SIDE = "support_spell_cascade_number_of_cascades_per_side"


def doom_blast_model(skills: list[Skill], curses: list[CurseUse],
                     choices: dict[str, float] | None = None) -> tuple[list[dict], list[dict], set[int]]:
    """Doom Blast's rate from its curse's expiries (see above): (lines, notes, groups to count in Full DPS)."""
    blasts = [s for s in skills if s.name == DOOM_BLAST and s.group is not None]
    mods: list[dict] = []
    notes: list[dict] = []
    groups: set[int] = set()
    shares = {c.name: c for c in curses}
    for blast in blasts:
        curse = next((shares[s.name] for s in skills if s.group == blast.group and s.name in shares), None)
        cursing = next((s for s in skills if s.group == blast.group and s.name in shares), None)
        areas = 1 + 2 * number((cursing.support_stats if cursing is not None else {}).get(CASCADES_PER_SIDE))
        if curse is None:
            rate, how = 0.0, "no curse in its group is applied (0)"
        elif not curse.by_hand and "infinite Duration" in curse.how:
            rate, how = 0.0, f"{curse.name} has infinite Duration, so it never expires on the boss (0)"
        elif not curse.by_hand:
            rate, how = 0.0, (f"{curse.name} is {curse.how.split(':')[0]}; Impending Doom supports only curses you cast "
                              "yourself (it excludes Triggered, Persistent, Aura and UsedByProxy curses: game files) (0)")
        else:
            rate = curse.share / curse.duration
            how = (f"{curse.name} cast by hand every {curse.duration:.3g} s (its duration), expiring once a cast as the next lands (MEDIUM: "
                   "whether a curse replaced as it ends counts as expiring is UNVERIFIED)")
            if curse.zone:  # (MECHB34, R26-78 (b): areas overwritten past the Limit)
                chosen = number((choices or {}).get(curse.name))
                cap = 1 / DOOM_BLAST_COOLDOWN
                laid = (f"; Spell Cascade lays {areas:g} areas a cast, each removing an older one: {areas:g} Doom "
                        "Blasts a cast (MEDIUM-LOW, the guides' words)" if areas > 1 else "")
                if chosen * areas > rate:
                    rate = min(chosen * areas, cap)
                    how = (f"{curse.name} laid as {curse.zone}'s Cursed Ground and recast {chosen:.3g} times a second* "
                           f"(the rate the search chose): past the Limit of {CURSE_AREAS} areas each cast removes the "
                           "oldest, whose curse expires: one Doom Blast a cast (MEDIUM, RESEARCH26 R26-78: poe-vault's "
                           "0.5 Impending Doom guide)" + laid + (f", at most one per {DOOM_BLAST_COOLDOWN:g} s cooldown"
                                                                  if chosen * areas > cap else ""))
                else:
                    how += (f"; laid as {curse.zone}'s Cursed Ground, recasting it faster would overwrite areas past the "
                            f"Limit of {CURSE_AREAS}, {areas:g} Doom Blast{'s' if areas > 1 else ''} a cast "
                            f"(RESEARCH26 R26-78{'; Spell Cascade' if areas > 1 else ''}; up to one per "
                            f"{DOOM_BLAST_COOLDOWN:g} s), each cast taking the main skill's time: not counted, as the "
                            "search offers no press rate for a skill with a duration yet")
        mods += trigger_rate(DOOM_BLAST, rate)
        if rate > 0:
            groups.add(blast.group)
        notes.append({"label": "Doom Blast (Impending Doom) per second*", "value": round(rate, 3),
                      "basis": f"one each time the curse expires on the boss: {how}; PoB alone scores it at its own "
                               "cast speed",
                      "play": "Let the curse run out on the boss before recasting it: each expiry triggers one Doom Blast.",
                      "confidence": "MEDIUM" if rate > 0 else "HIGH"})
    return mods, notes, groups


# Hayoxi's Fulmination's Annihilation (MECHB29; GEM7's item, MECHB28's findings: an UNDERCOUNT) ---------------------------
# The support (game files SupportHayoxisBindingPlayer, GrantedEffectStatSets; gem_stat_descriptions.csd): "Supported
# Skills create Cursed Ground" (curse_apply_as_curse_zone), "Limit 2 areas of Cursed Ground" (maximum_curse_zones_allowed
# 2), "Trigger Annihilation when Cursed Ground from Supported Skills have persisted for 7 seconds"
# (trigger_from_hayhoxis_binding_after_x_ms 7000); it gives the curse a 2 s cooldown, 1 stored use (GrantedEffectsPerLevel)
# and supports no Triggered, Channelling, Attack, totem, trap or mine curse (its excluded skill types; PoB sup_int.lua
# 5398). Annihilation (SupportTriggeredAnnihilationPlayer): "Hits a total of 6 times over 2 seconds"
# (annihilation_hit_intervals 6, annihilation_blast_duration_ms 2000), radius 17 (1.7 m). None of these varies: the
# support has one level, and no item, passive, rune or jewel line grants any of them (checked: the Stat fields of every
# game table for the 10 curse-zone / Hayoxi / annihilation stat ids: only the Cursed Ground, Doedre's Undoing and Hayoxi
# supports' sets, two monster Temporal Chains sets and Annihilation's own; PoB's ModCache holds no Cursed Ground line;
# poe2db not checked: UNVERIFIED). Patch notes --history "Hayoxi": 0.5.0 only a bug fix (it could support non-curses);
# "Cursed Ground": 0.5.0 only Doedre's Undoing's rework.
# PoB (MECHB29's probes POE2T1146-1147, Spark Stormweaver + Despair / Hayoxi's Fulmination): nothing reads the trigger or
# the hit count (castTime 0, Triggered, InbuiltTrigger), so with no rate it scores 0 (Speed 0; Full DPS 97.2, Spark
# alone, with or without its group in Full DPS: an UNDERCOUNT); a triggerRate r gives Speed r and r x one hit (688.4 at
# r = 1/7: 98.3; at 0.5: 344.2): its hit is one of the 6. It doesn't apply the support's "100% of Physical Damage
# Converted to other Damage Types matching the Supported Curse Gem's Tags" (annihilation.csd): PhysicalHitAverage 604 of
# 688 under Despair (Chaos): not modelled here (MECH-B's open item, said in the note).
# The model, one Annihilation per area that lasts 7 s:
#   - an area erupts once, when it has persisted 7 s (the text names one trigger; a second at 14 s: UNVERIFIED, not
#     counted, moot under the play below); an area replaced at the Limit before 7 s doesn't erupt (it hasn't persisted
#     7 s; KeywordPopups Limit: "the oldest effect will dissapear");
#   - how long an area lasts: the curse's own duration (CurseUse.duration: PoB's, with the build's modifiers; MEDIUM,
#     MECHB34, the manager's ruling 15 Nov 22:15 on RESEARCH26 R26-62: "a curse area lasts only the curse's duration
#     ... the sourced reading, and the conservative one. Score it that way (0 Annihilations under 7 s where that
#     follows), and show 'until replaced' as a row"). Sources: official forum thread 3900027 (Selous, 9 Jan 2026: Hayoxi's
#     7 s trigger needs "Curse Duration—or the effect might simply not work"); no game text gives the area a duration of
#     its own (checked, MECHB29 / RESEARCH26: no stat id in the game files names one; KeywordPopups has no Cursed Ground
#     entry; PoB has no Cursed Ground handling; poedb.tw's "15-34 s" is PoE1's support). So under 7 s of curse duration
#     no area erupts: 0, the headline; the other reading (areas last until replaced at the Limit: the same 2 per 7 s,
#     LOW) is the note's "until replaced" row. This zero rests on a source (the forum reply), not on an unverified
#     claim, so CLAUDE.md's "never zero on an unverified claim" (AUDIT36 A36-1, which counted the other reading before)
#     no longer applies;
#   - the play (a player who takes it plays to feed it: CLAUDE.md): two areas under the boss, a new one cast every 3.5 s
#     (7 s / 2 areas, or the curse's cooldown if that is longer), so each area reaches 7 s, erupts and is replaced by the
#     next cast: 2 eruptions per 7 s. Without it (the curse recast each duration, as curse_uses counts it): 1 per duration;
#   - the play's extra casts (its rate minus curse_model's one a duration) take their cast time from the main skill:
#     charged here, as less Cast Speed on it, so that with curse_model's line the main skill loses both casts' share;
#   - each eruption: 6 hits on the boss (it stands in the cursed area; that it stays in the 1.7 m column all 2 s: LOW):
#     its trigger rate is eruptions x 6 (PoB's hit is one of the 6: probe);
#   - a curse not cast by hand: a meta can't trigger a supported curse (the support excludes Triggered); a Blasphemy
#     Aura's or an item's curse: whether it makes Cursed Ground is UNVERIFIED: left as PoB has it, said in the note.
HAYOXI = "Hayoxi's Fulmination"
ANNIHILATION = "Annihilation"
HAYOXI_DELAY = 7.0  # trigger_from_hayhoxis_binding_after_x_ms 7000
HAYOXI_COOLDOWN = 2.0  # the support's Cooldown 2000 ms on the curse
ANNIHILATION_HITS = 6  # annihilation_hit_intervals


def annihilation_model(skills: list[Skill], curses: list[CurseUse], main: Skill | None,
                       areas: dict[str, tuple[float, str]] | None = None) -> tuple[list[dict], list[dict], set[int]]:
    """Hayoxi's Fulmination's Annihilation from its curse's Cursed Ground areas (see above): (lines, notes, groups to
    count in Full DPS). `areas`: the curses' area Limits with the build's Limit lines (GEM43, curse_areas)."""
    blasts = [s for s in skills if s.name == ANNIHILATION and s.group is not None]
    mods: list[dict] = []
    notes: list[dict] = []
    groups: set[int] = set()
    shares = {c.name: c for c in curses}
    for blast in blasts:
        cast = next((s for s in skills if s.group == blast.group and s.name in shares), None)
        curse = shares[cast.name] if cast is not None else None
        rate, without, confidence, play = 0.0, 0.0, "LOW", ""
        if curse is None:
            how = "no curse in its group is applied (0)"
        elif not curse.by_hand:
            how = (f"{curse.name} is {curse.how.split(':')[0]}: whether a curse not cast by hand makes Cursed Ground is "
                   "UNVERIFIED (a meta can't trigger it: the support excludes Triggered skills); left as PoB has it")
        else:
            cooldown = (cast.cooldown or HAYOXI_COOLDOWN) / (cast.cooldown_recovery or 1.0)
            limit, limit_how = curse_areas(areas, cast.name)  # (GEM43: the build's Limit lines, MEDIUM-LOW)
            every = max(HAYOXI_DELAY / limit, cooldown)
            rate, without = 1 / every, 1 / curse.duration
            plain = 1 / max(HAYOXI_DELAY / CURSE_AREAS, cooldown)  # (GEM43: at the support's own 2 areas, the row)
            short = curse.duration < HAYOXI_DELAY - 1e-9
            confidence = "MEDIUM-LOW" if limit_how else "MEDIUM"
            if short:  # (the manager's ruling 15 Nov 22:15, R26-62: an area lasts the curse's duration: none erupts)
                replaced = rate
                rate, without = 0.0, 0.0
                how = (f"{curse.name}'s {curse.duration:.3g} s duration is under the {HAYOXI_DELAY:g} s an area must "
                       "persist, and an area lasts the curse's duration (MEDIUM: official forum 3900027, Hayoxi's "
                       "trigger needs enough Curse Duration 'or the effect might simply not work'; no game text gives "
                       "the area a duration of its own), so none erupts (0); 'until replaced' row (LOW: if areas lasted "
                       f"until replaced at the Limit of {limit:g}, cast every {every:.3g} s): {replaced:.3f} "
                       "eruptions/s")
                play = (f"Raise {curse.name}'s Curse Duration to {HAYOXI_DELAY:g} s or more (it has "
                        f"{curse.duration:.3g} s): below that no Cursed Ground area lasts long enough to erupt. "
                        f"Without it: 0 Annihilations/s; with it (cast every {every:.3g} s, {limit:g} areas): "
                        f"{replaced:.3f}/s")
            else:
                how = (f"{curse.name} cast every {every:.3g} s ({HAYOXI_DELAY:g} s / {limit:g} areas, its "
                       f"{cooldown:.3g} s cooldown allowing), so each area persists {HAYOXI_DELAY:g} s, erupts and is "
                       f"replaced by the next cast: {rate:.3f} eruptions/s (a play strategy*; recast only each "
                       f"{curse.duration:.3g} s duration: {without:.3f}/s); areas last the curse's duration (MEDIUM: "
                       "official forum 3900027), at least 7 s here"
                       + (f"; {limit:g} areas: {limit_how}; row: the support's {CURSE_AREAS} areas, {plain:.3f}/s"
                          if limit_how else ""))
                play = (f"Cast {curse.name} under the boss every {every:.3g} s, keeping {limit:g} areas: each "
                        f"erupts after {HAYOXI_DELAY:g} s. Without it (recast each {curse.duration:.3g} s): "
                        f"{without:.3f} Annihilations/s; with it: {rate:.3f}/s"
                        + (f" (at the support's {CURSE_AREAS} areas, without the Limit lines: {plain:.3f}/s)"
                           if limit_how else ""))
            extra = max(0.0, rate - without)
            took = cast.cast_time or 0.7
            if main is not None and cast is not main and extra > 0:
                first = min(1.0, took / curse.duration)  # (curse_model's line for the cast each duration)
                lost = min(1.0 - first, took * extra)
                if first < 1.0 and lost > 0:
                    mods.append(line("1% more Attack and Cast Speed", -100 * lost / (1.0 - first), skill=main.name))
                    how += (f"; the {extra:.3f} extra casts/s take {lost:.1%} of {main.name}'s time ({took:.2f} s "
                            "each)")
        mods += trigger_rate(ANNIHILATION, rate * ANNIHILATION_HITS)
        if rate > 0:
            groups.add(blast.group)
        notes.append({"label": "Annihilation (Hayoxi's Fulmination) per second*", "value": round(rate, 3),
                      "basis": (f"one each time a Cursed Ground area has persisted {HAYOXI_DELAY:g} s: {how}; "
                                f"{ANNIHILATION_HITS} hits each over 2 s, all taken to land on the boss in the area (LOW: "
                                "that it stays in the 1.7 m column all 2 s); PoB alone gives it no rate (0). PoB keeps "
                                "its damage Physical: the conversion to the curse's damage types isn't applied (an "
                                "error either way, not modelled)"),
                      **({"play": play} if play else {}),
                      "confidence": confidence})
    return mods, notes, groups


# Minions dying, not only Killed (MECHB8; plans/term-minion-dies.md, FIX_QUEUE #95, AUDIT15 A15-18). KeywordPopups
# MinionDeath: "Minions whose durations expire or that are despawned by the player are considered to have died. However,
# effects that state they trigger when a Minion is Killed do not trigger in these cases." KeywordPopups Limit: "If a new
# effect is created while at the maximum number of effects, the oldest effect will dissapear" (that this counts as a
# despawn: MEDIUM). So "when a Minion Dies" fires on all of these, summed:
#   - Killed: minion_deaths (Sacrifice, Explosive Demise; 0 with its note);
#   - Witchtoads exploding: toad_model's rate;
#   - Offerings: each cast impales (uses up) a skeleton, two with Danse Macabre (KeywordPopups Offering; RESEARCH22
#     #133), at the cycle danse_macabre_model uses: k = N // n casts of D s each, then the revive (MEDIUM: that a used
#     skeleton "died" and isn't only consumed is the MinionDeath reading);
#   - temporary minions from a triggered summon (Skill.minion: Wardbound Minions ...): each use's minion dies once, at its
#     duration's end or replaced at the limit, so one death per use at steady state (HIGH from MinionDeath).
# Not counted (labelled, undercounts): the boss killing your minions; summoning past a Limit by hand (no use rate for a
# pressed summon is modelled); Summoned Wolves (Predator's Mark Activates on its target's death, none on a lone boss, or
# when Cross Slash hits the Marked boss with both gouges (ActiveSkills wolf_cross_slash), which may summon a wolf and
# replace the oldest at the limit: UNVERIFIED, A22-3, held for the user's in-game test; a kill rate per boss preset would
# give some too); a second Witchtoad area. Offerings and Sacrifice may share skeletons: the
# sum isn't held to what the skeletons' revival allows together (a possible small overcount, labelled).
def minion_died_rate(skills: list[Skill], main: Skill | None, stats: dict, supports: dict[int, list[str]] | None = None,
                     toads: float = 0.0, rates: dict[str, float] | None = None) -> tuple[float, str]:
    """Your minions dying per second ("when a Minion Dies": Killed, expired, despawned or replaced), and how. `toads`:
    toad_model's Witchtoads per second; `rates`: triggered skills' uses per second (build.trigger_rates)."""
    killed, how = minion_deaths(skills, main, stats)
    total, parts = killed, [f"Killed {killed:.3f}/s ({how})"]
    if toads > 0:
        total += toads
        parts.append(f"Witchtoads exploding {toads:.3f}/s (toad_model)")
    skeletons = [s for s in skills if s.summon and s.summon.get("persistent") and "Skelet" in s.name
                 and not number(s.summon.get("duration"))]
    count = int(sum(number(s.summon.get("limit")) for s in skeletons))
    for offering in (s for s in skills if s.name in OFFERING_SECONDS):
        n = 2 if DANSE_MACABRE in (supports or {}).get(offering.group, []) else 1
        every, casts = OFFERING_SECONDS[offering.name], count // n
        if casts <= 0:
            parts.append(f"{offering.name}: no skeleton to impale (0)")
            continue
        revive, _ = revive_seconds(skeletons)
        cycle = max(casts * every, (casts - 1) * every + revive)
        used = casts * n / cycle
        total += used
        parts.append(f"{offering.name} impales {n} skeleton{'s' if n > 1 else ''} a cast, {casts} cast"
                     f"{'s' if casts > 1 else ''} per {cycle:.3g} s: {used:.3f}/s (MEDIUM: a used skeleton has died)")
    for spell in (s for s in skills if s.minion and s.triggered):
        use = number((rates or {}).get(spell.name))
        if use > 0:
            total += use
            parts.append(f"{spell.name}'s temporary minions {use:.3f}/s (one per use, each dies at its duration's end "
                         "or replaced at its limit)")
    parts.append("not counted: the boss killing your minions, summoning past a limit by hand, Summoned Wolves (a "
                 "Marked kill, or Cross Slash Activating the Mark on the boss: UNVERIFIED), a second Witchtoad area (undercounts); Offerings and Sacrifice sharing skeletons isn't "
                 "held to their revival together (a possible small overcount)")
    return total, "; ".join(parts)


# Kills the build makes in a boss fight (MECHB9; the manager's ruling on A17-4 / research #124, 12 Nov ~12:40, and the
# boss presets' adds, MECH-D's MECHD1). Two kinds, kept apart because the lines that read them say different things:
#   - enemies: the boss preset's killable adds (the King in the Mists' Affliction Totems, Atziri's waves), the stats'
#     ADD_KILLS_STAT (bosses.kill_stats, merged into the stats by Assumptions.models; 0 with a note against a lone
#     boss, where the kill ends the fight). Every add is taken as killed by the build (MECHD1:
#     a build taking on-kill lines plays to kill them, CLAUDE.md's second rule). LOW (the presets' add rates).
#   - your own minions Killed: the game's text calls a minion its summoner brings to 0 Life "Killed" (KeywordPopups
#     MinionDeath), so the ruling counts them as Kills in the headline at the build's own rate (minion_deaths: Sacrifice,
#     Explosive Demise, Minion Pact (MECHB11); Dark Pact / Abyssal Pact have no skill in PoB, so no use rate, not
#     counted), LOW, held for the user's in-game test, with a "without it" row.
# A line that says "an enemy" ("when you kill an enemy", Reaper's Invocation) reads the enemies only: your minions are
# allies, not enemies (the lines' own text; KeywordPopups MinionDeath / Allies). A line that says only "on Kill" reads
# both. The readers of plain on-Kill lines (Onslaught, Rage, charges, charms) are MECH-C's (conditions.py, flasks.py).
ADD_KILLS_STAT = "AddKillsPerSecond"
ADD_POWER = 1.0  # an add's monster Power (KeywordPopups Power: "An average monster has a Power of 1", Normal x1; LOW)


def kill_rate(stats: dict, own: float = 0.0, own_how: str = "") -> tuple[float, float, str]:
    """(enemies killed per second, all kills per second including your own minions Killed, how). `own`: minion_deaths'
    rate (only Killed minions, never expired or despawned ones)."""
    adds = max(number(stats.get(ADD_KILLS_STAT)), 0.0)
    if adds > 0:
        how = (f"{adds:.3f} of the boss's adds killed per second (the boss preset's kill rate, LOW; every add taken as "
               "killed by the build)")
    else:
        how = ("no enemy dies before the boss (a lone boss; the King in the Mists' and Atziri's adds come from the boss "
               "preset's AddKillsPerSecond, MECH-D's, when it's in the stats)")
    if own > 0:
        how += (f"; plus your own minions Killed {own:.3f}/s, counted as Kills by lines that don't say 'enemy' (the "
                f"ruling on A17-4: LOW, held for an in-game test; {own_how})")
    return adds, adds + own, how


def kills_note(kills: tuple[float, float, str]) -> list[dict]:
    """The play guide's line for the build's kills, with the without-own-minions row (empty when there are none)."""
    enemies, total, how = kills
    if total <= 0:
        return []
    note = {"label": "Kills in the boss fight", "value": f"{total:.3f}/s ({enemies:.3f}/s of them enemies)", "basis": how,
            "confidence": "LOW"}
    if total > enemies:
        note["play"] = (f"Kill your own minions to feed on-Kill lines (Sacrifice, Explosive Demise): with it "
                        f"{total:.3f} Kills/s, without it {enemies:.3f}/s. Whether killing your own minion counts as a "
                        "Kill for these lines is held for an in-game test (LOW).")
    return [note]


# Heartbound Loop (MECHB9; FIX_QUEUE, COVE10's row): "300 Physical Damage taken on Minion Death" (1000 on the Loreweave
# version; ModCache also holds 250 / 350 / 501 rolls). PoB parses it (HeartboundLoopSelfDamage) but applies it only per
# cast of Summon Skeletons, as damage per summoned minion (CalcOffence selfHitHandlers), never at the rate minions die.
# The game: on Minion Death, which KeywordPopups MinionDeath counts for minions that died in any way (Killed, expired,
# despawned): minion_died_rate's rate. So the damage taken per second is the lines' sum x that rate. (MECHB20, AUDIT29
# A29-5) It is Hit damage: "Any damage that isn't damage over time is Hit damage" (KeywordPopups Hit), and this is a
# one-off amount per death, so "damage taken over time" lines don't reduce it (PoB treats it as damage over time: 300 ->
# 225 in MECHC14's probe, an undercount of the damage taken). Armour may reduce it as a Physical Hit (whether a
# self-inflicted Hit meets Armour, and whether it can be evaded, is UNVERIFIED); it's not reduced here, so the damage
# taken is at most too high (the safe side for recovery). The recovery reader is MECH-C's (objective.boss_recovery): it's
# on build.self_damage and in the notes until then.
HEARTBOUND = re.compile(r"^(\d+(?:\.\d+)?) Physical Damage taken on Minion Death$", re.I)


def heartbound_damage(texts: list[str], died: tuple[float, str]) -> tuple[float, list[dict]]:
    """Physical damage per second the build takes from "N Physical Damage taken on Minion Death" lines at the build's
    minion-death rate (minion_died_rate's (per second, how)), and its note."""
    per = sum(float(m.group(1)) for t in texts if (m := HEARTBOUND.match(t.strip())))
    if per <= 0:
        return 0.0, []
    rate, how = died
    taken = per * max(rate, 0.0)
    return taken, [{"label": "Heartbound Loop: damage taken on Minion Death",
                    "value": f"{taken:,.0f} Physical damage per second",
                    "basis": (f"{per:g} per minion death x {rate:.3f} deaths per second ({how}); Hit damage (KeywordPopups Hit: "
                              "not damage over time), so damage-over-time lines don't reduce it; Armour isn't applied "
                              "(whether it meets a self-inflicted Hit is UNVERIFIED: at most too high); PoB counts it "
                              "only per Summon Skeletons cast, as damage over time"),
                    "confidence": "LOW",
                    "play": (f"Each of your minions dying costs you {per:g} Life: {taken:,.0f} per second at this "
                             "build's minion deaths" if taken > 0 else
                             "Nothing in this build makes its minions die, so the ring costs no Life here")}]


# Fireflower (MECHB25; COV28's parsed_unused row, an OVERCOUNT of sustain): "Take 100 Fire Damage when you Ignite an
# Enemy" (Uniques amulet.lua, the Current variant; poe2db Fireflower, current). PoB parses it (EyeOfInnocenceSelfDamage,
# ModParser 3583) and no calculation reads it. The rate is the build's own: the main skill's Ignites per second (hits x
# its Ignite chance, crits weighted, as Arbiter's Ignition reads them above). Each new Ignite counts, including one that
# replaces an Ignite already on the boss (MEDIUM: the line says "when you Ignite an Enemy", no exception; the higher
# reading, the safe side for sustain). Ignites from other skills (side groups, triggered skills) aren't counted: an
# undercount of the damage taken, labelled. It goes to PoB as "N Fire Damage taken per second" (ModParser 116: FireDegen),
# as Heartbound Loop's does, so recovery and the Life flask see it; PoB treats that as damage over time, though the game
# deals it as one Hit per Ignite (KeywordPopups Hit), so how resistances and "damage taken over time" lines apply to it
# is UNVERIFIED (as for Heartbound Loop, MECHB20).
FIREFLOWER = re.compile(r"^Take (\d+(?:\.\d+)?) Fire Damage when you Ignite an Enemy$", re.I)


def ignite_self_damage(texts: list[str], stats: dict) -> tuple[float, float, list[dict]]:
    """(Fire damage taken per second, Ignites per second, notes) for "Take N Fire Damage when you Ignite an Enemy"
    lines at the main skill's own Ignite rate; (0, 0, []) without such a line."""
    per = sum(float(m.group(1)) for t in texts if (m := FIREFLOWER.match(t.strip())))
    if per <= 0:
        return 0.0, 0.0, []
    crit = min(number(stats.get("CritChance")), 100.0) / 100
    chance = (number(stats.get("IgniteChanceOnHit")) * (1 - crit) + number(stats.get("IgniteChanceOnCrit")) * crit) / 100
    ignites = hits_per_second(stats) * min(max(chance, 0.0), 1.0)
    taken = per * ignites
    return taken, ignites, [{
        "label": "Fireflower: Fire damage taken when you Ignite",
        "value": f"{taken:,.0f} Fire damage per second",
        "basis": (f"{per:g} per Ignite x {ignites:.3f} Ignites per second (the main skill's hits x its {chance:.1%} "
                  "Ignite chance, crits weighted; each new Ignite counted, MEDIUM; other skills' Ignites not counted, "
                  "an undercount); in PoB as Fire damage taken per second, so recovery sees it (how resistances apply to "
                  "this one Hit per Ignite is UNVERIFIED)"),
        "confidence": "MEDIUM",
        "play": (f"Fireflower burns you for {per:g} Fire damage each time you Ignite: {taken:,.0f} per second at this "
                 "build's Ignite rate" if taken > 0 else "This build doesn't Ignite, so Fireflower's self-damage costs nothing here")}]


# Totems other than Spell Totem (MECHB8; MECHB7's Handover item 2). PoB prices one totem: the damaging part beside a
# totem-summoning skill (Shockwave Totem's Shockwave Slam, Artillery Ballista's Ballista Bolt, Siege Ballista's
# Artillery, Dark Effigy's Vile Effusion, a Mortar Cannon's grenade) carries no ActiveTotemLimit (engine probe POE2T1018:
# 0), and PoB multiplies only ailment stacks by the totem count (CalcOffence 5099-5101, a Single-ailment flag), never the
# hits. The game (KeywordPopups Totem): "Totems are allied constructs which use skills for you ... Totem Limit is shared
# between different types of Totem by default". The model:
#   - totems up = the summoning skill's Totem Limit (the bridge's totemLimit: PoB's ActiveTotemLimit / ActiveBallistaLimit
#     for that skill, with the build's "+N Totems" lines), less one for each other totem-summoning skill in the build
#     (the shared limit; each assumed to keep one totem placed), at least 1;
#   - each totem uses the skill at PoB's one-totem rate, all in reach of the boss (MEDIUM: the player places them at the
#     boss; base_totem_range 60-120 is a placement range, not the skill's reach); placing them (one cast each per 8-12 s
#     duration) isn't taken from anything (the player's own skill time isn't the damage);
#   - counted as more attack and cast speed on the damaging part, as totem_model does: Ignites from several totems don't
#     add up (only the strongest deals damage), Poison stacks and hits do.
# Left to their own models: Spell Totem (totem_model, its charges) and Ancestral Warrior Totem (3 Endurance Charges a
# totem; not modelled here, labelled).
# One-totem supports (AUDIT23 A23-3): Splinter Totem I / II, Greatwood II and Cirel's Cultivation carry
# number_of_totems_allowed_is_1, "Supported Skills can only have one active Totem" (gem_stat_descriptions; game files
# GrantedEffectStatSets; PoB's sup_str.lua lists it and reads it nowhere). The model reads the stat from the group's
# supports (bridge activeSkills supportStats; a flag stat reads 1, CalcTools 183), not the gem names, so a fifth carrier
# counts too: then one totem, no extra speed.
# PoB's own ailment stacks (AUDIT24 A24-3, an OVERCOUNT): CalcOffence 5264-5267 multiplies a totem-flagged skill's
# Ignite / Poison / Bleed stack count by the TotemsSummoned override, else the skill's ActiveTotemLimit, and nothing
# sets either to 1 for these supports. The model adds ActiveTotemLimit BASE (1 - limit) on that skill, source
# "Assumption:OneTotem" (TOTEM_ONE_TAG). The loop: the line lowers the limit the bridge would read next pass; both
# bridge reads (totemLimit, ailmentTotems) leave that source out, so the model reads the same limit every pass and
# writes the same line (a fixed point). A TotemsSummoned override (the Configuration tab) wins in PoB: then no line.
# Splinter Totem I / II (support_splinter_totem_X_times 2): its totem "splinter[s] into smaller versions of itself after
# it uses an Attack or Spell ... up to a maximum", each splinter dealing 20% / 15% less damage per splinter (poe2db
# Splinter_Totem_I, 12 Nov 2026; gem_stat_descriptions "can splinter up to {0} times"; no KeywordPopups entry): the
# splinters are more totems, but how many each splinter makes isn't stated (UNVERIFIED). MECHB34 (RESEARCH26 R26-76,
# ASSUMED, LOW-MEDIUM: forum 3885913, Dec 2025, "I was anticipating basically 4 mini totems in its final form ... upon
# reaching the smallest size, they all die"; the gem's "smaller versions of itself", plural; "Only one Totem can be
# splintering at a time"; no patch note since 0.4.0c changes it): two per splinter, so stage k holds 2^k totems, each
# acting support_splinter_totem_splinter_after_X_actions (1) times at (1 + damage%)^k damage and (1 + speed%)^k skill speed
# (the "_final_each_splinter" stats, -20 / -10 with I, -15 / -7 with II; read by nothing in PoB: SkillStatMap, Modules),
# for support_splinter_totem_X_times (2) splinters; the last stage dies after acting, and the totem is placed again (its
# cast time, the totem skill's base: LOW). PoB scores one full totem acting the whole time. Two readings of the time a
# stage takes: its totems act AT ONCE (each stage one action time) or IN TURN (one after another): the lower is the
# headline (the overcount side), the other a row; the stays-one-totem reading (PoB's) a row too. Ailments: still one
# totem's (one_totem_ailments).
TOTEM_ONE_STAT = "number_of_totems_allowed_is_1"
TOTEM_ONE_TAG = "OneTotem"
TOTEM_SPLINTER_STAT = "support_splinter_totem_X_times"
SPLINTER_ACTIONS_STAT = "support_splinter_totem_splinter_after_X_actions"
SPLINTER_DAMAGE_STAT = "support_splinter_totem_damage_+%_final_each_splinter"
SPLINTER_SPEED_STAT = "support_splinter_totem_skill_speed_+%_final_each_splinter"
SPLINTER_PER = 2  # totems per splinter (ASSUMED, R26-76)


def splinter_factor(times: float, actions: float, damage: float, speed: float, action_time: float,
                    place_time: float) -> tuple[float, float, str]:
    """(the lower reading's factor on PoB's one-totem DPS, the higher one's, how) for Splinter Totem (see above)."""
    stages = range(int(times) + 1)
    dealt = sum(actions * SPLINTER_PER ** k * (1 + damage / 100) ** k for k in stages)
    at_once = sum(actions * action_time / (1 + speed / 100) ** k for k in stages) + place_time
    in_turn = sum(actions * SPLINTER_PER ** k * action_time / (1 + speed / 100) ** k for k in stages) + place_time
    high, low = dealt * action_time / at_once, dealt * action_time / in_turn
    how = (f"one placed totem acts {sum(actions * SPLINTER_PER ** k for k in stages):g} times (1 -> 2 -> 4 totems, "
           f"{actions:g} action a stage, {damage:g}% damage and {speed:g}% skill speed per splinter): {dealt:.2f} full-totem "
           f"actions, then placed again ({place_time:.2f} s); PoB counts one full totem acting every {action_time:.2f} s. "
           f"Its splinters acting at once: x{high:.3f}; one after another: x{low:.3f}")
    return low, high, how
TOTEM_OWN_MODEL = {"Spell Totem", "Ancestral Warrior Totem"}


def totem_count_model(skills: list[Skill], main: Skill | None, texts: Iterable[str] = (),
                      stats: dict | None = None) -> tuple[list[dict], list[dict]]:
    """More totems than one for the main skill's totem (see above): a speed line on the main skill and its note."""
    if main is None or main.group is None:
        return [], []
    group = [s for s in skills if s.group == main.group]
    if any(number(s.support_stats.get(TOTEM_ONE_STAT)) > 0 for s in group):
        mods, notes = one_totem_ailments(main, group)  # ("Supported Skills can only have one active Totem": no extra speed)
        more, more_notes = splinter_model(main, group, stats or {})
        return mods + more, notes + more_notes
    if any(s.name in TOTEM_OWN_MODEL for s in group):
        return [], []
    summoner = next((s for s in group if s.totem_limit > 0), None)
    if summoner is None:
        return [], []
    others = sorted({s.name for s in skills if s.totem_limit > 0 and s.group != main.group})
    pob = int(summoner.totem_limit)
    doubled = any(ANCESTRAL_BOND_DOUBLE.match(t.strip()) for t in texts)
    own = summoner.totem_limit_own if 0 < summoner.totem_limit_own <= pob else float(pob)
    high, low, bond_words = bond_totems(own, pob - own, doubled)
    limit = int(high)
    up = max(1, limit - len(others))
    if up <= 1 and not others:
        return [], []
    mods = [line("1% more Attack and Cast Speed", 100.0 * (up - 1), skill=main.name)] if up > 1 else []
    basis = (f"{summoner.name}'s Totem Limit {limit} (PoB's {pob}, with the build's +Totem lines"
             + (f"; {bond_words}" if bond_words else "") + ")"
             + (f" (lower row less the other totem skills: {max(1, int(low) - len(others))} totems)"
                if low != high and others else "")
             + (f", less {len(others)} for {', '.join(others)} (KeywordPopups Totem: the limit is shared; each assumed to "
                "keep one totem placed)" if others else "")
             + f": {up} totems, each using {main.name} at PoB's one-totem rate, all in reach of the boss (MEDIUM: placed "
               "at it); PoB counts one. Counted as more speed: Ignites from several totems don't add up (only the "
               "strongest deals damage); placing them isn't taken from your time")
    notes = [{"label": f"Totems up ({main.name})", "value": up, "basis": basis,
              "play": f"Keep {up} {summoner.name} totems placed at the boss; re-place them as they expire.",
              "confidence": "MEDIUM"}]
    if summoner.melee_totem_added > 0:  # (GEM41) the is_melee_attack_totem reading, and the count without it
        without = max(1, int(bond_totems(own, max(0.0, pob - own - summoner.melee_totem_added
                                                  - summoner.attack_totem_added), doubled)[0]) - len(others))
        notes.append({"label": f"{summoner.name}: Melee Attack totem lines", "value": f"{up} with / {without} without",
                      "basis": (f"the game flags {summoner.name} is_melee_attack_totem (GrantedEffectStatSets; poe2db's "
                                f"hidden stats and Melee tag) though its skill types lack Attack and Melee, so the "
                                f"build's \"Melee Attack Skills have +N to maximum number of Summoned Totems\" lines "
                                f"(+{summoner.melee_totem_added:g}) are counted toward its limit, which PoB never does: "
                                f"the flag's purpose (MEDIUM-HIGH: RESEARCH59 R59-3, the hidden tag is only on its "
                                f"summon set). Without them: {without} totems"),
                      "confidence": "MEDIUM-HIGH"})
    if summoner.attack_totem_added > 0:  # (GEM42, R59-3) "Attack Skills have +N" lines on such a totem, MEDIUM
        without = max(1, int(bond_totems(own, max(0.0, pob - own - summoner.attack_totem_added), doubled)[0])
                      - len(others))
        notes.append({"label": f"{summoner.name}: Attack totem lines", "value": f"{up} with / {without} without",
                      "basis": (f"the build's \"Attack Skills have +N to maximum number of Summoned Totems\" lines "
                                f"(+{summoner.attack_totem_added:g}) counted for {summoner.name} as an Attack totem "
                                f"(is_melee_attack_totem; RESEARCH59 R59-3: probably, MEDIUM). Without them: {without} "
                                f"totems"),
                      "confidence": "MEDIUM"})
    return mods, notes


# Your totems dying a second (MECHB39; the shared rate the manager asked for, 05:40 / 17:55 18 Nov, for MECH-C's Soul
# Mantle and MECH-B's totem-death readers: Unnamed Heartwood, Tawhoa's Vengeance). RESEARCH31 R31-2 (MEDIUM): a totem
# expiring or being replaced counts as dying (PoE2 forum 3751378, a PoE1 GGG statement). From the build (CLAUDE.md, no
# flat rate): each totem-summoning skill (Skill.totem_limit > 0) keeps its totems placed, re-placed as they expire: the
# main skill's totem the Totem Limit less one for each other totem skill (KeywordPopups Totem: the limit is shared; each
# other skill assumed to keep one placed, as totem_count_model), or `up` when a model knows fewer are up (Spell Totem's
# charges, totem_model); each lasting its own totem duration (the bridge's useRates totemDuration: PoB's TotemDuration
# with the build's modifiers; 8 / 12 s base). Deaths = up / duration; pressed faster than that at the limit (the search's
# chosen press rate, press_choice), each placement replaces one: deaths = presses (capped by the skill's own speed). The
# boss killing totems: not counted (no source gives a rate; R31-2: a LOW row, 0 in the headline). No totem skill, or no
# duration read: 0 with the reason.
def totem_deaths(skills: list[Skill], main: Skill | None, rates: dict[str, dict],
                 up: dict[str, float] | None = None, choices: dict[str, float] | None = None,
                 texts: Iterable[str] = (), each: dict[str, float] | None = None) -> tuple[float, str]:
    """(your totems dying a second, how) from each totem skill's totems kept up over its own duration (see above).
    `rates`: {skill name: its bridge useRates row}; `up`: {skill name: totems up} where a model knows better; `each`,
    if given, is filled with {skill name: its own totems' deaths a second} (MECHB40: Tawhoa's Vengeance reads one skill's)."""
    summoners = [s for s in skills if s.totem_limit > 0]
    if not summoners:
        return 0.0, "the build has no totem skill: no totem dies (0)"
    names = list(dict.fromkeys(s.name for s in summoners))
    doubled = any(ANCESTRAL_BOND_DOUBLE.match(t.strip()) for t in texts)
    total, parts = 0.0, []
    for name in names:
        skill = next(s for s in summoners if s.name == name)
        is_main = main is not None and skill.group == main.group
        own = skill.totem_limit_own if 0 < skill.totem_limit_own <= skill.totem_limit else skill.totem_limit
        limit = bond_totems(own, skill.totem_limit - own, doubled)[0]  # (Ancestral Bond's doubling, as totem_count_model)
        kept = (max(1.0, limit - (len(names) - 1)) if is_main else 1.0)
        if up and name in up:
            kept = max(0.0, number(up[name]))
        row = rates.get(name) or {}
        lasts = number(row.get("totemDuration"))
        if lasts <= 0:
            parts.append(f"{name}: no totem duration read (0)")
            if each is not None:
                each[name] = 0.0
            continue
        expiry = kept / lasts
        deaths, how = expiry, f"{kept:g} up, each lasting {lasts:.2f} s, re-placed as it expires: {expiry:.3f}/s"
        chosen = press_choice(row, choices)
        if chosen is not None and chosen > expiry and kept > 0:
            presses = min(chosen, number(row.get("speed")) or chosen)
            deaths, how = presses, (f"placed {presses:.3g} times a second* at its limit of {kept:g} (the search's chosen "
                                    f"rate), each replacing one: {presses:.3f}/s (without it, expiry alone: "
                                    f"{expiry:.3f}/s)")
        total += deaths
        if each is not None:
            each[name] = deaths
        parts.append(f"{name}: {how}")
    return total, (f"{total:.3f} totems die a second: " + "; ".join(parts)
                   + " (RESEARCH31 R31-2: expiring or being replaced counts as dying, MEDIUM; the boss killing totems "
                     "isn't counted: no source gives a rate, a LOW row at 0)")


# Unnamed Heartwood (MECHB39; the Druid's ascendancy notable AscendancyDruid1Notable6: "+1 to maximum number of Summoned
# Totems" (PoB parses it) and "Totems die 6 seconds after their Life is reduced to 0" (last_tremor_duration_ms 6000;
# PoB ModCache 9641: no mod). The second line acts only when something brings a totem's Life to 0: the boss killing
# totems, which totem_deaths doesn't count (no source gives a rate; R31-2 a LOW row). So no number moves: a labelled
# note, with the row a boss-kill rate would give (each totem it kills keeps acting 6 s more, and dies 6 s later).
LAST_TREMOR = re.compile(r"^Totems die (\d+(?:\.\d+)?) seconds after their Life is reduced to 0$", re.I)


def last_tremor_notes(texts: list[str]) -> list[dict]:
    """Unnamed Heartwood's "Totems die N seconds after their Life is reduced to 0": a labelled no-change note."""
    seconds = max((float(m.group(1)) for t in texts if (m := LAST_TREMOR.match(t.strip()))), default=0.0)
    if seconds <= 0:
        return []
    return [{"label": f"Totems die {seconds:g} s after their Life reaches 0 (Unnamed Heartwood)*", "value": "no change",
             "basis": (f"it acts only when something brings a totem's Life to 0: the boss killing your totems, which isn't "
                       "counted (no source gives a rate: RESEARCH31 R31-2, a LOW row at 0), so no number moves. If the "
                       f"boss kills totems, each keeps acting {seconds:g} s more before it dies (its death, and Soul "
                       f"Mantle's curse, {seconds:g} s later). Totems expiring or replaced (models.totem_deaths) aren't "
                       "brought to 0 Life"),
             "play": "Unnamed Heartwood's second line matters only when the boss kills your totems; place them out of its "
                     "attacks either way.",
             "confidence": "LOW"}]


# Tawhoa's Vengeance (MECHB40; MECHB39's probe POE2T3395: PoB scores it 0). The lineage support Tawhoa's Tending
# (SupportHardyTotemsPlayerThree: support_totem_life_+%_final 25, support_hardy_totems_trigger_splinter_explosion_on_death_
# chance_% 100) grants it: "Deals Physical Damage in an area, based on Totem Life" (TriggeredSplinterExplosionHardyTotems:
# base_physical_damage_equal_to_%_of_totem_life 20, triggered_on_death_% 100, radius 3 m). PoB has the skill but gives
# it no base damage and no trigger rate (checked: the stat id appears in vendor PoB src only in sup_str.lua and its stat
# description file, so no code reads it; probes POE2T3395 / POE2T4602 score it 0 without a base). So each
# death of a totem from the supported skill's group (models.totem_deaths' own count for that skill, `each`) sets off one
# explosion of 20% of that totem's Life (the bridge's useRates totemLife on the totem-summoning skill: PoB's TotemLife,
# with Tawhoa's Tending's 25% more; the totem's own skill's row lacks the support) as base Physical, scored by PoB as the
# group's own triggered hit (so the build's modifiers, crit and the boss's armour apply): SkillData PhysicalMin / Max and
# triggerRate, its group counted in Full DPS. Probe POE2T4602: Shockwave Totem, 3,113 Life, 0.0625/s: +16.7 DPS.
# Labelled: "Totem Life" read as the totem's maximum Life (MEDIUM; RESEARCH asked); a totem expiring or replaced counts
# as dying (RESEARCH31 R31-2, MEDIUM; without it, only totems the boss kills, not counted: 0, the "without it" row); the
# boss inside the 3 m blast (MEDIUM: totems placed at the boss, as totem_count_model).
TAWHOA = "Tawhoa's Vengeance"
TAWHOA_SHARE_STAT = "base_physical_damage_equal_to_%_of_totem_life"
TAWHOA_SHARE = 20.0  # (the game files' and PoB's value, every level; read from the skill's stats when given)


def tawhoa_model(skills: list[Skill], rows: dict[str, dict], deaths: dict[str, float],
                 deaths_how: str = "") -> tuple[list[dict], list[dict], set[int]]:
    """Tawhoa's Vengeance's explosions (see above): (mods, notes, groups to count in Full DPS). `rows`: {totem skill
    name: its useRates row (totemLife)}; `deaths`: {totem skill name: its totems' deaths a second} (totem_deaths' each)."""
    best = None
    for vengeance in (s for s in skills if s.name == TAWHOA and s.group is not None):
        summoner = next((s for s in skills if s.group == vengeance.group and s.totem_limit > 0), None)
        if summoner is None:
            continue
        life = number((rows.get(summoner.name) or {}).get("totemLife"))
        rate = number(deaths.get(summoner.name))
        share = number(vengeance.level_stats.get(TAWHOA_SHARE_STAT)) or TAWHOA_SHARE
        if best is None or rate * life * share > best[1] * best[2] * best[3]:
            best = (vengeance, rate, life, share, summoner)
    if best is None:
        return [], [], set()
    vengeance, rate, life, share, summoner = best
    base = share / 100 * life
    label = f"{TAWHOA}: a blast each time a {summoner.name} totem dies*"
    if rate <= 0 or base <= 0:
        why = ("no totem Life read" if base <= 0 else "none of its totems die (no duration read)")
        return [], [{"label": label, "value": 0, "basis": f"{why}: 0 (as PoB scores it)" + (f"; {deaths_how}" if deaths_how else ""),
                     "confidence": "MEDIUM"}], set()
    mods = [{"kind": "SkillData", "skill": TAWHOA, "key": "PhysicalMin", "value": _round(base)},
            {"kind": "SkillData", "skill": TAWHOA, "key": "PhysicalMax", "value": _round(base)},
            *trigger_rate(TAWHOA, rate)]
    note = {"label": label, "value": f"{rate:.3f} a second, {base:,.0f} base Physical each",
            "basis": (f"{share:g}% of the {summoner.name} totem's {life:,.0f} Life (PoB's totem Life with the build's "
                      f"modifiers and Tawhoa's Tending's 25% more: its maximum Life, HIGH, R33-14's game text \"20% of Totem's maximum Life\") as base Physical, "
                      f"scored by PoB as the group's own hit with the build's modifiers; {rate:.3f} of its totems die a "
                      "second (models.totem_deaths: expiring or replaced counts as dying, RESEARCH31 R31-2, MEDIUM)"
                      + (f"; {deaths_how}" if deaths_how else "") + "; the boss inside its 3 m blast (totems placed at "
                      "the boss, MEDIUM). PoB alone gives it no damage (0)"),
            "play": (f"Place {summoner.name} totems at the boss and re-place them as they expire: each one that dies "
                     f"explodes. Without it (if only totems the boss kills explode): 0 from {TAWHOA}"),
            "confidence": "MEDIUM"}
    return mods, [note], {vengeance.group}


# Fiery Death (MECHB65; COV58 rows 23 / 38, an UNDERCOUNT where adds die). The support (SupportFieryDeathPlayer:
# chance_to_trigger_fiery_death_on_ignited_enemy_death_% 60) makes "enemies it Ignites ... have a chance to explode on
# death": its triggered skill (TriggeredFieryDeathPlayer: triggered_by_fiery_death_support_% 100,
# corpse_explosion_monster_life_% 10, radius 2 m; game files 26650308) goes off when an enemy the supported skill Ignited
# dies. The boss's own death ends the fight, so only adds feed it: the boss preset's adds killed a second (kill_rate;
# 0 on a lone boss, every add taken as killed by the build, LOW) x the share the supported skill Ignited (PoB's
# IgniteChancePerHit for its group, one hit before the add dies, read against the boss's Ailment Threshold: RESEARCH60
# R60-14, MEDIUM: a monster's threshold is a per-level base (DefaultMonsterStats; 74,191 at level 83), not its Life, so
# an add and the boss at the same level match; a boss 1-2 levels above its adds has a 3.7-7.5% higher one, the row) x
# the support's 60%. Each explosion: PoB's Fiery Death hit for its group (AverageHit
# with the build's modifiers; the 10% of the dying add's Life read as PoB reads it, LOW), every one reaching the boss
# (LOW: the add dies somewhere near it, the blast 2 m, as Combust's). Added beside PoB's numbers (added_input):
# objective.ON_DEATH takes PoB's own Fiery Death entry out of Full DPS (it matches the support's description), so this
# never counts twice.
FIERY_DEATH = "Fiery Death"
FIERY_DEATH_CHANCE_STAT = "chance_to_trigger_fiery_death_on_ignited_enemy_death_%"
FIERY_DEATH_CHANCE = 60.0  # (the game files' and PoB's value; the support's stat when given)
FIERY_DEATH_LEVEL_ROW = 1.075  # (R60-14: a boss 2 levels above its adds, its Ailment Threshold 7.5% higher)


def fiery_death_model(adds: float, adds_how: str, ignite_pct: float, chance_pct: float, hit: float,
                      source: str) -> tuple[float, dict]:
    """(added DPS, note) for Fiery Death (above). `adds` adds killed a second, `ignite_pct` the supported skill's
    IgniteChancePerHit, `chance_pct` the support's trigger chance, `hit` PoB's Fiery Death AverageHit, `source` the
    supported skill."""
    label = f"{FIERY_DEATH}: Ignited adds exploding on death ({source})*"
    ignited = min(max(ignite_pct, 0.0), 100.0) / 100
    chance = min(max(chance_pct or FIERY_DEATH_CHANCE, 0.0), 100.0) / 100
    rate = max(adds, 0.0) * ignited * chance
    upper = max(adds, 0.0) * min(1.0, ignited * FIERY_DEATH_LEVEL_ROW) * chance * max(hit, 0.0)  # (R60-14's row)
    if rate <= 0 or hit <= 0:
        why = ("no enemy dies before the boss (a lone boss): the boss's own death ends the fight" if adds <= 0 else
               f"{source} doesn't Ignite (PoB's chance 0 against the boss's Ailment Threshold, which an add at its "
               "level shares: RESEARCH60 R60-14, MEDIUM)" if ignited <= 0 else
               "PoB gives its explosion no hit")
        return 0.0, {"label": label, "value": 0, "confidence": "LOW",
                     "basis": f"{why}: 0 (PoB's own Fiery Death entry is left out of Full DPS as on-death damage)"}
    added = rate * hit
    return added, {"label": label, "value": round(added, 1), "confidence": "LOW",
                   "basis": (f"{adds:.3f} adds killed a second ({adds_how}) x {ignited:.0%} Ignited by {source} (PoB's "
                             f"chance a hit against the boss's Ailment Threshold, a per-level base an add at its level "
                             f"shares: RESEARCH60 R60-14, MEDIUM) x {chance:.0%} = {rate:.3f} explosions "
                             f"a second x {hit:,.0f} a hit (PoB's Fiery Death hit; the dying add's Life as PoB reads it, "
                             f"LOW), each reaching the boss (LOW). Row: the boss 2 levels above its adds (its threshold "
                             f"7.5% higher, R60-14): +{upper:,.1f} DPS"),
                   "play": f"Ignite the boss's adds with {source}: each one that dies Ignited may explode on the boss."}


# Minions the build kills itself are dead part of the fight (MECHB40; PLANS term-persistent-minions item 4, an OVERCOUNT:
# minion_deaths counted their deaths for Energy / buffs / corpses, but every Reviving minion's damage stayed counted as
# always alive). A Reviving minion Killed lies dead until it revives (KeywordPopups Reviving; revive_seconds: the game's
# 7.5 s constant with PoB's MinionRevivalSpeed, MEDIUM; the skills' own 12 s base the other row). With N Reviving minions
# Killed k times a second by the build's own sources (minion_deaths: Sacrifice's corpse uses, Minion Pact, Explosive
# Demise; capped by revival), each death costs T s of one minion, so the share alive = 1 - deaths x T / N = N / (N + T k).
# Counted as "Minions deal X% more Damage" (negative) on each Reviving minion skill (the Unearth count's form): their hits
# and ailments alike (MEDIUM: deaths spread evenly over all Reviving minions, though Sacrifice takes only undead ones and
# Explosive Demise only non-Arsonists). Not counted (labelled): forced revives (Skeletal Cleric, Offerings, Mana Flask:
# an undercount of the share alive), the boss killing minions (no rate). No death source: no line.
# Forced revives (forced_revives; plans/term-persistent-minions.md item 1) bring a fallen minion back at once, each at the
# build's own rate (CLAUDE.md: no flat rate): Skeletal Clerics' Revive (ResurrectSkeletonClericMinion: "Revive a fallen
# Skeleton", cooldown 5 s, cast 1.2 s; game files 26650308) one per Cleric per 5 s while a Skeleton is fallen (the
# minions' own Cooldown Recovery not read, MEDIUM); Replenishing Horde's "N% Chance to revive a random Permanent Minion
# whenever you use a Command Skill" x the build's Command uses (command_uses, each on its cooldown: a play strategy);
# "One of your Persistent Minions revives when an Offering expires" (Citaqualotl's Thesis) at each Offering's base
# duration (OFFERING_SECONDS, recast as it ends, as PoB keeps it up); "Using a Mana Flask revives one of your Persistent
# Minions" at the Mana flask's uses a second (flasks.uses_per_second; Assumptions passes it). The dead count is then
# max(0, deaths - forced) x T: each forced revive takes one dead minion off the floor (MEDIUM: taken to find one).
CLERIC_REVIVE = (5.0, 1.2)  # (cooldown s, cast s): ResurrectSkeletonClericMinion
REPLENISHING = re.compile(r"^(\d+(?:\.\d+)?)% Chance to revive a random Permanent Minion whenever you use a Command Skill$",
                          re.I)
OFFERING_REVIVE = re.compile(r"^One of your Persistent Minions revives when an Offering expires$", re.I)
MANA_FLASK_REVIVE = re.compile(r"^Using a Mana Flask revives one of your Persistent Minions$", re.I)


# Eternal March (MECHB41; a runeforged gem the search offers, PoB 0: base_deal_no_damage, and no PoB code reads its two
# stats, checked: skill_eternal_march_* appear in vendor PoB src only in Data/Skills/other.lua EternalMarchPlayer).
# "Spend Runic Ward to instantly Revive your Minions. Prioritises the most powerful minions first"; skill_stat_descriptions:
# "Spends up to {0} Runic Ward to Revive Minions with total maximum Life equal to {1} times the Runic Ward spent" (level
# 20: 853 Ward, 20 x; quality "Spends up to {0} additional Runic Ward"); 4 s cooldown, Instant. A forced revive: each use
# brings back (Ward spent x the multiple) / the Reviving minions' maximum Life of them (their average; the most powerful
# first isn't modelled: MEDIUM), at its use rate (press_use_rate: on its cooldown), the Ward spent being what the build's
# Runic Ward pays for (ward_paid counts it as a WardUse of its own "revive" kind beside the Ward-cost skills: one share for
# all; the previous model round's share, the first round PoB's regeneration over its planned spend). No Reviving minion
# Life read: 0, labelled. Fractions of a minion a use are kept (an average over uses).
ETERNAL_MARCH = "Eternal March"
EM_WARD, EM_LIFE = "skill_eternal_march_maximum_ward_cost", "skill_eternal_march_life_per_ward_spent_%"


def eternal_march_revives(skill: Skill, uses: float, ward_share: float, life: float,
                          pool: list[tuple[str, float, float]] | None = None) -> tuple[float, str]:
    """(minions revived a second, how) by Eternal March used `uses` times a second, paying `ward_share` of its full Ward
    a use, for Reviving minions of `life` maximum Life (their average). `pool` (MECHB42, R33-15): (name, maximum Life,
    dead ones waiting a use) for each Reviving minion kind; then the Life budget goes to the highest-Life dead first
    ("Prioritises the most powerful minions first", Life as the proxy for power: MEDIUM, "powerful" undefined), at most
    the dead waiting (a revive needs a fallen minion, MEDIUM-HIGH); the average-Life count is the note's row."""
    ward = number(skill.level_stats.get(EM_WARD))
    multiple = number(skill.level_stats.get(EM_LIFE)) / 100
    if ward <= 0 or multiple <= 0 or uses <= 0:
        return 0.0, f"{ETERNAL_MARCH}: not used or its stats unread (0)"
    if life <= 0:
        return 0.0, f"{ETERNAL_MARCH}: its minions' Life wasn't read (0, labelled)"
    spent = ward * min(max(ward_share, 0.0), 1.0)
    average = spent * multiple / life
    head = (f"{ETERNAL_MARCH} {uses:.3f} uses/s, each spending {spent:,.0f} of up to {ward:,.0f} Runic Ward (what the "
            f"build's Ward pays for) to revive {multiple:g} x that in minion Life")
    if pool is None:
        return uses * average, (f"{head}: {average:.2f} minions of {life:,.0f} Life a use ({uses * average:.2f}/s; the "
                                "most powerful first not modelled, MEDIUM)")
    budget, each, taken = spent * multiple, 0.0, []
    for name, own, dead in sorted(pool, key=lambda p: -p[1]):
        if own <= 0 or dead <= 0 or budget <= 0:
            continue
        n = min(dead, budget / own)
        budget -= n * own
        each += n
        taken.append(f"{n:.2f} {name} ({own:,.0f} Life)")
    return uses * each, (f"{head}, the highest-Life fallen first (R33-15; Life as the measure of power, MEDIUM): "
                         f"{' + '.join(taken) or 'none fallen'} = {each:.2f} a use ({uses * each:.2f}/s; at the average "
                         f"{life:,.0f} Life with no cap by the fallen: {average:.2f} a use, the upper row)")


def cleric_revives(skills: list[Skill]) -> float:
    """Skeletal Clerics' revives a second (one each per CLERIC_REVIVE cooldown) where the build has another Persistent
    Skeleton for them, else 0."""
    clerics = sum(number(s.summon.get("limit")) for s in skills if s.summon and "Skeletal Cleric" in s.name)
    if clerics > 0 and any(is_skeleton(s) and s.summon.get("persistent") and "Skeletal Cleric" not in s.name
                           for s in skills if s.summon):
        return clerics / max(CLERIC_REVIVE)
    return 0.0


def cleric_excess(skills: list[Skill], reviving: list[Skill], deaths: float) -> tuple[float, str]:
    """(the Clerics' revives a second that find no fallen Skeleton, how): R33-15 (RESEARCH33, revive-targets-eternal-
    march.md, HIGH as text): a Skeletal Cleric "revive[s] fallen Skeletons" only, and a revive needs a dead minion
    (MEDIUM-HIGH). With deaths spread over the Reviving minions by their count (minion_deaths' MEDIUM reading), the
    Skeletons' deaths are `deaths` x their share; the Clerics' rate above that is lost. MECHB42: before, their revives
    counted against every minion's deaths (Zombies, Spectres too): an OVERCOUNT in a mixed army."""
    clerics = cleric_revives(skills)
    count = sum(number(s.summon.get("limit")) for s in reviving)
    if clerics <= 0 or count <= 0:
        return 0.0, ""
    share = sum(number(s.summon.get("limit")) for s in reviving if is_skeleton(s)) / count
    excess = max(0.0, clerics - max(deaths, 0.0) * share)
    return excess, (f"the Clerics revive only fallen Skeletons ({share:.0%} of your Reviving minions, so at most "
                    f"{deaths * share:.2f} of their deaths a second; R33-15)" if excess > 0 else "")


def forced_revives(skills: list[Skill], texts: Iterable[str] = (), mana_uses: float = 0.0,
                   eternal: tuple[float, str] | None = None) -> tuple[float, list[str]]:
    """(fallen minions brought back a second by the build's own forced revives, the parts) (see above). `eternal`:
    Eternal March's (revives a second, how), eternal_march_revives."""
    texts = [t.strip() for t in texts]
    total, parts = 0.0, []
    if eternal is not None and eternal[1]:
        total += max(eternal[0], 0.0)
        parts.append(eternal[1])
    rate = cleric_revives(skills)
    if rate > 0:
        clerics = sum(number(s.summon.get("limit")) for s in skills if s.summon and "Skeletal Cleric" in s.name)
        total += rate
        parts.append(f"{clerics:g} Skeletal Clerics revive a fallen Skeleton each every {max(CLERIC_REVIVE):g} s "
                     f"({rate:.2f}/s)")
    chance = sum(float(m.group(1)) for t in texts if (m := REPLENISHING.match(t))) / 100
    if chance > 0:
        uses, _ = command_uses(skills)
        total += chance * uses
        parts.append(f"Replenishing Horde: {chance:.0%} of {uses:.2f} Command uses a second ({chance * uses:.2f}/s)")
    if any(OFFERING_REVIVE.match(t) for t in texts):
        offered = [n for n in dict.fromkeys(s.name for s in skills if s.name in OFFERING_SECONDS and s.group is not None)]
        rate = sum(1 / OFFERING_SECONDS[n] for n in offered)
        total += rate
        parts.append(f"an Offering expiring ({', '.join(offered) or 'none in the build'}: {rate:.2f}/s)")
    if mana_uses > 0 and any(MANA_FLASK_REVIVE.match(t) for t in texts):
        total += mana_uses
        parts.append(f"a Mana Flask use ({mana_uses:.2f}/s)")
    return total, parts


def minion_alive_model(skills: list[Skill], main: Skill | None, stats: dict, texts: Iterable[str] = (),
                       mana_uses: float = 0.0) -> tuple[list[dict], list[dict]]:
    """(mods, notes): the build's Reviving minions' damage x the share of the fight they're alive (see above)."""
    reviving = [s for s in skills if s.summon and s.summon.get("persistent") and not number(s.summon.get("duration"))]
    count = sum(number(s.summon.get("limit")) for s in reviving)
    if count <= 0:
        return [], []
    rate, how = minion_deaths(skills, main, stats)
    if rate <= 0:
        return [], []
    revive, revive_how = revive_seconds(reviving)
    forced, forced_parts = stats.get(FORCED_REVIVES_STAT) or forced_revives(skills, texts, mana_uses)
    excess, excess_how = cleric_excess(skills, reviving, rate)  # (MECHB42, R33-15: Clerics revive Skeletons only)
    forced = max(0.0, number(forced) - excess)
    forced_parts = list(forced_parts) + ([excess_how] if excess_how else [])
    dead = min(max(0.0, rate - forced) * revive / count, 1.0)
    alive = 1.0 - dead
    names = list(dict.fromkeys(s.name for s in reviving))
    mods = [line("Minions deal 1% more Damage", -100.0 * dead, skill=name) for name in names] if dead > 1e-4 else []
    own = sum(number(s.summon.get("limit")) * (number(s.summon.get("reviveBase")) or RESUMMON_SECONDS)
              for s in reviving) / count
    slow = ""
    if own > RESUMMON_SECONDS + 1e-6:
        t12 = revive * own / RESUMMON_SECONDS
        k = count * rate / (count - revive * rate) if count > revive * rate else rate  # (the kills before the cap)
        alive12 = 1 - min(max(0.0, count * k / (count + t12 * k) - forced) * t12 / count, 1.0) if k > 0 else 1.0
        slow = f"; with the skills' own {own:.3g} s base: {alive12:.0%} alive"
    note = {"label": "Your Reviving minions alive (the build kills its own)*", "value": f"{alive:.0%} of the fight",
            "basis": (f"{rate:.3f} of your {count:g} Reviving minions die a second ({how}); each lies dead {revive:.3g} s "
                      f"({revive_how}), so {rate:.3f} x {revive:.3g} / {count:g} = {dead:.0%} of them are dead on "
                      f"average: their damage x{alive:.2f} ({', '.join(names)}){slow}"
                      + (f"; forced revives {forced:.2f}/s bring fallen ones back at once ({'; '.join(forced_parts)}), "
                         f"so {max(0.0, rate - forced):.3f} x {revive:.3g} / {count:g} dead" if forced > 0 else "")
                      + ". MEDIUM: deaths spread evenly over them; each forced revive taken to find a fallen minion. "
                      "PoB counts them alive all fight (an OVERCOUNT before)"),
            "play": (f"Without sacrificing your minions they'd all be alive; with it {alive:.0%} are on average. Keep "
                     "more minions than the build kills, or a revive source, to keep their damage up"),
            "confidence": "MEDIUM"}
    return mods, [note]


# "Minions have N% Surpassing chance to fire an additional Projectile" (MECHB39; the Genesis Tree belt mods
# GenesisTreeBeltMinionAdditionalProjectileChance and its Crafted copy): PoB's ModCache 8704 reads it as a minion
# ProjectileCount with leftover text, never applied (probe POE2T3394: no minion projectile wording parses whole either).
# On a lone boss an extra projectile adds no hit: the game's Projectile group rule, "only one Projectile in the group can
# hit each target unless otherwise specified" (RESEARCH29 R29-1), and the "otherwise" is projectiles_can_shotgun, which
# no player minion skill carries (checked: game files 26650308, GrantedEffectStatSets Implicit / Constant / Static
# stats: IncendiaryShot, FragmentationRounds, PermafrostBolts, GalvanicShards, ComboKnifeThrow, IceFragments and three
# monster sets only; Mods and PassiveSkills: none; patch notes: no hit, not evidence of absence). So no number moves on a
# boss: a labelled note (adds and chains / pierce off other targets aren't modelled).
MINION_EXTRA_PROJECTILE = re.compile(r"^Minions have \+?(\d+(?:\.\d+)?)% Surpassing chance to fire an additional "
                                     r"Projectile$", re.I)


def minion_projectile_notes(texts: list[str]) -> list[dict]:
    """The minions' extra-projectile chance: no hit added on a lone boss (see above), a labelled note."""
    chance = sum(float(m.group(1)) for t in texts if (m := MINION_EXTRA_PROJECTILE.match(t.strip())))
    if chance <= 0:
        return []
    return [{"label": "Minions' extra Projectile chance on the boss*", "value": "no change",
             "basis": (f"+{chance:g}% Surpassing chance (about {chance / 100:.2f} extra Projectiles a use): against a lone "
                       "boss only one Projectile of a group can hit it (KeywordPopups 74; RESEARCH35 R35-15: a "
                       "non-crossbow skill's extra projectiles fire in a spread, one group, MEDIUM) unless the skill "
                       "can shotgun, and no player minion skill can (game files). PoB doesn't apply the line either. "
                       "With adds (not modelled) the extra Projectiles would hit other targets"),
             "play": "", "confidence": "MEDIUM"}]  # (MECHB45: R35-15's table, the rule's wording; no test)


def splinter_model(main: Skill, group: list[Skill], stats: dict) -> tuple[list[dict], list[dict]]:
    """Splinter Totem's splinters as a DPS factor on the main skill (see above, R26-76)."""
    carrier = next((s for s in group if number(s.support_stats.get(TOTEM_SPLINTER_STAT)) > 0), None)
    speed_now = number(stats.get("Speed"))
    if carrier is None or speed_now <= 0:
        return [], []
    support = carrier.support_stats
    times = number(support.get(TOTEM_SPLINTER_STAT))
    actions = number(support.get(SPLINTER_ACTIONS_STAT)) or 1.0
    damage = number(support.get(SPLINTER_DAMAGE_STAT)) or -20.0
    speed = number(support.get(SPLINTER_SPEED_STAT)) or -10.0
    summoner = next((s for s in group if s.totem_limit > 0), None)
    place = (summoner.cast_time if summoner is not None and summoner.cast_time else 1.0)
    low, high, how = splinter_factor(times, actions, damage, speed, 1 / speed_now, place)
    return [raw_mod("DPS", "MORE", 100 * (low - 1), main.name)], [{
        "label": f"{main.name}: Splinter Totem's splinters*", "value": f"x{low:.3f}",
        "basis": how + f"; counted: x{low:.3f}, the lower reading (whether a stage's totems act at once is UNVERIFIED); "
                       "two totems a splinter and the smallest dying after acting: ASSUMED (LOW-MEDIUM, RESEARCH26 R26-76, "
                       "forum 3885913); placing again takes the totem skill's base cast time (LOW); ailments stay one "
                       "totem's",
        "play": (f"Place the totem again once its smallest splinters die. Stays one totem (PoB): x1; splinters one "
                 f"after another: x{low:.3f}; all at once: x{high:.3f}"),
        "confidence": "LOW"}]


def one_totem_ailments(main: Skill, group: list[Skill]) -> tuple[list[dict], list[dict]]:
    """PoB's ailment stacks for a one-totem support's skill held to one totem (A24-3, see above)."""
    count = main.ailment_totems
    if not count or count.get("override") is not None or number(count.get("limit")) <= 1:
        return [], []
    limit = number(count["limit"])
    splinter = any(number(s.support_stats.get(TOTEM_SPLINTER_STAT)) > 0 for s in group)
    return [raw_mod("ActiveTotemLimit", "BASE", 1 - limit, main.name, tag=TOTEM_ONE_TAG)], [{
        "label": f"{main.name}: one totem's ailments*", "value": 1,
        "basis": f"A support makes it \"only have one active Totem\" (number_of_totems_allowed_is_1); PoB multiplied its "
                 f"Ignite / Poison / Bleed stacks by its Totem Limit {limit:g} (CalcOffence 5264): held to 1"
                 + ("; Splinter Totem's splinters' own ailments not counted (their hits: the splinters row)"
                    if splinter else ""),
        "confidence": "HIGH (the support's own text)" if not splinter else "MEDIUM (splinters' ailments not counted)"}]


# Minion Pact's damage when no minion is left (AUDIT23 A23-2's other half, MECHB11; an OVERCOUNT): PoB gives the 30% /
# 35% more (support_minion_pact_damage_+%_final) whenever a minion is in your Presence (MinionPresenceCount >= 1,
# PoB's sup_int.lua), and the bridge's Presence count doesn't fall as Minion Pact kills them. The game's text ties the
# damage to the removal: "remove 100% of your maximum Life from a nearby Minion on use to deal 30% more damage"; with no
# minion left to take it from, the use gets none (the text's reading, MEDIUM). With N Reviving minions, revival T and
# attempted kills k per second (minion_deaths' sources), a use finds a minion N / (N + T k) of the time (the share of
# kills the revival lets through); the bonus is held to that share: (1 + p share) / (1 + p) as a Damage MORE. Left as PoB
# has it: no minions (PoB's count is 0, no bonus either) and builds with temporary minions too (they feed it as well;
# their supply isn't modelled, so no cut on a guess).
def minion_pact_model(skills: list[Skill], main: Skill | None, stats: dict) -> tuple[list[dict], list[dict]]:
    if main is None:
        return [], []
    pact = number(main.support_stats.get(MINION_PACT_STAT))
    more = number(main.support_stats.get("support_minion_pact_damage_+%_final"))
    uses = number(stats.get("Speed"))
    if pact <= 0 or more <= 0 or uses <= 0:
        return [], []
    rate, how = minion_deaths(skills, main, stats)
    reviving = [s for s in skills if s.summon and s.summon.get("persistent") and not number(s.summon.get("duration"))]
    count = sum(number(s.summon.get("limit")) for s in reviving)
    if count <= 0 or any(s.summon and s not in reviving for s in skills):
        return [], []  # (none: PoB's Presence count is 0 too; temporary minions also feed it: their supply isn't modelled)
    revive, _ = revive_seconds(reviving)
    kills = count * rate / max(count - revive * rate, 1e-9)  # (minion_deaths' rate solved back for its kills)
    share = count / (count + revive * kills)
    why = (f"{count:g} Reviving minions, each back {revive:.3g} s after the last death, against {kills:.2f} "
           f"attempted kills/s: a minion is there for {share:.0%} of uses")
    if share >= 0.999:
        return [], []
    scale = (1 + more / 100 * share) / (1 + more / 100)
    return [raw_mod("Damage", "MORE", 100 * (scale - 1), main.name)], [{
        "label": f"Minion Pact: a minion to take Life from*", "value": f"{share:.0%} of uses",
        "basis": f"{why}. PoB counts its {more:g}% more on every use while a minion is in your Presence; the gem gives it "
                 f"for removing a minion's Life, so x{scale:.3f}. Without Minion Pact the minions aren't killed "
                 f"this way. ({how})",
        "confidence": "MEDIUM-LOW (the minions' Life read, pact_uses_per_kill; the damage-per-removal reading of the gem's text)"}]


# Poison Spores' Pustule Explosion (MECHB10; COVC12's finding, POE2T1425) ---------------------------------------------------
# The game: "Each enemy can have up to 1 Pustule attached" (statset_0.csd, skill_specific_stat_description_mode 1) and the
# Pustule "Detonates after a delay" (base_skill_detonation_time 15000 ms) (checked: the game files' poison_spore_support
# statset_0 / statset_1 .csd and PoB's sup_dex.lua TriggeredPoisonSporesPustule; poe2db Poison_Spores, 12 Nov 2026: "Each
# enemy can have up to 1 Pustule attached", "Detonation Time is 15 seconds"). PoB scores the Pustule Explosion set as an
# attack used at the weapon's rate (1.2/s on a bow, POE2T1425): against a lone boss at most one explodes per fuse, so its
# damage is held to (1 / fuse) / PoB's rate. The fuse is PoB's DetonationTime (base x the build's Detonation Time lines).
# Not counted (UNDERCOUNT side, labelled): Poison stored on the Pustule makes it expire faster
# (toxic_pustule_duration_expires_1%_faster_per_x_stored_poison_damage_multiplied_by_sixty) and burst harder (up to 300%
# more, toxic_pustule_burst_1%_more_damage_per_x_stored_poison); PoB reads neither (checked: grep of PoB's
# Data/SkillStatMap.lua and Modules/*.lua for "toxic_pustule": none). Whether the build's Poisons on the boss count as
# Poisons "inflicted on" the Pustule is UNVERIFIED, so the speed-up isn't guessed. Pustules on adds that burst next to the
# boss are left out (a lone boss).
# Toxic Domain (AUDIT23 A23-1): the same rule, "Each enemy can have up to 1 Pustule attached" (toxic_domain/statset_0.csd,
# its mode 1) and base_skill_detonation_time 15000 on its Pustule Explosion set (PoB's act_dex.lua ToxicDomainPlayer).
# Each skill is held to its own one Pustule: whether Spores' and Domain's Pustules share the one slot is UNVERIFIED (a
# build with both would count up to two).
# Toxic Growth (MECHB14, an OVERCOUNT): its Pustules lie on the ground under a Limit, not one per enemy. Game files:
# "Fires 5 Pustules" (base_number_of_projectiles 5), "[Limit] 5 pustules" (number_of_poisonbloom_arrow_bloom_allowed 5,
# +0.05 a quality), base_skill_detonation_time 15000 on both sets (toxic_growth statset_0 / statset_1 .csd; PoB's
# act_dex.lua ToxicGrowthPlayer the same); KeywordPopups Limit: "If a new effect is created while at the maximum number
# of effects, the oldest effect will dissapear" (it disappears; the text says nothing of a burst). So at most Limit
# Pustules burst per fuse: Limit / fuse a second (5 / 15 s = 0.33/s), reached only by firing no sooner than the fuse
# allows (one cast fills the Limit; firing again sooner replaces the waiting Pustules, so spamming it bursts none: the
# play row says so). PoB scores the Explosion set at the attack rate, one explosion a cast; it's held to
# min(1, (Limit / fuse) / PoB's rate). The Limit: the set's own stat with quality (calcLib.buildSkillInstanceStats) plus
# "+N to Limit" lines, which PoB maps to AdditionalCooldownUses (Overabundance I / II, the amulet line "Skills have +1 to
# Limit": SkillStatMap base_limit_+, ModCache) (checked: every Stats id holding "limit" with "+" / "additional" looked
# up in Mods, PassiveSkills, GrantedEffectStatSets(PerLevel), GrantedEffectQualityStats: base_limit_+ on
# SupportIncreaseLimitPlayer(Two) and UniqueBaseLimit1; plant_skill_limit_+ (Toxic Growth is a Plant skill) and
# virtual_total_limit_+ on none of them; the elemental / orb / storm / fissure / temporary-minion limits don't match the
# skill's types; second source PoB's ModItem / ModItemExclusive / sup_dex.lua). Each burst is taken as hitting the boss
# (Pustules land in a 4.5 m spread with a 0.8 m burst: how many reach a pinnacle boss is UNVERIFIED, so this is the
# upper bound, labelled). Not counted, as for the Spores: stored Poison's sooner / harder burst (an undercount), and the
# Pustules set's own impacts (5 a cast; PoB counts one: an undercount, not touched here).
PUSTULE_SKILL, PUSTULE_SET, PUSTULE_FUSE = "Poison Spores", "Pustule Explosion", 15.0
PUSTULE_SKILLS = (PUSTULE_SKILL, "Toxic Domain", "Toxic Growth")
PUSTULE_SETS = {"Toxic Growth": "Explosion"}  # (the others: PUSTULE_SET)
PUSTULE_LIMIT = {"Toxic Growth": 5}  # (base, when the bridge gives no pustuleLimit; the others: one per enemy)


def pustule_groups(skills: list[Skill], name: str = PUSTULE_SKILL) -> list[int]:
    """Groups whose `name` (a PUSTULE_SKILLS skill) PoB calculates at its Pustule Explosion set (Full DPS or main)."""
    label = PUSTULE_SETS.get(name, PUSTULE_SET)
    return sorted({s.group for s in skills if s.name == name and s.stat_set == label and s.group is not None})


# Stored Poison (MECHB15; AUDIT25 A25-8, a possibly large UNDERCOUNT): "Pustules store expected damage of [Poison|Poisons]
# inflicted on them" (poison_spore_support/statset_1.csd, toxic_domain/statset_1.csd), "Stored [Poison|Poison] grants up
# to {1}% more explosion Damage" (statset_0.csd: toxic_pustule_max_burst_damage_+%_final_from_stored_poison 300, on
# TriggeredPoisonSporesExplosion, ToxicGrowthPlayer, ToxicDomainPustuleExplosion), 1% more per X stored
# (toxic_pustule_burst_1%_more_damage_per_x_stored_poison: 2 at gem level 1, 969 at 20; GrantedEffectStatSetsPerLevel).
# ActiveSkills: Poison Spores "Attach a Toxic Pustule to the enemy ... They can also be [Poison|Poisoned], causing them
# to Detonate faster and more violently"; Toxic Domain "Pustules will Detonate after a duration or when enough [Poison]
# has been applied". poe2db (Poison_Spores, 12 Nov 2026) quotes the same lines and nothing more.
# Whether the Poisons a build inflicts on the boss are "inflicted on" the Pustule attached to it is UNVERIFIED (checked:
# the three skills' ActiveSkills descriptions, their statset .csd files, skill_stat_descriptions.csd, KeywordPopups (no
# Pustule entry), poe2db's Poison Spores / Toxic Growth / Toxic Domain pages, mobalytics' and poe2wiki's pages; no
# monster table for the Pustule is exported, so whether it is its own hittable object can't be read either). The text
# says "them", the Pustules, and nothing says hits on the carrier reach them. So the bonus isn't scored (accuracy
# first); it's sized as a "with it" row from the build's own Poison: stored over one fuse = PoB's PoisonDPS on the
# boss x the fuse (at steady stacks the expected damage of the Poisons inflicted each second equals the Poison DPS),
# more = min(max, stored / X). The sooner burst ("expires 1% faster per x stored poison damage multiplied by sixty":
# no game text, poe2db shows only the stat id; whether "x sixty" scales the stored damage or X is UNVERIFIED) isn't
# sized, so the row is a floor of the "with it" case on bursts, and an upper bound on what reaches the Pustule.
def pustule_stored(rates: list[dict], poison_dps: float, fuse: float) -> tuple[float, str]:
    """The stored-Poison "more" (percent) a Pustule would burst with if every Poison the build inflicts on the boss
    were stored in it over its fuse, and how (see above); 0 with no Poison or no stat read."""
    pers = [(number(r.get("storedPoisonPerPercent")), number(r.get("storedPoisonMaxMore"))) for r in rates
            if number(r.get("storedPoisonPerPercent")) > 0]
    if not pers or poison_dps <= 0 or fuse <= 0:
        return 0.0, ""
    per, top = min(pers)
    top = top or 300.0
    stored = poison_dps * fuse
    more = min(top, stored / per)
    return more, (f"{poison_dps:,.0f} Poison DPS x {fuse:.1f} s = {stored:,.0f} stored, 1% more per {per:,.0f}: "
                  f"+{more:.0f}% more (max {top:.0f}%)")


# (MECHB44; RESEARCH35 R35-4, toxic-growth-pustules-on-boss.md, and GEM25's lead (a)) Toxic Growth's ground Pustules land
# in a 4.5 m spread (the hidden secondary radius as the rain area, MEDIUM-LOW) and burst 0.8 m (+1.5 m with full stored
# Poison); of the Limit's n Pustules a fuse, k = min(n, max(1, n x ((r_boss + 0.8) / 4.5)^2)) reach the boss (the one
# aimed at it at least; spread evenly over the area: R35-4's formula, also GEM25's pustules_reaching for Accelerated
# Growth), so at most k bursts on the boss a fuse, not n (an OVERCOUNT of up to ~5x before on the small presets). Area
# modifiers scale the spread and the burst together (not read: their ratio barely moves). Rows: full stored Poison's
# +1.5 m burst (an undercount here: Toxic Growth's ground Pustules don't store the boss's Poisons, R26-79, so LOW) and
# every Pustule (the old reading). Boss arenas (MECHB45; RESEARCH35 R35-22, GEM26's routing): the May 2026 reports that
# Pustules don't burst in boss arenas stop after 31 May and Maxroll's 0.5.5 guide (8 Sep 2026) uses Toxic Growth on
# bosses, though no patch line names a fix: headline it works (MEDIUM-LOW), a "0 in boss arenas" row.
TOXIC_SPREAD, TOXIC_BURST, TOXIC_STORED_BURST = 4.5, 0.8, 1.5  # metres


def pustules_on_boss(n: float, radius: float, burst: float = TOXIC_BURST) -> float:
    """Of n ground Pustules a cast, those whose burst reaches a boss of `radius` metres (see above)."""
    return min(n, max(1.0, n * ((radius + burst) / TOXIC_SPREAD) ** 2))


def pustule_cap(rates: list[dict], name: str = PUSTULE_SKILL, poison_dps: float = 0.0,
                radius: float = 0.3) -> tuple[list[dict], list[dict]]:
    """The Pustule Explosion held to one a fuse (Poison Spores, Toxic Domain: one per enemy) or to its Limit a fuse
    (Toxic Growth) (see above). `rates`: bridge useRates for each group's `name` skill. `poison_dps`: PoB's PoisonDPS
    on the boss, for the stored-Poison harder burst (pustule_stored; scored for Poison Spores / Toxic Domain since MECHB34,
    R26-79)."""
    speed = sum(number(r.get("speed")) * (number(r.get("repeats")) or 1.0) for r in rates)
    if speed <= 0:
        return [], []
    fuses = [number(r.get("detonationTime")) for r in rates if number(r.get("detonationTime")) > 0]
    fuse = min(fuses) if fuses else PUSTULE_FUSE
    stored_more, stored_how = pustule_stored(rates, poison_dps, fuse)
    ground = name in PUSTULE_LIMIT
    stored_mods: list[dict] = []
    if stored_more > 0 and not ground:  # (MECHB34, R26-79: scored; Toxic Growth's ground Pustules aren't carried)
        stored_mods = [line("1% more Damage", stored_more, skill=name)]
        stored = [{
            "label": f"{name}: stored Poison's harder burst*", "value": f"x{1 + stored_more / 100:.2f} (without it: x1)",
            "basis": "The game: Pustules \"store expected damage of Poisons inflicted on them\" and burst up to 300% "
                     "harder; the Poisons you inflict on the boss are taken to reach the Pustule attached to it (ASSUMED, "
                     "LOW-MEDIUM, RESEARCH26 R26-79: Toxic Domain's own text, its Pustules \"can be Poisoned\" and are "
                     "only ever on enemies; Poison Spores \"can also be Poisoned\"; patch 0.4.0's shared rule): "
                     f"{stored_how}. Its sooner burst isn't sized (the stat's units are UNVERIFIED): bursting sooner "
                     "stores less per burst but bursts more often, not counted either way",
            "play": f"Poison the boss while its Pustule waits. Without it: x1; with it: the explosion x"
                    f"{1 + stored_more / 100:.2f}, sooner too",
            "confidence": "LOW-MEDIUM"}]
    else:
        stored = [] if stored_more <= 0 else [{
            "label": f"{name}: stored Poison's harder burst, not counted*",
            "value": f"x1 (with it: x{1 + stored_more / 100:.2f})",
            "basis": "Toxic Growth's Pustules are on the ground, hit directly, not attached to the boss: the Poisons you "
                     f"inflict on the boss don't reach them (RESEARCH26 R26-79). If they did: {stored_how}",
            "confidence": "LOW"}]
    limits = [number(r.get("pustuleLimit")) for r in rates if number(r.get("pustuleLimit")) > 0]
    limit = (max(limits) if limits else float(PUSTULE_LIMIT[name])) if ground else 1.0
    reach = pustules_on_boss(limit, radius) if ground else 1.0  # (MECHB44, R35-4: of the Limit, those reaching the boss)
    share = min(1.0, reach / fuse / speed)
    if share >= 1.0:
        return stored_mods, stored
    fuse_text = f"{fuse:.1f} s fuse{'' if fuses else ' (base; PoB gave no Detonation Time)'}"
    if ground:
        return [raw_mod("DPS", "MORE", 100 * (share - 1), name)] + stored_mods, [{
            "label": f"{name}: at most its Pustule Limit bursts a fuse*", "value": f"x{share:.3f}",
            "basis": f"PoB counts {speed:.2f} explosions/s; the game keeps {limit:g} Pustules at a time "
                     f"(Limit{'' if limits else ', base'}: a new one makes the oldest disappear), each bursting after "
                     f"its {fuse_text}, and of them {reach:.2f} burst on a {radius:g} m boss (a {TOXIC_SPREAD:g} m spread, "
                     f"{TOXIC_BURST:g} m bursts: RESEARCH35 R35-4, MEDIUM-LOW): at most {reach / fuse:.3f}/s. Rows: with "
                     f"full stored Poison's +{TOXIC_STORED_BURST:g} m burst "
                     f"{pustules_on_boss(limit, radius, TOXIC_BURST + TOXIC_STORED_BURST):.2f} a fuse (LOW: ground "
                     f"Pustules don't store the boss's Poisons, R26-79); every Pustule on the boss {limit:g} a fuse "
                     f"(x{min(1.0, limit / fuse / speed):.3f}, the old reading, an upper bound). Not counted (undercount "
                     "side): the Pustules' impacts beyond one. Boss arenas: taken to burst (RESEARCH35 R35-22, "
                     "MEDIUM-LOW: the May 2026 reports stop after 31 May, Maxroll's 0.5.5 guide uses it on bosses, no "
                     "patch line names a fix); row: if they still don't burst in boss arenas, 0 from the Pustules",
            "play": f"Fire {name} about once every {fuse:.0f} s and let its Pustules burst: firing again sooner "
                    "replaces the waiting ones (spammed, without the pacing: no bursts at all)",
            "confidence": "LOW-MEDIUM (game files give the Limit, the fuse and what the Limit does; the hits on the "
                          "boss are UNVERIFIED)"}] + stored
    return [raw_mod("DPS", "MORE", 100 * (share - 1), name)] + stored_mods, [{
        "label": f"{name}: one Pustule on the boss at a time*", "value": f"x{share:.3f}",
        "basis": f"PoB counts {speed:.2f} Pustule Explosions/s; the game allows one Pustule per enemy, bursting after its "
                 f"{fuse_text}: {1 / fuse:.3f}/s. Not "
                 "counted (undercount side): stored Poison making it burst sooner (its harder burst: the stored-Poison "
                 "row), and Pustules on adds",
        "confidence": "MEDIUM (game files and poe2db agree on one Pustule and the 15 s fuse)"}] + stored


# Runic Ward pays for Ward-cost skills (MECHB13; SEARCH7's Explosive Transmutation finding, an OVERCOUNT) ------------
# KeywordPopups Ward: "Runic Ward constantly regenerates at a default rate of 5% per second" (PoB: the game constant
# BaseWardRegenerationPercentPerMinute 300, as WardRegenPercent; WardRegenRecovery adds the build's regeneration and
# recovery modifiers). PoB charges each use its Runic Ward cost (CalcOffence's costs; WardCost) but checks only that the
# pool covers one use (WardCostWarningList), never how often the build can pay it, so a Ward-cost skill counts at its
# trigger / cast rate however little Ward the build regenerates. The skills with a Ward cost in PoB's data (Data/Skills/
# other.lua, `cost = { Ward = ... }`, 24 skills: the Transmutation Explosion, Frostflame Nova, Skyfall, Grim Pillars,
# Wardbound Minions, Refutation, Voltaic Barrier ...) plus any modifier that adds one; the bridge flags them
# (activeSkills wardCost) and prices one use (useRates wardCost, PoB's WardCost after multipliers).
# The rule (MEDIUM): over a long boss fight the sustained uses are what the regeneration pays for: every Ward-cost skill
# the build uses shares it, each held to its planned rate x min(1, regeneration / the Ward all of them would spend).
# Left out: the full pool at the start of the fight (pool / cost more uses once: an undercount, small over a long
# fight); Wardbound Minions' and Refutation's "spend all your Runic Ward" (their own models) beyond their listed cost.


@dataclass
class WardUse:
    """A Ward-cost skill's planned use: `kind` "triggered" (a model's triggerRate), "main" (the main skill at its PoB
    rate after the press hook), "pressed" (a pressed Full DPS group at its press rate) or "full" (another Full DPS group,
    at PoB's rate); `rate` uses a second; `cost` Runic Ward a use."""
    name: str
    kind: str
    rate: float
    cost: float
    group: int | None = None


WARD_ON_KILL = re.compile(r"recover (\d+(?:\.\d+)?)% of maximum runic ward on kill", re.I)
WARD_ON_MINION_KILLED = re.compile(r"recover (\d+(?:\.\d+)?)% of maximum runic ward when one of your reviving minions "
                                   r"is killed", re.I)
# Runic Ward recovery lines no rate reads yet (checked: every Stats.json id holding "ward" with recover / gain / regen /
# leech / restore / remnant / on_kill / when, each looked up in Mods, PassiveSkills, GrantedEffectStatSets(PerLevel) and
# GrantedEffectQualityStats; PoB's unique and mod text holding "Runic Ward"; second source PoB's ModParser): named in
# the note, never silently dropped (the user, 12 Nov: "regen is not the only source of recovery, not by a longshot")
# (MECHB14) Three of them now have a rate: Ward when a Charm is used (the charms' uses a second, flasks.uses_per_second),
# Life Recovery from Flasks applied to Ward (the Life flask's average recovery, flasks.recovery_per_second, in place of
# PoB's, which counts the flask as always running: CalcPerform 1642 adds flaskTotal / duration x the % as WardRecovery
# while its slot is active), and the Life sacrificed on Attack (half of it, at the build's attacks a second, no more than
# its Life recovery pays back). Still unread: "on reaching Maximum Rage" (how often the build refills its Rage is MECH-C's
# Rage model, conditions.rage_held, which gives no such rate yet: named, routed).
WARD_UNREAD = {
    "Runic Ward on reaching Maximum Rage": re.compile(r"runic ward on reaching maximum rage", re.I),
}
# (MECHB48; the manager 21:20 from MECHC48: Way of the Stonefist's glove form, "Recover (3-5)% of maximum Runic Ward on
# reaching Maximum Rage"; PoB nil, ModCache 9137) read at MECHC47's build.rage_max_reaches (reaches of the maximum a
# second, where the build climbs to it and loses all); with no such rate it stays in WARD_UNREAD (named, not counted).
WARD_ON_MAX_RAGE = re.compile(r"recover (\d+(?:\.\d+)?)% of maximum runic ward on reaching maximum rage", re.I)
WARD_ON_CHARM = re.compile(r"recover (\d+(?:\.\d+)?) runic ward when a charm is used", re.I)
WARD_FROM_FLASK = re.compile(r"(\d+(?:\.\d+)?)% life recovery from flasks also applies to runic ward", re.I)
WARD_SACRIFICE = re.compile(r"sacrifice (\d+(?:\.\d+)?)% of maximum life to gain half that much runic ward when you "
                            r"attack", re.I)


def ward_flask_percent(texts: list[str]) -> float:
    """The build's "N% Life Recovery from Flasks also applies to Runic Ward", summed (PoB's LifeFlaskRecoveryAppliesToWard)."""
    return sum(float(m.group(1)) for t in texts if (m := WARD_FROM_FLASK.search(t)))


def ward_income(regen: float, pool: float, texts: list[str], *, kalguur: dict | None = None, stuns: float = 0.0,
                stuns_how: str = "", kills: tuple[float, float] = (0.0, 0.0), on_block: float = 0.0, block: float = 0.0,
                every: float = 0.0, charm_uses: float = 0.0, charm_how: str = "", flask_life: float = 0.0,
                pob_flask_ward: float = 0.0, attacks: float = 0.0, life: float = 0.0,
                life_recovery: float = 0.0, rage_reaches: tuple | None = None) -> tuple[float, list[str], list[str]]:
    """Runic Ward a second from every source the build has (the user's rule, 12 Nov: not regeneration alone): PoB's
    WardRegenRecovery (regeneration, its recovery lines, Mana regeneration applied to Ward); Remnants of Kalguur
    (`kalguur`: its level stats, plus "multiplier", the build's extra Remnants / pickups) from `stuns` Stuns a second
    (chance each, at most one per its cooldown) and kills; Ward on Block (`on_block` x `block`% of the boss's hits, one
    every `every` s); "% of maximum Runic Ward on Kill" (`kills`: enemies killed / all kills a second, models.kill_rate)
    and on a Reviving Minion Killed (all kills less enemies); (MECHB14) Ward when a Charm is used (`charm_uses` a second,
    `charm_how`), Life flask recovery applied to Ward (`flask_life`, the Life flasks' average recovery a second, in place
    of PoB's always-running part `pob_flask_ward` inside `regen`), and Life sacrificed on Attack (`attacks` a second,
    of `life` maximum Life, no more than `life_recovery` a second pays back). (income, the parts, the lines no rate reads)."""
    flask_pct = ward_flask_percent(texts)
    regen = regen - (pob_flask_ward if flask_pct > 0 else 0.0)
    income, parts = max(regen, 0.0), [f"regeneration {max(regen, 0.0):.1f}/s (PoB's WardRegenRecovery"
                                      + (f", less its always-running flask part {pob_flask_ward:.1f}/s)"
                                         if flask_pct > 0 and pob_flask_ward > 0 else ")")]
    if flask_pct > 0 and flask_life > 0:
        income += flask_pct / 100 * flask_life
        parts.append(f"{flask_pct:g}% of Life flask recovery {flask_life:.1f}/s (as often as its charges allow)")
    charm = sum(float(m.group(1)) for t in texts if (m := WARD_ON_CHARM.search(t)))
    if charm > 0 and charm_uses > 0:
        income += charm * charm_uses
        parts.append(f"{charm:g} Ward a Charm use at {charm_uses:.3f} uses/s" + (f" ({charm_how})" if charm_how else ""))
    sacrifice = sum(float(m.group(1)) for t in texts if (m := WARD_SACRIFICE.search(t)))
    if sacrifice > 0 and attacks > 0 and life > 0:
        spent = sacrifice / 100 * life * attacks
        paid = min(spent, max(life_recovery, 0.0))
        income += paid / 2
        parts.append(f"half the Life sacrificed on Attack ({sacrifice:g}% of {life:,.0f} Life x {attacks:.2f} attacks/s = "
                     f"{spent:,.0f}/s" + (f", held to the {life_recovery:,.0f} Life/s the build recovers" if paid < spent
                                          else "") + f": {paid / 2:,.0f} Ward/s; MEDIUM-LOW)")
    if kalguur:
        gain = number(kalguur.get("ward_remnants_gain_per_globe"))
        chance = number(kalguur.get("ward_remnants_chance_to_spawn_remnant_on_stun_%")) / 100
        cooldown = number(kalguur.get("ward_remnants_spawn_remnant_on_stun_cooldown_ms")) / 1000
        on_kill = number(kalguur.get("ward_remnants_chance_to_spawn_orb_on_killing_enemy_%")) / 100
        more = number(kalguur.get("multiplier")) or 1.0
        from_stuns = 1.0 / (cooldown + 1.0 / (chance * stuns)) if stuns > 0 and chance > 0 else 0.0
        remnants = (from_stuns + on_kill * kills[0]) * more
        income += remnants * gain
        parts.append(f"Remnants of Kalguur {remnants:.3f}/s x {gain:g} Ward ({chance:.0%} a Stun at {stuns:.2f} Stuns/s"
                     + (f" [{stuns_how}]" if stuns_how else "") + ", "
                     f"at most one per {cooldown:g} s; {on_kill:.0%} a kill at {kills[0]:.3f} kills/s"
                     + (f"; x{more:.2f} the build's extra Remnants and pickups" if more != 1.0 else "") + ")")
    if on_block > 0 and block > 0 and every > 0:
        income += on_block * block / 100 / every
        parts.append(f"Ward on Block {on_block:g} x {block:.0f}% of the boss's hits (one every {every:.2f} s)")
    pct_kill = sum(float(m.group(1)) for t in texts if (m := WARD_ON_KILL.search(t)))
    if pct_kill and kills[0] > 0:
        income += pct_kill / 100 * pool * kills[0]
        parts.append(f"{pct_kill:g}% of maximum Ward on Kill at {kills[0]:.3f} kills/s")
    pct_minion = sum(float(m.group(1)) for t in texts if (m := WARD_ON_MINION_KILLED.search(t)))
    killed = max(kills[1] - kills[0], 0.0)
    if pct_minion and killed > 0:
        income += pct_minion / 100 * pool * killed
        parts.append(f"{pct_minion:g}% of maximum Ward per Reviving Minion Killed at {killed:.3f}/s (LOW: every Killed "
                     "minion taken as Reviving)")
    pct_rage = sum(float(m.group(1)) for t in texts if (m := WARD_ON_MAX_RAGE.search(t)))
    reaches = number(rage_reaches[0]) if rage_reaches else 0.0
    if pct_rage and rage_reaches:  # (MECHB48: MECHC47's reaches of Maximum Rage a second)
        income += pct_rage / 100 * pool * reaches
        parts.append(f"{pct_rage:g}% of maximum Ward on reaching Maximum Rage, {reaches:.3f} times a second "
                     f"({rage_reaches[1]})")
    unread = [name for name, pattern in WARD_UNREAD.items() if any(pattern.search(t) for t in texts)
              and not (name == "Runic Ward on reaching Maximum Rage" and pct_rage and rage_reaches)]
    return income, parts, unread


def ward_plan(uses: list[WardUse], regen: float, pool: float, parts: list[str] | None = None,
              unread: list[str] | None = None) -> tuple[float, list[dict]]:
    """The share of their planned rates the build's Runic Ward recovery (`regen` per second, every source: ward_income,
    whose `parts` and `unread` lines the note names) pays for the Ward-cost skills `uses` (one share for all: they spend
    the same Runic Ward), and the notes. 1.0 when it pays for all, or when nothing is spent."""
    spend = sum(u.rate * u.cost for u in uses if u.rate > 0 and u.cost > 0)
    if spend <= 0:
        return 1.0, []
    share = min(1.0, max(regen, 0.0) / spend)
    names = ", ".join(f"{u.name} {u.rate:.2f}/s x {u.cost:g} Ward" for u in uses if u.rate > 0 and u.cost > 0)
    sources = "; ".join(parts or [f"regeneration {regen:.1f}/s (PoB's WardRegenRecovery)"])
    missing = (f". Not counted (no rate reads them yet, so this may be an undercount): {', '.join(unread)}"
               if unread else "")
    if share >= 1.0:
        return 1.0, [{
            "label": "Runic Ward pays for the Ward-cost skills", "value": f"{spend:.1f} of {regen:.1f} Ward/s",
            "basis": f"{names}: the build's Runic Ward recovery pays for every use ({sources}){missing}",
            "play": f"The build feeds its Runic Ward from: {sources}.",
            "confidence": "MEDIUM"}]
    return share, [{
        "label": "Ward-cost skills held to what Runic Ward recovery pays for*", "value": f"x{share:.3f}",
        "basis": f"{names} would spend {spend:.1f} Runic Ward a second; the build recovers {regen:.1f}/s ({sources}; base "
                 f"regeneration 5% of its {pool:.0f} maximum a second, KeywordPopups Ward), so each is used "
                 f"{share:.1%} as often (without this cap: the rates above"
                 + ("; with no Runic Ward recovery none of them is used" if regen <= 0 else "")
                 + f"). The full pool at the start of the fight isn't counted (a few more uses once){missing}",
        "play": f"The build feeds its Runic Ward from: {sources}. Every Ward-cost use spends it, so they're used only as "
                f"often as that pays for ({share:.0%} of the rates above); more Ward recovery (Remnants of Kalguur, Ward on "
                "Block, regeneration) raises it.",
        "confidence": "MEDIUM"}]


# Frostflame Nova's Volatile Ice (MECHB13; MECHB11's notes, AUDIT23 A23-1, a likely OVERCOUNT) ------------------------
# Game files: the gem's description "the ice latches onto Ignited enemies, refreshing the duration of their active Ignite
# and rapidly Freezing them but preventing them from being Ignited further until the Ignite expires"; its Volatile Ice set
# (skill_specific_stat_description_mode 1, frostflame_nova.csd): "Hits enemies every 0.5 seconds until affected Ignite
# expires". PoB scores the set as one hit per cast (ShowAverage, at the cast rate) whether or not the boss is Ignited. The
# model (MEDIUM-LOW): 2 hits a second while the boss carries an Ignite, at the share of the fight it does from every Full
# DPS group's Ignites (each group's PoB Ignite stack potential at its use rate, 1 - e^-potential, combined as
# independent); 0 with no Ignite source. One ice at a time (whether a second cast's ice latches too: UNVERIFIED). Left
# out: the refreshed Ignite's longer uptime and the Ignites it blocks (MECH-A's Ignite model), its Freeze buildup bonus.
FROSTFLAME = "Frostflame Nova"
FROSTFLAME_HITS = 2.0  # "every 0.5 seconds"


def ignite_share(rates: list[dict], scales: dict[str, float] | None = None) -> tuple[float, str]:
    """The share of the fight the boss carries an Ignite from the groups `rates` (bridge useRates rows), each at PoB's
    use rate x its press scale (`scales`, objective.press_scales) when it's pressed beside the main skill."""
    free, parts = 1.0, []
    for rate in rates:
        potential = number((rate.get("stackPotential") or {}).get("Ignite"))
        potential *= (scales or {}).get(rate.get("name"), 1.0)
        if potential <= 0:
            continue
        up = 1.0 - math.exp(-potential)
        free *= 1.0 - up
        parts.append(f"{rate.get('name')} {up:.0%}")
    return 1.0 - free, ("; ".join(parts) or "no skill of the build Ignites the boss")


def frostflame_model(speed: float, share: float, how: str) -> tuple[list[dict], list[dict]]:
    """Frostflame Nova as the main skill at FROSTFLAME_HITS hits a second while the boss is Ignited (`share`, `how`:
    ignite_share), in place of PoB's one hit per cast at `speed` casts a second: a DPS "more" on the skill."""
    if speed <= 0:
        return [], []
    hits = FROSTFLAME_HITS * share
    more = hits / speed
    return [raw_mod("DPS", "MORE", 100 * (more - 1), FROSTFLAME)], [{
        "label": "Frostflame Nova: Volatile Ice hits while the boss is Ignited*", "value": f"{hits:.2f} hits/s",
        "basis": f"the ice 'Hits enemies every 0.5 seconds until affected Ignite expires' (game files) and latches only "
                 f"onto Ignited enemies: 2 hits/s x the boss Ignited {share:.0%} of the fight ({how}); PoB counts one "
                 f"hit per cast ({speed:.2f}/s), so x{more:.3f}. One ice at a time (UNVERIFIED); the refreshed Ignite's "
                 "longer uptime and the Ignites it blocks aren't counted",
        "play": "Keep the boss Ignited with another skill; the ice hits only while that Ignite lasts (without an Ignite "
                "source it deals nothing).",
        "confidence": "MEDIUM-LOW"}]



# Frostflame Nova beside the main skill (MECHB14): the same ice, for every group that uses it. PoB adds a Full DPS
# Frostflame group's Volatile Ice at one hit per cast too (its Wave set deals no damage: base_deal_no_damage), so a
# pressed or Full DPS Frostflame was counted whether or not the boss was Ignited (an OVERCOUNT). One ice at a time over
# all of them (UNVERIFIED, as above). A cast's ice lasts until the Ignite it refreshed expires, so each cast gives at
# most 2 hits/s x the Ignite's duration (the longest of the igniting groups' PoB IgniteDuration, refreshed in full: an
# upper bound): a rarely pressed Frostflame is held by its casts as well as by the Ignite share. The skill-tagged "more"
# reaches every Frostflame group, so it is the total over what PoB counts for all of them (each group's rate x its press
# scale; the main skill's at its own rate).


def frostflame_plan(uses: list[tuple[float, float]], share: float, how: str,
                    ignite_duration: float = 0.0) -> tuple[list[dict], list[dict]]:
    """Frostflame Nova's ice over all its groups: `uses` (PoB's casts a second, the press scale) for each group,
    `share` / `how` from ignite_share, `ignite_duration` the longest Ignite (s; 0: not known, no per-cast cap)."""
    counted = sum(speed * scale for speed, scale in uses)
    if counted <= 0:
        return [], []
    hits = FROSTFLAME_HITS * share
    cap = ""
    if ignite_duration > 0 and counted * FROSTFLAME_HITS * ignite_duration < hits:
        hits = counted * FROSTFLAME_HITS * ignite_duration
        cap = (f"; held by its casts ({counted:.2f}/s, each ice lasting at most the {ignite_duration:.1f} s Ignite it "
               "refreshes)")
    more = hits / counted
    mod = raw_mod("DPS", "MORE", 100 * (more - 1), FROSTFLAME)
    mod[HIT_CUT_PER_USE] = more  # (MECHB53, MECH99's split: the ice's hits a cast, the Nova cast as often)
    return [mod], [{
        "label": "Frostflame Nova: Volatile Ice hits while the boss is Ignited*", "value": f"{hits:.2f} hits/s",
        "basis": f"the ice 'Hits enemies every 0.5 seconds until affected Ignite expires' (game files) and latches only "
                 f"onto Ignited enemies: 2 hits/s x the boss Ignited {share:.0%} of the fight ({how}){cap}; PoB counts "
                 f"one hit per cast ({counted:.2f}/s over {len(uses)} group{'s' if len(uses) > 1 else ''}), so "
                 f"x{more:.3f}. One ice at a time (UNVERIFIED); the refreshed Ignite's longer uptime and the Ignites it "
                 "blocks aren't counted",
        "play": "Keep the boss Ignited with another skill and cast Frostflame Nova while it burns; the ice hits only "
                "while that Ignite lasts (without an Ignite source it deals nothing).",
        "confidence": "MEDIUM-LOW"}]

# Light Stuns of the boss (MECHB13; the manager's 18:20 relay of the user's Kalguuran Remnants note) -------------------
# KeywordPopups LightStun: "Any Hit has a chance to Light Stun the target ... The chance is based on the damage dealt, up
# to 100% base chance for Hits that deal 100% of the target's maximum Life. Chances lower than 15% are treated as 0%.
# Physical damage, and player (but not monster) Melee Damage, each have 50% more Light Stun chance." Bosses take them
# (checked: research/boss-poise-stun-threshold.md item 4: no stun-immunity mod on any of the 11 pinnacle varieties' mod
# lists; Monster.ot gives every monster a 0.5 s Light Stun, research/boss-heavy-stun-duration.md; second source poe2db
# The_Arbiter_of_Ash's mod list). The chance is linear in the hit (LightStunRatioScale 58's role UNVERIFIED, RESEARCH20
# #116; LOW). Not read: light stun chance / threshold modifiers, the boss's Energy Shield in front of its Life.
LIGHT_STUN_FLOOR = 0.15


def light_stun_rate(stats: dict, melee: bool = False) -> tuple[float, str]:
    """Light Stuns of the boss per second from the main skill's hits: each hit's chance is its damage (Physical x1.5, all
    x1.5 for a player Melee skill) over the boss's maximum Life (bosses.of(stats).life), 0 under 15%. None with "Your
    Hits cannot Stun enemies" (MECH84: PoB's CannotStun flag, conditions.cannot_stun_mods, read as "Flag:CannotStun")."""
    stats = at_main_share(stats)  # (MECH93: the main skill at its share of the fight, AT_MAIN_SHARE's note)
    if stats.get("Flag:CannotStun"):
        return 0.0, "Your Hits cannot Stun enemies: no Light Stuns"
    life = bosses.of(stats).life
    hits = hits_per_second(stats)
    if life <= 0 or hits <= 0:
        return 0.0, "no hits"
    crit = min(number(stats.get("CritChance")), 100) / 100
    hit = sum((number(stats.get(f"{t}HitAverage")) * (1 - crit) + number(stats.get(f"{t}CritAverage")) * crit)
              * (1.5 if t == "Physical" else 1.0) for t in DAMAGE_TYPES) * (1.5 if melee else 1.0)
    chance = min(hit / life, 1.0)
    if chance < LIGHT_STUN_FLOOR:
        return 0.0, (f"a hit of {hit:,.0f} is {chance:.1%} of the boss's {life:,} Life, under the 15% floor: no Light "
                     "Stuns (KeywordPopups LightStun)")
    return hits * chance, (f"{hits:.2f} hits/s x {chance:.0%} Light Stun chance (a {hit:,.0f} hit of the boss's {life:,} "
                           "Life; KeywordPopups LightStun, linear: LOW)")


MODEL_FIELDS.extend(f for f in ("Flag:CannotStun", f"Flag:{MECH_BRINK}") if f not in MODEL_FIELDS)  # (MECH84: conditions.cannot_stun_mods)


def stun_rate(stats: dict, melee: bool = False) -> tuple[float, str]:
    """Stuns of the boss per second, Heavy (heavy_stun_rate) and Light (light_stun_rate), for "when you Stun" sources."""
    heavy, heavy_how = heavy_stun_rate(stats)
    light, light_how = light_stun_rate(stats, melee)
    return heavy + light, f"Heavy {heavy:.3f}/s ({heavy_how}); Light {light:.3f}/s ({light_how})"


# One use, two damaging stat sets (MECHB15; FIX_QUEUE's undercount list, MECHB14's finding) --------------------------------
# Rolling Slam: "[Slam|Slam] the ground to [Stun|Stun] enemies and [Knockback|knock them away], then continue forward and
# perform a devastating second [Slam|Slam]" (ActiveSkills rolling_slam). PoB has three sets: "Rolling Slam"
# (base_deal_no_damage), "First Slam" (272% at level 20) and "Second Slam" (543%), all at total_attack_time 1000 ms,
# and scores one set per group; the search keeps the best (gems.py), the Second Slam. One use does both, so the use's
# damage is the two sets' sum: a DPS "more" of (First + Second) / scored, from the bridge's setRates (each set in its
# own calculation, PoB's TotalDPS). Both slams are taken as hitting the boss (the first's Knockback moves no pinnacle
# boss that's immune to it, and the second lands 1.5 m further on (melee_conditional_step_distance 15): a large boss is
# still under it; LOW-MEDIUM, labelled). Other skills whose sets are labelled First / Second / Third / Final in PoB's
# skill files are Combo or sequence strikes, each its own use (a different model, not this one) (checked: grep of
# label = "First|Second|Third|Final" over PoB's Data/Skills: Rolling Slam's two, Second Wind I-III (supports), Final
# Strike / Burst / Pulse, Third Strike).
# (MECHB63; RESEARCH59 R59-4, research/bonestorm-volley-landing-r59.md) Bonestorm: "release to fire them at enemies and
# explode" (ActiveSkills bonestorm): each spike is a Projectile hit and its explosion an area hit at the contact point
# (BonestormExplosionPlayer, is_area_damage), so a spike that hits the boss explodes on it: one use does both sets
# (MEDIUM-LOW at R59-4; MEDIUM since RESEARCH60 R60-1, research/bonestorm-explosion-struck-boss-r60.md: forum 3656373
# "a single explosion after each Projectile expires (whether it be a hit, or a miss)"; no excluding stat on either set).
# PoB scores one ("Projectile" or "Explosion"). The "spikes only" reading is the row. With Pierce, Chain or Fork on the
# skill (bonestorm_flight_moves on its sets) the spike flies on and explodes at the end of its flight (R60-1: forum
# 3617828), so the headline is spikes only (MEDIUM-LOW) and the explosion on the struck boss the row (MULTI_SET_MOVED).
MULTI_SET_SKILLS = {"Rolling Slam": ("First Slam", "Second Slam"), "Bonestorm": ("Projectile", "Explosion")}
MULTI_SET_WHY = {
    "Rolling Slam": ("Both taken as hitting the boss (the second lands 1.5 m on)",
                     "MEDIUM (game text: a slam, then a second slam; PoB's own per-set numbers; both on the boss "
                     "LOW-MEDIUM)"),
    "Bonestorm": ("each spike that hits the boss explodes on it (RESEARCH60 R60-1, MEDIUM; R59-4); row, spikes only: x1",
                  "MEDIUM (R60-1: forum 3656373, an explosion after each projectile 'whether it be a hit, or a miss'; "
                  "PoB's own per-set numbers)")}
# (R60-1) what moves a set's later hit off the boss the first one struck: {skill: test on a set's PoB row}
MULTI_SET_MOVED = {"Bonestorm": bonestorm_flight_moves}


def multi_set_model(main: str | None, scored: str | None, sets: list[dict]) -> tuple[list[dict], list[dict]]:
    """A main skill whose one use performs several damaging stat sets (MULTI_SET_SKILLS), PoB scoring one: a DPS "more"
    of their summed TotalDPS over the scored set's. `sets`: the bridge's setRates for the main group's skill."""
    want = MULTI_SET_SKILLS.get(main or "")
    if not want or scored not in want:
        return [], []
    dps = {s.get("label"): number(s.get("TotalDPS")) for s in sets}
    if dps.get(scored, 0) <= 0 or any(dps.get(label, 0) <= 0 for label in want):
        return [], []
    more = sum(dps[label] for label in want) / dps[scored]
    parts = " + ".join(f"{label} {dps[label]:,.0f}" for label in want)
    moved = MULTI_SET_MOVED.get(main or "")
    moves = sorted({m for s in sets if moved for m in moved(s)})
    if moves:  # (R60-1: the explosion flies on with the spike, off the struck boss: the headline counts the spikes)
        first = want[0]
        scale = dps[first] / dps[scored]
        return ([raw_mod("DPS", "MORE", 100 * (scale - 1), main)] if scored != first else []), [{
            "label": f"{main}: its {want[-1]} not on the boss the {first} struck*",
            "value": f"x{scale:.3f}",
            "basis": f"{' / '.join(moves)} on {main} moves the {want[-1]} to the end of the {first}'s flight (RESEARCH60 "
                     f"R60-1: forum 3617828, 'projectile chains then pierce then explode'), so the {first} alone counts "
                     f"({dps[first]:,.0f} DPS, PoB's). Row, the {want[-1]} on the struck boss too ({parts} DPS): "
                     f"x{more:.3f}",
            "confidence": "MEDIUM-LOW (R60-1: two player reports)"}]
    return [raw_mod("DPS", "MORE", 100 * (more - 1), main)], [{
        "label": f"{main}: one use performs {' and '.join(want)}*", "value": f"x{more:.3f}",
        "basis": f"PoB scores the {scored} alone ({dps[scored]:,.0f} DPS); each use does both ({parts} DPS, each set "
                 f"calculated by PoB). {MULTI_SET_WHY[main][0]}",
        "confidence": MULTI_SET_WHY[main][1]}]


# Tornado Shot's copied projectiles (MECHB17; FIX_QUEUE "Tornado Shot's copies", plans/term-projectile-range.md item 2;
# PoB counts none: its only Tornado Shot config, tornadoShotSecondaryHitChance, is read nowhere in CalcOffence). Game
# files (build 26476662): ActiveSkills tornado_shot, "Arrows, thrown [Spear|Spears] and [Crossbow] bolts fired at the
# Tornado are sucked into it, causing the Tornado to spit out a ring of copied [Projectile|Projectiles]. Copied
# [Projectile|Projectiles] cannot be copied again"; tornado_shot/statset_1.csd: "Tornado spits out {0} copies of
# [Projectile|Projectiles] fired into it" (base_number_of_projectiles 3), "Copied [Projectile|Projectiles] deal {0}% more
# damage" (tornado_shot_projectile_damage_+%_final: -60 at gem level 1, -41 at 20, +0.75 a quality), "Tornado disappears
# after being [Hit] {0} times" (tornado_shot_number_of_hits_allowed: 5 at 1, 8 at 20), "[Limit] {0} Tornado" (1), a
# 15 s base_skill_effect_duration. KeywordPopups Projectile: "When a group of multiple Projectiles is fired from the same
# source at the same time, only one Projectile in the group can hit each target unless otherwise specified".
# So on one boss each arrow sucked in gives ONE copied hit at the penalty (its ring is a group), and the arrow itself is
# gone ("sucked into it"; whether it also hits the boss: UNVERIFIED, taken as not, plans/term-projectile-range.md):
# against a skill whose one arrow a use hits the boss, a use through the Tornado gives N x (1 - penalty) hits for 1, N
# the arrows a use fires (PoB's ProjectileCount). A skill whose arrows all hit anyway (SHOTGUN_SKILLS, SEQUENCE_SKILLS)
# gives N x (1 - penalty) for N: never a gain. (PoB counts each shotgun arrow only since GEM2's c2d9315 / 8674bd0, train
# 46; before them it counted one, so "direct = count" here was ahead of PoB's own number for the shotgun skills.) The rate comes from the build (CLAUDE.md rule 2): each
# Tornado takes H arrows or lasts its duration, whichever ends first, so U = min(H / N, duration x uses/s) main uses
# go through one Tornado, and each Tornado costs one Tornado Shot use (1 / its own PoB use rate): the main skill's
# damage is x (N x (1 - penalty) / direct) x (U / r) / (U / r + Tornado Shot's use time). Below x1 the player shoots the
# boss directly, which PoB already scores: nothing changes. LOW: (a) every arrow of a volley reaches the Tornado (it is
# placed on the boss and shot at close range); (b) each sucked-in arrow's ring is its own group (the Tornado counts each
# arrow as its own Hit toward H). The lower reading of (b), one ring group per volley, would make it never worth it.
# Not counted: Tornado Shot's own damage over time (PoB's, when its group is in Full DPS); duration modifiers (the base
# 15 s is used, which can only cut U); the copies' 6 m reach (the boss stands in the Tornado).
TORNADO_SHOT = "Tornado Shot"
TORNADO_HITS_STAT = "tornado_shot_number_of_hits_allowed"
TORNADO_DAMAGE_STAT = "tornado_shot_projectile_damage_+%_final"
TORNADO_DURATION_STAT = "base_skill_effect_duration"
# (MECHB61, an OVERCOUNT found by MECHC57's probes POE2T7109-7111 on example build 16) N is what is FIRED at the Tornado
# ("Arrows, thrown Spears and Crossbow bolts fired at the Tornado are sucked into it", ActiveSkills Tornado Shot), not the
# ProjectileCount of whichever set PoB scores: Ice Shot's Shards set counts its 12 shards (14.66 against the Arrow set's
# 5.75), and Ice Shot "sprays a cone of ice shards when it hits a target" (ActiveSkills Ice Shot), so the shards are made
# where an arrow hits, never fired at the Tornado. The fired count is the skill's FIRST stat set's (in PoB's data every
# multi-set projectile attack lists the fired projectile first: scratch/mechb61/sets.py, 39 skills), except a set that is
# the same fired projectile under a condition (TORNADO_FIRED_VARIANTS: Fragmentation Rounds' "Vs Frozen", High Velocity
# Rounds' "Vs Armour Broken", Storm Lance / Explosive Spear's "Frenzy-Charged", Oil Barrage's "Empowered"), whose own count
# is the fired one. The factor still scales the scored set: each copied arrow that hits the boss makes that set's hit
# (its shards, explosion, beams) as a direct arrow does. And a projectile that is no arrow, thrown spear or bolt (a gem
# whose weapons hold no Bow, Crossbow or Spear, e.g. Falling Thunder's Quarterstaff bolts) isn't sucked in at all.
TORNADO_FIRED_VARIANTS = frozenset({"Vs Frozen", "Vs Armour Broken", "Frenzy-Charged", "Empowered"})
TORNADO_WEAPONS = frozenset({"Bow", "Crossbow", "Spear"})


def tornado_fired_count(scored_set: str | None, sets: list[dict], scored_count: float) -> tuple[float, str]:
    """(projectiles a use fired at the Tornado, how): the scored set's count when it is the fired set (the first, or a
    TORNADO_FIRED_VARIANTS set), else the first set's (bridge setRates ProjectileCount)."""
    first = sets[0] if sets else {}
    label = first.get("label") or ""
    if not sets or not scored_set or scored_set == label or scored_set in TORNADO_FIRED_VARIANTS:
        return scored_count, ""
    fired = max(number(first.get("ProjectileCount")), 1.0)
    return fired, (f"the scored {scored_set} set's {scored_count:g} projectiles are made where the {label} hits, not fired "
                   f"at the Tornado, so the {label} set's {fired:g} a use are counted")


def tornado_copy_model(main: Skill | None, main_types: set[str], stats: dict, tornado: Skill | None,
                       tornado_stats: dict, tornado_speed: float, sets: list[dict] | None = None,
                       weapons: set[str] | None = None) -> tuple[list[dict], list[dict]]:
    """The main projectile attack fired through Tornado Shot's Tornado, when that out-damages shooting the boss (above).
    `sets`: the main skill's bridge setRates sets (for the fired count, tornado_fired_count); `weapons`: its gem's
    weapon types."""
    if main is None or tornado is None or main.name == TORNADO_SHOT:
        return [], []
    label = f"{TORNADO_SHOT}: {main.name}'s arrows fired through the Tornado*"
    if (not main.attack or "Projectile" not in main_types or main.triggered
            or (weapons and not weapons & TORNADO_WEAPONS)):
        return [], [{"label": label, "value": 0, "confidence": "theory",
                     "basis": f"{main.name} isn't a projectile attack the player fires (arrows, thrown spears, bolts), so "
                              "the Tornado copies nothing of it"}]
    count, fired_how = tornado_fired_count(main.stat_set, sets or [], max(number(stats.get("ProjectileCount")), 1.0))
    speed = number(stats.get("Speed"))
    hits = number(tornado_stats.get(TORNADO_HITS_STAT))
    penalty = number(tornado_stats.get(TORNADO_DAMAGE_STAT))
    duration = number(tornado_stats.get(TORNADO_DURATION_STAT)) / 1000
    if speed <= 0 or tornado_speed <= 0 or hits <= 0 or duration <= 0:
        return [], [{"label": label, "value": 0, "confidence": "theory",
                     "basis": "no use rate or Tornado stats read from PoB: not counted"}]
    direct = count if main.name in SHOTGUN_SKILLS | SEQUENCE_SKILLS else 1.0
    per_use = count * (1 + penalty / 100) / direct
    uses = min(hits / count, duration * speed)
    # (MECHB62, O1 from COV56's calibration, an OVERCOUNT: a volley can't be fired in part) When the Tornado's H hits end
    # it, not its duration, the player fires whole volleys: ceil(H / N) of them, and the last volley's arrows past the H-th
    # fly on to the boss as a direct shot's share (a use's direct damage x the share not taken in; the lower reading,
    # LOW). Before, the model charged only H / N uses' time (build 16: 1.39 volleys charged, 2 fired).
    by_hits = hits / count < duration * speed
    volleys = max(1.0, math.ceil(uses - 1e-9)) if by_hits else uses
    left = volleys - uses if by_hits else 0.0
    firing = volleys / speed
    factor = (per_use * uses + left) / (volleys + speed / tornado_speed)
    how = (f"{count:g} arrow(s) a use" + (f" ({fired_how})" if fired_how else "") + ", each sucked in and copied into a ring of which one copy hits the boss at "
           f"{penalty:+g}% more (one copy of the ring a target: the ring leaves together, KeywordPopups 74; MEDIUM, "
           f"RESEARCH35 R35-15: a ring fired at once is the rule's own case), against {direct:g} direct "
           f"hit(s): x{per_use:.3f} a use; a Tornado takes {hits:g} arrows or lasts {duration:g} s, so {uses:.2f} uses "
           f"of arrows a Tornado"
           + (f", fired as {volleys:g} whole volleys ({firing:.2f} s; the last one's {left:.2f} of a use flies on to the "
              f"boss as a direct shot: the lower reading, LOW)" if by_hits else f" ({firing:.2f} s)")
           + f", and each Tornado costs a {TORNADO_SHOT} use ({1 / tornado_speed:.2f} s)")
    if factor <= 1:
        return [], [{"label": label, "value": "x1 (shoot the boss directly)", "confidence": "LOW",
                     "basis": f"{how}: x{factor:.3f}, below shooting the boss, so not counted. Without the Tornado: x1; "
                              f"through it: x{factor:.3f}"}]
    return [line("1% more Damage", 100 * (factor - 1), skill=main.name)], [{
        "label": label, "value": f"x{factor:.3f}", "confidence": "LOW",
        "basis": f"{how}: x{factor:.3f}. Play: put the Tornado on the boss, fire {main.name} into it, recast when it's "
                 f"gone. Without the Tornado: x1; through it: x{factor:.3f}. LOW: every arrow assumed to reach the "
                 "Tornado, and each arrow's ring its own group (if a volley's rings are one group, x"
                 f"{((1 + penalty / 100) / direct * uses + left) / (volleys + speed / tornado_speed):.3f}, so not worth "
                 "it); "
                 "the sucked-in arrow taken as not hitting (UNVERIFIED)"}]


# "N% increased Melee Damage if you've dealt a Projectile Attack Hit in the past eight seconds" (COV35, from the coverage
# report's open rows: a jewel affix JewelMeleeDamageIfProjectileHitRecently, Daevata's Wind, the unique mod
# UniqueMeleeDamageIfProjectileHitRecently1, the desecrated AbyssModSpearKurgalPrefix...EightSeconds and the small passive
# "Melee Damage if Projectile Hit"). PoB parses it under Condition:HitProjectileRecently, which only its unset Configuration
# box (conditionHitProjectileRecently) sets: 0 before, an UNDERCOUNT. Its rate is the build's own: the share of the fight
# with a Projectile Attack Hit in the past 8 s, 1 - e^(-8 s x the build's Projectile Attack hits a second) (hits taken as
# evenly random: the lower reading, as triggered_recently_model; MEDIUM). The hits: the main skill's if it is a
# Projectile Attack (PoB's Speed x hit chance), plus each other enabled Projectile Attack skill's uses (its group's rate:
# cooldown, duration or the search's chosen press rate, else 0: conditions.skill_use_rate), one hit a use (LOW: a use
# that misses or fires several projectiles counts once). An increased line scales linearly with the uptime, so PoB gets
# the same line without the condition at line x share.
PROJECTILE_HIT_RECENTLY = re.compile(r"^(\d+(?:\.\d+)?)% increased Melee Damage if you've dealt a Projectile Attack Hit "
                                     r"in the past eight seconds$", re.I)
PROJECTILE_HIT_WINDOW = 8.0  # "in the past eight seconds" (the line's own window)
# (COV36) Adaptable Assault's "+0.4 metres to Melee Strike Range if you've dealt a Projectile Attack Hit in the past
# eight seconds" (a Martial Artist-side notable; ModCache 93: MeleeWeaponRangeMetre / UnarmedRangeMetre BASE under the
# same never-set condition): the same share, as "+N metres to Melee Strike Range" at N x share (PoB reads the range only
# for skills whose area is the weapon's range, CalcOffence 570 / 1516; an average range for a radius is LOW).
PROJECTILE_HIT_RANGE = re.compile(r"^\+(\d+(?:\.\d+)?) metres to Melee Strike Range if you've dealt a Projectile Attack "
                                  r"Hit in the past eight seconds$", re.I)


def projectile_hit_recently_model(texts: list[str], rates: dict[str, tuple[float, str]]) -> tuple[list[dict], list[dict]]:
    """(mods, notes): the "Melee Damage if you've dealt a Projectile Attack Hit in the past eight seconds" lines at the
    share of the fight with such a hit in the window, from `rates` ({Projectile Attack skill: (hits a second, how)})."""
    total_line = sum(float(m.group(1)) for t in texts if (m := PROJECTILE_HIT_RECENTLY.search(t.strip())))
    metres = sum(float(m.group(1)) for t in texts if (m := PROJECTILE_HIT_RANGE.search(t.strip())))
    if not total_line and not metres:
        return [], []
    hits = sum(max(0.0, number(r)) for r, _ in rates.values())
    share = 1 - math.exp(-hits * PROJECTILE_HIT_WINDOW)
    parts = "; ".join(f"{name}: {number(r):.2f}/s ({how})" for name, (r, how) in sorted(rates.items()))
    basis = (f"Projectile Attack hits {hits:.2f}/s ({parts or 'no Projectile Attack skill in the build: 0'}): one in the "
             f"past {PROJECTILE_HIT_WINDOW:g} s {share:.0%} of the fight (hits taken as evenly random, the lower reading); "
             + (f"{total_line:g}% increased Melee Damage counts as {total_line * share:.3g}%; " if total_line else "")
             + (f"+{metres:g} metres to Melee Strike Range counts as +{metres * share:.3g}; " if metres else "")
             + "(PoB's box is never set: 0 before)")
    mods = [line("1% increased Melee Damage", total_line * share)] if total_line * share > 0 else []
    if metres * share > 0:
        mods.append(line("+1 metres to Melee Strike Range", metres * share))
    return mods, [{"label": "Projectile Attack Hit in the past 8 s: share of the fight", "value": round(share, 3),
                   "basis": basis, "play": "Hit with a Projectile Attack at least every few seconds (a thrown spear, an "
                                           "arrow) to keep the melee bonus up",
                   "confidence": "MEDIUM (LOW where a side skill's rate is the search's chosen press rate)"}]


# Pursuit I-III (MECH106; COV56's routed row, an UNDERCOUNT: never counted). "Supported Skills deal more Melee damage if
# you have struck with a Projectile Attack Hit in the last eight (Pursuit III: two) seconds" (PoB sup_dex.lua
# SupportAdvancingAssault*: support_advancing_assault_melee_damage_+%_final_if_projectile_attack_damage_hit_in_past_8_seconds
# 20 / 25, ..._in_past_2_seconds 30; game 26650308 the same stats). PoB puts the MORE behind Condition:HitProjectileRecently,
# set only by its unticked box (conditionHitProjectileRecently; nothing of ours ticks it: COV35's model above scales its item
# lines instead, so ticking it would double them). Here: the supported skill gets "N% more Melee Damage" x the share of the
# fight with a Projectile Attack Hit in the gem's own window, from the build's own Projectile Attacks
# (Assumptions.projectile_attack_rates, as COV35: 1 - e^(-hits x window), hits evenly random, the lower reading, MEDIUM).
# A MORE at a time share s is 1 + N x s on average, so N x s % more, on that skill only (line(..., skill=)).
PURSUIT_STATS = {"support_advancing_assault_melee_damage_+%_final_if_projectile_attack_damage_hit_in_past_8_seconds": 8.0,
                 "support_advancing_assault_melee_damage_+%_final_if_projectile_attack_damage_hit_in_past_2_seconds": 2.0}


def pursuit_model(supported: dict[str, dict[str, float]], rates: dict[str, tuple[float, str]]
                  ) -> tuple[list[dict], list[dict]]:
    """(mods, notes) for Pursuit (see above). `supported`: {skill: its support stats}; `rates`: the build's Projectile
    Attacks {name: (hits a second, how)}."""
    hits = sum(max(0.0, number(r)) for r, _ in rates.values())
    parts = "; ".join(f"{name}: {number(r):.2f}/s ({how})" for name, (r, how) in sorted(rates.items()))
    mods, notes = [], []
    for skill, got in sorted(supported.items()):
        for stat, window in PURSUIT_STATS.items():
            more = number(got.get(stat))
            if more <= 0:
                continue
            share = 1 - math.exp(-hits * window)
            if more * share > 0:
                mods.append(line("1% more Melee Damage", more * share, skill=skill))
            notes.append({"label": f"Pursuit on {skill}: Projectile Attack Hit in the past {window:g} s*",
                          "value": f"{share:.0%} of the fight, {more:g}% more Melee Damage counts as {more * share:.3g}%",
                          "basis": (f"Projectile Attack hits {hits:.2f}/s ({parts or 'no Projectile Attack in the build: 0'})"
                                    f", one in the past {window:g} s {share:.0%} of the fight (hits evenly random, the lower "
                                    "reading); PoB's box is never set (0 before)"),
                          "play": (f"Hit with a Projectile Attack at least every {window:g} s (a thrown spear, an arrow) "
                                   f"to keep {skill}'s Pursuit bonus up: without it x1, with it x{1 + more / 100:.2f}"),
                          "confidence": "MEDIUM (LOW where a side skill's rate is the search's chosen press rate)"})
    return mods, notes


# Projectile skills the group rule doesn't cap (MECHB45; RESEARCH35 R35-15, research/projectile-group-rule-scope.md; an
# UNDERCOUNT: PoB scores one projectile hit a use for both, checked by reading their skill data (no DPS multiplier, part or
# config: Data/Skills/act_int.lua SparkPlayer / FreezingShardsPlayer; CalcOffence 1114's projectile-count DPS needs the
# Barrageable type, which neither has) and by probe POE2T4663). KeywordPopups 74 caps only a group fired "from the same
# source at the same time ... unless otherwise specified"; these two specify otherwise in their own text (game 26650308):
# - Spark: "Projectiles fired at the same time can [Hit] the same target no more than once every {0} seconds"
#   (spark_min_time_between_target_clearing_ms 660 on SparkPlayer and the Infused / Earthbound sets; spark/statset_0.csd),
#   its sparks living base_skill_effect_duration 2 s (PoB's Duration, with the build's duration modifiers). So one cast's
#   sparks can hit a boss once per 0.66 s window of their life: at most min(sparks, floor(life / 0.66)) hits a cast (the
#   first hit taken a moment after the cast, so floor, not ceil: the lower reading; the ceil reading is a row). Each cast
#   is its own group, so overlapping casts each hit. Headline: every window finds a spark on the boss, cast point-blank
#   into it (the manager's ruling of 14 Nov for GEM2's Merging fragments, by the user's rule of 9 Nov: a condition the
#   player controls counts when the build leans into it, with "without it" and a play note). LOW: whether a spark that
#   touches the boss inside a window passes through and comes back, and how many wander back, is UNVERIFIED (no file says;
#   the research question is in MECHB45's report).
# - Freezing Shards (an item's skill): "Launch icy Projectiles in a sweeping arc. Multiple Projectiles can hit the same
#   enemy." Headline: all its projectiles (PoB's ProjectileCount, base 5) at point-blank (the same ruling); LOW: how much of
#   the arc a boss covers is UNVERIFIED (no arc stat in its set).
# Without it (PoB): one hit a use, x1. Main skill only (another group's copy keeps PoB's one: an undercount, said).
# (MECHB49, RESEARCH38 R38-13, MEDIUM-LOW, an OVERCOUNT of up to ~3x fixed) Spark's headline is ONE hit a cast on a lone
# boss: the stat clears the cast's hit list every 0.66 s (spark_min_time_between_target_clearing_ms), the sparks keep to a
# ~2 m lane along the aim (spark_pathing_width_bounds 20) at 10 m/s (Projectiles Metadata/Projectiles/Spark), so all of a
# point-blank cast reach the boss within ~0.1 s, the first hits and the rest pass through and leave before the list
# clears; a second hit needs a spark to come back (an arena wall). Rows: 2 (returned off a wall, LOW) and the cap
# min(sparks, floor(life / 0.66)) (3 at 2 s). PoB's own count is that one, so the headline adds nothing.
SPARK_HEADLINE_HITS, SPARK_WALL_HITS = 1.0, 2.0
GROUP_EXCEPTION_ENTRY = "model-mechb45-projectile-group-exceptions"
SPARK, FREEZING_SHARDS = "Spark", "Freezing Shards"
SPARK_REHIT, SPARK_LIFE = 0.66, 2.0  # spark_min_time_between_target_clearing_ms 660; base_skill_effect_duration 2000
FREEZING_SHARDS_BASE = 5.0  # FreezingShardsPlayer base_number_of_projectiles
FREEZING_SHARDS_SHARE = 0.4  # (MECHB46, RESEARCH36 R36-5: the lower report, "the majority ... fly off": 2 of 5; LOW, a flat game-decided share)


def group_exception_model(main: Skill | None, stats: dict,
                          forbidden: set[str] = frozenset()) -> tuple[list[dict], list[dict]]:
    """Spark's and Freezing Shards' hits a use on one boss, against PoB's one (see above)."""
    if main is None or main.name not in (SPARK, FREEZING_SHARDS) or GROUP_EXCEPTION_ENTRY in forbidden:
        return [], []
    count = number(stats.get("ProjectileCount"))
    if main.name == SPARK:
        sparks = max(count, 1.0)
        life = number(stats.get("Duration")) or SPARK_LIFE
        windows = max(1, math.floor(life / SPARK_REHIT + 1e-9))
        upper = max(1, math.ceil(life / SPARK_REHIT - 1e-9))
        cap, high = min(sparks, windows), min(sparks, upper)
        hits = min(SPARK_HEADLINE_HITS, cap)
        label = "Spark: one hit a cast on a lone boss*"
        basis = (f"{sparks:g} sparks a cast living {life:.2f} s (PoB's Duration). The cast's hit list clears every "
                 f"{SPARK_REHIT:g} s (spark_min_time_between_target_clearing_ms 660), but its sparks keep to a ~2 m "
                 "lane at 10 m/s, reach the boss together, the first hits and the rest pass through and leave before "
                 "the list clears (RESEARCH38 R38-13, MEDIUM-LOW): one hit a cast, PoB's own count. Rows: a spark "
                 f"returned off an arena wall, x{min(SPARK_WALL_HITS, cap):g} (LOW); the cap min({sparks:g}, "
                 f"floor({life:.2f} / {SPARK_REHIT:g})) = x{cap:g} (ceil x{high:g}), every window finding a spark")
        play = ("Spark hits a lone boss about once a cast; casting with a wall behind the boss may bring a spark back "
                f"for a second hit (x{min(SPARK_WALL_HITS, cap):g}).")
    else:
        shards = max(count, FREEZING_SHARDS_BASE)
        hits = max(1.0, round(shards * FREEZING_SHARDS_SHARE, 2))
        label = "Freezing Shards: some of a cast's shards hit the boss*"
        basis = (f"its text: \"Multiple Projectiles can hit the same enemy\" (an exception to KeywordPopups 74), so all "
                 f"{shards:g} may hit (HIGH) but not all do: player reports conflict at point-blank (RESEARCH36 R36-5: "
                 "\"the majority of projectiles often seem to fly off\" against \"much easier for every projectile to "
                 f"connect\"), and no arc angle is in the data. Headline the lower report: {FREEZING_SHARDS_SHARE:.0%} "
                 f"of the arc, {hits:g} hits a cast (a flat, game-decided share: LOW, named to the manager). Rows: all "
                 f"{shards:g} at point-blank x{shards:g}; PoB's one x1")
        play = (f"Cast Freezing Shards point-blank: {hits:g} of its {shards:g} shards taken to hit (x{hits:g}); if the "
                f"whole arc lands, x{shards:g}; from range, as few as one (PoB's x1).")
    if hits <= 1:
        return [], [{"label": label, "value": "x1", "confidence": "LOW", "entry": GROUP_EXCEPTION_ENTRY,
                     "basis": basis + ": nothing to add"}]
    return [with_per_use(raw_mod("DPS", "MORE", 100 * (hits - 1), main.name), hits)], [{  # (GEM33: hits a cast)
        "label": label, "value": f"x{hits:g}", "confidence": "LOW", "entry": GROUP_EXCEPTION_ENTRY,
        "basis": basis, "play": play}]


# Crossbow skills' additional projectiles fired in sequence (MECHB45; RESEARCH35 R35-15; an UNDERCOUNT, probe POE2T4663).
# The game (26650308): KeywordPopups 122, "Multiple Projectiles fired from a single Crossbow skill can all hit the same
# target, and single-Projectile skills fire additional Projectiles in sequence rather than in a spread"; the skills
# carry projectiles_crossbow_barrage (ImplicitStats of MeleeCrossbowPlayer, ExplosiveShotPlayer, HighVelocityRoundsPlayer,
# GlacialBoltPlayer, RapidShotPlayer, ArmourPiercingBoltsPlayer, IceShardsPlayer, ShockburstRoundsPlayer,
# CrossbowRequiemPlayer: every player set with it, checked with scratch/mechb45/carriers.py over GrantedEffectStatSets),
# and the first four also crossbow_barrage_attack_time_ratio_% 10. PoB means to count them (SkillStatMap 2847 maps the
# ratio to BarrageAttackTimePenalty, "actual handling ... in CalcOffence"; CalcOffence 1114-1126: DPS x the projectile
# count, each additional projectile adding the penalty % of attack time, 100% if the skill gives none), but that path
# needs SkillType.Barrageable, which no crossbow skill has (PoB act_*.lua): probe POE2T4663, Rapid Shot / High Velocity
# Rounds / Armour Piercing Rounds with 1, 2 and 3 projectiles all read the same TotalDPS. So, PoB's own reading applied
# here: DPS x N (PoB's ProjectileCount, which carries Run and Gun's TwoAdditionalProjectilesChance) and attack time
# +ratio% per additional projectile. Skills with no ratio stat: PoB's default 100% (x1 on DPS, so nothing applied),
# UNVERIFIED, with the 10% reading as a row. MEDIUM where the ratio is in the files (KeywordPopups 122 says they all hit;
# whether an extra bolt spends ammunition is UNVERIFIED, taken as no, as PoB's path takes it). Main skill only.
# Permafrost Bolts, Incendiary Shot, Fragmentation Rounds and Galvanic Shards are GEM2's Merging fragments (SHOTGUN_SKILLS:
# shotgun_fragments_share), not this.
CROSSBOW_SEQUENCE_ENTRY = "model-mechb45-crossbow-sequence-projectiles"
CROSSBOW_SEQUENCE_RATIO = {"Crossbow Shot": 10.0, "Explosive Shot": 10.0, "High Velocity Rounds": 10.0,
                           "Glacial Bolt": 10.0, "Rapid Shot": None, "Armour Piercing Rounds": None, "Ice Shards": None,
                           "Shockburst Rounds": None, "Requiem": None}  # crossbow_barrage_attack_time_ratio_% or None
CROSSBOW_DEFAULT_RATIO, CROSSBOW_ROW_RATIO = 100.0, 10.0  # PoB's default when unspecified; the sibling skills' 10


def crossbow_sequence_model(main: Skill | None, stats: dict,
                            forbidden: set[str] = frozenset()) -> tuple[list[dict], list[dict]]:
    """A crossbow skill's additional projectiles in sequence, all hitting one target (see above)."""
    if main is None or main.name not in CROSSBOW_SEQUENCE_RATIO or CROSSBOW_SEQUENCE_ENTRY in forbidden:
        return [], []
    count = number(stats.get("ProjectileCount"))
    extra = count - 1
    if extra <= 1e-9:
        return [], []
    ratio = CROSSBOW_SEQUENCE_RATIO[main.name]
    label = f"{main.name}: its additional projectiles fire in sequence and all hit the boss*"
    row = count / (1 + CROSSBOW_ROW_RATIO / 100 * extra)
    if ratio is None:
        flat = count / (1 + CROSSBOW_DEFAULT_RATIO / 100 * extra)
        return [], [{"label": label, "value": f"x{flat:.3f}", "confidence": "UNVERIFIED", "entry": CROSSBOW_SEQUENCE_ENTRY,
                     "basis": (f"{count:g} projectiles a use, all can hit one target (KeywordPopups 122); {main.name} "
                               "carries no crossbow_barrage_attack_time_ratio_%, so each additional one taken to add "
                               f"100% of the attack time (PoB's default for that case): x{flat:.3f}, nothing applied "
                               f"(UNVERIFIED: the game data gives the cost only for Explosive Shot, Glacial Bolt, High "
                               f"Velocity Rounds and Crossbow Shot, RESEARCH36 R36-5). Row: at its sibling skills' 10% each, x{row:.3f}. PoB counts none of them "
                               "(its sequence path needs the Barrageable type: probe POE2T4663)")}]
    factor = count / (1 + ratio / 100 * extra)
    return ([with_hits_per_use(raw_mod("DPS", "MORE", 100 * extra, main.name), count),
             raw_mod("SkillAttackTime", "MORE", ratio * extra, main.name)],
            [{"label": label, "value": f"x{factor:.3f}", "confidence": "MEDIUM", "entry": CROSSBOW_SEQUENCE_ENTRY,
              "basis": (f"{count:g} projectiles a use fired in sequence, all hitting one target (KeywordPopups 122), each "
                        f"additional one adding {ratio:g}% of the attack time (crossbow_barrage_attack_time_ratio_%): "
                        f"x{count:g} damage over x{1 + ratio / 100 * extra:.2f} attack time = x{factor:.3f}. PoB means to "
                        "count this (BarrageAttackTimePenalty) but its path needs the Barrageable type, which crossbow "
                        "skills lack (probe POE2T4663: 1-3 projectiles, the same DPS). Whether an extra bolt spends "
                        "ammunition: UNVERIFIED, taken as no (PoB's reading)"),
              "play": f"{main.name}'s extra projectiles all hit a single boss: x{factor:.3f} (without them, x1)."}])


# Bonestorm with Spells' Projectiles in a circle (MECHB45; COV47's routing, FIX_QUEUE line 138, RESEARCH31 R31-11; an
# OVERCOUNT before: GEM19's bonestorm_model counted every spike of a full 20-spike channel on the boss whatever the
# layout). Sire of Shards: "Spells fire Projectiles in a circle" (PoB Data/Uniques/staff.lua; game stat
# local_display_socketed_spells_projectiles_circle / the cultivated spell_projectile_skills_fire_X_additional_projectiles_
# in_a_circle: "Spells fire {0} additional Projectiles / Spells fire Projectiles in a circle"; SPELL_CIRCLE matches both).
# R31-11 (b): a circle spreads a release's spikes evenly over 360 degrees with one aimed at the target (PoE1 behaviour,
# MEDIUM-LOW): a boss 5 m away spans ~23 degrees, so one spike a release reaches it (and the group rule caps a release to
# one in any case: R35-15, MEDIUM). With one spike a release, the full channel's 20 spikes over 2.5 s give no more than one;
# the best play is PoB's own reading, a release at the 0.3 s minimum channel (1 spike a 0.3 s). So GEM19's stage
# multiplier is not applied (PoB's one spike a release stands), and "all spikes hit" (GEM19's x) is a row. Whether the
# circle splits one release: UNVERIFIED (R31-11).
def bonestorm_circle(texts: list[str], bs_mods: list[dict], bs_notes: list[dict]) -> tuple[list[dict], list[dict]]:
    """GEM19's Bonestorm mods and notes, or none and a labelled note when the build's Spells fire in a circle."""
    circle = next((t for t in texts if spell_circle_layout(t)), None)
    if circle is None or not bs_mods:
        return bs_mods, bs_notes
    spikes = (bs_notes[0].get("value") if bs_notes else "") or "a full channel"
    return [], [{
        "label": f"{BONESTORM}: Projectiles in a circle, one spike a release on the boss*", "value": "x1 (PoB's)",
        "confidence": "MEDIUM-LOW", "entry": BONESTORM_ENTRY,
        "basis": (f"\"{circle}\": a release's spikes spread over 360 degrees with one aimed at the target (RESEARCH31 "
                  "R31-11 (b), MEDIUM-LOW; the group rule caps a release to one hit anyway, R35-15), so one spike a release "
                  "reaches a lone boss and the best play is a release at the 0.3 s minimum channel: PoB's own one spike "
                  f"a 0.3 s. Row (UNVERIFIED): if every spike of a full channel hits, {spikes} a release (GEM19's model)"),
        "play": f"With Spells firing in a circle, release {BONESTORM} at its 0.3 s minimum: one spike reaches the boss a "
                f"release (a full channel adds nothing on one target)."}]


# Ancestral Bond's doubled Totem Limit for PoB's own per-totem reads (MECHB45; COV47's routing after its 30a28c10, an
# UNDERCOUNT): PoB leaves "Your Totem Limit is doubled" unparsed (ModCache 9994, text left over: never applied), so its own
# uses of the limit read the undoubled number: TotemsSummoned = the Configuration override or the skill's
# ActiveTotemLimit (CalcOffence 1938, CalcPerform 1302-1303), which "per Summoned Totem" / "for each summoned totem" lines
# (ModParser 1661-1664: PerStat TotemsSummoned) and a totem skill's Ignite / Poison / Bleed stacks (CalcOffence
# 5264-5267) read. The models already count the doubling themselves (bond_totems), from the bridge's totemLimit, which
# leaves out the "Assumption:OneTotem" source. So each totem-summoning skill gets ActiveTotemLimit BASE (doubled - PoB's)
# under that tag (TOTEM_ONE_TAG): PoB's reads see the doubled limit, the models' reads don't, so nothing doubles twice
# (the same fixed point as the one-totem correction). Skipped where a one-totem support holds the skill to 1 (its own
# tagged line sets the limit; whether Ancestral Bond doubles that 1 is UNVERIFIED: the lower reading) and where a
# TotemsSummoned override is set (it wins in PoB; the bridge's totemLimit reads the override too, so no line).
def bond_limit_mods(skills: list[Skill], texts: Iterable[str]) -> tuple[list[dict], list[dict]]:
    """Ancestral Bond's doubled Totem Limit handed to PoB's own per-totem reads (see above)."""
    if not any(ANCESTRAL_BOND_DOUBLE.match(t.strip()) for t in texts):
        return [], []
    mods, parts, done = [], [], set()
    for s in skills:
        if s.totem_limit <= 0 or s.name in done:
            continue
        done.add(s.name)
        if any(number(x.support_stats.get(TOTEM_ONE_STAT)) > 0 for x in skills if x.group == s.group):
            continue
        own = s.totem_limit_own if 0 < s.totem_limit_own <= s.totem_limit else s.totem_limit
        high = bond_totems(own, s.totem_limit - own, True)[0]
        if high > s.totem_limit:
            mods.append(raw_mod("ActiveTotemLimit", "BASE", high - s.totem_limit, s.name, tag=TOTEM_ONE_TAG))
            parts.append(f"{s.name} {s.totem_limit:g} -> {high:g}")
    if not mods:
        return [], []
    return mods, [{"label": "Ancestral Bond: PoB's per-totem reads at the doubled Totem Limit*",
                   "value": "; ".join(parts), "confidence": "MEDIUM",
                   "basis": ("PoB leaves 'Your Totem Limit is doubled' unparsed, so its 'per Summoned Totem' lines and a "
                             "totem skill's ailment stacks read the undoubled limit; handed to PoB as each totem skill's "
                             "ActiveTotemLimit (a source the totem models' own count leaves out, so it isn't doubled "
                             "again). Which comes first, the doubling or the +Totem lines: UNVERIFIED, (base + adds) x 2 "
                             "taken (bond_totems)")}]


# Full DPS entries that share a name (MECHB45; GEM26's routing, an UNDERCOUNT): PoB's SkillDPS rows carry only a name
# (Calcs.lua mergeFullDPSPass: name, dps, count, trigger, skillPart; the bridge passes name, dps, count, source), and
# objective.entry_scales scales every row of that name. Several skills grant a skill of the same name (Ice Fragments:
# Ice-Tipped Arrows, Escape Shot, Fragments of the Past, Shred, Frozen Spite ...), so zeroing one group's "Ice Fragments"
# zeroed all of them. Instead, the one group's own amount (its useRates TotalDPS, the same per-group calculation PoB's Full
# DPS makes) comes off the name's total: scale = (total - removed) / total over that name's rows. Exact for the Full DPS
# sum; a second model cutting the same name must combine its cut here too (entry_cuts sums them).
def entry_cut_scale(entries: list[dict], name: str, removed: float) -> float:
    """The entry_scales value for `name` that takes `removed` DPS off the total of its SkillDPS rows (see above)."""
    total = sum(number(e.get("dps")) * (number(e.get("count")) or 1.0) for e in entries or [] if e.get("name") == name)
    if total <= 0:
        return 1.0
    return max(0.0, min(1.0, (total - max(removed, 0.0)) / total))


# Oil Barrage's use: a wind-up, then one group of projectiles (MECHB46; MECHB45's find, an OVERCOUNT of ~x1.5). Game files
# 26650308, OilBarragePlayer (second source poe2db Oil_Barrage, current: "Attack Speed: 300% of base", "Fires 3
# Projectiles", "[Channelling] ends after one group of [Projectiles]", the same hidden stats): AttackSpeedMultiplier 200
# (PoB reads it: CalcOffence 2874, AttackRate x3), base_number_of_projectiles 3, projectiles_barrage ("Projectiles are
# fired in sequence, allowing multiple Projectiles to Hit the same target", ActiveSkills oil_barrage),
# channel_start_duration_as_%_of_attack_time 350, display_attack_time_+% 350, channel_end_duration_as_%_of_attack_time 1000,
# skill_do_not_elapse_channel_time_while_barraging. PoB reads none of the channel stats (MECHB3's check) and scores one
# projectile an attack time (probe POE2T4663: TotalDPS = AverageDamage x Speed at 3, 4 and 5 projectiles alike).
# Reading (MEDIUM-LOW): a plain (Base) use is the 350% wind-up and then the group, which together take the tooltip's
# attack time +350% (display_attack_time_+%), i.e. 4.5 PoB attack times for 3 hits on the target: one hit every 1.5
# attack times, x0.667. Each additional projectile taken to add a whole attack time (PoB's default barrage penalty where
# a skill gives no ratio, as crossbow_sequence_model): (N + 1.5) attack times for N hits (UNVERIFIED; row: extra
# projectiles free, N / 4.5). Applied as attack time x (N + 1.5) / N, so PoB's hit rate (ailments, on-hit) moves with
# the DPS; "Speed" then reads hits a second, not uses. The 1000% channel end: taken as not spent, since the channel ends
# after the group (UNVERIFIED; row: if it is, 3 hits in 14.5 attack times). The Empowered barrage ("Consumes a Power
# Charge every 1.5 seconds to continue Channelling", a sustained channel): kept at PoB's one projectile an attack time,
# its one wind-up a channel not taken off (UNVERIFIED both ways; row: a group of N every attack time, xN); its share of
# the time is GEM17's gated_set_model share (oil_barrage_share), and the factor here weighs the two by it.
OIL_BARRAGE = "Oil Barrage"
OIL_VOLLEY_ENTRY = "model-mechb46-oil-barrage-volley"
OIL_WINDUP = 3.5  # channel_start_duration_as_%_of_attack_time 350
OIL_GROUP = 3  # base_number_of_projectiles 3 (fired within one attack time: display_attack_time_+% 350 = 3.5 + 1)
OIL_CHANNEL_END = 10.0  # channel_end_duration_as_%_of_attack_time 1000 (a row only)


def oil_barrage_volley_model(main: Skill | None, stats: dict, sets: list[dict], share: float,
                             forbidden: set[str] = frozenset(),
                             previous: list[dict] | None = None) -> tuple[list[dict], list[dict]]:
    """Oil Barrage's plain use as the game makes it (see above): `stats` with ProjectileCount, `sets` the bridge's setRates
    for its group, `share` of the time the Empowered barrage runs (GEM17's gated share)."""
    if main is None or main.name != OIL_BARRAGE or OIL_VOLLEY_ENTRY in forbidden:
        return [], []
    if main.stat_set not in (None, "Base", "Empowered"):
        return [], []
    n = number(stats.get("ProjectileCount")) or OIL_GROUP
    units = OIL_WINDUP + 1 + max(0.0, n - OIL_GROUP)  # attack times a plain use takes
    k = n / units  # hits an attack time, over PoB's one
    dps = unscale_own(sets, previous, OIL_VOLLEY_ENTRY)
    base, gated = dps.get("Base", 0.0), dps.get("Empowered", 0.0)
    s = min(1.0, max(0.0, number(share))) if base > 0 and gated > 0 else 0.0
    h = (1 - s) * k + s  # the hit rate over PoB's
    mixed = (1 - s) * base + s * gated
    g = ((1 - s) * base * k + s * gated) / (mixed * h) if s > 0 and mixed > 0 else 1.0
    total = h * g
    mods = [raw_mod("SkillAttackTime", "MORE", 100 * (1 / h - 1), main.name, tag=OIL_VOLLEY_ENTRY)]
    if abs(g - 1) > 1e-9:
        mods.append(raw_mod("DPS", "MORE", 100 * (g - 1), main.name, tag=OIL_VOLLEY_ENTRY))
    free = n / (OIL_WINDUP + 1)
    ended = OIL_GROUP / (OIL_WINDUP + 1 + OIL_CHANNEL_END) if n <= OIL_GROUP else n / (units + OIL_CHANNEL_END)
    return mods, [{
        "label": f"{main.name}: a plain use is a wind-up, then one group of {n:g} projectiles*", "value": f"x{total:.3f}",
        "confidence": "MEDIUM-LOW", "entry": OIL_VOLLEY_ENTRY,
        "basis": (f"PoB scores one projectile an attack time and no wind-up (probe POE2T4663). The game: a 350% wind-up "
                  f"(channel_start_duration_as_%_of_attack_time), then one group; the tooltip's attack time +350% "
                  f"(display_attack_time_+%), so {n:g} hits in {units:g} attack times (each projectile past {OIL_GROUP} "
                  f"taken to add one attack time, UNVERIFIED), all on the target (they fire in sequence): x{k:.3f} on the "
                  f"plain use" + (f"; the Empowered barrage {s:.0%} of the time kept at PoB's one projectile an attack time "
                                  "(UNVERIFIED), its one wind-up a held channel not taken off (RESEARCH36 R36-10: the "
                                  "held channel ends on release or when a Power Charge is due every 1.5 s and none is "
                                  "left, MEDIUM; the wind-up once a channel, UNVERIFIED)" if s > 0 else "")
                  + f". Rows (UNVERIFIED): extra projectiles free x{free:.3f}; if each use also spends its 1000% channel "
                  f"end x{ended:.3f}; Empowered firing a group of {n:g} every attack time x{n:g} on its share"),
        "play": (f"Each plain {main.name} fires its {n:g} projectiles after a long wind-up: x{k:.3f} on PoB's rate "
                 f"(PoB counts one projectile and no wind-up).")}]


# Fortifying Cry's Shield Waves (MECHB46; COV47's routing, an UNDERCOUNT: PoB gives the hidden granted Shield Wave no
# trigger rate). Game 26650308: FortifyingCryPlayer "Perform a Warcry that grants Guard and Triggers Shield Wave when
# subsequent Shield Attacks deal damage" (ActiveSkills); fortifying_cry.csd: "Can [Trigger] Shield Wave once per {0} enemy
# [Power] in range, counting up to {1} [Power]" (shielding_cry_an_additional_empowered_attack_per_X_mp 5, its _mp_cap 50);
# base_skill_effect_duration 8000 (the window, MEDIUM: Guard's is the secondary 4000); fortifying_cry_shockwave.csd: "This
# Attack is Triggered by Fortifying Cry and counts as Empowered by it". PoB maps neither stat to WarcryPowerPer / Cap
# (SkillStatMap maps warcry_empowers_per_X_monster_power only), so it counts no Empowers for it either. Waves a cry =
# min(floor(min(Power, 50) / 5), the Shield Attack hits in the 8 s window): a lone Unique boss's 20 Power gives 4 (PoB's
# WarcryPower, the useRates row's warcryPower; Echoing Cry's less Power read as unbuffed_warcry_empowers does). Shield
# Attack hits: the main skill's when it is an Attack that needs a shield (PoB's RequiresShield type), Speed x hit chance;
# other pressed shield skills not read (an undercount, labelled); 0 with none (no flat rate). Echoing Cry's Echoes: not
# counted (UNVERIFIED, an undercount). Rate = Fortifying Cry's uses a second x waves a cry, as Shield Wave's triggerRate.
FORTIFYING_CRY = "Fortifying Cry"
SHIELD_WAVE = "Shield Wave"
SHIELD_WAVE_ENTRY = "model-mechb46-fortifying-cry-shield-wave"
SHIELD_WAVE_PER = 5.0  # shielding_cry_an_additional_empowered_attack_per_X_mp
SHIELD_WAVE_CAP = 50.0  # shielding_cry_an_additional_empowered_attack_per_X_mp_mp_cap
SHIELD_WAVE_WINDOW = 8.0  # base_skill_effect_duration 8000 ms


SHIELD_WAVE_ECHOES = 2  # Echoing Cry: "Echo 2 times, with a 1.3 second delay" (RESEARCH36 R36-11)


def shield_wave_model(cry_row: dict, echo_less: float, shield_hits: float, hits_how: str,
                      forbidden: set[str] = frozenset()) -> tuple[list[dict], list[dict]]:
    """Shield Wave's trigger rate (see above): `cry_row` Fortifying Cry's useRates row (speed, warcryPower), `echo_less`
    Echoing Cry's support stat (negative, or 0), `shield_hits` the build's Shield Attack hits a second."""
    if SHIELD_WAVE_ENTRY in forbidden:
        return [], []
    cries = number(cry_row.get("speed"))
    if cries <= 0:
        return [], []
    n, n_how = unbuffed_warcry_empowers({"warcryPowerPer": SHIELD_WAVE_PER, "warcryPowerCap": SHIELD_WAVE_CAP,
                                         "warcryPower": cry_row.get("warcryPower")}, echo_less)
    per = min(float(n), max(shield_hits, 0.0) * SHIELD_WAVE_WINDOW)
    rate = cries * per
    full = cries * n
    # (MECHB47, RESEARCH36 R36-11, MEDIUM-LOW) Echoing Cry: "Echo 2 times" (gem_stat_descriptions; poe2db Echoing_Cry),
    # each echo the warcry again at the same 50% less Power: if each adds its own allowance, 3 x n a use; if it
    # refreshes it, n. (MECHB49, RESEARCH38 R38-12, MEDIUM: they ADD, the headline: BuffDefinitions'
    # display_num_empowered_attacks has MergeMode 1, separate instances as Withered's, and the Jul 2026 stack-counter bug,
    # forum 3982833, "stacks double after each cast", needs echoes to add; the refresh reading is the row.) The bug's
    # doubling is not modelled (labelled).
    refresh = per
    if echo_less < 0:
        per = min(float(n) * (1 + SHIELD_WAVE_ECHOES), max(shield_hits, 0.0) * SHIELD_WAVE_WINDOW)
        rate = cries * per
    echo_row = (f"; with Echoing Cry its {SHIELD_WAVE_ECHOES} echoes each add their own allowance (RESEARCH38 R38-12, "
                f"MEDIUM: the count is stored as separate instances), so {per:g} a use; if they refreshed it instead, "
                f"{refresh:g} a use, {cries * refresh:.3f}/s (row); the Jul 2026 bug that doubles the stacks each cast "
                "isn't modelled; its 10 m travel gate is in the cries a second" if echo_less < 0 else "")
    mods = [{"kind": "SkillData", "skill": SHIELD_WAVE, "key": "triggerRate", "value": rate},
            {"kind": "SkillData", "skill": SHIELD_WAVE, "key": "triggered", "value": True}]
    return mods, [{
        "label": f"{FORTIFYING_CRY}: Shield Waves a second*", "value": round(rate, 3), "confidence": "MEDIUM",
        "entry": SHIELD_WAVE_ENTRY,
        "basis": (f"PoB gives Shield Wave no trigger rate. Each cry Triggers it once per {SHIELD_WAVE_PER:g} enemy Power "
                  f"(up to {SHIELD_WAVE_CAP:g}) when later Shield Attacks deal damage (game files): {n_how}; capped by the "
                  f"Shield Attack hits in its {SHIELD_WAVE_WINDOW:g} s ({hits_how}: {shield_hits * SHIELD_WAVE_WINDOW:.1f}"
                  f"), so {per:g} a cry x {cries:.3f} cries/s. A Shield Wave isn't a Shield Attack (no RequiresShield "
                  "type, RESEARCH36 R36-11): it can't feed itself. Other pressed shield skills not counted (an "
                  f"undercount){echo_row}"),
        "play": (f"Hit with Shield Attacks after each {FORTIFYING_CRY}: {per:g} Shield Waves a cry, {rate:.2f}/s"
                 + (f" (with no Shield Attack, 0)" if per > 0 else
                    f" (this build has no Shield Attack: 0; with one, up to {full:.2f}/s)"))}]


# Warcries' granted triggered skills PoB scores at a flat rate (MECHB46; GEM26's sweep POE2T3595, the manager 10:50,
# OVERCOUNTS: each scored at its castTime 1 rate whether or not anything triggers it, so a side group in Full DPS kept it):
# - Infernal Cry's Combust (InfernalCryCorpseExplosionPlayer, its implicit triggered_by_infernal_cry): "Enemies in the warcry's area are destabilised and will
#   Combust on death" (ActiveSkills infernal_cry); PoB: 82.1 DPS at 1 a second beside a Boneshatter. One a death of an
#   enemy the cry reached: the boss preset's adds killed a second (models.kill_rate; 0 on a lone boss, whose own death
#   ends the fight) x the share of the time the cry's 8 s debuff is fresh (cries a second x its duration, at most 1),
#   every Combust taken to reach the boss (LOW: the add dies somewhere in the 4 m cry area; the Combust's 1.6 m radius).
# - Ancestral Cry's Volcanic Eruption ("your Melee Strikes Trigger Volcanic Eruption") and Volcanic Steps ("you Trigger
#   Volcanic Steps while travelling", ancestral_cry_triggers_shockwave_every_X_units_travelled 12), both only "While
#   embodying Kaom" (ActiveSkills ancestral_cry); PoB: 102.7 and 119.1 DPS beside a Boneshatter, always. Eruption at
#   PoB's rate x Kaom's uptime (kaom_uptime) when the main skill is a Melee Strike, else 0; Steps 0: no travel is
#   modelled in a boss fight (an UNDERCOUNT where the player walks or rolls through Kaom's uptime, a row; how far a
#   dodge roll counts as travelling: UNVERIFIED).
SIDE_TRIGGERS = {"Combust": "Infernal Cry", "Volcanic Eruption": "Ancestral Cry", "Volcanic Steps": "Ancestral Cry"}
INFERNAL_CRY = "Infernal Cry"


def side_trigger_keep(child: str, cries: float, duration: float, adds: float, kaom: float,
                      melee_strike: bool) -> tuple[float, str]:
    """(the share of PoB's flat rate kept, why) for a Warcry's granted triggered skill (see above). `cries` the Warcry's
    uses a second, `duration` its debuff's, `adds` adds killed a second, `kaom` Kaom's uptime."""
    if child == "Combust":
        fresh = min(1.0, max(cries, 0.0) * max(duration, 0.0))
        rate = max(adds, 0.0) * fresh
        return min(1.0, rate), (f"one a death in the cry's area: {adds:.3f} adds killed/s x {fresh:.0%} of the time "
                                f"the cry's {duration:g} s debuff is up = {rate:.3f}/s" if adds > 0 else
                                "no enemy dies in the cry's area before the boss (a lone boss): 0")
    if child == "Volcanic Eruption":
        if not melee_strike:
            return 0.0, "only Melee Strikes Trigger it, and the main skill isn't one: 0"
        return min(1.0, max(kaom, 0.0)), f"only while embodying Kaom, {kaom:.0%} of the fight"
    if child == "Volcanic Steps":
        return 0.0, ("only while travelling as Kaom: no travel is modelled in a boss fight, 0 (an undercount where the "
                     f"player walks or rolls through Kaom's {kaom:.0%} uptime)")
    return 1.0, ""


# Unarmed Attacks' area per Intelligence (MECHB47; COV48's lane rows: Facebreaker, a Way of the Stonefist form, "N%
# increased Area of Effect for Unarmed Attacks per M Intelligence"). PoB parses it only in part (ModCache 1387: leftover
# "  for  Attacks  ", so never applied: Item.lua's `not modLine.extra`). Read here as PoB's own reading of the rest:
# AreaOfEffect INC N per M Intelligence, on Attacks (KeywordFlag Attack) while Unarmed (PoB's Condition:Unarmed,
# CalcPerform 3257), from the build's Intelligence. An UNDERCOUNT only where the area matters (an area-scaled skill or
# a model reading the radius on the boss); HIGH that the line means this.
UNARMED_AREA = re.compile(r"^(\d+(?:\.\d+)?)% increased Area of Effect for Unarmed Attacks per (\d+) Intelligence$", re.I)
UNARMED_AREA_ENTRY = "model-read-mechb47-unarmed-area"


def unarmed_area_model(texts: list[str], stats: dict, forbidden: set[str] = frozenset()) -> tuple[list[dict], list[dict]]:
    """The lines above as one AreaOfEffect INC on Unarmed Attacks, from the build's Intelligence (PoB's Int)."""
    if UNARMED_AREA_ENTRY in forbidden:
        return [], []
    found = [(float(m.group(1)), float(m.group(2))) for t in texts if (m := UNARMED_AREA.match(t.strip()))]
    intelligence = number(stats.get("Int"))
    total = sum(n * math.floor(intelligence / per) for n, per in found if per > 0)
    if not found or total <= 0:
        return [], []
    return [raw_mod("AreaOfEffect", "INC", total, condition="Unarmed", keywords=["Attack"])], [{
        "label": "Unarmed Attacks' area from Intelligence*", "value": f"+{total:g}%", "confidence": "HIGH",
        "entry": UNARMED_AREA_ENTRY,
        "basis": (f"{'; '.join(f'{n:g}% per {per:g} Intelligence' for n, per in found)} at {intelligence:,.0f} "
                  "Intelligence, on Attacks while Unarmed: PoB parses the line only in part and never applies it")}]


# Explosive Rhythm / Explosive Fervour (MECHB47; COV48's lane rows 17.9 + 17.9, Trarthan Cannon: "Gain 1 Explosive Rhythm
# every (2-3) times you use a Grenade Skill", "Remove all Explosive Rhythm on reaching 10 to gain Explosive Fervour for
# 10 Seconds"; PoB parses neither: ModCache 7491-7493 {} with leftover text, 9302 nil). KeywordPopups (26650308):
# ExplosiveRhythm "Each Explosive Rhythm Buff grants 10% increased Cooldown Recovery Rate to your Grenade Skills";
# ExplosiveFervour "15% increased Attack Speed per different Grenade Skill you've used Recently, causes Grenade Skills to
# ignore their cooldown and fire an additional projectile, and makes Grenades explode on any impact. You cannot gain
# Explosive Rhythm while you have Explosive Fervour". A cycle on the main Grenade skill, from its own row: the build
# phase takes k uses a stack at stack s's rate, min(its uncapped rate, repeats / cooldown x (r0 + 0.1 s) / r0) (r0: its
# Cooldown Recovery, PoB's; the 10% adds to it as an increase), s = 0..9; then 10 s of Fervour at its uncapped rate
# (castRate: no cooldown) with one more projectile, x (N + 1) / N (every projectile a grenade on the boss: MEDIUM-LOW).
# Headline: Fervour's Attack Speed NOT counted (its increase adds to the build's own, which the row doesn't give: the
# lower reading); a row with it as x (1 + 0.15 G) (G: the build's different Grenade skills, the upper reading). The
# "explode on any impact" timing not read. Against PoB's rate (its cooldown-capped Speed all fight), as a DPS MORE.
RHYTHM_EVERY = re.compile(r"^gain 1 explosive rhythm every (\d+) times you use a grenade skill", re.I)
FERVOUR_LINE = re.compile(r"remove all explosive rhythm on reaching (\d+) to gain explosive fervour for (\d+) seconds", re.I)
RHYTHM_CDR, FERVOUR_SPEED = 0.10, 0.15
RHYTHM_ENTRY = "model-mechb47-explosive-rhythm"


def explosive_rhythm_model(main: Skill | None, texts: list[str], row: dict, recovery: float, projectiles: float,
                           grenades: int, forbidden: set[str] = frozenset()) -> tuple[list[dict], list[dict]]:
    """The cycle above: `row` the main skill's useRates row (speed, cooldown, castRate, repeats), `recovery` its Cooldown
    Recovery (1 + increases), `projectiles` PoB's ProjectileCount, `grenades` the build's different Grenade skills."""
    if main is None or RHYTHM_ENTRY in forbidden:
        return [], []
    every = next((int(m.group(1)) for t in texts if (m := RHYTHM_EVERY.search(t.strip()))), 0)
    fervour = next(((int(m.group(1)), int(m.group(2))) for t in texts if (m := FERVOUR_LINE.search(t))), None)
    speed, cooldown = number(row.get("speed")), number(row.get("cooldown"))
    uncapped = max(number(row.get("castRate")), speed)
    repeats, r0 = number(row.get("repeats")) or 1.0, recovery if recovery > 0 else 1.0
    if not every or fervour is None or speed <= 0:
        return [], []
    stacks, seconds = fervour
    if cooldown > 0:
        rates = [min(uncapped, repeats / cooldown * (r0 + RHYTHM_CDR * s) / r0) for s in range(stacks)]
    else:
        rates = [speed] * stacks
    build_time = sum(every / r for r in rates)
    extra = (projectiles + 1) / projectiles if projectiles >= 1 else 1.0

    def factor(attack_speed: float) -> float:
        fervour_uses = seconds * uncapped * attack_speed
        return (every * stacks + fervour_uses * extra) / ((build_time + seconds) * speed)
    low, high = factor(1.0), factor(1 + FERVOUR_SPEED * max(grenades, 1))
    # (MECHB56; MECH100's USES_RAISE) the uses part (Fervour's uncapped uses, no extra projectile) is more uses a second,
    # each one hit: tagged so the ailment readers see them (a factor at or under 1 stays a time cut, as before). The
    # extra projectile (hits a use) stays in the DPS value only (the lower reading for the readers).
    uses = (every * stacks + seconds * uncapped) / ((build_time + seconds) * speed)
    mod = raw_mod("DPS", "MORE", 100 * (low - 1), main.name)
    if uses > 1 + 1e-9 and low > 1 + 1e-9:
        mod[USES_RAISE] = min(uses, low)
    return [mod], [{
        "label": f"{main.name}: Explosive Rhythm / Fervour cycle*", "value": f"x{low:.3f}", "confidence": "MEDIUM-LOW",
        "entry": RHYTHM_ENTRY,
        "basis": (f"PoB reads neither line. A Rhythm every {every} uses, +{RHYTHM_CDR:.0%} Cooldown Recovery each: "
                  f"{stacks} stacks in {build_time:.1f} s ({rates[0]:.2f} -> {rates[-1]:.2f} uses/s), then Explosive "
                  f"Fervour for {seconds} s with no cooldown ({uncapped:.2f} uses/s) and one more projectile "
                  f"(x{extra:.2f}, every grenade taken to reach the boss), against PoB's {speed:.2f} uses/s all fight: "
                  f"x{low:.3f}. Fervour's 15% Attack Speed per different Grenade skill not counted (it adds to the "
                  f"build's own increases, which aren't read: the lower reading); row with it ({grenades} Grenade "
                  f"skill{'s' if grenades != 1 else ''}): x{high:.3f}"),
        "play": (f"Use {main.name} on cooldown to build {stacks} Explosive Rhythm, then fire it nonstop through the "
                 f"{seconds} s of Explosive Fervour.")}]


# Fissures at the boss (MECHB48; RESEARCH37 R37-16, research/radius-transform-jewels-and-fissure-layouts.md; COV48's lane
# row "Skills which create Fissures have a #% chance to create an additional Fissure"). PoB reads no Fissure count
# (checked: every "fissure" in PoB's Modules, SkillStatMap and ModCache: the chance line is left unparsed, ModCache
# 9410-9413; base_number_of_fissures, base_number_of_additional_fissures and skill_additional_fissure_chance_% have no
# statMap in act_str.lua / sup_str.lua), so each Fissure stat set scores ONE Fissure a use. What the game makes a use:
# - its base count (base_number_of_fissures: Forge Hammer 5, Starborn Onslaught 3; the rest one, by their text);
# - the supports' extra Fissures (base_number_of_additional_fissures: Upheaval I 1, Upheaval II 2, Kaom's Madness 3;
#   their less damage / speed PoB already applies, sup_str.lua);
