FISSURE_LIMIT_STATS = {"Forge Hammer": ("forge_hammer_base_maximum_number_of_fissures", 10.0),
                       "Molten Crash": ("molten_crash_max_number_of_fissures", 8.0)}
FISSURE_HALF_WIDTH, FISSURE_ARC_DEGREES, FISSURE_MELEE_METRES, FISSURE_ROW_METRES = 1.0, 120.0, 1.5, 3.0
FISSURE_ENTRY = "model-mechb48-fissures-at-boss"


def fissure_arc_share(boss_radius: float, metres: float) -> float:
    """The share of Fury of the Mountain's randomly aimed Fissures that pass within the boss's reach (see above)."""
    reach = max(boss_radius, 0.0) + FISSURE_HALF_WIDTH
    if metres <= reach:
        return 1.0
    return min(1.0, 2.0 * math.degrees(math.asin(reach / metres)) / FISSURE_ARC_DEGREES)


def fissure_rage_paid(name: str, rage_paid: dict | None) -> tuple[float, str]:
    """(the share of `name`'s uses whose Rage is paid, how) from MECH-C's build.rage_paid ({"share", "asked", "paid"}:
    share = min(1, paid / asked) over all the Rage spenders, None when nothing gains or spends Rage; MECHC48)."""
    if not rage_paid:
        return 0.0, "the build gains no Rage for it to spend, 0"
    share = min(1.0, max(0.0, number(rage_paid.get("share"))))
    asked, paid = number(rage_paid.get("asked")), number(rage_paid.get("paid"))
    if share >= 1.0 - 1e-9:
        return 1.0, f"every use paid: the build's Rage keeps up ({paid:.2f}/s spent of {asked:.2f}/s asked)"
    return share, (f"{share:.0%} of its uses paid: Rage {paid:.2f}/s comes for {asked:.2f}/s asked by all its "
                   f"spenders (cut alike, LOW)")


def fissure_count_model(main: Skill | None, scored: str | None, sets: list[dict], level_stats: dict,
                        support_stats: dict, texts: list[str], boss_radius: float,
                        det_share: float | None = None, forbidden: set[str] = frozenset(),
                        previous: list[dict] | None = None,
                        rage_paid: dict | None = None, cap: float | None = None,
                        overgrown: tuple[float, str] | None = None) -> tuple[list[dict], list[dict]]:
    """A Fissure skill's Fissures a use at the boss against PoB's one (see above). `cap`: the build's Fissure Limit
    (Assumptions.fissure_limit, GEM41), else FISSURE_MAX_A_USE's base. `level_stats` / `support_stats` the
    activeSkills row's, `texts` the build's lines, `det_share` the share of a DETONATED_SETS skill's set-off part the
    detonated model counts (Earthshatter's spikes, Forge Hammer's hammers), None for the others; `rage_spent` MECH-C's
    build.rage_paid (Molten Crash's Rage Fissure); `overgrown` (MECHB65): (share of the build's plants Overgrown, how)
    from overgrown_share, for Entangle's vines."""
    if main is None or main.name not in FISSURE_SETS or FISSURE_ENTRY in forbidden:
        return [], []
    labels, layout = FISSURE_SETS[main.name]
    cap = cap if cap is not None and cap > 0 else FISSURE_MAX_A_USE.get(main.name, math.inf)
    base = min(cap, number(level_stats.get(FISSURE_BASE_STAT)) or 1.0)
    extra = number(support_stats.get(FISSURE_EXTRA_STAT))
    lines = [float(m.group(1)) for t in texts if (m := FISSURE_CHANCE.match(t.strip()))]
    own = number(level_stats.get(FISSURE_CHANCE_STAT))
    chance = min(1.0, (sum(lines) + own) / 100.0)
    rage, rage_how = (0.0, "")
    if main.name in FISSURE_RAGE:
        paid, rage_how = fissure_rage_paid(main.name, rage_paid)
        rage = FISSURE_RAGE[main.name] * paid
    own_hit = FISSURE_OWN_HIT.get(main.name, 0.0)
    count = min(cap, base + extra + rage + chance) + own_hit
    along, along_rows, along_what = FISSURE_ALONG.get(main.name, (1.0, (), ""))
    if count * along <= 1.0 + 1e-9 and main.name not in FISSURE_BESIDE and main.name not in FISSURE_VINES:
        return [], []
    share = fissure_arc_share(boss_radius, FISSURE_MELEE_METRES) if layout == "arc" else 1.0
    row_share = fissure_arc_share(boss_radius, FISSURE_ROW_METRES) if layout == "arc" else None
    dps = unscale_own(sets, previous, FISSURE_ENTRY)
    beside = None  # (FISSURE_BESIDE: the use's other set's DPS)
    stars, star_dps = None, 0.0  # (STAR_FALL: the stars landed a use and the Star Fall set's DPS)
    if main.name in DETONATED_SETS and det_share is not None:
        plain_labels, det_label, *_ = DETONATED_SETS[main.name]
        if scored not in plain_labels + (det_label,):
            return [], []
        plain = max((dps.get(k, 0.0) for k in plain_labels), default=0.0)
        total = plain + dps.get(det_label, 0.0) * det_share
        fissure = plain if labels[0] in plain_labels else dps.get(det_label, 0.0) * det_share
    elif main.name in STAR_FALL:  # (MECHB50: the use = the Impact set's count + the stars landed x the Star Fall set)
        if scored not in labels + (STAR_FALL[main.name],):
            return [], []
        star_set = next((x for x in sets if x.get("label") == STAR_FALL[main.name]), {})
        star_dps = dps.get(STAR_FALL[main.name], 0.0)
        stars = star_fall_hits(level_stats, number(star_set.get("AreaOfEffectRadius")) / 10, boss_radius)
        beside = stars[0] * star_dps
        fissure, total = dps.get(labels[0], 0.0), dps.get(scored or "", 0.0)
    elif main.name in FISSURE_VINES and scored in labels + (FISSURE_VINES[main.name][0],):  # (MECHB51: R42-8)
        vine_label, vine_rate, vine_over = FISSURE_VINES[main.name]
        vine_hit = number(next((x for x in sets if x.get("label") == vine_label), {}).get("AverageDamage"))
        grown = min(1.0, max(0.0, number((overgrown or (0.0, ""))[0])))  # (MECHB65: the Overgrown share's +3)
        vine_rate = vine_rate + (vine_over - vine_rate) * grown
        beside = vine_rate * vine_hit
        fissure, total = dps.get(labels[0], 0.0), dps.get(scored or "", 0.0)
    elif main.name in FISSURE_BESIDE and scored in FISSURE_BESIDE[main.name] + labels:
        beside = max((dps.get(k, 0.0) for k in FISSURE_BESIDE[main.name]), default=0.0)
        fissure, total = dps.get(labels[0], 0.0), dps.get(scored or "", 0.0)
    else:
        total = dps.get(scored or "", 0.0)
        fissure = total if scored in labels else 0.0
    if total <= 0:
        return [], []

    def scale(n: float) -> float:  # (PoB's one Fissure taken as hitting: the share applies to the whole use)
        if beside is not None:  # (the use's other set + n Fissures, over the one set PoB scored)
            return (beside + n * fissure) / total
        return 1.0 + fissure / total * (n - 1.0)
    factor, one = scale(count * share * along), scale(base * along)
    if fissure > 0 and abs(factor - 1.0) < 1e-9:
        return [], []
    # (MECHB57, the brief's item 1, an UNDERCOUNT for the hit readers: each Fissure at the boss is a hit, so a use lands
    # `hits` against PoB's one: the Fissures, plus the use's other set's hit beside them (Molten Crash's slam) and the
    # stars that land (Starborn Onslaught); models.HIT_CUT_PER_USE, the skill used as often. Not counted as hits (the
    # lower reading): Entangle's vines (hits a second, not a use) and a detonated set's set-off part.)
    hits = (count * share * along + (1.0 if main.name in FISSURE_BESIDE else 0.0)
            + (stars[0] if stars is not None else 0.0))
    parts = [f"{base:g} base"] + ([f"+{extra:g} from supports (Upheaval / Kaom's Madness)"] if extra else []) + (
        [f"+{rage:.2f} from its 10 Rage a use ({rage_how})"] if main.name in FISSURE_RAGE else []) + (
        [f"+{chance:.0%} chance of one more ({' + '.join(f'{x:g}%' for x in lines + ([own] if own else []))}"
         f"{', held to 100%' if sum(lines) + own > 100 else ''})"] if chance else [])
    how = {"line": "a fan in melee: every one passes within the boss's reach (R37-16, the fan LOW, the melee count "
                   "MEDIUM-LOW)",
           "slam": "from the slam's landing at the boss: all hit in melee (R37-16, MEDIUM-LOW)",
           "spiral": "a spiral from the hammer lodged at the boss: all hit (R37-16, MEDIUM-LOW)",
           "nova": ("a ring out from the impact on the target: all at the boss (R37-16, MEDIUM), with the impact's own "
                    "area hit beside them (RESEARCH39 R39-5, MEDIUM)"),
           "arc": f"aimed at random over {FISSURE_ARC_DEGREES:g} degrees: {share:.0%} pass within the boss's "
                  f"{boss_radius:g} m + {FISSURE_HALF_WIDTH:g} m at {FISSURE_MELEE_METRES:g} m (R37-16, MEDIUM-LOW)"}[layout]
    if fissure <= 0:
        return [], [{"label": f"{main.name}: {count:.2f} Fissures a use*", "value": "x1", "confidence": "MEDIUM-LOW",
                     "entry": FISSURE_ENTRY,
                     "basis": (f"{'; '.join(parts)}, {how}; but the scored {scored} set isn't a Fissure (or none is "
                               f"set off), so nothing changes")}]
    if layout == "nova":  # (it lands on its target: no range row)
        if stars is not None:  # (MECHB50: the Star Fall beside the Impact set; PoB scores one of the two)
            def with_stars(n_star: float, n: float = count * share) -> float:
                return (n_star * star_dps + n * fissure) / total
            star_part = (f"; and its Star Fall: {stars[3]}: {stars[0]:.2f} land spread evenly over the ring's area "
                         f"(the ring fixed, R40-16), at {star_dps:,.1f} DPS each (the Star Fall set; LOW, the "
                         f"placement isn't in the data). PoB scores the {scored} set alone ({total:,.1f}; an "
                         f"UNDERCOUNT): x{factor:.3f}. Rows: the ring scaled with the star, {stars[1]:.2f} stars, "
                         f"x{with_stars(stars[1]):.3f}; spread evenly over the distance, {stars[2]:.2f}, "
                         f"x{with_stars(stars[2]):.3f}; no star counted, x{with_stars(0.0):.3f}")
        else:
            star_part = f". The Fissures are {fissure / total:.0%} of the {scored} DPS scored: x{factor:.3f}"
        return [with_per_use(raw_mod("DPS", "MORE", 100 * (factor - 1), main.name, tag=FISSURE_ENTRY), hits)], [{
            "label": f"{main.name}: {count:.2f} Fissures a use at the boss*"
                     + (f" + {stars[0]:.2f} stars" if stars is not None else ""), "value": f"x{factor:.3f}",
            "confidence": "MEDIUM" if stars is None else "MEDIUM-LOW", "entry": FISSURE_ENTRY,
            "basis": (f"PoB counts one Fissure a use. The game makes {count:.2f}: {'; '.join(parts)}; {how}"
                      + star_part
                      + (f" (the impact's hit and {count - own_hit:.2f} Fissures; without the impact's own hit, "
                         f"x{scale((count - own_hit) * share):.3f})" if own_hit else "")
                      + ". Not counted: the branching Fissures (2 from each, outward: 0 at the boss, R37-16 LOW)")}]
    rows = "".join(f"; with a base of {b:g} a use (RESEARCH39 R39-7, LOW: not settled), "
                   f"x{scale(min(cap, b + extra + rage + chance) * share * along):.3f}"
                   for b in FISSURE_BASE_ROWS.get(main.name, ()))
    if along != 1.0:  # (R42-5: the areas along each wave)
        parts.append(f"each hitting the boss with {along:g} {along_what} (RESEARCH42 R42-5, MEDIUM-LOW geometry; "
                     "PoB scores one a wave)")
        rows += "".join(f"; {a:g} {along_what} a wave: x{scale(count * share * a):.3f}" for a in along_rows)
    rows += f"; at range only the one aimed at the boss: x{one:.3f}" + (
        f"; at {FISSURE_ROW_METRES:g} m {row_share:.0%} of them: x{scale(count * row_share * along):.3f}"
        if row_share is not None else "")
    return [with_per_use(raw_mod("DPS", "MORE", 100 * (factor - 1), main.name, tag=FISSURE_ENTRY), hits)], [{
        "label": f"{main.name}: {count:.2f} Fissures a use at the boss*", "value": f"x{factor:.3f}",
        "confidence": "MEDIUM-LOW", "entry": FISSURE_ENTRY,
        "basis": (f"PoB counts one Fissure a use. The game makes {count:.2f}: {'; '.join(parts)}; {how}. "
                  + (f"The Fissures are {fissure / total:.0%} of the {scored} DPS scored" if beside is None else
                     (f"Its vines: {vine_rate:.3g} vine hits a second at most on one boss (3 attached "
                      f"to each enemy, 1 s each, one hit on attaching: RESEARCH42 R42-8, MEDIUM / LOW-MEDIUM"
                      + (f"; 3 more on its Overgrown share {grown:.0%}: {overgrown[1]}" if grown > 0 else
                         "; none of its plants Overgrown") +
                      f"), {beside:,.1f} DPS, beside its Fissures ({fissure:,.1f} DPS each), PoB scoring the {scored} "
                      f"set alone ({total:,.1f}; an UNDERCOUNT); every fissure Overgrown (3 more each) a row: "
                      f"x{(beside * FISSURE_VINES[main.name][2] / vine_rate + count * share * fissure) / total:.3f}; "
                      "Overgrown fissures expire 25% slower: the cover is already taken as full, no change"
                      if main.name in FISSURE_VINES else
                      f"One use makes its {FISSURE_BESIDE[main.name][0]} set ({beside:,.1f} DPS) and its Fissures "
                      f"({fissure:,.1f} DPS each), PoB scoring the {scored} set alone ({total:,.1f}; an UNDERCOUNT)"))
                  + f": x{factor:.3f}{rows}. Not "
                  "counted: the end spikes, vines and shockwaves of the extra Fissures (R37-16: beyond the boss, LOW)" + (
                      "; the branching Fissures (2 from each, outward: 0 at the boss, R37-16 LOW)"
                      if number(level_stats.get("number_of_branching_fissures")) else "")),
        "play": (f"Use {main.name} in melee range, facing the boss, so every Fissure runs through it. At range only "
                 f"the one aimed at it hits: x{one:.3f} instead of x{factor:.3f}.")}]


# The Last Lament's "Sacrifice 300 Life to not consume the last bolt when firing" (MECHB48; COV48's lane row 17.3). PoB
# parses it only in part (ModCache 9335: a Life BASE on the skill "Sacrifice", leftover "to not consume the last bolt
# when firing"), so it never applies it (Item.lua's `not modLine.extra`): no overcount from PoB. What it does: at the
# clip's last bolt the shot costs N Life instead of the bolt, so no reload while Life pays. The build decides how often
# (CLAUDE.md: no flat rate): its Life recovery left after the boss's landed hits, its Life costs and its own steady loss
# (recovery.life_flows, as Demon Form's cycle) pays for net / N shots a second; such shots come at PoB's FiringRate with
# no reload, the rest of the fight at PoB's clip-and-reload Speed: a share f = min(1, net / (N x FiringRate)) of the fight
# fires unbroken, and the main skill's uses go from Speed to f x FiringRate + (1 - f) x Speed. MEDIUM-LOW: Life spent
# this way runs the pool down to about N (RESEARCH38 R38-7: the Sacrifice isn't optional and can't pay at N Life or
# less, the bolt then used up, N + 1 likely needed; so the steady state above stands); the defence floors still read the full pool (an overcount of the defences, said in the note).
# Not with Chaos Inoculation (Life 1) or a Life pool of N or less; nothing where no bolt is consumed already.
LAMENT_LINE = re.compile(r"^sacrifice (\d+) life to not consume the last bolt when firing$", re.I)
LAMENT_ENTRY = "model-mechb48-last-bolt-sacrifice"
LAMENT_STATS = ("BoltCount", "FiringRate", "Speed", "EffectiveReloadTime", "ChanceToNotConsumeAmmo", "Life",
                "ChaosInoculation")


def last_bolt_sacrifice_model(main: Skill | None, texts: list[str], stats: dict, flows: tuple, forbidden: set[str] = frozenset()
                              ) -> tuple[list[dict], list[dict]]:
    """The line above on the main Crossbow skill: `stats` PoB's LAMENT_STATS, `flows` recovery.life_flows'."""
    if main is None or LAMENT_ENTRY in forbidden:
        return [], []
    cost = next((float(m.group(1)) for t in texts if (m := LAMENT_LINE.match(t.strip()))), 0.0)
    if cost <= 0:
        return [], []
    speed, firing = number(stats.get("Speed")), number(stats.get("FiringRate"))
    reload, bolts = number(stats.get("EffectiveReloadTime")), number(stats.get("BoltCount"))
    label = f"{main.name}: Life Sacrificed for the last bolt*"
    if bolts <= 0 or reload <= 0 or firing <= speed or number(stats.get("ChanceToNotConsumeAmmo")) >= 100:
        return [], [{"label": label, "value": "x1", "confidence": "MEDIUM-LOW", "entry": LAMENT_ENTRY,
                     "basis": f"{main.name} has no clip to reload (PoB gives no reload for it): the line changes nothing"}]
    life = number(stats.get("Life"))
    if number(stats.get("ChaosInoculation")) > 0 or life <= cost:
        return [], [{"label": label, "value": "x1", "confidence": "MEDIUM-LOW", "entry": LAMENT_ENTRY,
                     "basis": f"your {life:,.0f} Life can't pay {cost:g} a shot: every reload stays"}]
    back, hit_life, spent, steady, parts = flows
    net = back - hit_life - spent - steady
    share = min(1.0, max(net, 0.0) / (cost * firing))
    factor = (share * firing + (1 - share) * speed) / speed
    every = firing / speed
    note = {"label": label, "value": f"x{factor:.3f}", "confidence": "MEDIUM-LOW", "entry": LAMENT_ENTRY,
            "basis": (f"PoB parses the line only in part and never applies it. Your Life recovery {back:,.1f}/s, less "
                      f"{'; '.join(parts) or 'nothing'}{f' and {steady:,.1f}/s of your own loss' if steady > 0 else ''}: "
                      f"{net:,.1f} Life a second pays {max(net, 0.0) / cost:.3f} shots of {cost:g} Life, at "
                      f"{firing:.2f} shots a second with no reload: {share:.0%} of the fight without reloading, the rest "
                      f"at PoB's {speed:.2f} with its {reload:.2f} s reloads: x{factor:.3f} (every reload skipped: "
                      f"x{every:.3f}). Your Life runs down to about {cost:g} while you do it (the defence floors still "
                      "read the full pool; the Sacrifice isn't optional and can't pay at 300 Life or less: RESEARCH38 R38-7)"),
            "play": (f"Keep firing {main.name} past the last bolt while your Life refills; reload only when it's low. "
                     f"Without it: x1; with this build's recovery: x{factor:.3f}.")}
    if factor <= 1 + 1e-9:
        return [], [note]
    # (MECHB56; MECH100's USES_RAISE) the skipped reloads are more shots a second, each one hit: the whole factor
    return [{**raw_mod("DPS", "MORE", 100 * (factor - 1), main.name, tag=LAMENT_ENTRY), USES_RAISE: factor}], [note]


# Runic Bindings (MECHB48; COV48's lane row 12.9, The Unleashed, Revered Vestments: "Gain 1 Runic Binding on Hit with
# Spells, no more than once every 0.5 seconds", "Lose all Runic Bindings when you Shapeshift to gain that much Unbound
# Potential"). An OVERCOUNT: PoB parses neither (ModCache 7509-7510: {} with leftover text). KeywordPopups RunicBinding
# (26650308): "Each Runic Binding grants 10% reduced Spell Damage and 2% reduced Skill cost Efficiency. You can have up to
# 10 Runic Bindings. Runic Bindings last for 10 seconds. Runic Bindings cannot be gained while Shapeshifted". On a main
# Spell that hits: gained at r = min(1 / 0.5 s, its hits a second at its share of the fight). (MECHB49, RESEARCH38
# R38-8, MEDIUM-HIGH: BuffDefinitions runic_binding MergeMode 4, as the charges, Infusions and Fear buffs, whose popup
# says "This duration is refreshed when you gain another": ONE shared timer a new Binding refreshes.) So while gains
# come under 10 s apart (r >= 0.1/s) none lapse and all 10 stand once gained (10 / r s to reach them, 5 s at 2 a second:
# the ramp not taken off, a long fight); slower, each lapses before the next: 10 r on average. MECHB48's reading, each its
# own 10 s (min(10, 10 r)), is the row (it read slow Spells lower: an OVERCOUNT of their DPS, now fixed). 10% reduced
# Spell Damage each (as the line "1% increased Spell Damage" x -10 n, PoB's own parse). The cost
# Efficiency (2% reduced each) isn't read (a small overcount of Mana sustain, said). The Unbound Potential a Shapeshift
# turns them into (KeywordPopups UnboundPotential: 20% increased Damage each, up to 10, one lost every 5 s, all lost on
# turning Human) isn't counted: a main Spell is cast as a Human (an UNDERCOUNT only for a build that shapeshifts to
# spend them, said). HIGH on the penalty's size, MEDIUM on the stacks.
BINDING_LINE = re.compile(r"^gain 1 runic binding on hit with spells, no more than once every (\d+(?:\.\d+)?) seconds$",
                          re.I)
BINDING_MAX, BINDING_SECONDS, BINDING_LESS = 10, 10.0, 10.0
BINDING_ENTRY = "model-mechb48-runic-binding"


def runic_binding_model(main: Skill | None, texts: list[str], stats: dict, forbidden: set[str] = frozenset()
                        ) -> tuple[list[dict], list[dict]]:
    """The penalty above on a main Spell: `stats` PoB's Speed and HitChance, with _main_share."""
    if main is None or BINDING_ENTRY in forbidden:
        return [], []
    every = next((float(m.group(1)) for t in texts if (m := BINDING_LINE.match(t.strip()))), None)
    if every is None:
        return [], []
    label = "Runic Bindings on your Spells*"
    if not main.spell:
        return [], [{"label": label, "value": 0, "confidence": "MEDIUM", "entry": BINDING_ENTRY,
                     "basis": (f"{main.name} isn't a Spell: no Bindings from it (other Spells' hits aren't read; the "
                               "Unbound Potential a Shapeshift makes of them isn't counted)")}]
    hits = hits_per_second(at_main_share(stats))
    rate = min(1.0 / every if every > 0 else math.inf, hits)
    own = min(float(BINDING_MAX), rate * BINDING_SECONDS)  # (each its own 10 s: the row)
    stacks = float(BINDING_MAX) if rate * BINDING_SECONDS >= 1 else rate * BINDING_SECONDS  # (R38-8: one shared timer)
    if stacks <= 0:
        return [], [{"label": label, "value": 0, "confidence": "MEDIUM", "entry": BINDING_ENTRY,
                     "basis": f"{main.name} doesn't hit: no Bindings"}]
    less = BINDING_LESS * stacks
    return [line("1% increased Spell Damage", -less)], [{
        "label": label, "value": f"{stacks:.1f} ({less:.0f}% reduced Spell Damage)", "confidence": "MEDIUM",
        "entry": BINDING_ENTRY,
        "basis": (f"PoB reads neither line. One a hit with Spells at most every {every:g} s: {main.name} hits "
                  f"{hits:.2f} times a second at its share of the fight, so {rate:.2f} a second; they share one "
                  f"{BINDING_SECONDS:g} s timer each new one refreshes (RESEARCH38 R38-8, MEDIUM-HIGH: MergeMode 4): "
                  f"{stacks:.1f} of {BINDING_MAX} stand ({BINDING_MAX / rate if rate > 0 else 0:.0f} s to reach them, "
                  f"not taken off), {BINDING_LESS:g}% reduced Spell Damage each (KeywordPopups RunicBinding, HIGH). Row: "
                  f"each its own {BINDING_SECONDS:g} s, {own:.1f} ({BINDING_LESS * own:.0f}% reduced). Not read: their {2 * stacks:.0f}% reduced Skill cost "
                  "Efficiency (more Mana spent), and the Unbound Potential a Shapeshift would turn them into (20% "
                  "increased Damage each while Shapeshifted: not counted, your main Spell is cast as a Human)"),
        "play": ("The Unleashed's Runic Bindings cut your Spell damage while you cast: Shapeshift to spend them as "
                 f"Unbound Potential. Without them: no penalty; this build: {less:.0f}% reduced Spell Damage.")}]


# Melee Physical damage taken reflected to the attacker (MECHB49; COV48's lane rows 12.9 [unique] / 7.0 [affix]). The
# stat melee_physical_damage_taken_%_to_deal_to_attacker (Stats 1081, game 26650308) is on Mods
# UniquePhysicalDamageTakenPercentToReflect1 (Bramblejack, 250%), PhysicalDamageTakenPercentToReflectUniqueBodyStr2
# (1000%) and a Soul Core (SoulCoreStats 463, 250%) (checked: the stat id over Mods' Stat1-6, SoulCoreStats' Stats,
# PassiveSkills' and GrantedEffectStatSets' stat columns; poe2db not checked: UNVERIFIED as a full list, and the model
# reads the line by its text, whatever carries it). PoB parses it only in part (ModCache 1887 / 3487: a PhysicalDamage
# BASE with "taken reflected to Attacker" left over), so it never applies it (Item.lua's `not modLine.extra`): no
# overcount from PoB, the reflected damage an UNDERCOUNT. What it deals: N% of the Physical damage each boss Melee hit
# deals you (after your mitigation: PoB's PhysicalTakenHit, the boss's average Physical hit, LOW: each Melee hit taken
# to carry it), on each landed hit (a Blocked or Evaded hit deals you none) of the boss's Melee share
# (boss_melee_share's lower bound, as Thorns' Retaliation: 0 on the worst-case preset and on bosses not read), one hit
# per damaging boss use (bosses.benefit_skill_time, LOW). Whether the reflected damage is a Hit the boss's Armour
# reduces isn't in its text or KeywordPopups (Armour: "reduces Damage taken from Hits"): UNVERIFIED; the headline takes
# it as a hit (PoB's Armour formula A / (A + 10 x hit), the preset's enemyArmour: the lower reading), the row without it.
# Not counted: the boss's other damage-taken modifiers (LOW) and any reflect-damage-taken modifier on the boss
# (bosses.py's presets carry none; whether the game's bosses have one: UNVERIFIED).
MELEE_REFLECT = re.compile(r"^(\d+(?:\.\d+)?)% of Melee Physical Damage taken reflected to Attacker$", re.I)
MELEE_REFLECT_ENTRY = "model-mechb49-melee-reflect"
MELEE_REFLECT_FIELDS = ["PhysicalTakenHit", "EvadeChance", "EffectiveBlockChance", "enemySkillTime"]


def melee_reflect_model(texts: list[str], stats: dict, boss: str, every: float, land: float,
                        boss_armour: float) -> tuple[float, list[dict]]:
    """(added DPS, notes) for "N% of Melee Physical Damage taken reflected to Attacker" (see above): `every` the seconds
    between boss hits, `land` the share that land, `boss_armour` the preset's enemyArmour."""
    lines = [float(m.group(1)) for t in texts if (m := MELEE_REFLECT.match(t.strip()))]
    if not lines:
        return 0.0, []
    percent = sum(lines)
    taken = max(number(stats.get("PhysicalTakenHit")), 0.0)
    share, share_how = boss_melee_share(boss)
    hits = (land / every if every > 0 else 0.0) * share
    raw = taken * percent / 100
    cut = boss_armour / (boss_armour + 10 * raw) if raw > 0 and boss_armour > 0 else 0.0
    dps, row = hits * raw * (1 - cut), hits * raw
    label = f"{percent:g}% of Melee Physical damage taken reflected*"
    basis = (f"PoB parses the line only in part and never applies it. {percent:g}% of the {taken:,.0f} Physical damage a "
             f"boss hit deals you (PoB's PhysicalTakenHit, after your mitigation; each Melee hit taken to carry it, LOW) "
             f"= {raw:,.0f} a landed Melee hit; {land:.0%} of its hits land, one every {every:.2f} s, and {share_how}: "
             f"{hits:.3f} a second. Taken as a hit the boss's Armour ({boss_armour:,.0f}) reduces by {cut:.0%} "
             f"(UNVERIFIED: the lower reading): {dps:,.1f} DPS; as damage Armour doesn't touch: {row:,.1f}")
    note = {"label": label, "value": f"{dps:,.1f} DPS", "confidence": "LOW", "entry": MELEE_REFLECT_ENTRY,
            "basis": basis, "play": "Let the boss's Melee hits land on you (no Evasion or Block against them) to "
                                    "reflect their Physical damage."}
    return dps, [note]


# Forge Hammer's throw-and-recall loop (MECHB49; RESEARCH38 R38-6, HIGH that the recall is a use with no Impact, MEDIUM on
# the rates). ActiveSkills forge_hammer: "While the hammer is lodged in the ground, reusing this Skill recalls the hammer
# and resets the Skill's cooldown"; its Recall set (ForgeHammerRecallPlayer) has no damage and 70% more attack speed
# (supplementary_stat_container_attack_speed_+%_final 70); "Cooldown does not recover while the hammer is lodged". PoB
# caps the skill at one use per its 8 s cooldown (CalcOffence 3005-3009), so it never counted the recall, and never the
# loop: a player who throws and recalls lands an Impact every T + T / 1.7 s (T the throw's attack time, PoB's CastRate
# before the cap: the bridge's castRate), an UNDERCOUNT up to ~x5 for a build with no Warcry to shatter it (a play
# strategy: the headline there, labelled; the hammer's return delay, if any, UNVERIFIED). With a Warcry the hammer is
# left lodged for it, so a cycle is T + the Warcry's wait + 8 s (no recovery while lodged): PoB's 1 / 8 s a little high;
# both are rows there, the headline PoB's (the detonated model's shatter share on it).
FORGE_HAMMER, FORGE_RECALL_SPEED = "Forge Hammer", 1.7
FORGE_LOOP_ENTRY = "model-mechb49-forge-hammer-loop"


def forge_hammer_loop_model(main: Skill | None, speed: float, cast_rate: float, cooldown: float, cries: float,
                            forbidden: set[str] = frozenset()) -> tuple[list[dict], list[dict]]:
    """The throw-recall loop above on a main Forge Hammer: `speed` PoB's capped uses a second, `cast_rate` one throw's
    rate before the cap, `cooldown` its cooldown (s), `cries` the build's Warcries a second."""
    if main is None or main.name != FORGE_HAMMER or FORGE_LOOP_ENTRY in forbidden or speed <= 0 or cast_rate <= 0:
        return [], []
    throw = 1.0 / cast_rate
    loop = 1.0 / (throw + throw / FORGE_RECALL_SPEED)
    lodged = 1.0 / (throw + (1.0 / cries if cries > 0 else 0.0) + cooldown) if cooldown > 0 else speed
    label = "Forge Hammer: throw and recall, an Impact each loop*"
    rows = (f"PoB scores its Impact at most once per {cooldown:g} s cooldown ({speed:.3f}/s). Throwing and recalling "
            f"(the recall resets the cooldown, 70% faster, no Impact) lands one every {throw:.2f} + {throw / FORGE_RECALL_SPEED:.2f} s"
            f" = {loop:.3f}/s (x{loop / speed:.2f}; the hammer's return delay UNVERIFIED); lodged for a Warcry, one every "
            f"{throw:.2f} s + the Warcry's wait + {cooldown:g} s = {lodged:.3f}/s (x{lodged / speed:.2f})")
    if cries > 0 or loop <= speed:
        return [], [{"label": label, "value": "rows only", "confidence": "MEDIUM", "entry": FORGE_LOOP_ENTRY,
                     "basis": rows + ("; the build has a Warcry to shatter it, so it's left lodged: PoB's rate with the "
                                      "shatter share stays the headline" if cries > 0 else "")}]
    factor = loop / speed
    # (MECHB56; MECH100's USES_RAISE) the loop's Impacts are more uses a second, each one hit: the whole factor
    return [{**raw_mod("DPS", "MORE", 100 * (factor - 1), main.name, tag=FORGE_LOOP_ENTRY), USES_RAISE: factor}], [{
        "label": label, "value": f"x{factor:.3f}", "confidence": "MEDIUM", "entry": FORGE_LOOP_ENTRY,
        "basis": rows + ": with no Warcry in the build, the loop is the headline (a play strategy, RESEARCH38 R38-6)",
        "play": (f"Throw Forge Hammer, then press it again at once to recall it, and repeat: {loop:.2f} Impacts a second "
                 f"instead of one per {cooldown:g} s. Without it: x1; with it: x{factor:.3f}.")}]


# Eye of Winter's shards on the boss (MECHB49; RESEARCH38 R38-14, MEDIUM on the shape, LOW on the number; an UNDERCOUNT
# of ~x2-4: PoB scores ONE shard a use, probe POE2T3438, and GEM19's eye_of_winter_model adds its first hit's 900% more).
# The Eye "does not Hit enemies", so it flies through the boss (Projectiles: the Eye 2.25 m/s, a shard 10 m/s), firing
# its shards (ProjectileCount a second, base 30) evenly around it: while it's inside the boss's hit radius R every shard
# starts in the boss and hits it once (2R / 2.25 s of them); from x > R a shard meets it with chance asin(R / x) / pi,
# integrated over the approach from the build's fighting distance d and the same length out (the shards' and the Eye's
# range aren't in any client file: the exit taken as long as the approach, LOW). N shards a use = 30 / s x (2R / v +
# 2 x the integral / v). A use deals (1 + 9) + (N - 1) shard hits against PoB's 1, so on top of GEM19's line this
# model's factor is (1 + more + N - 1) / (1 + more) (one model's DPS MORE on the other's). Headline: the Eye aimed
# through the boss (a play choice, LOW); rows: the first hit only (GEM19's alone) and aimed past it (the side terms).
EYE_SPEED, EYE_SHARDS = 2.25, 30.0  # Metadata/Projectiles/FrozenSphere ProjectileSpeed 225; EyeOfWinterPlayer 30 a second
EYE_SHARDS_ENTRY = "model-mechb49-eye-shards"


def eye_side_shards(rate: float, radius: float, distance: float, steps: int = 200) -> float:
    """Shards that meet a boss of hit radius `radius` from outside it while the Eye travels from `distance` to it."""
    if distance <= radius or radius <= 0:
        return 0.0
    width = (distance - radius) / steps
    total = sum(math.asin(radius / (radius + (i + 0.5) * width)) / math.pi for i in range(steps)) * width
    return rate * total / EYE_SPEED


def eye_shards_model(main: Skill | None, stats: dict, radius: float, distance: float, first_factor: float,
                     forbidden: set[str] = frozenset()) -> tuple[list[dict], list[dict]]:
    """Eye of Winter's shards that hit the boss (above): `stats` PoB's AverageDamage, Speed, TotalDPS (GEM19's line
    taken back out: TotalDPS / first_factor) and ProjectileCount; `first_factor` GEM19's DPS factor now (1 for none)."""
    if main is None or main.name != EYE or EYE_SHARDS_ENTRY in forbidden or main.triggered:
        return [], []
    hit, uses = number(stats.get("AverageDamage")), number(stats.get("Speed"))
    total = number(stats.get("TotalDPS")) / max(first_factor, 1e-9)
    rate = number(stats.get("ProjectileCount")) or EYE_SHARDS
    if hit <= 0 or uses <= 0 or total <= 0 or radius <= 0:
        return [], []
    inside = rate * 2 * radius / EYE_SPEED
    side = eye_side_shards(rate, radius, max(distance, radius))
    shards, past = inside + 2 * side, 2 * side
    first_more = first_factor - 1  # (GEM19's extra over PoB's TotalDPS)

    def factor(n: float) -> float:
        return (1 + first_more + max(n - 1, 0.0) * hit * uses / total) / (1 + first_more)
    value, past_value = factor(shards), factor(past)
    if value <= 1 + 1e-9:
        return [], []
    return [with_per_use(raw_mod("DPS", "MORE", 100 * (value - 1), main.name, tag=EYE_SHARDS_ENTRY),
                         max(1.0, shards))], [{  # (GEM33: the shards a cast landing, MECH99's survey)
        "label": f"{main.name}: about {shards:.0f} shards a cast hit the boss*", "value": f"x{value:.3f}",
        "confidence": "LOW", "entry": EYE_SHARDS_ENTRY,
        "basis": (f"PoB counts one shard a use. The Eye flies through the boss (it hits nothing itself) at {EYE_SPEED:g} "
                  f"m/s firing {rate:g} shards a second around it: {inside:.1f} while inside its {radius:g} m hit radius "
                  f"(each hits once) + {side:.1f} coming in from {distance:g} m and as many going out (asin(R / x) / pi "
                  f"of them; the exit range UNVERIFIED) = {shards:.1f} a cast (RESEARCH38 R38-14: MEDIUM shape, LOW "
                  f"number), each PoB's {hit:,.0f} shard, on top of the first hit's bonus: x{value:.3f}. Rows: the first "
                  f"hit only, x1; aimed past the boss ({past:.1f} shards), x{past_value:.3f}"),
        "play": (f"Aim Eye of Winter through the boss so it flies through its body: about {shards:.0f} shards hit "
                 f"(x{value:.3f}); aimed past it, about {past:.0f} (x{past_value:.3f}).")}]


# Minions alive, each one dealing its damage (MECHB50; the manager 03:05, PLANS6 kw-pack.md; probe POE2T4749,
# scratch/mechb50/p4749.log: an UNDERCOUNT, large). PoB's Full DPS takes a minion skill's minion output x the gem's
# count (Calcs.lua 334-368, calcs.getActiveSkillCount: the gem's `count` field), and the bridge sets that count to 1
# (bridge gemInstance): so PoB scores ONE minion whatever the build keeps alive (probe: Raise Zombie's Full DPS 32.0 =
# one zombie at a limit of 10; Wolf Pack 46.8 = one wolf of 3-6). Nothing else multiplied it (checked: every "Minions deal
# 1% more Damage" line in models / assumptions is a per-skill model of its own: the meta-triggered Temporary minions
# (minion_count), Unearth's constructs, the dead share, Gigantic; Objective.entry_scales' users none for minions). The
# count, from the build's own limits (CLAUDE.md: no flat rate):
# - Persistent minions with no duration (Skeletal Warriors / Snipers / ..., Companions, Spectres): PoB's minion limit
#   (the bridge's `limit`: the minion's limit stat + ActiveMinionLimit, with the build's "+N to maximum" lines), else the
#   gem's own skill_desired_initial_amount (`desired`), else 1. A Reviving minion is taken alive all fight: its deaths are
#   the minion-death model's (the "100% less" dead share there multiplies this). HIGH for the count, MEDIUM that all of
#   them reach the boss.
# - Wolf Pack: the pack is one Companion (its text: "treated as a single Companion for effects that count or limit
#   Companions"), with skill_wolf_pack_size wolves (3 at levels 1-6, 4 at 7-12, 5 at 13+, 6 at 20: PoB act_str / poe2db;
#   the gem's level row read; quality's +0.05 a point not read, the lower reading).
# - Temporary minions with a duration need what pays a raise, so how many stand is the build's supply: Raise Zombie (limit
#   10, 20 s; a corpse or a Power Charge a raise) since MECHB53 from zombie_alive_count; others PoB's one kept, labelled
#   (UNVERIFIED, an undercount where the supply is there). Skills with their own count model are left to it (Unearth; meta-triggered minions).
# Only the hits multiply: several minions' Ignites / Bleeds don't add on one boss (the strongest counts, KeywordPopups
# Debuff), so the minion's damage over time (PoB's CombinedDPS - TotalDPS) is taken once (the lower reading; Poison, which
# stacks, is an undercount there, labelled). The entry is scaled through Objective.entry_scales.
MINION_COUNT_ENTRY = "model-mechb50-minion-count"
WOLF_PACK, WOLF_PACK_STAT = "Wolf Pack", "skill_wolf_pack_size"
MINION_OWN_COUNT = frozenset({"Unearth", "Skyfall"})  # (MECHB62: skyfall_minion_model)
# (MECHB63; RESEARCH59 R59-11, research/skyfall-manifest-limit-lines-r59.md) "+N to Limit" lines on Skyfall's "[Limit] 12
# [Temporary Minions]" and Manifest Rune's "[Limit] 10 Summoned Verisium Manifestations" (neither skill has the Limit
# type; "Temporary Minion" is no skill type, so "Temporary Minion Skills" means skills summoning Temporary Minions by
# their text): temporary_minion_limit_+ "Temporary Minion Skills have +N to Limit of Minions summoned" raises both
# (MEDIUM; carriers: the passives Expendable Army / Known by All, a corruption upgrade, the Genesis Tree ring "of
# Multitudes", the Alloy "of the Stars"); base_limit_+ "Skills have +N to Limit" probably does (MEDIUM-LOW, R58-9's
# reading of 0.4.0: a cap described as a Limit is modifiable; carrier the unique UniqueBaseLimit1; Overabundance can't
# socket into them): in the headline, the cap without it a row. They add before Archon of Undeath's 100% more.
TEMP_MINION_LIMIT_LINE = re.compile(r"^Temporary Minion Skills have \+(\d+) to Limit(?: of Minions summoned)?$", re.I)
SKILLS_LIMIT_LINE = re.compile(r"^Skills have \+(\d+) to Limit$", re.I)


def temporary_minion_limit(texts: list[str], base: float) -> tuple[float, float, str]:
    """(the Limit with the build's lines, the Limit without the "Skills" line (the row), how) for a skill summoning
    Temporary Minions whose own cap is `base` (see above)."""
    temp = sum(int(m.group(1)) for t in texts if (m := TEMP_MINION_LIMIT_LINE.match(t.strip())))
    skills = sum(int(m.group(1)) for t in texts if (m := SKILLS_LIMIT_LINE.match(t.strip())))
    if not temp and not skills:
        return base, base, ""
    parts = ([f"+{temp:g} from Temporary Minion Skills' Limit lines (MEDIUM)"] if temp else []) + (
        [f"+{skills:g} from 'Skills have +N to Limit' (MEDIUM-LOW; row without it: {base + temp:g})"] if skills else [])
    return base + temp + skills, base + temp, f"Limit {base:g} {' '.join(parts)} (RESEARCH59 R59-11)"


def minion_alive_count(skill: Skill, pack: float = 0.0) -> tuple[float, str, str]:
    """(minions alive dealing damage, how, confidence) for a minion skill (see above); 1 = PoB's own."""
    summon = skill.summon or {}
    if skill.minion is not None or skill.name in MINION_OWN_COUNT:
        return 1.0, "counted by its own model", "-"
    if number(summon.get("duration")) > 0 or not summon.get("persistent"):  # (Raise Zombie: zombie_alive_count)
        return 1.0, (f"Temporary minions ({number(summon.get('duration')):g} s, limit {number(summon.get('limit')):g}): "
                     "how many stand is the build's corpse / charge supply, not counted (PoB's one kept; UNVERIFIED, an "
                     "undercount where the supply is there)"), "UNVERIFIED"
    limit, desired = number(summon.get("limit")), number(summon.get("desired"))
    if skill.name == WOLF_PACK and pack > 0:
        packs = max(limit, 1.0)
        return packs * pack, (f"{packs:g} pack{'s' if packs != 1 else ''} of {pack:g} wolves (skill_wolf_pack_size at "
                              "its level; one Companion each)"), "HIGH (all in reach: MEDIUM)"
    if limit >= 1:
        return limit, f"its minion limit {limit:g} (PoB's, with the build's +maximum lines)", "HIGH (all in reach: MEDIUM)"
    if desired >= 1:
        return desired, f"the gem's {desired:g} (skill_desired_initial_amount)", "HIGH (all in reach: MEDIUM)"
    return 1.0, "no count given: PoB's one", "-"


# Raise Zombie's zombies alive (MECHB53; RESEARCH44 R44-7, research/rq51-staff-leylines-zombie-mote-r44.md; the manager
# 16:56; was PoB's one, UNVERIFIED). Its text: "Consume a Corpse or Power Charge to create a short-lived Zombie. Zombies
# created from Power Charges are Empowered and also create two additional non-empowered Zombies" (RaiseZombiePlayer,
# game 26650308: base_number_of_zombies_allowed 10, base_skill_effect_duration 20000; Empowered gives
# power_charged_zombie_movement_speed_+%_final 25, _damage_taken_-%_final 30 and, per level (GrantedEffectStatSetsPerLevel),
# power_charged_zombie_hit_damage_+%_final 100 at level 1 to 253 at 20: "Empowered Zombies deal (100-253)% more damage
# with Hits" (poe2db, read 21 Nov). PoB has no statMap for the last (act_int.lua 16690: listed, not mapped), so the
# Empowered one's hits count x(1 + that) here: the count is in hit-weighted zombies, the cap taken off pro rata). A raise
# with neither makes nothing. So zombies made a second = 3 x raises paid by a Power Charge + raises paid by a corpse, and
# alive = min(limit, that x the duration), from the build's own supply (CLAUDE.md: no flat rate):
# - presses a second: its group's use rate (conditions.skill_use_rate: once per its duration, or the search's chosen rate
#   up to its limit / duration);
# - Power Charges reaching it: conditions.charges_reaching(build, "Power", "Raise Zombie") (MECHC51; the charge model's
#   split among the consumers);
# - corpses: the boss preset's killed adds and the build's own sources (corpse_supply), its even share with the build's
#   other corpse users; on a lone boss none.
# Which is spent when both are there isn't stated (R44-7, checked: every Stats id holding zombie, and charge / corpse
# priority ids; Odealo's guide implies the charge): headline Power Charge first (LOW), row corpse first. No raise paid
# (no Power Charge source, no corpse): 0 zombies, the note says so. raise_zombie_does_not_use_corpses ("does not require
# a corpse") has no carrier (checked: Mods, PassiveSkills, GrantedEffectStatSets / PerLevel, GrantedEffectQualityStats,
# SoulCoreStats by stat row, 26650308; poe2db not checked: UNVERIFIED there), so it isn't read.
RAISE_ZOMBIE = "Raise Zombie"
ZOMBIES_PER_CHARGE = 3  # (the Empowered one + two more: its text)
ZOMBIE_EMPOWERED_STAT = "power_charged_zombie_hit_damage_+%_final"


def zombie_alive_count(presses: float, charges: float, corpses: float, limit: float, duration: float,
                       empowered_more: float = 0.0) -> tuple[float, str, str]:
    """(zombies alive, hit-weighted; how; confidence) for Raise Zombie (see above): `presses` its uses a second,
    `charges` the Power Charges a second reaching it, `corpses` its corpses a second, `limit` / `duration` PoB's (the
    build's lines in), `empowered_more` the Empowered zombie's % more hit damage (power_charged_zombie_hit_damage_+%_final)."""
    presses, charges, corpses = max(number(presses), 0.0), max(number(charges), 0.0), max(number(corpses), 0.0)
    limit, duration = max(number(limit), 0.0) or 10.0, max(number(duration), 0.0)

    more = max(number(empowered_more), 0.0) / 100

    def alive(paid_charge: float, paid_corpse: float) -> tuple[float, float]:
        made = ZOMBIES_PER_CHARGE * paid_charge + paid_corpse
        weight = (made + more * paid_charge) / made if made > 0 else 1.0  # (the Empowered one's hits x(1 + more))
        return min(limit, made * duration) * weight, made
    c = min(charges, presses)
    k = min(corpses, presses - c)
    head, made = alive(c, k)
    k2 = min(corpses, presses)
    row, _ = alive(min(charges, presses - k2), k2)
    how = (f"{presses:.3f} raises/s, {c:.3f} paid by a Power Charge ({ZOMBIES_PER_CHARGE} zombies each: the Empowered one "
           f"+ 2) and {k:.3f} by a corpse (1 each): {made:.3f} zombies/s x {duration:g} s, at most {limit:g}"
           + (f", the Empowered ones' hits x{1 + more:g} (power_charged_zombie_hit_damage_+%_final, PoB 0)" if more and c
              else "")
           + f" = {head:.2f} zombies' hits (a Power Charge spent first whenever held: R44-7, LOW); row, a corpse first: "
           f"{row:.2f}")
    if presses <= 0:
        how = "its raises aren't rated (no press rate): 0 zombies"
    elif head <= 0:
        how = (f"{presses:.3f} raises/s, but no Power Charge reaches it and no corpse is there (nothing dies on a "
               "single boss without killable adds): each raise makes nothing, 0 zombies (no flat rate)")
    return head, how, "LOW" if c > 0 and k2 > 0 else "MEDIUM"


def minion_count_scale(count: float, hit_dps: float, combined_dps: float) -> float:
    """The Full DPS entry's scale for `count` minions: hits x count, the damage over time once (see above)."""
    if count <= 1 or combined_dps <= 0:
        return 1.0
    hit = min(max(hit_dps, 0.0), combined_dps) if hit_dps > 0 else combined_dps
    return (hit * count + (combined_dps - hit)) / combined_dps


# Skyfall's Verisium Comet-Spawn (MECHB62; RESEARCH58 R58-7, research/skyfall-comet-spawn-r58.md, HIGH except the duration;
# an UNDERCOUNT: PoB had no minion for it, the bridge's installSkyfallMinion adds one). PoB scores ONE minion. How many
# stand comes from the build (CLAUDE.md: no flat rate): Skyfall needs 270 Glory at gem 20 and makes 100% of the Runic Ward
# the build spends as Glory (models.GLORY_FROM_WARD, MECH-C's glory_plan from build.ward_sustain), so its casts a second
# are its Glory's (Assumptions.glory_caps); each cast makes 3 (verisium_comet_number_of_minions_to_create), 6 when it
# consumes a Verisium Infusion (the Verisium-Infused set adds its own 3); each lives the skill's duration (20 s,
# base_skill_effect_duration, MEDIUM-HIGH that it times them: no other timed effect, "Temporary" minions), at most its
# Limit 12 (base_number_of_verisium_octopus_minions_allowed; the bridge's instanceLimit when it reads it). Alive =
# min(limit, a cast's minions x casts a second x duration), Archon of Undeath's doubled limit mixed in where it binds
# (undeath_limit_mix). No Ward spent: no cast, 0 minions (said). (MECHB64, MECHB63's next (c)) The Infused share: "Consumes
# a Verisium Infusion, if possible, to increase the number of Minions summoned" (ActiveSkills skyfall), 6 a cast then;
# the share of casts that find one is Assumptions.skyfall_infused's (the build's Verisium supply, MECH-C's infusion_supply
# "Any"; Skyfall first, as the other consumers "prioritise using non-Verisium Infusions": RESEARCH60 R60-7, HIGH),
# so 3 + 3 x share a cast; every cast Infused (6) the row. The slam PoB lacks (GAExpedition2OctopusSlam: 95% damage, 2 s cooldown; R58-7) takes one of the
# minion's attacks each cooldown: of its A attacks a second, min(1, 1 / (2 A)) are slams at x0.95 (its 60% Physical as
# Cold not applied: the boss's armour against its Cold resistance, UNVERIFIED either way; its 15% more at the centre a
# row). All of them taken to reach the boss (as minion_counts, MEDIUM). The count scales the Comet-Spawn's own Full DPS
# entry (SKYFALL_MINION, the bridge names it apart from the comet's), as minion_counts does: NOT a "Minions deal N% more
# Damage" line, which PoB turns into one bigger hit, and armour cuts a big Physical hit far less than many small ones
# (probe POE2T4975: 100% more gave the Comet-Spawn x3.0 its DPS, 1,070% more x35.2). Its damage over time, if the build
# gives it any, is multiplied too (a minion Ignite / Bleed doesn't add on one boss: LOW, said).
SKYFALL = "Skyfall"
SKYFALL_PER_CAST, SKYFALL_PER_INFUSED_CAST = 3, 6
SKYFALL_LIMIT, SKYFALL_SECONDS = 12.0, 20.0
SKYFALL_SLAM_MORE, SKYFALL_SLAM_CENTRE, SKYFALL_SLAM_COOLDOWN = 0.95, 1.15, 2.0
SKYFALL_ENTRY = "model-mechb62-skyfall-minions"
SKYFALL_MINION = "Verisium Comet-Spawn"  # (its Full DPS entry's name: engine/bridge.lua's SkillDPS export)


def skyfall_minion_model(uses: float, uses_how: str, limit: float, seconds: float, speed: float,
                         undeath: tuple[float, float] | None = None, limit_how: str = "",
                         infused: tuple[float, str] = (0.0, "")) -> tuple[float, list[dict]]:
    """(the Comet-Spawn entry's scale, notes) for Skyfall's Comet-Spawn (see above): `uses` Skyfall's casts a second (its Glory), `limit` /
    `seconds` its Limit and duration, `speed` one minion's attacks a second (PoB's), `undeath` Archon of Undeath's mix."""
    uses, limit = max(number(uses), 0.0), max(number(limit), 0.0) or SKYFALL_LIMIT
    seconds = max(number(seconds), 0.0) or SKYFALL_SECONDS
    share, infused_how = min(max(number(infused[0]), 0.0), 1.0), infused[1]
    per_cast = SKYFALL_PER_CAST + (SKYFALL_PER_INFUSED_CAST - SKYFALL_PER_CAST) * share

    def count_at(lim: float, per: float = per_cast) -> float:
        return min(lim, per * uses * seconds)
    count, mix_how = undeath_limit_mix(count_at, limit, undeath)
    if not mix_how:
        count = count_at(limit)
    infused = count_at(limit, SKYFALL_PER_INFUSED_CAST)
    slams = min(1.0, 1.0 / (SKYFALL_SLAM_COOLDOWN * speed)) if speed > 0 else 0.0
    factor = 1.0 - slams * (1.0 - SKYFALL_SLAM_MORE)
    centre = 1.0 - slams + slams * SKYFALL_SLAM_MORE * SKYFALL_SLAM_CENTRE
    scale = count * factor
    per_how = (f"{per_cast:.2f} Comet-Spawn a cast ({share:.0%} of casts Verisium-Infused, 6 each: {infused_how})"
               if share > 0 else f"{SKYFALL_PER_CAST} Comet-Spawn a cast"
               + (f" (no Verisium Infusion reaches it: {infused_how})" if infused_how else ""))
    how = (f"{uses:.3f} casts a second ({uses_how}) x {per_how} x {seconds:.3g} s each, at most "
           f"{limit:g}{' (' + limit_how + ')' if limit_how else ''}{'; ' + mix_how if mix_how else ''} = {count:.2f} alive"
           if uses > 0 else
           f"no cast: {uses_how or 'its Glory comes from Runic Ward spent, and the build spends none'}: 0 Comet-Spawn "
           "(no flat rate)")
    return scale, [{
        "label": f"{SKYFALL}: {count:.3g} Verisium Comet-Spawn dealing damage*", "value": f"x{scale:.3f}",
        "confidence": "MEDIUM" if uses > 0 else "HIGH", "entry": SKYFALL_ENTRY,
        "basis": (f"PoB had no minion for Skyfall (the bridge adds the Comet-Spawn: R58-7) and scores one; {how}. Its slam "
                  f"(95% damage, 2 s cooldown, a skill PoB lacks) takes {slams:.0%} of its attacks: x{factor:.3f} (the "
                  f"slam's 15% more at the centre: x{centre:.3f}, a row). Rows: every cast Verisium-Infused (6 a cast), "
                  f"{infused:.2f} alive (x{infused * factor:.3f}). All taken to reach the boss (MEDIUM); a minion "
                  "Ignite / Bleed from the build's own lines would be multiplied too (LOW)"),
        "play": (f"Spend Runic Ward to fill Skyfall's Glory, and cast it whenever it is ready: about {count:.1f} "
                 f"Comet-Spawn stand (x{scale:.3f} on one); with a Verisium Infusion each cast makes 6 "
                 f"({infused:.1f} stand).")}]


# (MECHB63; GEM40's find, the manager 24 Nov 18:50, a DPS OVERCOUNT on every Warcry build) The time a Warcry's own cast
# takes from the main skill. The Warcry models count each Warcry at its use rate (conditions.skill_use_rate: its cooldown,
# else once per its duration), but its casts' time was charged only where another model charges it: press_model (a
# Warcry group pressed in Full DPS), Search.press_sync (a rate the search chose), roar_model (Ferocious Roar used for its
# own effects), Kaom's embodiment (Ancestral Cry, MECHB29) and glory_busy (a Glory skill's presses). The rest (example
# build 13's Infernal Cry, 0.162 uses/s) cost the main skill nothing. Assumptions.warcry_presses picks the Warcries none
# of those charge and hands them here: (name, uses a second, why, seconds a use) each, a use's seconds being
# press_action's (the bridge's castRate: 1 / WarcryCastTime with the build's warcry speed). The time comes off the main
# skill as "less Attack and Cast Speed" (as remnant_presses and Kaom's casts do; the lines multiply in PoB, so two such
# charges come off a little short, LOW). Using a Warcry while moving or between the main skill's uses without losing any
# of them isn't counted (MEDIUM: a Warcry is a skill use of its own, KeywordPopups Warcry).
WARCRY_PRESS_MOST = 0.9


def warcry_press_model(presses: list[tuple[str, float, str, float]], main: str | None) -> tuple[list[dict], list[dict]]:
    """(mods, notes): the main skill's time spent casting the Warcries in `presses` ((name, uses/s, why, seconds a use)),
    as one "less Attack and Cast Speed" line on `main` (at most WARCRY_PRESS_MOST of the fight)."""
    took = [(name, uses, why, seconds) for name, uses, why, seconds in presses if uses > 0 and seconds > 0]
    busy = min(sum(uses * seconds for _, uses, _, seconds in took), WARCRY_PRESS_MOST)
    if busy <= 0 or not main:
        return [], []
    parts = "; ".join(f"{name} {uses:.3f}/s ({why}) x {seconds:.2f} s" for name, uses, why, seconds in took)
    return [line("1% more Attack and Cast Speed", -100 * busy, skill=main)], [{
        "label": f"Time casting Warcries ({main})*", "value": f"x{1 - busy:.3f}",
        "basis": (f"{parts}: {busy:.1%} of the fight not spent on {main} (each Warcry at the use rate its models count, "
                  "its cast time with the build's warcry speed). Without the Warcries: x1"),
        "play": f"Each Warcry takes its cast time from {main}: {', '.join(n for n, *_ in took)} on cooldown.",
        "confidence": "MEDIUM (game cooldowns and cast times; using a Warcry costs its whole cast time)"}]


# Bear skills' added base attack time from the default stance (MECHB50; PLANS7 gs-bear-stance.md, an OVERCOUNT): the
# game's bear_skills_additional_base_attack_time_when_performing_from_default_stance, "+{0} seconds to base attack time
# if not standing" (GrantedEffectStatSets 26650308: Furious Slam 400, Rampage 500, Walking Calamity 300 ms; the mirror
# ..._from_standing_stance, "if standing": Landslide -333, a "[DNT] Landslide" (ActiveSkills bear_landslide) PoB doesn't
# have, and the bear companion's slam -500, a monster skill). PoB reads neither (checked:
# FuriousSlamPlayer castTime 1, no statMap for the stat; no Modules hit) and nothing modifies them (checked: the three
# stance stat ids in Mods, PassiveSkills, GrantedEffectQualityStats: 0 rows). PoB adds a BASE "Speed" mod's seconds to
# a skill's base attack time (CalcOffence 2881-2883), so the added time goes in as that. Which skills leave the bear
# standing isn't in the stat data (is_in_bear_standing_stance_or_would_be has no carrier in the stat sets).
# (MECHB51; RESEARCH41 R41-3, HIGH: the animation timelines' stand_up / drop_down events plus guides) Maul, Ferocious Roar
# and Walking Calamity leave the bear STANDING; Furious Slam, Rampage, Fury of the Mountain, any dodge roll and more than
# ~0.34 s of walking drop it. So the next Slam / Rampage / Walking Calamity skips its added time only straight after one
# of those three. The rotation, from the build (the user's no-flat-rate rule), the best of:
# - "without it": every use from the default stance (+a base seconds, final a / m: m PoB's speed divisor, the bridge's
#   useRates speedMod);
# - "Maul (or Walking Calamity) then <skill>": a press skill the build already has (a button it presses: no new press);
#   each use costs that skill's own use time (TotalAttackTime, final seconds) and adds its own hit on the boss (its
#   useRates TotalDPS / speed; not added when its group is already in Full DPS: PoB counts it there), no added time;
# - Ferocious Roar (a cooldown Warcry the build presses anyway): uses after a Roar, min(1, Roar rate / the skill's rate),
#   skip it; the Roar's own cast time not charged (as before, LOW);
# - Walking Calamity as the main skill: Walking Calamity then Walking Calamity stands, so only the first use after each
#   dodge roll pays: min(1, dodges a second x its time) of the uses (the user's dodge rate on the boss's attacks).
# The previous pass's own mods are taken back out of PoB's speed first (tag BEAR_STANCE_ENTRY). Labelled MEDIUM (the
# stance rules HIGH; the walking between uses not counted: the lower reading of drops, LOW).
BEAR_DEFAULT_STANCE = {"Furious Slam": 0.4, "Rampage": 0.5, "Walking Calamity": 0.3}
BEAR_STANCE_ENTRY = "model-mechb50-bear-stance"
BEAR_STANDERS = ("Maul", "Walking Calamity")  # pressed before the skill (R41-3)
BEAR_ROAR = "Ferocious Roar"  # a cooldown Warcry that also stands the bear (R41-3)
# (MECHB63; RESEARCH59 R59-5, research/rampage-stance-cost-r59.md, MEDIUM-LOW; MECHC59's question) Rampage is ONE
# channelled use whose slams PoB times as uses (castTime 1), so the added time above landed on every slam. The game's
# "+0.5 seconds to base attack time if not standing" is most likely the rear-up at the channel's start: it also sits on
# Walking Calamity (a 10 s buff, a one-time start), beside Rampage's other start-only form costs
# (shapeshift_minimum_channel_time_ms_+, base_minimum_channel_time_ms), and players call Rampage's slams rapid with a
# clunky start. The headline pays it once a channel: each channel taken at its minimum length (CHANNEL_MIN_STATS, 3.65 s:
# MECHC59's recast play; a channel held longer pays less, the lower reading), so a slam carries added x plain / channel
# of base time; the stand-before plays (a Maul / Roar before each channel) the same way. Row: every slam pays it (the
# reading before). MECHC59's recast play takes its recast gap as this charge (conditions.CHANNEL_RECAST's note), now
# once a channel as there.
BEAR_ONCE_A_CHANNEL = frozenset({"Rampage"})


def bear_stance_model(main: Skill | None, speed: float, forbidden: set[str] = frozenset(), rate: dict | None = None,
                      standers: list[dict] = (), dodges: float = 0.0, prev: list[dict] = (), channel: float = 0.0
                      ) -> tuple[list[dict], list[dict]]:
    """The default stance's added base attack time on a bear skill, and the rotation that skips it (see above). `speed`
    PoB's attacks a second; `rate` the main skill's useRates row (speed, speedMod, TotalDPS) or None (every use from the
    default stance); `standers` the build's other skills that stand the bear, each {"name", "speed", "TotalDPS",
    "full": its group in Full DPS}; `dodges` dodge rolls a second; `prev` this model's mods from the last pass;
    `channel` a BEAR_ONCE_A_CHANNEL skill's minimum channel seconds (0: every use pays)."""
    if main is None or BEAR_STANCE_ENTRY in forbidden:
        return [], []
    added = BEAR_DEFAULT_STANCE.get(main.name)
    if added is None:
        return [], []
    stated = added  # (the game's own number, quoted in the notes; `added` may become a slam's share of it: R59-5)
    m = number((rate or {}).get("speedMod")) or 0.0
    now = number((rate or {}).get("speed"))
    if rate is None or m <= 0 or now <= 0:
        row = ""
        if channel > 0 and speed > 0:  # (R59-5: once a channel, see BEAR_ONCE_A_CHANNEL)
            added = added * min(1.0, 1 / speed / channel)
        if speed > 0:
            row = f" (PoB's {speed:.2f} attacks/s before it: about x{1 / (1 + added * speed):.3f}, the speed modifiers aside)"
        return [raw_mod("Speed", "BASE", added, main.name, tag=BEAR_STANCE_ENTRY)], [{
            "label": f"{main.name}: +{added:g} s base attack time from the default stance*", "value": f"+{added:g} s",
            "confidence": "MEDIUM", "entry": BEAR_STANCE_ENTRY,
            "basis": (f"the game's '+{stated:g} seconds to base attack time if not standing' "
                      "(bear_skills_additional_base_attack_time_when_performing_from_default_stance), which PoB doesn't "
                      f"read{row}; every use taken from the default stance (no rotation read)")}]
    base_prev = sum(number(x.get("value")) for x in prev if x.get("name") == "Speed" and x.get("type") == "BASE")
    time_prev = sum(number(x.get("value")) for x in prev if x.get("name") == "TotalAttackTime")
    more_prev = 1.0
    for x in prev:
        if x.get("name") == "DPS" and x.get("type") == "MORE":
            more_prev *= 1 + number(x.get("value")) / 100
    plain = max(1 / now - base_prev / m - time_prev, 1e-6)  # one use from standing, PoB's seconds without this model
    hit = number(rate.get("TotalDPS")) / now / (more_prev or 1.0)  # its damage a use
    per_use, once = added, 1.0
    if channel > 0:  # (R59-5: once a channel of `channel` s, spread over its slams; BEAR_ONCE_A_CHANNEL)
        once = min(1.0, plain / channel)
        added = added * once
    t_default = plain + added / m

    def dps(t: float, extra: float = 0.0) -> float:
        return (hit + extra) / t if t > 0 else 0.0
    plays = [("without it", f"every use from the default stance (+{added:g} s base, {added / m:.3f} s at its speed)",
              dps(t_default), [raw_mod("Speed", "BASE", added, main.name, tag=BEAR_STANCE_ENTRY)])]
    for st in standers:
        rate_s = number(st.get("speed"))
        if st.get("name") == BEAR_ROAR:
            if rate_s <= 0:
                continue
            share = min(1.0, rate_s * (channel if channel > 0 else t_default))  # (uses / channels after a Roar)
            t = plain + (1 - share) * added / m
            plays.append((f"{BEAR_ROAR} before it", f"{BEAR_ROAR} on its cooldown ({rate_s:.3f}/s) stands the bear: "
                          f"{share:.0%} of the uses skip the added time (the Roar's own cast time not charged, LOW)",
                          dps(t), [raw_mod("Speed", "BASE", (1 - share) * added, main.name, tag=BEAR_STANCE_ENTRY)]))
        elif st.get("name") in BEAR_STANDERS and st.get("name") != main.name and rate_s > 0:
            own = number(st.get("TotalDPS")) / rate_s * once if not st.get("full") else 0.0  # (once a channel)
            t = plain + once / rate_s
            mods = [raw_mod("TotalAttackTime", "BASE", once / rate_s, main.name, tag=BEAR_STANCE_ENTRY)]
            if own > 0 and hit > 0:
                mods.append(raw_mod("DPS", "MORE", 100 * own / hit, main.name, tag=BEAR_STANCE_ENTRY))
            plays.append((f"{st['name']} then {main.name}",
                          f"each use straight after a {st['name']} ({1 / rate_s:.3f} s each, its own hit "
                          + (f"{own:,.1f} added" if own > 0 else "counted in its own Full DPS group" if st.get("full")
                             else "0") + "): no added time", dps(t, own), mods))
    if main.name == "Walking Calamity" and dodges > 0:
        share = min(1.0, dodges * t_default)  # (the first use after each dodge roll pays)
        plays.append(("Walking Calamity then Walking Calamity",
                      f"each use leaves the bear standing, so only the first after a dodge roll ({dodges:.3f}/s) pays: "
                      f"{share:.0%} of the uses", dps(plain + share * added / m),
                      [raw_mod("Speed", "BASE", share * added, main.name, tag=BEAR_STANCE_ENTRY)]))
    best = max(plays, key=lambda p: p[2])
    base = plays[0][2]
    rows = "; ".join(f"{name}: {how}, {value:,.1f} DPS (x{value / base:.3f})" if base > 0 else f"{name}: {how}"
                     for name, how, value, _ in plays)
    chosen = best[0] != "without it"
    if channel > 0:  # (R59-5's row: every slam pays, the reading before)
        slam = dps(plain + per_use / m)
        rows += (f"; ONCE A CHANNEL (RESEARCH59 R59-5, MEDIUM-LOW): each {channel:.3g} s minimum channel pays it once "
                 f"(x{once:.3f} of it a slam; a longer held channel pays less); row, every slam pays it: {slam:,.1f} DPS"
                 + (f" (x{slam / base:.3f})" if base > 0 else ""))
    return best[3], [{
        "label": f"{main.name}: the bear's stance ({best[0]})*", "value": f"x{best[2] / base:.3f}" if base > 0 else "-",
        "confidence": "MEDIUM-LOW (R59-5: once a channel)" if channel > 0 else "MEDIUM", "entry": BEAR_STANCE_ENTRY,
        "basis": (f"the game's '+{stated:g} seconds to base attack time if not standing' "
                  "(bear_skills_additional_base_attack_time_when_performing_from_default_stance; PoB doesn't read it). "
                  "Maul, Ferocious Roar and Walking Calamity leave the bear standing; Slams, Rampage, dodge rolls and "
                  "walking drop it (RESEARCH41 R41-3, HIGH). PoB's one use from standing "
                  f"{plain:.3f} s and {hit:,.1f} damage on the boss; the rotations: {rows}. Scored: {best[0]}"),
        "play": ((f"Play {best[0]}: {best[1]}." if chosen else f"Every {main.name} from the default stance.")
                 + " Rolling or walking between them drops the bear back to all fours.")}]


# A perfect-release stat set chosen (MECHB50; PLANS6 kw-perfect-timing.md item 1, a small OVERCOUNT unlabelled before):
# when the scored set of a Perfect Timing skill (PoB SkillType PerfectTiming: Gathering Storm, Perfect Strike, Snipe)
# is its perfect one, every release counts as Perfect. That is a play choice, not a game rate ("release every use in
# the window": MEDIUM), so it is named, with the plain set as the "without it" row. Snipe's own model (ailment_set_model
# above) already says so; Gathering Storm's "Perfect Dash" / "Tempest Shockwave" and Perfect Strike's "Perfect Strike"
# (PoB act_int / act_str stat sets) get the note here. A miss share would scale with the window (PoB's PerfectTiming
# output): a human rate, never guessed (a question for the user, the plan's).
PERFECT_SETS = {"Gathering Storm": (("Perfect Dash", "Tempest Shockwave"), ("Normal Dash", "Shockwave")),
                "Perfect Strike": (("Perfect Strike",), ("Normal Strikes",))}


def perfect_timing_note(main: Skill | None, scored: str | None, sets: list[dict]) -> list[dict]:
    """A labelled play note when a Perfect Timing skill's perfect set is the one scored (see above)."""
    if main is None or main.name not in PERFECT_SETS or scored not in PERFECT_SETS[main.name][0]:
        return []
    dps = {x.get("label"): number(x.get("TotalDPS")) for x in sets}
    perfect, plain_labels = dps.get(scored, 0.0), PERFECT_SETS[main.name][1]
    plain = max((dps.get(k, 0.0) for k in plain_labels), default=0.0)
    row = (f"; every release imperfect ({' / '.join(plain_labels)}): {plain:,.1f} DPS, x{plain / perfect:.3f}"
           if perfect > 0 else "")
    return [{"label": f"{main.name}: every release Perfectly Timed*", "value": scored, "confidence": "MEDIUM",
             "basis": (f"the {scored} set scored ({perfect:,.1f} DPS): a play choice, every release inside the Perfect "
                       f"Timing window (no miss share counted: a human rate){row}"),
             "play": (f"Release {main.name} inside its Perfect Timing window every time; missing it drops a use to the "
                      f"plain set{f' (x{plain / perfect:.3f})' if perfect > 0 else ''}.")}]


# Gathering Storm's Tempest Shockwave set (MECHB59; AUDIT37 W3, a latent OVERCOUNT: the set could be scored with no Bell,
# and at every use with one). Patch 0.5.0: "Now causes Perfectly Timed dash to explode any Tempest Bell on hit, creating a
# massive shockwave"; the skill text: the Perfect dash "also explodes Tempest Bells on hit creating a shockwave". So the
# set's hits come once per Bell exploded: at most the Bells a second (conditions.bell_feed, the rate its Shocked Ground
# already reads), none with no Bell. Only the shockwave is counted while this set is scored (the dash's own hit is the
# Perfect Dash set's: the search compares the two).
GATHERING_STORM, GATHERING_ENTRY = "Gathering Storm", "model-mechb59-gathering-shockwave"
TEMPEST_SHOCKWAVE = "Tempest Shockwave"


def gathering_shockwave_model(main: Skill | None, scored: str | None, speed: float, feed: dict,
                              forbidden: set[str] = frozenset()) -> tuple[list[dict], list[dict]]:
    """The Tempest Shockwave set held to the Bells the build explodes (see above). `speed` PoB's uses a second, `feed`
    conditions.bell_feed's {rate, how}."""
    if main is None or main.name != GATHERING_STORM or scored != TEMPEST_SHOCKWAVE or GATHERING_ENTRY in forbidden \
            or speed <= 0:
        return [], []
    rate = min(max(number(feed.get("rate")), 0.0), speed)
    factor = rate / speed
    mod = raw_mod("DPS", "MORE", 100 * (factor - 1), main.name, tag=GATHERING_ENTRY)
    mod[HIT_CUT_PER_USE] = factor
    return [mod], [{
        "label": f"{main.name}: {rate:.2f} Tempest Shockwaves a second*", "value": f"x{factor:.3f}",
        "confidence": "MEDIUM", "entry": GATHERING_ENTRY,
        "basis": (f"PoB scores a shockwave on each of its {speed:.2f} uses a second; the game makes one only when a "
                  f"Perfectly Timed dash explodes a Tempest Bell (patch 0.5.0): {feed.get('how')}"),
        "play": ("Place a Tempest Bell at the boss and dash through it with a Perfectly Timed release; without a Bell "
                 "this shockwave never happens.")}]


# Volcano's channel (MECHB50; PLANS7 gs-volcano-channel.md: an OVERCOUNT on a tap, an UNDERCOUNT on a full channel).
# VolcanoPlayer (GrantedEffectStatSets 26650308, the same in PoB act_str): cast time 0.8 s, channel_start / channel_end_
# duration_as_%_of_cast_time 50 / 50, volcano_gain_stage_every_%_of_cast_time 100 (a stage each cast time channelled),
# volcano_maximum_number_of_stages 4, volcano_initial_explosion_damage_+%_final_per_additional_stage 150, ..._number_of_
# additional_projectiles_per_additional_stage 4; nothing modifies them (checked: every volcano_ stat id in Mods,
# PassiveSkills, GrantedEffectQualityStats: 0 rows). PoB maps none of these (its Eruption set is one hit a cast time).
# One eruption channelled to k additional stages: the 0.5 wind-up + 1 + k stage times + the 0.5 end, (2 + k) cast
# times, for a hit x (1 + 1.5 k) (150% more per stage, taken as additive per stage: "+%_final_per_additional_stage" is
# one final multiplier of 150% x k, MEDIUM). Against PoB's one hit a cast time: x (1 + 1.5 k) / (2 + k): a tap x0.5,
# k = 3 x1.1. The model takes the best k as the play ("channel to the last stage"), k at most 3 (the 4 stages taken to
# include the first, the lower reading; 4 more a row: UNVERIFIED which). The 4 k extra projectiles a stage are sprayed
# around the volcano: not counted on a lone boss (LOW), a row with them all hitting at the Projectiles set's hit. Only
# when the Eruption set is the one scored; the generic channel_windup_model leaves Volcano to this.
VOLCANO, VOLCANO_ENTRY = "Volcano", "model-mechb50-volcano-channel"
VOLCANO_STAGES, VOLCANO_MORE, VOLCANO_PROJECTILES = 4, 1.5, 4
# (MECHB60; MECHB58's kw-limit item 1, Volcano's limit) volcano_statset_1: "Fires Projectiles every {0} seconds, or when
# Slammed" (volcano_fires_projectiles_every_x_ms 500: PoB's Projectiles set hitTimeOverride) and "Volcano is destroyed after
# {0} Slams" (volcano_slam_unscalable_limit 10), base_skill_effect_duration 8 s, Limit 1. With the Eruption set scored, none
# of these sprays is counted: how many of a spray's projectiles reach a lone boss, and whether a recast ends the old
# Volcano's sprays, are open (R-B26), so they stay out of the headline (the lower reading) and are ROWS: a spray every
# 0.5 s plus one for each Slam the build lands on it (its Slam skills at their use rate, at most 10 a Volcano life), each
# spray one projectile hit at the Projectiles set's hit (KeywordPopups 74's group rule: one of a spray a target).
# (MECHB61, RESEARCH57 R57-5, research/volcano-sprays-r57.md) The sprays now go in the HEADLINE (LOW):
# - a recast removes the old Volcano (KeywordPopups Limit: "the oldest effect will dissapear"; Limit 1: HIGH), so each
#   Volcano lives min(its duration, the time to the next eruption) and sprays every 0.5 s of that;
# - each Slam the build lands on it sprays too, at most 10 a Volcano (volcano_slam_unscalable_limit);
# - hits a spray: the projectiles burst in an area, and the group rule caps the projectile's contact, not its burst, so
#   several can hit (MEDIUM: a 0.5 guide's "These detonations can shotgun"); how many is geometry (LOW): the boss on the
#   Volcano, landings spread evenly over a disc of radius R: n x min(1, ((rho + r_boss) / R)^2), n the Projectiles set's
#   ProjectileCount (5 at base), rho its impact radius (PoB's AreaOfEffectRadius, 0.6 m at base), r_boss the preset's hit
#   radius, R = 3 m (the secondary radius read as the spray's reach: UNVERIFIED) x the projectile speed modifier.
#   About 0.7 hits a spray at r_boss 0.5 m, 1.4 at 1 m. Rows: one a spray (the group rule read strictly); all n (walls).
# - the Slam sprays' wider 0.8 m burst isn't used (the timed one's, lower); a second Volcano under "+1 to Limit" isn't.
VOLCANO_SPRAY_EVERY, VOLCANO_SLAM_LIMIT, VOLCANO_SECONDS = 0.5, 10.0, 8.0
VOLCANO_SPRAY_REACH, VOLCANO_SPRAY_COUNT, VOLCANO_SPRAY_RADIUS = 3.0, 5.0, 0.6  # m, projectiles, m (R57-5's base values)


def volcano_spray_hits(sets: list[dict], boss_radius: float, speed_mod: float = 1.0) -> tuple[float, float, str]:
    """(hits on the boss a spray, the projectiles a spray, how): R57-5's disc reading (see above)."""
    got = next((x for x in sets if x.get("label") == "Projectiles"), {})
    n = number(got.get("ProjectileCount")) or VOLCANO_SPRAY_COUNT
    rho = number(got.get("AreaOfEffectRadius")) / 10 or VOLCANO_SPRAY_RADIUS
    reach = VOLCANO_SPRAY_REACH * (speed_mod if speed_mod > 0 else 1.0)
    hits = n * min(1.0, ((rho + max(boss_radius, 0.0)) / reach) ** 2)
    return hits, n, (f"{n:g} projectiles a spray landing over a {reach:.2f} m disc around the Volcano under the boss, each "
                     f"bursting {rho:.2f} m: those within {rho:.2f} + {boss_radius:.2f} m (the boss's radius) hit, "
                     f"{hits:.2f} a spray (R57-5, LOW: the spray's reach UNVERIFIED)")


def volcano_channel_model(main: Skill | None, scored: str | None, sets: list[dict],
                          forbidden: set[str] = frozenset(), dodges: float = 0.0, cast_rate: float = 0.0,
                          slams: tuple[float, str] = (0.0, ""), lifetime: float = 0.0, boss_radius: float = 0.5,
                          speed_mod: float = 1.0) -> tuple[list[dict], list[dict]]:
    """Volcano's eruption channelled to its best stage count against PoB's one hit a cast time (see above). `dodges` the
    dodge rolls a second the build makes anyway, `cast_rate` its casts a second (R42-25's row); `slams` (the build's
    Slams a second, which), `lifetime` the Volcano's duration (s; 0: its base 8 s) for the sprays (MECHB60; in the
    headline since MECHB61, R57-5), `boss_radius` (m) and `speed_mod` (its projectile speed modifier) for their hits."""
    if main is None or main.name != VOLCANO or scored not in ("Eruption", "Projectiles") or VOLCANO_ENTRY in forbidden:
        return [], []
    speeds = {x.get("label"): number(x.get("Speed")) for x in sets}
    if scored == "Projectiles":  # (MECHB61: the same play scored from the Projectiles set: the eruptions' cast rate)
        cast_rate = speeds.get("Eruption", 0.0)

    def rate(k: int) -> float:
        return (1 + VOLCANO_MORE * k) / (2 + k)
    best = max(range(VOLCANO_STAGES), key=rate)  # (0..3 additional stages)
    factor = rate(best)
    avg = {x.get("label"): number(x.get("AverageDamage")) for x in sets}
    eruption, projectile = avg.get("Eruption", 0.0), avg.get("Projectiles", 0.0)
    rows = f"; a tap (no stage) x{rate(0):.3f}; the 4 stages beyond the first (UNVERIFIED) x{rate(VOLCANO_STAGES):.3f}"
    spray_gain, spray_how = 0.0, ""
    if eruption > 0 and projectile > 0:
        all_hit = (eruption * (1 + VOLCANO_MORE * best) + VOLCANO_PROJECTILES * best * projectile) / (eruption * (2 + best))
        rows += f"; its {VOLCANO_PROJECTILES * best} extra projectiles all hitting the boss x{all_hit:.3f} (LOW)"
        if cast_rate > 0:  # (MECHB60's rows; MECHB61: the headline, R57-5)
            life = lifetime if lifetime > 0 else VOLCANO_SECONDS
            casts = cast_rate / (2 + best)  # (eruptions a second: each recast removes the old Volcano)
            up = min(life, 1 / casts) if casts > 0 else life
            timed = casts * up / VOLCANO_SPRAY_EVERY
            slammed = min(max(slams[0], 0.0) * min(1.0, casts * up), VOLCANO_SLAM_LIMIT * casts)
            per = projectile / (eruption * cast_rate)
            hits, n, hits_how = volcano_spray_hits(sets, boss_radius, speed_mod)
            spray_gain = (timed + slammed) * hits * per
            spray_how = (f"; its sprays (\"Fires Projectiles every {VOLCANO_SPRAY_EVERY:g} seconds, or when Slammed\"): "
                         f"each Volcano lives {up:.2f} s (its {life:g} s, or until the next eruption's recast removes it: "
                         f"Limit 1, HIGH), {timed:.2f} timed sprays a second"
                         + (f" + {slammed:.2f} from {slams[1]}'s Slams (at most {VOLCANO_SLAM_LIMIT:g} a Volcano)"
                            if slammed > 0 else " (no Slam skill to Slam it)")
                         + f"; {hits_how}: +{spray_gain:.3f} on the eruptions' x{factor:.3f}")
            rows += (f"; the sprays at one hit each (the group rule read strictly) x{factor + (timed + slammed) * per:.3f}; "
                     f"all {n:g} of each hitting (walls) x{factor + (timed + slammed) * n * per:.3f}; no sprays "
                     f"x{factor:.3f}")
    if dodges > 0 and cast_rate > 0:  # (MECHB51; RESEARCH42 R42-25, MEDIUM-HIGH: a roll after release skips the end)
        rolled = min(1.0, dodges * (2 + best) / cast_rate)
        skip = (1 + VOLCANO_MORE * best) / (1.5 + best + 0.5 * (1 - rolled))
        rows += (f"; the end skipped by the dodge rolls you make anyway ({rolled:.0%} of releases followed by one: "
                 f"R42-25, its end isn't locked; a roll only to skip it loses time, 0.75 s against ~0.5 cast time) "
                 f"x{skip:.3f} (a row, MEDIUM)")
    mod = raw_mod("DPS", "MORE", 100 * (1 / (2 + best) - 1), main.name, tag=VOLCANO_ENTRY)
    mod["hit_cut"] = 1 / (2 + best)  # (MECHB52: the hit part, one eruption per 2 + k cast times; the rest is its stages)
    # (MECHB53, MECH99's split: a TIME cut, kept on "hit_cut": each eruption costs 2 + k cast times of channel, so its
    # uses are fewer, not its hits a use)
    # (MECHB54; GEM33's 29f15646, the manager 02:50: PoB builds an ailment from the hit BEFORE DpsMultiplier, so the
    # stages' more inside the "DPS" MORE never reached Volcano's Ignite, an UNDERCOUNT) the per-eruption more x (1 + 1.5 k)
    # as a "Damage" MORE (PoB carries it into the hit's ailments), the eruptions' rate as the "DPS" MORE: their product is
    # the old factor exactly
    mods = [mod] + ([raw_mod("Damage", "MORE", 100 * VOLCANO_MORE * best, main.name, tag=VOLCANO_ENTRY)] if best else [])
    if spray_gain > 0:  # (MECHB61, R57-5: the sprays beside the eruptions, as the eruption hit's equivalent)
        mods.append(raw_mod("DPS", "MORE", 100 * spray_gain / factor, main.name, tag=VOLCANO_ENTRY))
    if scored == "Projectiles":
        # (MECHB61, R57-5) PoB scores this set as one projectile hit a spray at its own rate and no eruption; the play is
        # the Eruption set's (channelled eruptions, each Volcano spraying until the next one replaces it), so the same
        # total is expressed over PoB's number, and the search is indifferent between the two sets
        spray_speed = speeds.get("Projectiles", 0.0)
        if eruption <= 0 or projectile <= 0 or cast_rate <= 0 or spray_speed <= 0:
            return [], []
        total = eruption * cast_rate * (factor + spray_gain)
        whole = total / (projectile * spray_speed)
        return [raw_mod("DPS", "MORE", 100 * (whole - 1), main.name, tag=VOLCANO_ENTRY)], [{
            "label": f"{main.name}: its eruptions and sprays (PoB scores one projectile a spray)*",
            "value": f"x{whole:.3f}", "confidence": "LOW", "entry": VOLCANO_ENTRY,
            "basis": (f"PoB scores the Projectiles set: one hit a spray at {spray_speed:.2f} a second ({projectile:.1f} each) "
                      f"and no eruption. The play (as the Eruption set's model): {best} additional stage(s), x{factor:.3f} "
                      f"of the Eruption's {eruption:.1f} x {cast_rate:.2f} casts{spray_how}: {total:.1f} against PoB's "
                      f"{projectile * spray_speed:.1f}: x{whole:.3f}{rows}"),
            "play": (f"Channel {main.name} to its last stage under the boss; each Volcano sprays until the next "
                     "replaces it.")}]
    return mods, [{
        "label": f"{main.name}: each eruption channelled to {best + 1} stages, and its sprays*",
        "value": f"x{factor + spray_gain:.3f}",
        "confidence": "MEDIUM-LOW", "entry": VOLCANO_ENTRY,
        "basis": (f"PoB scores one Eruption hit a cast time and reads none of the channel stats. The game: a 50% wind-up, "
                  f"a stage each cast time, a 50% end, 150% more Eruption damage per additional stage (game files): "
                  f"{best} additional stage{'s' if best != 1 else ''} take {2 + best} cast times for x{1 + VOLCANO_MORE * best:g} "
                  f"damage: x{factor:.3f}{spray_how}{rows}; the eruption's extra projectiles sprayed around the "
                  "volcano not counted on a lone boss (LOW)"),
        "play": (f"Channel {main.name} to its last stage before releasing: x{factor:.3f}; a quick tap is "
                 f"x{rate(0):.3f}.")}]


# Leap skills' attack time added by the distance leapt (MECHB51; PLANS7 gs-leap-attack-time.md, an OVERCOUNT; RESEARCH42
# R42-14): skill_added_attack_time_by_distance_ms, "Up to +{0} seconds to Total Attack Time based on distance travelled"
# (Leap Slam 500, Molten Crash 300 (both its sets), Devour 500; leap_slam_animation_distance_threshold 30, 3 m; PoB
# act_str.lua 8243, 13986 / 14055, 3764), beside the fixed total_attack_time_+_ms (Leap Slam 650, Molten Crash 550) PoB
# reads (SkillStatMap 2244). PoB reads the distance stat nowhere (checked: grep "by_distance" over SkillStatMap.lua,
# Modules, Classes: none). The added part grows with distance and is full at 3 m (linear: LOW). The leap's length in a
# boss fight is the game's (R42-14: "a hop under 1 m" beside a boss, ~0-0.17 s on Leap Slam): at the build's melee
# distance the headline takes the middle of that, 0.5 m (LOW, a flat number of the game's: named for the manager), with
# rows 0 m (leaping in place) and 1 m; a build standing further off leaps its distance (to 3 m). A TotalAttackTime BASE
# (final seconds, PoB CalcOffence 2839, as the fixed part). The wolves' WolfLeapAttackMinion (250 ms) is left out (a
# minion skill: its leap length is the minion AI's, UNVERIFIED; named in the report).
LEAP_ADDED_TIME = {"Leap Slam": 0.5, "Molten Crash": 0.3, "Devour": 0.5}
LEAP_FULL_METRES = 3.0
LEAP_BESIDE_METRES, LEAP_BESIDE_ROWS = 0.5, (0.0, 1.0)
LEAP_ENTRY = "model-mechb51-leap-time"


def leap_time_model(main: Skill | None, metres: float, melee_metres: float, speed: float = 0.0,
                    forbidden: set[str] = frozenset()) -> tuple[list[dict], list[dict]]:
    """The distance-added attack time of a leap skill (see above). `metres` the build's distance to the boss,
    `melee_metres` the melee distance (at or under it the leap is a hop beside the boss), `speed` PoB's uses a second."""
    if main is None or main.name not in LEAP_ADDED_TIME or LEAP_ENTRY in forbidden or main.triggered:
        return [], []
    full = LEAP_ADDED_TIME[main.name]
    beside = metres <= melee_metres + 1e-9
    leap = LEAP_BESIDE_METRES if beside else min(LEAP_FULL_METRES, metres)

    def added(d: float) -> float:
        return full * min(1.0, max(d, 0.0) / LEAP_FULL_METRES)

    def kept(d: float) -> str:
        return f"x{1 / (1 + added(d) * speed):.3f}" if speed > 0 else f"+{added(d):.3f} s"
    rows = [d for d in ((*LEAP_BESIDE_ROWS, LEAP_FULL_METRES) if beside else (LEAP_BESIDE_METRES, LEAP_FULL_METRES))
            if abs(d - leap) > 1e-9]
    head = added(leap)
    return [raw_mod("TotalAttackTime", "BASE", head, main.name, tag=LEAP_ENTRY)], [{
        "label": f"{main.name}: +{head:.3f} s attack time for the distance leapt*", "value": f"+{head:.3f} s",
        "confidence": "LOW", "entry": LEAP_ENTRY,
        "basis": (f"the game's 'Up to +{full:g} seconds to Total Attack Time based on distance travelled' "
                  f"(skill_added_attack_time_by_distance_ms), full at {LEAP_FULL_METRES:g} m (taken as linear, LOW; "
                  "RESEARCH42 R42-14), which PoB doesn't read. "
                  + (f"Beside the boss each leap is a short hop: {leap:g} m taken (the middle of R42-14's 0-1 m)"
                     if beside else f"From {metres:g} m each leap covers {leap:g} m")
                  + f": +{head:.3f} s a use ({kept(leap)} at PoB's {speed:.2f} uses/s); rows: "
                  + "; ".join(f"{d:g} m {kept(d)}" for d in rows)),
        "play": f"Leap from close by: each metre leapt adds {full / LEAP_FULL_METRES:.2f} s to {main.name}."}]



# Devour's target distance (GEM40; COV55's row 5 on example build 20, an OVERCOUNT where Devour deals damage beside the
# boss). The game (ActiveSkills wyvern_devour / PoB act_str.lua 3690, 26650308): "If the target is far enough away, you
# will leap to them and damage nearby enemies where you land. Targeting nearby enemies or corpses will not perform a leap
# or a Slam"; WyvernDevourPlayer: wyvern_devour_near_target_attack_speed_+%_final -15, wyvern_devour_far_target_attack_
# speed_+%_final +20 (no description: hidden stats; poe2db's Devour page lists the same pair), and skill_added_attack_
# time_by_distance_ms 500 (leap_time_model). Both stats are on WyvernDevourPlayer alone (checked: every GrantedEffect-
# StatSets row's constant stats; the two Stats ids in Mods, PassiveSkills, GrantedEffectStatSetsPerLevel,
# GrantedEffectQualityStats and SoulCoreStats: none; builder/, engine/: no reader). PoB reads neither and scores the
# Slam on every use. So:
# - Devour dealing damage (the main skill): only a far use leaps and Slams, so its uses are far ones: 20% more Attack
#   Speed, and the leap's added time at the distance where a use counts as far. That distance is not in the game data
#   ("far enough away"): Leap Slam's leap_slam_animation_distance_threshold 30 (3 m) is taken (LOW, named), where
#   leap_time_model's added time is full (+0.5 s). Row: near uses (beside the boss) Slam nothing: 0.
# - Devour used only to eat (a side skill feeding Power Charges from corpses or Hollow Focus bells): the quicker of a
#   near use (x0.85 speed, no leap) and a far one (x1.2 and +0.5 s), the player's choice for a target beside them
#   (MEDIUM-LOW): near unless its attack time is over ~1.5 s.
DEVOUR = "Devour"
DEVOUR_NEAR, DEVOUR_FAR = -15.0, 20.0  # (WyvernDevourPlayer's two _+%_final stats, game 26650308)
# (GEM42; RESEARCH59 R59-14, research/devour-rampage-distances-r59.md, LOW-MEDIUM) Devour has NO leap-threshold stat:
# it is a melee dash (base_melee_dash_range 4 m), so it leaps when the target is beyond melee reach, ~1.5 m: the
# headline leap is the boss's distance, at least 1.5 m (leap_time_model's added time 0.5 s x 1.5 / 3 = +0.25 s a use);
# Leap Slam's 3 m threshold (GEM40's reading, +0.5 s) is the row. Before: 3 m, an UNDERCOUNT of Devour's speed.
DEVOUR_FAR_METRES = 1.5
DEVOUR_FAR_ROW_METRES = 3.0


def devour_far_added() -> float:
    """(GEM42, R59-14) A far Devour's added attack time: the leap from DEVOUR_FAR_METRES (leap_time_model's linear
    reading: the full 0.5 s at 3 m)."""
    return LEAP_ADDED_TIME[DEVOUR] * min(1.0, DEVOUR_FAR_METRES / LEAP_FULL_METRES)
DEVOUR_ENTRY = "model-gem40-devour-target-distance"


def devour_side_near(speed: float) -> bool:
    """A side Devour that only eats: near (no leap) is quicker than far unless its base attack time is long."""
    if speed <= 0:
        return True
    base = 1.0 / speed
    return base / (1 + DEVOUR_NEAR / 100) <= base / (1 + DEVOUR_FAR / 100) + devour_far_added()


def devour_target_model(skills: list[Skill], main: Skill | None, devour_speed: float,
                        forbidden: set[str] = frozenset()) -> tuple[list[dict], list[dict]]:
    """Devour's near / far attack speed (see above): a "Speed" MORE on Devour, far when it is the main skill, the
    quicker one when it's a side skill that only eats. `devour_speed` PoB's Devour uses a second (its own row)."""
    devour = next((s for s in skills if s.name == DEVOUR), None)
    if devour is None or DEVOUR_ENTRY in forbidden or devour.triggered:
        return [], []
    if main is not None and main.name == DEVOUR:
        return [raw_mod("Speed", "MORE", DEVOUR_FAR, DEVOUR, tag=DEVOUR_ENTRY)], [{
            "label": "Devour: only a far target gives the leap and Slam, 20% more Attack Speed*",
            "value": f"x{1 + DEVOUR_FAR / 100:.2f} speed", "confidence": "MEDIUM-LOW", "entry": DEVOUR_ENTRY,
            "basis": ("the game: \"If the target is far enough away, you will leap to them and damage nearby enemies "
                      "where you land. Targeting nearby enemies or corpses will not perform a leap or a Slam\"; "
                      "WyvernDevourPlayer's far-target +20% / near-target -15% final attack speed (poe2db the same), "
                      "which PoB doesn't read. The damaging uses are far ones: +20%, and the leap's added time from "
                      f"{DEVOUR_FAR_METRES:g} m (a melee dash: it leaps past melee reach, ~{DEVOUR_FAR_METRES:g} m, "
                      f"RESEARCH59 R59-14, LOW-MEDIUM; Leap Slam's {DEVOUR_FAR_ROW_METRES:g} m is the row). "
                      "Row: near uses beside the boss (x0.85 speed) Slam nothing: 0"),
            "play": ("Devour a corpse or bell a few metres off the boss's far side so you leap onto it; one beside you "
                     "eats it with no Slam: without the leap 0 damage from Devour")}]
    near = devour_side_near(devour_speed)
    # (far: its +20% and the leap's +0.5 s together, as one speed factor on its own use time)
    value = DEVOUR_NEAR if near or devour_speed <= 0 else 100 * (
        1 / (1 / (1 + DEVOUR_FAR / 100) + devour_far_added() * devour_speed) - 1)
    return [raw_mod("Speed", "MORE", value, DEVOUR, tag=DEVOUR_ENTRY)], [{
        "label": "Devour: eating beside you, the target's distance sets its speed*",
        "value": f"x{1 + value / 100:.2f} speed ({'near' if near else 'far'})", "confidence": "MEDIUM-LOW",
        "entry": DEVOUR_ENTRY,
        "basis": ("WyvernDevourPlayer's near-target -15% / far-target +20% final attack speed (hidden stats, poe2db the "
                  "same), which PoB doesn't read; Devour isn't the main skill here, so it's used to eat (Power Charges), "
                  f"and the quicker use is taken: {'near (no leap)' if near else 'far (a leap)'} at PoB's "
                  f"{devour_speed:.2f} uses/s (the player's choice, MEDIUM-LOW; a far use leaps from "
                  f"{DEVOUR_FAR_METRES:g} m, +{devour_far_added():g} s, R59-14)")}]


# Momentum (GEM40; COV56's turn 2, an UNDERCOUNT: PoB applies its 40% only under the unticked "Moved 2m during Skill
# use?" box, ConfigOptions 484, Condition:Moved2m, and nothing in our code ticks it). The game (26650308,
# SupportMomentumPlayer): support_momentum_distance_travelled_to_gain_momentum 20 (2 m), support_momnetum_damage_+%_
# final_with_momentum 40; PoB's description "causing it to deal more damage if you move a sufficient distance while
# using the skill. Teleportation does not count towards the distance travelled"; poe2wiki: "After moving at least 2
# metres during a single use of a Supported Skill, the rest of that use deals 40% more Damage" (no patch note: grep_notes
# --history "Momentum", no hit). So it is the build's own walk during ONE use: a skill usable while moving (the game's
# UsableWhileMoving type) walks usage.BASE_RUN (3.7 m/s, MEDIUM) x PoB's MovementSpeedMod x (1 + its own
# movement_speed_+%_final_while_performing_action, e.g. Frostbolt -70) for the use's time (1 / PoB's Speed). A player
# who sockets Momentum moves while using the skill (the play that feeds it), so the headline counts the 40% on every use
# when that walk reaches 2 m before the hit, the hit taken at the use's end (MEDIUM-LOW; row: a hit at mid-use needs 2 m
# in half the time). Not counted (0, PoB's own, named): skills that stop you (no UsableWhileMoving: a melee Strike);
# travel skills' own dash or leap distance (UNVERIFIED how it counts; a forum report says vertical travel covers less);
# a channel that doesn't move you (its hold is the channel model's: left at PoB's 0). Rows: standing still x1.
# A channelled Travel skill (Rampage: "charge forward, Slamming the ground as you run"; its channel lasts at least
# base_minimum_channel_time_ms 3000 + shapeshift_minimum_channel_time_ms_+ 650, longer with Rage) moves you all through
# its use, so "the rest of that use" after 2 m is 1 - 2 / (speed x channel) of its damage, at its SHORTEST channel (a
# lower bound: Rage prolongs it), the charge taken at BASE_RUN x MovementSpeedMod (LOW: Rampage's own
# bear_rampage_base_movement_speed 55 isn't read, unit UNVERIFIED).
MOMENTUM = "Momentum"
MOMENTUM_METRES, MOMENTUM_MORE = 2.0, 40.0  # (SupportMomentumPlayer's two constants, game 26650308)
MOMENTUM_MOVE_STAT = "movement_speed_+%_final_while_performing_action"
MOMENTUM_CHANNEL_STATS = ("base_minimum_channel_time_ms", "shapeshift_minimum_channel_time_ms_+")
MOMENTUM_ENTRY = "model-gem40-momentum-walk-a-use"


def momentum_model(main: Skill | None, main_types: set[str], group_supports: list[str], stats: dict,
                   action_move: float, standing: bool = False,
                   forbidden: set[str] = frozenset(), channel: float = 0.0) -> tuple[list[dict], list[dict]]:
    """Momentum's 40% more on the main skill when the build's walk during one use reaches 2 m (see above).
    `action_move` the skill's movement_speed_+%_final_while_performing_action (0 if none); `channel` a channelled
    Travel skill's shortest channel, seconds (MOMENTUM_CHANNEL_STATS)."""
    from builder.search.usage import BASE_RUN
    if main is None or MOMENTUM not in group_supports or MOMENTUM_ENTRY in forbidden or main.triggered:
        return [], []
    label = "Momentum: 40% more Damage after walking 2 m during a use*"
    speed = number(stats.get("Speed"))
    move = number(stats.get("MovementSpeedMod")) or 1.0
    if {"Channel", "Travel"} <= main_types and number(channel) > 0 and not standing:
        charge = BASE_RUN * move
        share = max(0.0, 1.0 - MOMENTUM_METRES / (charge * number(channel)))
        more = MOMENTUM_MORE * share
        return ([raw_mod("Damage", "MORE", more, main.name, tag=MOMENTUM_ENTRY)] if more > 0 else []), [{
            "label": label, "value": f"x{1 + more / 100:.3f}", "confidence": "MEDIUM-LOW", "entry": MOMENTUM_ENTRY,
            "basis": (f"{main.name} charges you forward all through its channel: {BASE_RUN:g} m/s x{move:.2f} movement "
                      f"speed = {charge:.2f} m/s (LOW: its own charge speed stat not read), 2 m in "
                      f"{MOMENTUM_METRES / charge:.2f} s of its shortest {number(channel):.2f} s channel, so the rest, "
                      f"{share:.0%} of its damage, gets the 40% (poe2wiki: \"the rest of that use\"; a longer channel "
                      "with Rage gives more). Row: standing still x1"),
            "play": (f"Momentum works by itself on {main.name}'s charge: {share:.0%} of each channel after the first 2 m. "
                     f"Without it x1, with it x{1 + more / 100:.3f}")}]
    if "UsableWhileMoving" not in main_types or "Channel" in main_types or speed <= 0 or standing:
        why = ("the build stands still (its Standing still box)" if standing
               else f"{main.name} is channelled (the rest-of-the-channel share isn't read, UNVERIFIED)"
               if "Channel" in main_types
               else f"{main.name} can't be used while moving (no UsableWhileMoving type)" if speed > 0
               else "PoB gives the main skill no uses")
        return [], [{"label": label, "value": "x1", "confidence": "MEDIUM-LOW", "entry": MOMENTUM_ENTRY,
                     "basis": f"{why}: not counted (PoB's own 0, the box unticked)"}]
    walk = BASE_RUN * move * max(0.0, 1 + number(action_move) / 100)
    seconds = 1.0 / speed
    metres = walk * seconds
    on = metres >= MOMENTUM_METRES - 1e-9
    half = walk * seconds / 2 >= MOMENTUM_METRES - 1e-9
    factor = 1 + MOMENTUM_MORE / 100 if on else 1.0
    note = {"label": label, "value": f"x{factor:.2f}", "confidence": "MEDIUM-LOW", "entry": MOMENTUM_ENTRY,
            "basis": (f"walking while using {main.name}: {BASE_RUN:g} m/s x{move:.2f} movement speed x"
                      f"{1 + number(action_move) / 100:.2f} while performing it = {walk:.2f} m/s over its "
                      f"{seconds:.2f} s use = {metres:.2f} m ({'at least' if on else 'under'} Momentum's 2 m before "
                      f"the hit, taken at the use's end; poe2wiki: \"the rest of that use deals 40% more Damage\"). "
                      f"Rows: standing still x1; the hit at mid-use x{1 + MOMENTUM_MORE / 100 if half else 1.0:.2f}"),
            "play": (f"Keep walking while you use {main.name}: Momentum's 40% more needs 2 m covered during each use "
                     f"(you cover {metres:.2f} m). Without it x1, with it x{1 + MOMENTUM_MORE / 100:.2f}"
                     + ("" if on else " (more movement speed would reach it)"))}
    if not on:
        return [], [note]
    return [raw_mod("Damage", "MORE", MOMENTUM_MORE, main.name, tag=MOMENTUM_ENTRY)], [note]


# Firestorm's storms and Galvanic Field's orbs above one (GEM40; GEM39's next step 4, RESEARCH57 R57-7 / R57-13
# UNVERIFIED: whether two storms / orbs both hit one boss). Their Limits (firestorm_max_number_of_storms 1,
# galvanic_field_maximum_number_of_spheres 1, game 26650308) aren't "number_of_X_allowed" stats, so the bridge's
# instanceLimit misses them: read as Assumptions.earthshatter_limit reads its spikes (the stat + Overabundance's
# base_limit_+ + the "+N to Limit" lines). The headlines stay one: Firestorm's bolts share the boss's per-target hit
# limit (0.15 s: a second storm adds no hits under it, firestorm_rate_scale's shared reading), Galvanic Field one Orb
# a Shock. A raised Limit is a ROW (the manager's rule: a raised cap that adds no damage on a lone boss stays a row):
# Firestorm up to min(Limit, casts x duration) storms, each with its own hit limit (the per-storm reading); Galvanic
# Field a second Orb from a second Shock with the Buff up (MEDIUM-LOW).
STORM_LIMIT_STATS = {"Firestorm": "firestorm_max_number_of_storms", "Galvanic Field": "galvanic_field_maximum_number_of_spheres"}


def storm_limit_row(name: str, limit: float, casts: float, duration: float) -> list[dict]:
    """A row note for Firestorm / Galvanic Field when the build's Limit is over one (see above); [] at one."""
    if limit <= 1:
        return []
    if name == FIRESTORM:
        up = min(limit, max(casts, 0.0) * max(duration, 0.0)) if casts > 0 and duration > 0 else limit
        return [{"label": f"Firestorm: Limit {limit:g} storms (a row, not the headline)*",
                 "value": f"up to {up:.2f} storms", "confidence": "LOW",
                 "basis": (f"the build's Limit {limit:g} (firestorm_max_number_of_storms + base_limit_+ + \"+N to "
                           f"Limit\"), min(Limit, {casts:.2f} casts/s x {duration:.2f} s) = {up:.2f} storms on the boss. "
                           "Headline: one storm's bolts, as they share the boss's 0.15 s hit limit (RESEARCH57 R57-7, "
                           f"UNVERIFIED); if each storm has its own: up to x{up:.2f} the storm's damage")}]
    return [{"label": f"Galvanic Field: Limit {limit:g} Orbs (a row, not the headline)*", "value": f"up to x{limit:g} the Orb",
             "confidence": "LOW",
             "basis": (f"the build's Limit {limit:g} (galvanic_field_maximum_number_of_spheres + base_limit_+ + \"+N "
                       "to Limit\"): each Orb needs its own Shock with the Buff up (RESEARCH57 R57-13, UNVERIFIED that "
                       "two attach to one boss); headline one Orb")}]

